// Güzergahtaki şehirlerin önemli turistik/tarihi mekanları.
// places.js'teki şehir id'sine göre anahtarlanır. Kullanıcı, güzergah ve keşif
// sayfalarında bu listeleri görüp tek dokunuşla keşfe ekleyebilir; böylece
// gezilecek tarihi mekanları uygulama dışına çıkmadan görür.

export const ATTRACTIONS = {
  // --- Türkiye ---
  istanbul: [
    { name: 'Ayasofya', desc: 'MS 537’de Bizans İmparatoru Justinianus’un yaptırdığı Ayasofya, yaklaşık bin yıl dünyanın en büyük kilisesiydi ve 1453’te camiye çevrildi. Devasa kubbesi, altın mozaikleri ve Bizans ile Osmanlı sanatını aynı çatı altında buluşturan yapısıyla mimarlık tarihinin başyapıtlarındandır.' },
    { name: 'Sultanahmet Camii (Mavi Cami)', desc: 'Sultan I. Ahmed’in 1609–1616’da yaptırdığı cami, iç mekânını süsleyen binlerce mavi-yeşil İznik çinisi nedeniyle “Mavi Cami” olarak anılır. Altı minaresiyle döneminde tartışma yaratan yapı, Ayasofya’nın tam karşısında Sultanahmet Meydanı’na hâkim zarif bir Osmanlı başyapıtıdır.' },
    { name: 'Topkapı Sarayı', desc: 'Fatih Sultan Mehmed’in 1460’larda yaptırdığı Topkapı Sarayı, yaklaşık dört yüzyıl Osmanlı padişahlarının yönetim merkezi ve ikametgâhı oldu. Avluları, Harem dairesi, kutsal emanetler ve hazine koleksiyonuyla imparatorluğun ihtişamını bugüne taşıyan devasa bir saray-müzedir.' },
    { name: 'Kapalıçarşı', desc: 'Fatih Sultan Mehmed döneminde kurulan Kapalıçarşı, 60’ı aşkın sokağı ve 4.000’i geçen dükkânıyla dünyanın en eski ve en büyük kapalı çarşılarından biridir. Kuyumcuları, halıcıları ve baharatçılarıyla yüzyıllardır süren canlı bir ticaret ve el sanatları geleneğini yaşatır.' },
    { name: 'Galata Kulesi', desc: 'Cenevizlilerin 1348’de surlarının bir parçası olarak inşa ettiği Galata Kulesi, yüzyıllar boyunca yangın gözetleme kulesi olarak kullanıldı. Tarihî yarımadayı, Boğaz’ı ve Haliç’i kuşbakışı gören seyir terasıyla İstanbul’un en ikonik silüet öğelerinden biridir.' },
    { name: 'Dolmabahçe Sarayı & Boğaz', desc: 'Sultan Abdülmecid’in 1856’da açtırdığı Dolmabahçe Sarayı, Osmanlı’nın Batılılaşma döneminin görkemli barok-rokoko üslubunu yansıtır ve dünyanın en büyük avizelerinden birini barındırır. Atatürk’ün son günlerini geçirdiği saray, Boğaz kıyısındaki konumuyla vapur turlarının gözdesidir.' },
    { name: 'Yerebatan Sarnıcı', desc: 'MS 6. yüzyılda Justinianus döneminde inşa edilen Yerebatan Sarnıcı, 336 sütunuyla Bizans’ın kente su sağlayan devasa yeraltı su depolarının en büyüğüdür. Loş ışığı, sütun ormanı ve devşirme sütunların altındaki ters Medusa başlarıyla gizemli, büyüleyici bir atmosfer sunar.' },
    { name: 'Süleymaniye Camii', desc: 'Mimar Sinan’ın 1557’de tamamladığı Süleymaniye Camii, Kanuni Sultan Süleyman adına yükselen ve Haliç’e hâkim tepede kenti taçlandıran görkemli bir külliyedir. Dört minaresi, dengeli kubbe sistemi ve çevresindeki medrese, hamam ve türbeleriyle klasik Osmanlı mimarisinin doruğudur.' },
    { name: 'Mısır Çarşısı & Eminönü', desc: 'Yeni Cami külliyesinin parçası olarak 1664’te açılan Mısır Çarşısı, adını Mısır’dan gelen baharat ticaretinden alır ve yüzyıllardır baharat, kuruyemiş ve lokum kokularıyla dolar. Eminönü’nün hareketli iskeleleri, Yeni Cami ve balık ekmekçileriyle kentin en canlı köşelerindendir.' },
    { name: 'Boğaz Turu (Ortaköy–Bebek)', desc: 'İstanbul Boğazı boyunca yapılan tekne turu, iki kıtayı ayıran suların üzerinde tarihî yalıları, sahil saraylarını ve köprüleri en güzel açıdan gösterir. Ortaköy Camii’nden Bebek koylarına uzanan kıyı, kafeleri ve manzarasıyla kentin ruhunu yansıtan klasik bir deneyimdir.' },
  ],
  edirne: [
    { name: 'Selimiye Camii (UNESCO)', desc: 'Mimar Sinan’ın 80 yaşında “ustalık eserim” diyerek 1575’te tamamladığı Selimiye Camii, Ayasofya’nın kubbesini aşma hedefiyle inşa edilmiş ve tek kubbeli mekân tasarımının zirvesi kabul edilir. İnce dört minaresi ve iç çinileriyle klasik Osmanlı mimarisinin başyapıtı olarak UNESCO Dünya Mirası Listesi’ndedir.' },
    { name: 'Eski Cami', desc: 'Osmanlı’nın erken döneminde, 1414’te tamamlanan Eski Cami, dokuz kubbeli çok ayaklı planı ve duvarlarını kaplayan dev hat levhalarıyla ünlüdür. Edirne’nin en eski selatin camisi olarak erken Osmanlı mimarisinin sade ve görkemli bir örneğidir.' },
    { name: 'Üç Şerefeli Cami', desc: '1447’de tamamlanan Üç Şerefeli Cami, adını üç şerefeli (balkonlu) en yüksek minaresinden alır ve her minaresi farklı desende inşa edilmiştir. Geniş kubbesi ve avlusuyla, klasik Osmanlı cami mimarisine geçişin önemli bir dönüm noktasıdır.' },
    { name: 'II. Bayezid Külliyesi & Sağlık Müzesi', desc: 'Sultan II. Bayezid’in 1488’de yaptırdığı külliye, döneminin en gelişmiş hastanelerinden (darüşşifa) birini barındırıyordu; burada hastalar su sesi ve müzikle tedavi edilirdi. Bugün Sağlık Müzesi olarak Osmanlı tıp tarihinin insani ve yenilikçi yüzünü sergiler.' },
    { name: 'Meriç Köprüsü', desc: '19. yüzyılda yapılan Meriç Köprüsü, uzun kemerleri ve ortasındaki zarif köşküyle Meriç Nehri üzerinde Edirne’nin simge yapılarından biridir. Özellikle gün batımında nehre yansıyan silüetiyle sevilen bir yürüyüş ve fotoğraf noktasıdır.' },
    { name: 'Karaağaç', desc: 'Bir zamanlar Avrupa’ya açılan tren yolunun ucundaki Karaağaç semti; tarihî garı, Lozan Antlaşması Anıtı ve üniversite binalarıyla anılır. Ağaçlıklı yolları ve kafeleriyle Edirne’nin dingin, nostaljik bir kaçış köşesidir.' },
  ],
  izmir: [
    { name: 'Saat Kulesi & Konak Meydanı', desc: '1901’de Sultan II. Abdülhamid’in tahta çıkışının 25. yılı için dikilen Saat Kulesi, Fas esintili taş işçiliği ve dört çeşmesiyle İzmir’in simgesidir. Konak Meydanı’nda, körfez kıyısında güvercinler ve tarihî tramvaylar arasında kentin buluşma noktasıdır.' },
    { name: 'Kemeraltı Çarşısı', desc: '17. yüzyıldan bu yana İzmir’in ticaret kalbi olan Kemeraltı; tarihî hanları, camileri, sinagogları ve dar sokaklarıyla labirent gibi bir açık çarşıdır. Kızlarağası Hanı’nın avlusundan baharatçılara ve kahvecilere kadar çok kültürlü Ege ticaret geleneğini yaşatır.' },
    { name: 'Smyrna Agorası', desc: 'Antik Smyrna’nın Roma dönemi devlet agorasının kalıntıları; sütunlu galerileri, yeraltı su kanalları ve kemerleriyle kentin iki bin yıllık geçmişini gözler önüne serer. MS 178 depreminden sonra İmparator Marcus Aurelius’un desteğiyle yeniden inşa edilmiştir.' },
    { name: 'Kadifekale', desc: 'Büyük İskender’in generallerince kurulan, kente ve körfeze tepeden bakan Kadifekale (antik Pagos), yüzyıllar boyunca İzmir’in savunma noktası olmuştur. Surları ve panoramik manzarasıyla kentin en eski yerleşim çekirdeğini işaret eder.' },
    { name: 'Tarihi Asansör', desc: '1907’de hayırsever Nesim Levi tarafından, dik yamaçtaki iki mahalleyi birbirine bağlamak için yaptırılan Tarihi Asansör, döneminin mühendislik yeniliğidir. Bugün tepesindeki teras kafeden körfez ve gün batımı manzarası sunan sevilen bir semt simgesidir.' },
    { name: 'Kordon', desc: 'İzmir Körfezi boyunca uzanan Kordon; palmiyeli yürüyüş yolu, tarihî binaları ve atlı faytonlarıyla kentin en sevilen sahil güzergâhıdır. Çimenlik kıyısında gün batımını izlemek, İzmirlilerin vazgeçilmez bir günlük ritüelidir.' },
  ],
  bursa: [
    { name: 'Ulu Cami', desc: 'Yıldırım Bayezid’in 1399’da Niğbolu Zaferi’nin ardından yaptırdığı Ulu Cami, 20 kubbesi ve içindeki şadırvanıyla erken Osmanlı mimarisinin en görkemli örneklerindendir. Duvarlarını ve sütunlarını kaplayan 190’ı aşkın devasa hat levhasıyla adeta bir hüsn-i hat müzesidir.' },
    { name: 'Yeşil Cami & Yeşil Türbe', desc: 'Sultan Çelebi Mehmed’in 15. yüzyıl başında yaptırdığı Yeşil Cami ve karşısındaki Yeşil Türbe, yeşil-mavi İznik çinileriyle kaplı iç mekânlarıyla Osmanlı çini sanatının doruğu sayılır. Erken Osmanlı üslubunun en zarif ve dengeli örneklerindendir.' },
    { name: 'Koza Han', desc: '1491’de II. Bayezid tarafından yaptırılan Koza Han, yüzyıllarca İpek Yolu’nun ipek kozası ticaretinin merkeziydi ve hâlâ bu geleneği sürdürür. Çınarlı avlusu, şadırvanı ve mescidiyle bugün de canlı bir çarşı ve buluşma noktasıdır.' },
    { name: 'Cumalıkızık (UNESCO)', desc: 'Uludağ eteğindeki Cumalıkızık, Osmanlı’nın kuruluş dönemine, 700 yıl öncesine uzanan bir vakıf köyüdür. Dar arnavut kaldırımlı sokakları ile cumbalı ve rengârenk sıvalı ahşap evleriyle erken Osmanlı köy dokusunu bugüne taşıyan bir açık hava müzesidir (UNESCO).' },
    { name: 'Uludağ', desc: 'Antik çağda “Keşiş Dağı” olarak bilinen Uludağ, Bursa’ya tepeden bakan konumuyla hem Türkiye’nin en ünlü kayak merkezi hem de yaz aylarında yayla ve doğa yürüyüşü cennetidir. Teleferikle kısa sürede zirveye çıkılan dağ, dört mevsim ziyaretçi çeker.' },
    { name: 'Tophane & Osman-Orhan Türbeleri', desc: 'Bursa’nın fethedildiği tarihî tepe olan Tophane’de, Osmanlı’nın kurucusu Osman Gazi ile oğlu Orhan Gazi’nin türbeleri bulunur. Saat kulesi, surları ve kente hâkim manzarasıyla imparatorluğun doğduğu toprakları simgeleyen anlamlı bir noktadır.' },
  ],
  canakkale: [
    { name: 'Truva (Troya) Antik Kenti (UNESCO)', desc: 'Homeros’un İlyada destanına konu olan efsanevi Truva, dokuz katmanlık yerleşimiyle beş bin yıllık bir tarihe tanıklık eder ve arkeolog Schliemann’ın kazılarıyla dünyaca ünlendi. Surları, kalıntıları ve girişteki tahta at maketiyle mit ile tarihin buluştuğu bir UNESCO alanıdır.' },
    { name: 'Gelibolu Şehitlikleri & Anzak Koyu', desc: 'I. Dünya Savaşı’nın kader anlarına sahne olan Gelibolu Yarımadası, Çanakkale Savaşları’nda hayatını kaybeden yüz binlerce askerin anısını yaşatan şehitlikler ve anıtlarla doludur. Anzak Koyu ve siperler, her yıl dünyanın dört bir yanından ziyaretçiyi bir araya getiren dokunaklı bir anma alanıdır.' },
    { name: 'Çimenlik Kalesi', desc: 'Fatih Sultan Mehmed’in Boğaz’ı denetlemek için 1462’de yaptırdığı Çimenlik Kalesi, Çanakkale Savaşları’nda da stratejik rol oynamıştır. Bugün Deniz Müzesi olarak, tarihî toplarıyla ve Nusrat mayın gemisi maketiyle Boğaz savunmasının hikâyesini anlatır.' },
    { name: 'Assos (Behramkale)', desc: 'Tepesinde MÖ 6. yüzyıldan kalma Athena Tapınağı yükselen Assos, Aristoteles’in bir süre ders verdiği antik bir liman kentidir. Taş evli köyü, antik tiyatrosu ve Midilli’ye bakan gün batımı manzarasıyla büyüleyici bir duraktır.' },
    { name: 'Bozcaada', desc: 'Antik çağdan beri şarapçılığıyla ünlü Bozcaada; Venedik-Ceneviz izli görkemli kalesi, taş sokaklı kasabası ve Ayazma gibi plajlarıyla Ege’nin dingin adalarından biridir. Bağları ve rüzgârıyla huzurlu bir kaçamak sunar.' },
  ],
  antalya: [
    { name: 'Kaleiçi', desc: 'Antalya’nın tarihî çekirdeği Kaleiçi, Roma, Bizans, Selçuklu ve Osmanlı izlerini taşıyan surlarla çevrili eski kenttir. Dar arnavut kaldırımlı sokakları, restore konakları, butik otelleri ve eski Roma limanıyla açık hava müzesi gibi bir semttir.' },
    { name: 'Hadrian Kapısı', desc: 'İmparator Hadrianus’un MS 130’daki Antalya ziyareti anısına dikilen üç kemerli mermer zafer takı, kentin en zarif Roma anıtıdır. Kaleiçi’ne açılan bu görkemli kapı, iki bin yıldır ayakta kalan ince işçiliğiyle hayranlık uyandırır.' },
    { name: 'Düden Şelalesi', desc: 'Düden Çayı’nın oluşturduğu şelaleler, özellikle Lara’da suyun kırk metreden doğrudan Akdeniz’e döküldüğü noktasıyla etkileyicidir. Yukarı Düden’de ise şelalenin arkasındaki mağaradan yürüyüş yapılabilir; ikisi de serin, yeşil birer doğa molasıdır.' },
    { name: 'Antalya Müzesi', desc: 'Türkiye’nin en zengin arkeoloji müzelerinden Antalya Müzesi, başta Perge antik kentinden çıkan kusursuz Roma heykelleri olmak üzere bölgenin binlerce yıllık mirasını sergiler. Tanrılar Salonu ve imparator heykelleriyle antik Pamphylia’nın ihtişamını gözler önüne serer.' },
    { name: 'Aspendos Tiyatrosu', desc: 'MS 2. yüzyılda inşa edilen Aspendos Tiyatrosu, 15 bin kişilik kapasitesi ve neredeyse eksiksiz korunmuş sahne binasıyla dünyanın en iyi durumdaki antik tiyatrolarından biridir. Olağanüstü akustiğiyle bugün hâlâ opera ve konserlere ev sahipliği yapar.' },
    { name: 'Konyaaltı & Lara Plajları', desc: 'Antalya’nın iki büyük kent plajı, arkalarında yükselen karlı Toros Dağları manzarasıyla Akdeniz’in turkuaz sularını buluşturur. Çakıllı Konyaaltı ve kumlu Lara, yürüyüş yolları ve kıyı kafeleriyle kentliler ve turistler için gözde birer sahildir.' },
  ],
  ankara: [
    { name: 'Anıtkabir', desc: 'Türkiye Cumhuriyeti’nin kurucusu Mustafa Kemal Atatürk’ün anıtmezarı olan Anıtkabir, 1953’te tamamlanan görkemli anıtsal mimarisiyle ulusun en önemli manevi mekânıdır. Aslanlı Yol, tören meydanı ve Kurtuluş Savaşı’nı anlatan müzesiyle her yıl milyonlarca ziyaretçiyi ağırlar.' },
    { name: 'Ankara Kalesi', desc: 'Kentin en yüksek tepesinde yükselen Ankara Kalesi; Galat, Roma, Bizans ve Selçuklu dönemlerinden katmanlar taşıyan tarihî bir savunma yapısıdır. Surları içindeki taş evli eski mahalle ve surlardan izlenen kent panoramasıyla Ankara’nın kökenini simgeler.' },
    { name: 'Anadolu Medeniyetleri Müzesi', desc: 'Bir Osmanlı bedesteninde kurulu Anadolu Medeniyetleri Müzesi, Paleolitik’ten Hitit ve Frig dönemlerine Anadolu uygarlıklarının en değerli eserlerini barındırır. “Yılın Avrupa Müzesi” seçilen koleksiyonuyla, özellikle Hitit ve Çatalhöyük buluntularıyla dünyaca ünlüdür.' },
    { name: 'Hacı Bayram Camii & Augustus Tapınağı', desc: '15. yüzyıl velisi Hacı Bayram-ı Veli’ye adanan cami ile hemen yanındaki Roma dönemi Augustus Tapınağı, farklı çağların yan yana durduğu çarpıcı bir manzara sunar. Tapınağın duvarlarındaki Latince yazıtlar, imparatorun icraatlarını günümüze taşıyan eşsiz bir belgedir.' },
    { name: 'Roma Hamamı', desc: 'Ulus’ta, İmparator Caracalla döneminde (MS 3. yüzyıl) sağlık tanrısı Asklepios adına yapılan Roma Hamamı’nın kalıntıları, ısıtma sistemini (hypocaust) taşıyan sütuncuklarıyla açık havada sergilenir. Antik Ankara’nın (Ancyra) günlük yaşamına ışık tutar.' },
  ],
  konya: [
    { name: 'Mevlânâ Müzesi', desc: 'Ünlü mutasavvıf ve şair Mevlânâ Celaleddin Rumî’nin türbesini barındıran, turkuaz çinili kubbesiyle simgeleşen bu yapı, hem müze hem önemli bir maneviyat merkezidir. Semazenlerin ve Mevlevi geleneğinin doğduğu yer olarak dünyanın dört bir yanından ziyaretçi çeker.' },
    { name: 'Alâeddin Camii', desc: 'Konya’nın en eski ve en büyük camisi olan Alâeddin Camii, 12.–13. yüzyıllarda Selçuklu sultanları döneminde tepedeki höyük üzerine inşa edilmiştir. Ahşap sütunlu iç mekânı ve bahçesindeki Selçuklu sultanlarının türbeleriyle başkent Konya’nın görkemli geçmişini yansıtır.' },
    { name: 'İnce Minareli Medrese', desc: '1265’te Selçuklu veziri Sahip Ata tarafından yaptırılan İnce Minareli Medrese, taç kapısındaki olağanüstü taş oyma işçiliğiyle Selçuklu sanatının başyapıtlarındandır. Bugün Taş ve Ahşap Eserler Müzesi olarak Selçuklu bezeme sanatını sergiler.' },
    { name: 'Çatalhöyük (UNESCO)', desc: 'Yaklaşık dokuz bin yıllık Çatalhöyük, insanlığın bilinen en eski ve en büyük Neolitik yerleşimlerinden biridir; kapıları çatıda olan bitişik evleriyle kentleşmenin şafağına ışık tutar. Duvar resimleri ve ana tanrıça figürleriyle UNESCO Dünya Mirası Listesi’ndedir.' },
    { name: 'Sille', desc: 'Konya’ya birkaç kilometre uzaklıktaki Sille, Rumların ve Türklerin yüzyıllarca bir arada yaşadığı, taş evli tarihî bir köydür. Bizans dönemine uzanan Aya Eleni Kilisesi ve kayalara oyulmuş şapelleriyle çok kültürlü bir geçmişi bugüne taşır.' },
  ],
  trabzon: [
    { name: 'Sümela Manastırı', desc: 'Maçka’da, Altındere Vadisi’nde sarp bir kaya yüzeyine yüzlerce metre yükseklikte tutunan Sümela Manastırı, MS 4. yüzyıla uzanan bir Rum Ortodoks manastırıdır. Kayalara ve şapel duvarlarına işlenmiş canlı freskleriyle doğa ile inancın buluştuğu nefes kesici bir yapıdır.' },
    { name: 'Trabzon Ayasofyası', desc: '13. yüzyılda Trabzon Rum İmparatorluğu döneminde inşa edilen bu kilise, deniz manzaralı konumu ve iyi korunmuş İncil sahneli freskleriyle geç Bizans sanatının önemli bir örneğidir. Yüzyıllar içinde cami ve müze olarak da kullanılmıştır.' },
    { name: 'Atatürk Köşkü', desc: 'Trabzon’a tepeden bakan yeşil bir bahçe içindeki bu zarif beyaz köşk, 19. yüzyıl sonunda yapılmış ve Atatürk’ün kente gelişlerinde konakladığı yer olmuştur. Dönem eşyalarıyla döşeli iç mekânı ve manzarasıyla sevilen bir gezi noktasıdır.' },
    { name: 'Uzungöl', desc: 'Çevresini saran sisli dağların ve köknar ormanlarının suya yansıdığı Uzungöl, bir heyelan sonucu oluşmuş büyüleyici bir dağ gölüdür. Yaylaları, ahşap evleri ve serin havasıyla Doğu Karadeniz’in en ünlü doğa duraklarından biridir.' },
    { name: 'Boztepe', desc: 'Trabzon’a ve Karadeniz’e tepeden bakan Boztepe, çay bahçeleri ve seyir teraslarıyla kentin panoramasını izlemek için en sevilen noktadır. Özellikle gün batımında kent ve deniz manzarası büyüleyicidir.' },
  ],
  gaziantep: [
    { name: 'Zeugma Mozaik Müzesi', desc: 'Fırat kıyısındaki antik Zeugma kentinden çıkarılan mozaikleri barındıran bu müze, dünyanın en büyük mozaik müzelerinden biridir. Barajın altında kalmaktan kurtarılan zarif eserler arasında, bakışlarıyla ünlü “Çingene Kızı” mozaiği müzenin simgesidir.' },
    { name: 'Gaziantep Kalesi', desc: 'Kent merkezindeki höyük üzerinde yükselen kale, kökleri Hitit ve Roma dönemine uzanan, Bizans ve Osmanlı’da güçlendirilmiş tarihî bir savunma yapısıdır. İçindeki Kahramanlık Panorama Müzesi, kentin Kurtuluş Savaşı’ndaki direnişini anlatır.' },
    { name: 'Bakırcılar Çarşısı', desc: 'Gaziantep’in tarihî çarşı bölgesindeki Bakırcılar Çarşısı, ustaların el işçiliğiyle bakır kap kacak dövdüğü, sedef ve baharat kokan canlı bir zanaat merkezidir. Yüzyıllardır süren usta-çırak geleneğini bugüne taşır.' },
    { name: 'Emine Göğüş Mutfak Müzesi', desc: 'Tarihî bir Antep evinde kurulan bu müze, UNESCO’nun “Gastronomi Şehri” ilan ettiği Gaziantep’in zengin mutfak kültürünü sergiler. Baklavadan yuvalamaya, geleneksel araç gereç ve tariflerle kentin lezzet mirasını anlatır.' },
    { name: 'Tarihî Hanlar & Baklava', desc: 'Gaziantep’in eski şehrindeki taş hanlar bölgesi; avlulu kervansarayları, kahvehaneleri ve dünyaca ünlü baklavacılarıyla doludur. Antep fıstığıyla yapılan baklavanın en usta örnekleri bu tarihî sokaklarda tadılır.' },
  ],
  // -- Türkiye: yüksek cazibe (5-6 mekan) --
  mugla: [
    { name: 'Bodrum Kalesi & Sualtı Müzesi', desc: '15. yüzyılda Rodos Şövalyeleri tarafından Aziz Petrus adına inşa edilen bu görkemli kale, Halikarnas Mozolesi’nin taşlarıyla güçlendirilmiştir. Bugün içinde barındırdığı Sualtı Arkeoloji Müzesi ile dünyanın en önemli batık ve antik cam koleksiyonlarından birine ev sahipliği yapar.' },
    { name: 'Halikarnas Mozolesi', desc: 'Kral Mausolos için MÖ 4. yüzyılda yaptırılan ve “mozole” kelimesine adını veren bu anıtsal mezar, antik dünyanın yedi harikasından biriydi. Depremlerle yıkılan yapıdan bugüne yalnızca temelleri ve birkaç heykel parçası kalsa da ihtişamı efsaneleşmiştir.' },
    { name: 'Ölüdeniz & Babadağ', desc: 'Turkuaz sularıyla dünyanın en çok fotoğraflanan plajlarından biri olan Ölüdeniz, rüzgârdan korunan sakin lagünüyle ünlüdür. Üzerinde yükselen 1.960 metrelik Babadağ ise dünyanın en iyi yamaç paraşütü kalkış noktalarından biri olarak kabul edilir.' },
    { name: 'Dalyan & Kaunos', desc: 'Dalyan Deltası, nehrin kıvrımları boyunca uzanan sazlıkları, kaplumbağalarıyla ünlü İztuzu Plajı ve şifalı çamur banyolarıyla tanınır. Kayalıklara oyulmuş görkemli Likya kaya mezarları ve antik Kaunos kenti, bölgenin binlerce yıllık geçmişine tanıklık eder.' },
    { name: 'Saklıkent Kanyonu', desc: 'Toros Dağları’nı yaran bu 18 kilometrelik kanyon, Türkiye’nin en derin ve en görkemli kanyonlarından biridir. Yaz aylarında bile buz gibi akan berrak suyunda yapılan yürüyüş, yüksek kaya duvarları arasında serinletici bir doğa macerası sunar.' },
    { name: 'Marmaris & Datça', desc: 'Çam ormanlarıyla kaplı koyları ve hareketli marinasıyla Marmaris, mavi yolculukların önemli bir başlangıç noktasıdır. Ege ile Akdeniz’in buluştuğu Datça Yarımadası ise sakin köyleri, badem bahçeleri ve ucundaki antik Knidos kentiyle huzurlu bir kaçış sunar.' },
  ],
  aydin: [
    { name: 'Afrodisias (UNESCO)', desc: 'Aşk tanrıçası Afrodit’e adanan bu antik kent, olağanüstü korunmuş 30.000 kişilik stadyumu ve seçkin heykeltıraşlık okuluyla ün kazanmıştır. Mermer ocaklarına yakınlığı sayesinde kentin ustaları tüm Roma dünyasına eserler vermiş, bugün UNESCO Dünya Mirası listesinde yer almıştır.' },
    { name: 'Didyma Apollon Tapınağı', desc: 'Antik çağın en büyük tapınaklarından biri olan bu görkemli yapı, kâhinlik merkezi olarak ünlü Apollon Bilicilik Ocağı’na ev sahipliği yapıyordu. 120’den fazla devasa sütunuyla tasarlanan tapınak, hiç tamamlanamasa da ayakta kalan sütunlarıyla nefes kesici bir ihtişam sunar.' },
    { name: 'Priene & Milet', desc: 'Priene, Hippodamos’un ızgara planıyla kurulmuş, Athena Tapınağı’yla taçlanan zarif bir dağ eteği kentidir. Bir zamanlar önemli bir liman olan Milet ise 15.000 kişilik dev tiyatrosu ve bilim insanı Thales’in memleketi olarak antik dünyanın parlak merkezlerindendi.' },
    { name: 'Kuşadası & Güvercinada', desc: 'Ege’nin hareketli bir tatil ve kruvaziyer limanı olan Kuşadası, adını kıyısındaki güvercinlerle dolu adadan alır. Bir dar yolla karaya bağlanan Güvercinada, üzerindeki Osmanlı dönemi kalesi ve deniz manzarasıyla kentin simgesidir.' },
    { name: 'Nysa Antik Kenti', desc: 'Sultanhisar yakınlarındaki bu antik kent, coğrafyacı Strabon’un da eğitim gördüğü bir bilim ve kültür merkeziydi. Bir vadinin iki yakasını birleştiren anıtsal köprüsü, iyi korunmuş tiyatrosu ve kütüphanesiyle Meander Vadisi’nin en etkileyici kalıntılarındandır.' },
  ],
  nevsehir: [
    { name: 'Göreme Açık Hava Müzesi (UNESCO)', desc: 'Kapadokya’nın kalbindeki Göreme Açık Hava Müzesi, tüf kayalara oyulmuş onlarca Bizans dönemi kilise, şapel ve manastırdan oluşan bir keşiş yerleşimidir. Karanlık Kilise gibi yapılardaki canlı freskler, 10.–12. yüzyıl Ortodoks sanatının en iyi korunmuş örneklerindendir (UNESCO).' },
    { name: 'Sıcak Hava Balonu', desc: 'Kapadokya’nın simge deneyimi olan sıcak hava balonu turu, gün doğumunda yüzlerce balonla birlikte peribacalarının ve vadilerin üzerinde süzülmeyi sağlar. Pembe-turuncu şafak ışığında bölgenin gerçeküstü peyzajını kuşbakışı sunan, dünyaca ünlü bir aktivitedir.' },
    { name: 'Derinkuyu & Kaymaklı Yeraltı Şehri', desc: 'Yumuşak tüfe oyulmuş bu yeraltı şehirleri, katlar boyunca aşağı inen tünelleri, havalandırma bacaları ve yuvarlak taş kapılarıyla binlerce kişiyi barındırabiliyordu. Erken Hristiyanların baskı dönemlerinde saklandığı bu labirentler, antik mühendisliğin şaşırtıcı örnekleridir.' },
    { name: 'Uçhisar Kalesi', desc: 'Kapadokya’nın en yüksek noktasındaki Uçhisar Kalesi, içi odalar ve tünellerle delik deşik edilmiş devasa bir kaya kütlesidir. Zirvesinden tüm bölgenin peribacaları, vadileri ve uzaktaki Erciyes Dağı’na uzanan eşsiz bir panorama izlenir.' },
    { name: 'Paşabağ & Zelve', desc: 'Paşabağ, üç başlı “mantar” biçimli peribacalarıyla Kapadokya’nın en fotojenik vadilerinden biridir ve adını buraya çekilen keşişlerden alır. Yakınındaki Zelve ise 20. yüzyıla dek yaşanan, kayalara oyulmuş evleri ve kiliseleriyle terk edilmiş bir vadi yerleşimidir.' },
    { name: 'Avanos', desc: 'Kızılırmak kıyısındaki Avanos, nehrin kızıl kilinden çömlek yapımının Hititlerden beri sürdüğü tarihî bir çömlekçilik kentidir. Ayaklı çarkta çömlek yapımını izlemek ve denemek, kasabanın en sevilen deneyimidir.' },
  ],
  denizli: [
    { name: 'Pamukkale Travertenleri (UNESCO)', desc: 'Denizli’deki Pamukkale, kalsiyum yüklü termal suların yamaçta binlerce yılda oluşturduğu bembeyaz basamaklı travertenleriyle dünyanın en olağanüstü doğa harikalarından biridir. “Pamuk kalesi” anlamına gelen bu ışıltılı teraslar, üzerindeki antik kentle birlikte UNESCO Dünya Mirası’dır.' },
    { name: 'Hierapolis Antik Kenti', desc: 'Travertenlerin hemen üstünde kurulan Hierapolis, MÖ 2. yüzyıldan kalma bir Roma sağlık ve kaplıca kentidir. Devasa antik tiyatrosu, sütunlu caddesi ve Anadolu’nun en büyük antik nekropollerinden biriyle şifa arayanların yüzyıllarca aktığı bir merkezdi.' },
    { name: 'Kleopatra Antik Havuzu', desc: 'Hierapolis içindeki bu termal havuz, bir depremle suya devrilmiş antik mermer sütunların arasında yüzme imkânı sunmasıyla ünlüdür. Efsaneye göre Kleopatra’ya armağan edilen mineralli sıcak suları, antik çağdan beri şifalı sayılır.' },
    { name: 'Laodikeia Antik Kenti', desc: 'Denizli yakınındaki Laodikeia, zenginliğiyle ünlü büyük bir Roma kentiydi ve İncil’de adı geçen “Yedi Kilise”den birine ev sahipliği yaptı. Geniş caddeleri, tiyatroları, tapınakları ve erken kilise kalıntılarıyla süregelen kazılarla giderek gün ışığına çıkıyor.' },
    { name: 'Kaklık Mağarası', desc: 'Yeraltındaki termal suların oluşturduğu beyaz travertenleri nedeniyle “Yeraltı Pamukkalesi” olarak anılan Kaklık Mağarası, sarkıt, dikit ve minik havuzlarıyla büyüleyici bir doğa oluşumudur. Kükürtlü suları cilt hastalıklarına iyi geldiği inancıyla ziyaret edilir.' },
  ],
  sanliurfa: [
    { name: 'Göbeklitepe (UNESCO)', desc: 'Şanlıurfa yakınındaki Göbeklitepe, yaklaşık 12 bin yıl önce avcı-toplayıcılar tarafından dikilen T biçimli anıtsal taş sütunlarıyla insanlık tarihinin bilinen en eski tapınağıdır. Tarım ve yerleşik hayattan önce inşa edilmesi, uygarlık tarihini kökten değiştirmiş ve alanı UNESCO Dünya Mirası yapmıştır.' },
    { name: 'Balıklıgöl', desc: 'Hz. İbrahim’in Nemrut tarafından ateşe atıldığı, ateşin suya ve odunların kutsal balıklara dönüştüğüne inanılan Balıklıgöl, Şanlıurfa’nın en kutsal ve huzurlu köşesidir. Çevresindeki camiler, avlular ve gül bahçeleriyle önemli bir inanç ve dinlence merkezidir.' },
    { name: 'Şanlıurfa Kalesi', desc: 'Balıklıgöl’e tepeden bakan Şanlıurfa Kalesi, kökleri antik çağa uzanan, üzerindeki iki dev Roma sütunuyla (“Nemrut’un Tahtı”) simgeleşmiş bir savunma yapısıdır. Surlarından kentin, gölün ve tarihî çarşıların panoraması izlenir.' },
    { name: 'Harran', desc: 'Şanlıurfa’nın güneyindeki Harran, dünyanın en eski yerleşim ve bilim merkezlerinden biridir ve İslam’ın ilk üniversitelerinden birine ev sahipliği yapmıştır. Sıcağa karşı serin tutan konik “külah” biçimli kerpiç evleri ve antik kalıntılarıyla eşsiz bir dokuya sahiptir.' },
    { name: 'Haleplibahçe Mozaik Müzesi', desc: 'Şanlıurfa’daki Haleplibahçe Mozaik Müzesi, üzerine inşa edildiği Roma dönemi villalarının olağanüstü zemin mozaiklerini korur. Dünyada başka örneği bulunmayan, Amazon kraliçelerini tasvir eden av sahneli mozaikleriyle ünlüdür.' },
    { name: 'Karahantepe', desc: 'Göbeklitepe’nin çağdaşı olan Karahantepe, benzer T biçimli dikili taşları ve kayaya oyulmuş insan figürleriyle bölgedeki “Taş Tepeler” neolitik ağının önemli bir halkasıdır. Süregelen kazılarla, insanlığın ilk inanç dünyasına yeni ışık tutuyor.' },
  ],
  mardin: [
    { name: 'Eski Mardin & Taş Evler', desc: 'Mezopotamya ovasına bakan yamaca basamak basamak kurulu Eski Mardin, işlemeli bal rengi kalker taşından evleri, avluları ve dar geçitleriyle bir açık hava müzesidir. Farklı din ve dillerin yüzyıllarca bir arada yaşadığı çok kültürlü dokusu sokaklara sinmiştir.' },
    { name: 'Deyrulzafaran Manastırı', desc: 'Mardin yakınındaki Deyrulzafaran (“Safran Manastırı”), 1600 yılı aşkın geçmişiyle Süryani Ortodoks Kilisesi’nin uzun süre patriklik merkezi olmuş kutsal bir yapıdır. Taş işçiliği ve güneş tapınağına dayanan temelleriyle bölgenin köklü Hristiyan mirasını yaşatır.' },
    { name: 'Kasımiye Medresesi', desc: '15. yüzyılda tamamlanan Kasımiye Medresesi; zarif taç kapısı, kubbeleri ve avlusundaki, hayatın akışını simgeleyen havuzuyla Artuklu-Akkoyunlu mimarisinin bir başyapıtıdır. Ovaya bakan terasıyla Mardin’in en görkemli tarihî yapılarından biridir.' },
    { name: 'Zinciriye Medresesi', desc: '1385’te Artuklu hükümdarı tarafından yaptırılan Zinciriye (Sultan İsa) Medresesi, anıtsal taç kapısı ve ikiz kubbeleriyle dikkat çeker. Teraslarından Mardin’in taş evlerinin ve uçsuz bucaksız Mezopotamya ovasının en güzel panoraması izlenir.' },
    { name: 'Dara Antik Kenti', desc: 'Mardin yakınındaki Dara, Bizans’ın Sasanilere karşı bir sınır kalesi olarak kurduğu görkemli bir antik kenttir. Kayaya oyulmuş devasa su sarnıçları, nekropolü ve kemerli yapılarıyla “Mezopotamya’nın Efes’i” olarak anılır.' },
    { name: 'Midyat', desc: 'Mardin’in doğusundaki Midyat, işlemeli taş konakları ve dünyaca ünlü telkâri (gümüş tel) işçiliğiyle tanınan çok kültürlü bir kasabadır. Süryani manastırları, kiliseleri ve tarihî çarşısıyla bölgenin geleneklerini yaşatır.' },
  ],
  diyarbakir: [
    { name: 'Diyarbakır Surları (UNESCO)', desc: 'Kara bazalt taşından örülü Diyarbakır Surları, yaklaşık 5,5 kilometrelik uzunluğuyla Çin Seddi’nden sonra dünyanın en uzun ikinci sur sistemidir. Roma’dan Osmanlı’ya birçok uygarlığın kitabe ve kabartma bıraktığı surlar, Hevsel Bahçeleri’yle birlikte UNESCO Dünya Mirası’dır.' },
    { name: 'Hevsel Bahçeleri', desc: 'Dicle Nehri ile surlar arasında uzanan Hevsel Bahçeleri, binlerce yıldır kenti besleyen verimli bostan ve bahçelerden oluşur. Zengin kuş yaşamı ve tarım geleneğiyle, surlarla birlikte UNESCO korumasındaki canlı bir kültürel peyzajdır.' },
    { name: 'Ulu Camii', desc: 'Diyarbakır Ulu Camii, Anadolu’nun en eski camilerinden biridir ve Emevi mimarisinin izlerini taşıyan avlusuyla dikkat çeker. Farklı dönemlerden devşirme sütunları ve taş işçiliğiyle kentin çok katmanlı tarihini yansıtır.' },
    { name: 'On Gözlü Köprü', desc: 'Dicle Nehri üzerindeki On Gözlü Köprü, 1065’te inşa edilen, siyah bazalt kemerleriyle zarif bir ortaçağ köprüsüdür. Üzerindeki kitabesi ve nehir kıyısı manzarasıyla kentin en sevilen tarihî yapılarından biridir.' },
    { name: 'Hasan Paşa Hanı', desc: '16. yüzyıl sonunda yapılan Hasan Paşa Hanı, siyah bazalt ve beyaz taşın alacalı desenler oluşturduğu tarihî bir kervansaraydır. Ulu Cami’nin tam karşısındaki avlusu, bugün kahvaltı ve çay içilen canlı bir buluşma noktasıdır.' },
    { name: 'Meryem Ana Süryani Kilisesi', desc: 'Kökleri 3. yüzyıla uzanan Meryem Ana Kilisesi, Diyarbakır’ın Süryani Ortodoks cemaatinin yüzyıllardır ibadet ettiği tarihî bir mabettir. Taş işçiliği ve avlusuyla kentin köklü Hristiyan mirasını bugüne taşır.' },
  ],
  van: [
    { name: 'Akdamar Kilisesi', desc: 'Van Gölü’ndeki Akdamar Adası’nda yükselen bu 10. yüzyıl Ermeni kilisesi, dış duvarlarını kaplayan İncil ve Tevrat sahneli taş kabartmalarıyla ortaçağ sanatının bir başyapıtıdır. Göl ortasındaki konumu ve manzarasıyla büyüleyici bir açık hava anıtıdır.' },
    { name: 'Van Kalesi (Tuşpa)', desc: 'Van Gölü kıyısında uzun bir kaya kütlesi üzerine kurulu Van Kalesi, MÖ 9. yüzyılda Urartu Krallığı’nın başkenti Tuşpa’ya aittir. Kaya mezarları, çivi yazılı kitabeleri ve göle bakan manzarasıyla üç bin yıllık bir geçmişi barındırır.' },
    { name: 'Van Gölü & Van Kedisi', desc: 'Türkiye’nin en büyük gölü olan sodalı Van Gölü, çevresindeki dağlar ve adalarıyla eşsiz bir iç deniz manzarası sunar. Yöreye özgü, biri mavi biri kehribar renkte gözleriyle ünlü beyaz Van kedisi de bölgenin simgesidir.' },
    { name: 'Muradiye Şelalesi', desc: 'Van’ın kuzeyindeki Muradiye Şelalesi, üzerine kurulu asma köprüsü ve çevresindeki yeşilliğiyle bölgenin en fotojenik doğa noktalarından biridir. Eriyen karların beslediği gür suları, özellikle ilkbaharda görkemlidir.' },
    { name: 'Çavuştepe & Hoşap Kalesi', desc: 'Van yakınındaki Çavuştepe, Urartu kralı II. Sarduri’nin saray ve tapınak kalıntılarını barındırır; hemen ötesindeki Hoşap Kalesi ise sarp bir kayaya kurulu, süslü kapısıyla masalsı bir 17. yüzyıl kalesidir. İkisi birlikte bölgenin katmanlı tarihini sergiler.' },
  ],
  kars: [
    { name: 'Ani Harabeleri (UNESCO)', desc: 'Ermenistan sınırındaki Ani, ortaçağda “1001 Kilise Kenti” olarak anılan, bir zamanlar İstanbul ve Bağdat’la yarışan görkemli bir başkenttir. Bozkırın ortasında yükselen katedrali, kiliseleri ve surlarıyla bu terk edilmiş kent, UNESCO Dünya Mirası Listesi’ndedir.' },
    { name: 'Kars Kalesi', desc: 'Kente tepeden bakan Kars Kalesi, kökleri Selçuklu ve Saltuklu dönemine uzanan, yüzyıllar boyunca elden ele geçmiş stratejik bir savunma yapısıdır. Eteğindeki tarihî Taş Köprü ve hamamlarla birlikte kentin en eski dokusunu oluşturur.' },
    { name: 'Baltık Mimarili Taş Evler', desc: 'Kars’ın 1878–1918 arasındaki Rus yönetimi döneminden kalma bal rengi taş binaları, geniş ızgara planlı caddeleri ve Baltık esintili cepheleriyle kente Avrupai bir görünüm kazandırır. Bu özgün doku, Kars’ı Anadolu’nun diğer kentlerinden ayırır.' },
    { name: 'Çıldır Gölü', desc: 'Kars ve Ardahan sınırındaki yüksek Çıldır Gölü, kışın tümüyle buz tutmasıyla ünlüdür; üzerinde atlı kızak turları ve Eskimo usulü buzda balık avı yapılır. Yaz aylarında ise çevresindeki yaylalarla huzurlu bir doğa durağıdır.' },
    { name: 'Sarıkamış', desc: 'Kars’ın sarıçam ormanlarıyla kaplı yüksek platosundaki Sarıkamış, toz karı ve kristal kar taneleriyle ünlü bir kayak merkezidir. Aynı zamanda I. Dünya Savaşı’nda yaşanan trajik Sarıkamış Harekâtı’nın anıldığı anlamlı bir yerdir.' },
  ],
  karabuk: [
    { name: 'Safranbolu Evleri (UNESCO)', desc: '18.–19. yüzyıllarda ipek yolu ticaretiyle zenginleşen Safranbolu, kusursuz korunmuş cumbalı ahşap Osmanlı konaklarıyla bir açık hava müzesi gibidir. Geleneksel Türk kent dokusunun en iyi örneği olarak tümüyle UNESCO Dünya Mirası listesindedir.' },
    { name: 'Cinci Han & Hamamı', desc: '17. yüzyılda kervanların konakladığı bu görkemli kervansaray, İpek Yolu ticaretinin canlılığına tanıklık etmiştir ve bugün butik otel olarak hizmet verir. Yanındaki tarihî Cinci Hamamı, dört asırdır aralıksız işleyen zarif bir Osmanlı hamamıdır.' },
    { name: 'Eski Çarşı & Yemeniciler Arastası', desc: 'Safranbolu’nun kalbindeki bu tarihî çarşı, yüzyıllardır bakırcılık, yemenicilik ve demircilik gibi geleneksel zanaatların sürdürüldüğü bir merkezdir. Safran katkılı lokumları ve el yapımı hediyelik dükkânlarıyla kentin canlı ticaret ruhunu yaşatır.' },
    { name: 'Hıdırlık Tepesi', desc: 'Safranbolu’nun kırmızı kiremitli çatılarını ve tarihî dokusunu kuşbakışı izlemek için en gözde noktadır. Özellikle gün batımında konakların üzerine düşen ışıkla, ziyaretçilere kartpostallık bir panorama sunar.' },
    { name: 'Bulak (Mencilis) Mağarası', desc: 'Yaklaşık 6 kilometre uzunluğundaki bu devasa mağara, içindeki yeraltı gölü, akarsuları ve göz alıcı sarkıt-dikit oluşumlarıyla büyüler. Gezilebilen bölümü, milyonlarca yılda şekillenen etkileyici bir yeraltı dünyasını gözler önüne serer.' },
    { name: 'Yörük Köyü', desc: 'Safranbolu yakınlarındaki bu köy, adını buraya yerleşen konar-göçer Yörüklerden alır ve zamanda donmuş gibi korunmuş taş-ahşap konaklarıyla dikkat çeker. Ortak çamaşırhanesi ve otantik köy dokusuyla geleneksel Anadolu yaşamını yansıtır.' },
  ],
  hatay: [
    { name: 'Hatay Arkeoloji Müzesi', desc: 'Antakya’daki Hatay Arkeoloji Müzesi, çevredeki antik villalardan çıkarılan olağanüstü Roma dönemi zemin mozaikleriyle dünyanın en zengin mozaik koleksiyonlarından birine sahiptir. Mitolojik sahneleri canlı renklerle işleyen bu mozaikler, antik Antiokheia’nın ihtişamını yansıtır.' },
    { name: 'St. Pierre Kilisesi', desc: 'Antakya’da bir dağ yamacındaki mağaraya oyulmuş St. Pierre (Aziz Petrus) Kilisesi, Hristiyanların ilk gizli ibadet yerlerinden biri kabul edilir. “Hristiyan” kelimesinin ilk kez burada kullanıldığına inanılması, onu inanç tarihi için kutsal kılar.' },
    { name: 'Uzun Çarşı', desc: 'Antakya’nın kalbindeki Uzun Çarşı; baharat, künefe, sabun ve el işi dükkânlarıyla asırlardır süren çok kültürlü bir ticaret geleneğini yaşatır. Dar sokakları ve hanlarıyla kentin en canlı, en kokulu köşesidir.' },
    { name: 'Habib-i Neccar Camii', desc: 'Antakya’daki Habib-i Neccar Camii, Anadolu’nun ilk camilerinden biri kabul edilir ve bir mabet temeli üzerine kurulmuştur. Farklı inançların izlerini bir arada taşıyan yapı, kentin binlerce yıllık hoşgörü geleneğini simgeler.' },
    { name: 'Titus Tüneli & Samandağ', desc: 'Samandağ’daki Titus Tüneli, antik liman kentini sel sularından korumak için Romalıların kayaya elle oyduğu, yüzlerce metre uzunluğunda görkemli bir su tünelidir. Yanı başındaki Beşikli Mağara kaya mezarları ve sahiliyle etkileyici bir doğa-tarih durağıdır.' },
    { name: 'Harbiye Şelaleleri', desc: 'Antakya yakınındaki Harbiye (antik Daphne), defne ağaçlarıyla gölgelenen serin çağlayanları ve yeşil vadisiyle Apollon ile Daphne mitine ev sahipliği yapar. Antik çağdan beri bir dinlence yeri olan bölge, defne sabunuyla da ünlüdür.' },
  ],
  kayseri: [
    { name: 'Erciyes Dağı', desc: 'İç Anadolu’nun 3.917 metrelik bu görkemli sönmüş volkanı, milyonlarca yıl önceki patlamalarıyla Kapadokya’nın peri bacalarını oluşturan tüf tabakalarını meydana getirmiştir. Bugün modern tesisleriyle Türkiye’nin en gelişmiş kayak merkezlerinden birine ev sahipliği yapar.' },
    { name: 'Kayseri Kalesi', desc: 'Roma döneminde temelleri atılan, Selçuklular ve Osmanlılar tarafından siyah volkanik taşlarla güçlendirilen bu heybetli kale, kent merkezinin tam ortasında yükselir. Yüzyıllar boyu şehri koruyan surları, bugün geleneksel bir çarşıyı içinde barındırır.' },
    { name: 'Gevher Nesibe Tıp Müzesi', desc: '13. yüzyılda Selçuklu Sultanı I. Gıyaseddin Keyhüsrev’in kız kardeşi Gevher Nesibe adına yaptırılan bu şifahane, dünyanın ilk tıp okulu ve hastane komplekslerinden biridir. Akıl hastalarının müzik ve su sesiyle tedavi edildiği bu yapı, tıp tarihinde çığır açmıştır.' },
    { name: 'Kültepe (Kaniş-Karum)', desc: 'Asurlu tüccarların MÖ 2. binyılda kurduğu bu ticaret kolonisi, Anadolu’nun bilinen en eski yazılı belgeleri olan çivi yazılı kil tabletlerin bulunduğu yerdir. Kaniş Krallığı’nın merkezi olan höyük, Anadolu tarihinin yazıya geçtiği başlangıç noktasıdır.' },
    { name: 'Sultan Sazlığı', desc: 'Tatlı ve tuzlu su gölleriyle sazlıkların iç içe geçtiği bu benzersiz ekosistem, flamingolar başta olmak üzere üç yüzden fazla kuş türüne ev sahipliği yapan uluslararası öneme sahip bir kuş cennetidir. Göç yolları üzerindeki konumu onu bir doğa hazinesi kılar.' },
    { name: 'Ağırnas & Talas', desc: 'Büyük mimar Mimar Sinan’ın doğduğu Ağırnas köyü, yer altına oyulmuş antik geçitleri ve taş evleriyle özgün bir dokuya sahiptir. Yakınındaki Talas ise Rum ve Ermeni mimarisinin izlerini taşıyan zarif tarihî taş konaklarıyla tanınır.' },
  ],
  eskisehir: [
    { name: 'Odunpazarı Evleri', desc: 'Eskişehir’in en eski yerleşim bölgesi olan Odunpazarı, cumbalı ve rengârenk boyanmış geleneksel Osmanlı evlerinin restore edildiği masalsı sokaklardan oluşur. UNESCO’ya aday bu tarihî doku, lületaşı atölyeleri ve butik müzeleriyle canlı bir kültür merkezine dönüşmüştür.' },
    { name: 'Porsuk Çayı & Gondol', desc: 'Kenti boydan boya geçen Porsuk Çayı, kıyı kafeleri ve üzerindeki zarif köprülerle Eskişehir’e Venedik havası katar. Su üzerinde şarkılar eşliğinde yapılan gondol turları, şehrin en romantik ve simgesel deneyimlerinden biridir.' },
    { name: 'Sazova (Masal) Parkı', desc: 'Ortasında yükselen görkemli bir masal şatosu, korsan gemisi ve gölüyle Sazova Parkı, çocukların ve ailelerin gözdesidir. Bilim, sanat ve kültür merkezlerini de barındıran bu geniş yeşil alan, kentin en sevilen dinlenme mekânıdır.' },
    { name: 'Balmumu Heykeller Müzesi', desc: 'Eski belediye başkanı Yılmaz Büyükerşen’in ustalıkla yaptığı balmumu heykellerden oluşan bu müze, Türkiye’nin en kapsamlı örneğidir. Tarihî kişiliklerin ve ünlülerin gerçekçi figürleri, kentin gelişen modern cam ve heykel sanatının bir yansımasıdır.' },
    { name: 'Frigya (Yazılıkaya-Midas)', desc: 'Efsanevi Kral Midas’ın halkı Friglerin MÖ 1. binyılda yaşadığı bu bölge, kayalara oyulmuş anıtsal tapınak cepheleri ve yazıtlarıyla ünlüdür. Peri bacalarını andıran vadileri ve gizemli kaya anıtlarıyla “Frigya Vadisi” eşsiz bir açık hava müzesidir.' },
  ],
  rize: [
    { name: 'Ayder Yaylası', desc: 'Kaçkar Dağları’nın eteklerinde, sık ormanlar ve şelalelerle çevrili bu ünlü yayla, sisli atmosferi ve şifalı kaplıcalarıyla Doğu Karadeniz’in gözde tatil merkezidir. Geleneksel ahşap evleri ve yeşil çayırlarıyla adeta bir masal diyarını andırır.' },
    { name: 'Zil Kale', desc: 'Fırtına Vadisi’nin derinliklerinde, sarp bir kayalığın üzerinde yükselen bu ortaçağ kalesi, vadiden geçen tarihî ticaret yollarını denetlemek için inşa edilmiştir. Ormanların ortasındaki gizemli konumu ve panoramik manzarasıyla bölgenin en etkileyici yapılarındandır.' },
    { name: 'Fırtına Vadisi & Kemer Köprüler', desc: 'Kaçkarların karlı zirvelerinden doğan Fırtına Deresi boyunca uzanan bu vadi, yeşilin her tonunu barındıran doğasıyla büyüler. Dere üzerinde yüzyıllardır ayakta duran zarif taş kemer köprüler, bölgenin usta taş işçiliğinin izlerini taşır.' },
    { name: 'Çay Bahçeleri', desc: 'Rize’nin bol yağış alan yamaçlarını basamak basamak kaplayan çay bahçeleri, Türkiye’nin çay üretiminin kalbini oluşturur. 1940’lardan beri süren çay tarımı, bölgenin hem ekonomisini hem de kültürünü şekillendiren yemyeşil bir manzara sunar.' },
    { name: 'Pokut & Sal Yaylaları', desc: 'Kaçkar Dağları’nın yüksek platolarında yer alan bu komşu yaylalar, geleneksel ahşap serander evleri ve nefes kesen bulut denizi manzaralarıyla ünlüdür. Gün doğumunda ayakların altında dalgalanan bulutlar, buranın en unutulmaz deneyimidir.' },
  ],
  mersin: [
    { name: 'Kızkalesi', desc: 'Kıyıdan birkaç yüz metre açıkta küçük bir adacığın üzerinde yükselen bu ortaçağ deniz kalesi, hakkında anlatılan trajik prenses efsanesiyle ünlüdür. Ermeni Krallığı döneminden kalan yapı, berrak sularla çevrili büyüleyici görünümüyle bölgenin simgesidir.' },
    { name: 'Cennet-Cehennem Obrukları', desc: 'Toros Dağları’nın kireçtaşının çökmesiyle oluşan bu dev doğal çukurlar, antik çağdan beri kutsal sayılmıştır. “Cennet” obruğunun dibindeki 5. yüzyıl Meryem Ana Kilisesi ve efsanelere konu olan derin “Cehennem” obruğu, mitoloji ve doğanın buluştuğu bir yerdir.' },
    { name: 'Tarsus', desc: 'Binlerce yıllık geçmişiyle Aziz Paulus’un doğduğu kent olan Tarsus, Hristiyanlık tarihinde büyük öneme sahiptir. Kleopatra ile Antonius’un buluştuğu söylenen Kleopatra Kapısı, tarihî Şelale ve şifalı olduğuna inanılan St. Paul Kuyusu kentin başlıca hazineleridir.' },
    { name: 'Kanlıdivane', desc: 'Derin bir obruk çukurun kenarına kurulan bu antik kent, çevresindeki kayalara oyulmuş Roma dönemi insan kabartmaları ve anıt mezarlarıyla dikkat çeker. Bizans dönemi kiliseleri ve gizemli atmosferiyle bölgenin en etkileyici arkeolojik alanlarındandır.' },
    { name: 'Soli Pompeiopolis', desc: 'Antik bir liman kenti olan Soli, adını dilbilgisi hatası anlamındaki “solecism” kelimesine vermiştir. Roma general Pompeius tarafından yeniden kurulan kentin deniz kıyısına uzanan görkemli sütunlu caddesi, bugün ayakta kalan sütunlarıyla eski ihtişamını yansıtır.' },
    { name: 'Alahan Manastırı', desc: 'Toros Dağları’nın yamacında, vadiye tepeden bakan bu 5. yüzyıl erken Bizans manastırı, incelikli taş işçiliğiyle ünlüdür. İyi korunmuş kiliseleri ve kabartmalarıyla erken Hristiyan mimarisinin Anadolu’daki en değerli örneklerinden biridir.' },
  ],
  adiyaman: [
    { name: 'Nemrut Dağı (UNESCO)', desc: 'MÖ 1. yüzyılda Kommagene Kralı I. Antiochos’un 2.150 metre zirvede yaptırdığı bu anıtsal mezar-tapınak, devasa tanrı ve kral heykelleriyle dünyanın en çarpıcı arkeolojik alanlarından biridir. Gün doğumu ve batımında başların üzerine düşen ışık, unutulmaz bir manzara sunar.' },
    { name: 'Cendere Köprüsü', desc: 'Romalıların MS 2. yüzyılda İmparator Septimius Severus onuruna inşa ettiği bu görkemli kemerli köprü, dünyanın ayakta duran en eski ve en büyük tek kemerli Roma köprülerindendir. Cendere Çayı üzerinde on sekiz asırdır dimdik ayakta durur.' },
    { name: 'Karakuş Tümülüsü', desc: 'Kommagene kraliyet ailesinin kadınlarına adanan bu anıt mezar, tepesindeki sütunların üstünde yer alan kartal, aslan ve boğa heykelleriyle tanınır. Adını sütunlardan birinin üzerindeki kartal (karakuş) figüründen alan tümülüs, hanedanın ihtişamını yansıtır.' },
    { name: 'Arsameia Antik Kenti', desc: 'Kommagene Krallığı’nın yazlık başkenti olan Arsameia, Kral Mithridates ile Herakles’in el sıkıştığı ünlü kaya kabartmasıyla ünlüdür. Kayalara oyulmuş gizemli tüneli ve uzun Grekçe yazıtıyla dönemin en önemli merkezlerinden biriydi.' },
    { name: 'Perre Antik Kenti', desc: 'Kommagene Krallığı’nın en büyük dört şehrinden biri olan Perre, bir zamanlar önemli bir konaklama ve su merkeziydi. Kayalara oyulmuş yüzlerce anıtsal mezardan oluşan geniş nekropolü, bölgenin köklü tarihine ışık tutar.' },
  ],
  bolu: [
    { name: 'Abant Gölü', desc: 'Bir heyelan sonucu oluşan bu göl, etrafını saran köknar ve çam ormanları, sisli atmosferi ve fayton turlarıyla mevsimin her halinde büyüleyici bir tablo sunar. İstanbul ve Ankara’ya yakınlığıyla doğaseverlerin en sevdiği kaçış noktalarındandır.' },
    { name: 'Yedigöller Milli Parkı', desc: 'Heyelanların dere önünü kapatmasıyla oluşan yedi ayrı gölden meydana gelen bu milli park, özellikle sonbaharda kızıla ve sarıya boyanan ormanlarıyla ünlüdür. Berrak gölleri ve yaban hayatıyla Türkiye’nin en etkileyici doğa harikalarındandır.' },
    { name: 'Kartalkaya', desc: 'Köroğlu Dağları üzerinde yer alan bu kayak merkezi, kuru ve tozlu kar kalitesiyle Türkiye’nin en gözde kış sporları merkezlerinden biridir. Sık ormanlar içindeki pistleri ve konforlu tesisleriyle her seviyeden kayakçıya hitap eder.' },
    { name: 'Gölcük Tabiat Parkı', desc: 'Bolu merkezine yakın bu küçük krater gölü, çevresindeki ihtişamlı ladin ormanlarını sularına yansıtan dingin atmosferiyle tanınır. Göl çevresindeki ahşap yürüyüş yolları, huzurlu bir doğa yürüyüşü için idealdir.' },
    { name: 'Mudurnu', desc: 'Köklü Ahilik esnaf geleneğini yüzyıllardır sürdüren bu tarihî kasaba, cumbalı ahşap konakları ve dar sokaklarıyla adeta bir zaman kapsülüdür. Osmanlı dönemi çarşısı ve tarihî hamamıyla geleneksel Anadolu dokusunu günümüze taşır.' },
  ],
  amasya: [
    { name: 'Kral Kaya Mezarları', desc: 'Yeşilırmak’a tepeden bakan sarp kayalara oyulmuş bu anıtsal mezarlar, MÖ 3.–1. yüzyıllarda hüküm süren Pontus krallarına aittir. Geceleri ışıklandırılan bu görkemli mezarlar, Amasya’nın antik başkent kimliğinin en çarpıcı simgesidir.' },
    { name: 'Yalıboyu Evleri', desc: 'Yeşilırmak’ın kıyısı boyunca sıralanan bu cumbalı ahşap Osmanlı konakları, sularına yansıyan görüntüleriyle Amasya’nın en tanınan manzarasını oluşturur. Restore edilen 19. yüzyıl evleri bugün butik otel ve kafe olarak kentin ruhunu yaşatır.' },
    { name: 'Amasya (Harşena) Kalesi', desc: 'Şehrin üzerinde yükselen Harşena Dağı’na kurulu bu kale, Pontus Krallığı’ndan Osmanlı’ya uzanan katmanlı bir tarihe sahiptir. İçindeki kayaya oyulmuş gizli su yolu (cellat suyu) ve zirveden şehre bakan panoramasıyla etkileyicidir.' },
    { name: 'Ferhat ile Şirin Su Kanalı', desc: 'Amasya’nın ölümsüz aşk efsanesine konu olan bu kanal, rivayete göre Ferhat’ın sevdiği Şirin’e kavuşmak için dağları delerek açtığı su yoludur. Kayalara oyulmuş bu antik su kanalı, hem mühendislik hem de folklor açısından değerlidir.' },
    { name: 'II. Bayezid Külliyesi', desc: 'Yeşilırmak kıyısında 1486’da tamamlanan bu zarif külliye, cami, medrese, imaret ve kütüphanesiyle Amasya’nın en büyük Osmanlı yapı topluluğudur. İki minareli simetrik camisi ve nehir kenarındaki huzurlu konumuyla kentin manevi merkezidir.' },
  ],
  sivas: [
    { name: 'Divriği Ulu Camii (UNESCO)', desc: '1229’da inşa edilen bu cami ve bitişiğindeki şifahane, adeta taşa işlenmiş dantel gibi görünen olağanüstü barok taç kapılarıyla dünyaca ünlüdür. Anadolu Selçuklu taş işçiliğinin zirvesi kabul edilen yapı, Türkiye’nin en erken UNESCO Dünya Mirası eserlerindendir.' },
    { name: 'Gök Medrese', desc: '1271’de Vezir Sahip Ata tarafından yaptırılan bu medrese, adını mavi çinilerle kaplı çifte minarelerinden alır. Zengin taş kabartmaları ve göz alıcı taç kapısıyla Selçuklu dönemi eğitim yapılarının en zarif örneklerindendir.' },
    { name: 'Çifte Minareli Medrese', desc: '1271 yılına tarihlenen bu medrese, günümüze yalnızca görkemli ön cephesi ve iki tuğla minaresiyle ulaşabilmiştir. Anıtsal taç kapısındaki incelikli geometrik ve bitkisel motifleriyle Sivas’ın Selçuklu meydanının simge yapılarındandır.' },
    { name: 'Kongre Binası (Atatürk Müzesi)', desc: '1919 Sivas Kongresi’nin toplandığı bu tarihî lise binası, Türk Kurtuluş Savaşı’nın örgütlenmesinde belirleyici rol oynamıştır. Kongre salonu ve Atatürk’ün çalışma odasının korunduğu yapı, bugün ulusal tarihe adanmış bir müzedir.' },
    { name: 'Balıklı Kaplıca (Kangal)', desc: 'Kangal ilçesindeki bu benzersiz termal kaynak, sıcak sularında yaşayan “doktor balıkları”yla dünya çapında ün kazanmıştır. Sedef gibi cilt hastalıklarına iyi geldiğine inanılan bu balıklar, ölü deriyi temizleyerek bölgeye şifa arayanları çeker.' },
  ],
  // -- Türkiye: orta cazibe (3-4 mekan) --
  manisa: [
    { name: 'Spil Dağı & Ağlayan Kaya', desc: 'Mitolojide çocuklarını kaybedip taşa dönüşen ve sonsuza dek ağlayan Niobe’nin hikâyesine ev sahipliği yapan bu milli park, endemik bitkileri ve baharda açan yabani laleleriyle ünlüdür. Manisa lalesinin anavatanı sayılan dağ, doğa ve efsaneyi buluşturur.' },
    { name: 'Sardes Antik Kenti', desc: 'Zengin Kral Krezüs’ün başkenti olan Lidya’nın merkezi Sardes, tarihte ilk madeni paranın basıldığı yer olarak medeniyet tarihinde çığır açmıştır. Görkemli Artemis Tapınağı ve antik jimnazyumuyla dönemin en varlıklı kentlerinden biriydi.' },
    { name: 'Sultan Camii & Mesir', desc: '16. yüzyılda Kanuni’nin annesi Hafsa Sultan adına yaptırılan bu külliye, her yıl düzenlenen Mesir Macunu Festivali’ne ev sahipliği yapar. Kırk bir baharatla hazırlanan ve şifa dağıtmak için halka saçılan mesir macunu geleneği, UNESCO listesindedir.' },
    { name: 'Kula Peribacaları (Jeopark)', desc: 'Binlerce yıl önceki volkanik patlamaların şekillendirdiği bu bölge, siyah lav tarlaları nedeniyle antik çağda “Katakekaumene” yani “Yanık Ülke” olarak anılmıştır. Türkiye’nin UNESCO Küresel Jeopark ağındaki ilk üyesi olan alan, peri bacaları ve volkanik konileriyle büyüler.' },
  ],
  balikesir: [
    { name: 'Ayvalık & Cunda Adası', desc: 'Zeytin ağaçlarıyla kaplı Ayvalık, dar arnavut kaldırımlı sokakları ve terk edilmiş Rum kiliselerinden dönüşen taş evleriyle özgün bir Ege kasabasıdır. Bir köprüyle bağlı Cunda Adası ise balık restoranları ve romantik gün batımı manzaralarıyla ünlüdür.' },
    { name: 'Kaz Dağları (Ida)', desc: 'Mitolojide tanrıların Truva Savaşı’nı izlediği ve ilk güzellik yarışmasının yapıldığı efsanevi İda Dağı, dünyanın en yüksek oksijen oranına sahip bölgelerinden biridir. Şelaleleri, endemik bitkileri ve şifalı havasıyla eşsiz bir milli parktır.' },
    { name: 'Sarımsaklı Plajı', desc: 'Ayvalık yakınlarındaki bu uzun ve ince altın kumlu sahil, sığ ve berrak sularıyla Ege’nin en gözde plajlarından biridir. Yaz aylarında hareketli atmosferi ve deniz sporlarıyla tatilcilerin akınına uğrar.' },
    { name: 'Manyas Kuş Cenneti', desc: 'Manyas Gölü kıyısındaki bu milli park, göç yolları üzerindeki konumu sayesinde her yıl yüz binlerce göçmen kuşu ağırlayan uluslararası öneme sahip bir sulak alandır. Pelikanlar, karabataklar ve balıkçıllarıyla kuş gözlemcilerinin cennetidir.' },
  ],
  samsun: [
    { name: 'Bandırma Vapuru Müzesi', desc: 'Atatürk’ün 19 Mayıs 1919’da Kurtuluş Savaşı’nı başlatmak üzere Samsun’a ayak bastığı efsanevi geminin birebir yeniden inşa edilmiş halidir. Milli Mücadele’nin başlangıcını simgeleyen bu gemi-müze, Türk tarihinin en anlamlı mekânlarından biridir.' },
    { name: 'Amazon Köyü Tema Parkı', desc: 'Antik çağda bölgede yaşadığına inanılan savaşçı kadınlar Amazonların efsanesini canlandıran bu açık hava müzesi, ahşap heykeller ve tematik yapılarla döneme dair bir yolculuk sunar. Yeşilırmak deltasındaki konumuyla mitoloji ve doğayı birleştirir.' },
    { name: 'Amisos Tepesi', desc: 'Teleferikle çıkılan bu tepe, adını kentin antik ismi Amisos’tan alır ve şehrin ile Karadeniz’in panoramasını sunar. Üzerinde bulunan Pontus dönemi kral kaya mezarları, bölgenin köklü geçmişine ışık tutar.' },
    { name: 'Onur Anıtı & Sahil', desc: 'Atatürk’ün Samsun’a çıkışını simgeleyen bu görkemli atlı heykel, kentin en tanınan simgesidir ve modern Türkiye’nin doğuşuna adanmıştır. Çevresindeki geniş sahil bandı, Karadeniz manzarası eşliğinde yürüyüş için idealdir.' },
  ],
  ordu: [
    { name: 'Boztepe', desc: 'Ordu şehir merkezinden teleferikle çıkılan bu tepe, şehrin fındık bahçeleriyle kaplı yamaçlarına ve masmavi Karadeniz’e hâkim eşsiz bir manzara sunar. Kafeleri ve mesire alanlarıyla hem yerlilerin hem de ziyaretçilerin gözde buluşma noktasıdır.' },
    { name: 'Perşembe & Çambaşı Yaylaları', desc: 'Ordu’nun yüksek kesimlerindeki bu yaylalar, sabahları ayakların altında dalgalanan bulut denizi manzaralarıyla ünlüdür. Yeşil çayırları, serin havası ve geleneksel yayla kültürüyle Karadeniz’in en huzurlu doğa noktalarındandır.' },
    { name: 'Yason Burnu Kilisesi', desc: 'Mitolojideki Argonotların efsanesine adını veren Yason Burnu, denize doğru uzanan bir çıkıntının ucundaki 19. yüzyıl kilisesiyle büyüler. Rüzgârlı burun, üç yanı denizle çevrili konumu ve romantik atmosferiyle sevilen bir uğrak yerdir.' },
    { name: 'Paşaoğlu Konağı', desc: '19. yüzyıl sonlarında zengin bir aile için inşa edilen bu görkemli konak, dönemin yaşam biçimini yansıtan zarif ahşap işçiliği ve mobilyalarıyla dikkat çeker. Bugün etnografya müzesi olarak Ordu’nun geleneksel kültürünü ziyaretçilere aktarır.' },
  ],
  giresun: [
    { name: 'Giresun Adası', desc: 'Doğu Karadeniz’in kıyıya yakın tek adası olan bu küçük ada, antik çağda savaşçı Amazon kadınları ve tanrıça Kybele kültüyle ilişkilendirilmiştir. Üzerindeki manastır kalıntıları ve efsaneleriyle bugün mitolojik bir gizem taşır.' },
    { name: 'Giresun Kalesi', desc: 'Şehrin üzerindeki tepeyi taçlandıran bu tarihî kale, Pontus Krallığı’ndan Bizans ve Osmanlı’ya uzanan katmanlı bir geçmişe sahiptir. İçinde Kurtuluş Savaşı kahramanı Topal Osman’ın anıt mezarını barındıran alan, bugün panoramik bir şehir parkıdır.' },
    { name: 'Kümbet & Bektaş Yaylaları', desc: 'Giresun’un yüksek platolarındaki bu yaylalar, her yaz düzenlenen geleneksel yayla şenlikleri ve horon havalarıyla ünlüdür. Yeşil çayırları, sisli tepeleri ve otantik dağ evleriyle Karadeniz yayla kültürünün canlı örnekleridir.' },
    { name: 'Şebinkarahisar Kalesi', desc: 'Sarp ve yalçın kayalıkların tepesinde yükselen bu etkileyici kale, adını da (“Kara Hisar”) bu heybetli konumundan alır. Yüzyıllar boyunca stratejik bir savunma noktası olan yapı, çevresine hâkim manzarasıyla nefes kesicidir.' },
  ],
  artvin: [
    { name: 'Karagöl (Şavşat)', desc: 'Şavşat yakınlarındaki bu heyelan set gölü, çevresini saran görkemli ladin ormanlarını berrak sularına yansıtan dingin atmosferiyle büyüler. Özellikle sonbaharda kızıla dönen ağaçlarıyla Karadeniz’in en fotojenik doğa parklarından biridir.' },
    { name: 'Maçahel (Camili) Biyosfer', desc: 'Türkiye’nin UNESCO tarafından ilan edilen ilk biyosfer rezervi olan Maçahel, dış dünyaya kapalı kalmış el değmemiş ormanları ve endemik türleriyle olağanüstü bir ekosistemdir. Geleneksel kara kovan arıcılığı ve saf balıyla da ünlüdür.' },
    { name: 'Borçka Karagöl', desc: 'Yaklaşık üç asır önce bir depremin tetiklediği heyelanla oluşan bu göl, suya batmış ağaç gövdeleri ve etrafını saran ormanla masalsı bir görünüm sunar. Sisli sabahları ve yansımalarıyla adeta gizemli bir peri diyarını andırır.' },
    { name: 'Kaçkar Dağları', desc: 'Doğu Karadeniz’in çatısını oluşturan bu sıradağlar, buzul çağından kalma göller, alpin çayırlar ve 3.937 metrelik zirvesiyle dağcıların ve doğaseverlerin gözdesidir. Sarp vadileri ve zengin bitki örtüsüyle Türkiye’nin en görkemli dağ silsilelerindendir.' },
  ],
  sinop: [
    { name: 'Sinop Kalesi & Tarihi Cezaevi', desc: 'Kökeni MÖ 7. yüzyıla uzanan antik surların içine kurulan Sinop Cezaevi, 1887’den 1997’ye dek faaliyet göstermiş ve pek çok ünlü yazarı ağırlamıştır. “Demir kapıların ardındaki” yaşamıyla efsaneleşen yapı, bugün ürperten bir müze olarak ziyaret edilir.' },
    { name: 'Balatlar Kilisesi', desc: 'Roma hamamı olarak kurulup sonradan kiliseye dönüştürülen bu yapı, iyi korunmuş İsa ve azizleri betimleyen renkli fresklerle bezelidir. Erken Hristiyanlık döneminin izlerini taşıyan bu kalıntılar, Sinop’un dini tarihine ışık tutar.' },
    { name: 'İnce Burun', desc: 'Türkiye anakarasının en kuzey ucu olan bu burun, üzerindeki tarihî deniz feneri ve el değmemiş kıyı manzarasıyla simgesel bir noktadır. Coğrafi konumu ve dingin doğasıyla ülkenin “kuzey sınırına” ulaşmak isteyenlerin uğrak yeridir.' },
    { name: 'Hamsilos Koyu', desc: 'Doğal kayalıkların oluşturduğu fiyorda benzeyen bu korunaklı koy, çam ormanlarıyla çevrili sakin sularıyla ünlüdür. Akdeniz’in tek fiyort benzeri oluşumu kabul edilen koy, tekne turları ve yürüyüş rotalarıyla huzurlu bir doğa cennetidir.' },
  ],
  kastamonu: [
    { name: 'Kastamonu Kalesi', desc: 'Şehrin üzerindeki tepeye kurulu bu ortaçağ kalesi, kökeni Bizans dönemine uzanan ve Candaroğulları ile Osmanlılar tarafından kullanılan stratejik bir savunma yapısıdır. Zirvesinden Kastamonu’nun tarihî evleri ve yeşil vadilerine hâkim bir manzara sunar.' },
    { name: 'Kasaba Köyü Mahmut Bey Camii', desc: '1366 yılında inşa edilen bu cami, hiç çivi kullanılmadan geçme tekniğiyle yapılmış ahşap direkleri ve altı yüzyıldır solmayan kalem işi süslemeleriyle bir başyapıttır. Anadolu’nun ayakta kalan en değerli ahşap camilerinden biridir.' },
    { name: 'Ilgaz Dağı Milli Parkı', desc: 'İç Anadolu ile Karadeniz’i ayıran Ilgaz Dağları üzerindeki bu milli park, kış aylarında kayak merkezi, yaz aylarında ise doğa yürüyüşü ve kamp cenneti olarak hizmet verir. Sık ormanları ve temiz havasıyla dört mevsim gözde bir doğa merkezidir.' },
    { name: 'Küre Dağları & Valla Kanyonu', desc: 'Türkiye’nin en derin ve en tehlikeli kanyonlarından biri olan Valla Kanyonu, yer yer 800 metreyi bulan sarp duvarlarıyla nefes kesicidir. Küre Dağları Milli Parkı içindeki bu kanyon, el değmemiş doğası ve zorlu rotalarıyla maceracıları cezbeder.' },
  ],
  malatya: [
    { name: 'Aslantepe Höyüğü (UNESCO)', desc: 'MÖ 4. binyıla uzanan bu höyük, dünyanın bilinen en eski saray yapısını ve en erken devlet örgütlenmelerinden birini barındırır. İçinde bulunan tarihteki en eski metal kılıçlarıyla ünlü bu alan, UNESCO Dünya Mirası listesindedir.' },
    { name: 'Battalgazi (Eski Malatya)', desc: 'Malatya’nın tarihî çekirdeği olan bu ilçe, 13. yüzyıldan kalma anıtsal Ulu Camii, Silahtar Mustafa Paşa Kervansarayı ve surlarıyla Selçuklu-Osmanlı mirasını yaşatır. Adını efsanevi savaşçı Battal Gazi’den alan yerleşim, katmanlı bir geçmişe sahiptir.' },
    { name: 'Levent Vadisi', desc: 'Milyonlarca yılda suyun ve rüzgârın aşındırdığı renkli kaya katmanları ve derin kanyonlarıyla bu vadi, “Anadolu’nun Kapadokyası” olarak anılır. Katmanların oluşturduğu görsel şölen, doğa fotoğrafçıları ve trekking tutkunlarının gözdesidir.' },
    { name: 'Kayısı Bahçeleri', desc: 'Malatya, dünya kuru kayısı üretiminin büyük bölümünü karşılayan “kayısı başkenti” olarak tanınır. Yaz aylarında hasat edilen ve güneşte kurutulan kayısı bahçeleri, bölgenin ekonomisini ve kültürünü şekillendiren altın rengi bir manzara sunar.' },
  ],
  elazig: [
    { name: 'Harput', desc: 'Elazığ’ın tarihî çekirdeği olan bu antik yerleşim, kökeni Urartulara uzanan görkemli kalesi, 12. yüzyıl Ulu Camii ve doğal buz oluşturan “buzluk” mağarasıyla ünlüdür. Bir dönem bölgenin en önemli kültür ve ilim merkeziydi.' },
    { name: 'Hazar Gölü', desc: 'Sıradağların arasına sıkışmış bu tektonik göl, berrak masmavi sularıyla “Elazığ’ın denizi” olarak anılır. Suları çekildiğinde ortaya çıkan batık bir kilisenin kalıntıları, göle mistik bir hava katar.' },
    { name: 'Keban Barajı', desc: 'Fırat Nehri üzerinde 1970’lerde inşa edilen bu devasa baraj, Türkiye’nin en büyük enerji projelerinden biridir ve arkasında geniş bir yapay göl oluşturmuştur. Etkileyici mühendislik yapısı ve göl manzarasıyla bölgenin simgelerindendir.' },
    { name: 'Palu Kalesi & Kaleleri', desc: 'Fırat Nehri kıyısındaki sarp bir kayalığa kurulan Palu Kalesi, Urartu döneminden kalma çivi yazılı yazıtları ve tarihî camisiyle katmanlı bir geçmişe sahiptir. Eski Palu yerleşimi, nehir kenarındaki dramatik konumuyla etkileyicidir.' },
  ],
  tunceli: [
    { name: 'Munzur Vadisi Milli Parkı', desc: 'Türkiye’nin en büyük milli parklarından biri olan bu vadi, turkuaz renkli Munzur Çayı, endemik bitkileri ve yaban keçileriyle olağanüstü bir biyoçeşitliliğe sahiptir. El değmemiş doğası ve kutsal atmosferiyle bölge halkı için özel bir anlam taşır.' },
    { name: 'Munzur Gözeleri', desc: 'Munzur Çayı’nın kayaların arasından güçlü bir şekilde doğduğu bu kaynaklar, yöre halkı tarafından kutsal sayılır ve ziyaret edilir. Buz gibi berrak sularıyla çevrelenen bu doğal alan, inanç ve doğanın iç içe geçtiği huzurlu bir mekândır.' },
    { name: 'Pertek Kalesi', desc: 'Keban Barajı’nın suları yükselince etrafı sularla çevrilerek bir ada kalesine dönüşen bu yapı, Fırat’ın ortasında yükselen görkemiyle etkileyicidir. Kökeni ortaçağa uzanan kale, tekneyle ulaşılan eşsiz konumuyla nefes kesicidir.' },
    { name: 'Rafting (Peri & Munzur)', desc: 'Tunceli’nin coşkulu akan Munzur ve Peri suları, berrak soğuk suları ve el değmemiş vadi manzaralarıyla rafting tutkunlarının gözdesidir. Doğal güzelliklerle çevrili bu rotalar, hem adrenalin hem de eşsiz bir doğa deneyimi sunar.' },
  ],
  bitlis: [
    { name: 'Nemrut Krater Gölü', desc: 'Van Gölü kıyısındaki Nemrut yanardağının kalderasında yer alan bu göl, dünyanın en büyük ikinci krater gölüdür. İçinde hem soğuk hem de sıcak su göllerini barındırması, onu jeolojik açıdan eşsiz ve büyüleyici bir doğa harikası kılar.' },
    { name: 'Ahlat Selçuklu Mezarlığı', desc: 'Van Gölü kıyısındaki bu geniş mezarlık, üzerlerindeki incelikli geometrik ve bitkisel motiflerle bezeli anıtsal Selçuklu mezar taşları (şahideler) ve kümbetleriyle ünlüdür. Dünyanın en büyük Türk-İslam mezarlığı olarak eşsiz bir taş işçiliği sergiler.' },
    { name: 'Bitlis Kalesi', desc: 'Rivayete göre Büyük İskender’in komutanlarından biri tarafından kurulan bu kale, dar bir vadiye sıkışmış taş şehrin tepesinde yükselir. Yüzyıllar boyu stratejik bir geçit noktasını koruyan yapı, kentin karakteristik siluetine hâkimdir.' },
    { name: 'İhlasiye Medresesi', desc: '16. yüzyılda inşa edilen bu tarihî medrese, kentin karakteristik kesme taş işçiliğini yansıtan zarif taç kapısı ve avlusuyla dikkat çeker. Bitlis’in köklü ilim geleneğinin önemli merkezlerinden biri olarak kent merkezinde yer alır.' },
  ],
  batman: [
    { name: 'Hasankeyf', desc: 'Dicle Nehri kıyısında on iki bin yıllık kesintisiz yerleşim geçmişine sahip bu antik kent, mağara evleri, köprü kalıntıları ve tarihî yapılarıyla eşsizdi. Ilısu Barajı’nın suları altında kalan kentin taşınabilen anıtları, yeni yerinde korunmaya devam eder.' },
    { name: 'Malabadi Köprüsü', desc: '12. yüzyılda Artuklular tarafından Batman Çayı üzerine inşa edilen bu köprü, dünyanın en geniş taş kemer açıklıklarından birine sahiptir. Kemerin içindeki odaları ve zarif mimarisiyle Ortaçağ mühendisliğinin bir başyapıtı kabul edilir.' },
    { name: 'Zeynel Bey Türbesi', desc: 'Akkoyunlu hükümdarı Uzun Hasan’ın oğlu Zeynel Bey için yaptırılan bu silindirik türbe, turkuaz ve lacivert çinilerle bezeli benzersiz görünümüyle Anadolu’da tektir. Baraj suları altında kalmaması için bütün halinde yeni yerine taşınmıştır.' },
    { name: 'Hasankeyf Mağaraları', desc: 'Hasankeyf’i çevreleyen kayalıklara binlerce yıl boyunca oyulmuş bu mağaralar, bir zamanlar on binlerce insanın yaşadığı devasa bir yerleşim ağı oluşturuyordu. Çok katlı bu kaya konutları, bölgenin köklü mağara yaşam kültürüne tanıklık eder.' },
  ],
  isparta: [
    { name: 'Eğirdir Gölü', desc: 'Türkiye’nin dördüncü büyük gölü olan Eğirdir, berrak suları, içindeki adacıkları ve göle uzanan bir yarımada üzerine kurulu şirin kasabasıyla büyüler. Etrafını saran dağların yansımaları ve balıkçı kültürüyle huzurlu bir tablo sunar.' },
    { name: 'Lavanta Bahçeleri (Kuyucak)', desc: '“Lavanta kokulu köy” olarak ünlenen Kuyucak, yaz aylarında yamaçlarını mora boyayan uçsuz bucaksız lavanta tarlalarıyla adeta bir masal diyarına dönüşür. Isparta’nın gül ve lavanta üretimindeki öncülüğünün en fotojenik simgesidir.' },
    { name: 'Sagalassos Antik Kenti', desc: 'Toros Dağları’nda 1.500 metre yükseklikte kurulan bu antik kent, olağanüstü korunmuş anıtsal çeşmesi ve tiyatrosuyla ünlüdür. Büyük İskender’in de fethettiği bu Pisidya şehri, dağların zirvesindeki konumuyla nefes kesici bir arkeolojik alandır.' },
    { name: 'Kovada Gölü Milli Parkı', desc: 'Eğirdir Gölü’nün güneyindeki bu milli park, berrak gölü, sık ormanları ve zengin bitki örtüsüyle bir doğa cennetidir. Yürüyüş rotaları, endemik türleri ve barındırdığı yaban hayatıyla doğaseverler için ideal bir kaçış noktasıdır.' },
    { name: 'Davraz', desc: 'Eğirdir ve Kovada göllerine tepeden bakan Davraz Dağı, kış aylarında kaliteli karı ve göl manzaralı pistleriyle popüler bir kayak merkezidir. Yaz aylarında ise yamaç paraşütü ve doğa yürüyüşleriyle dört mevsim aktif bir spor merkezidir.' },
  ],
  afyon: [
    { name: 'Afyon Kalesi', desc: 'Şehrin ortasında dimdik yükselen 226 metrelik kayalığın tepesindeki bu kale, kökeni Hititlere kadar uzanan çok eski bir savunma yapısıdır. Yaklaşık 700 basamakla çıkılan zirvesi, Afyonkarahisar’ın panoramasına hâkim heybetli bir konum sunar.' },
    { name: 'Frig Vadisi (Ayazini)', desc: 'Friglerden kalma bu vadi, kayalara oyulmuş anıtsal mezarlar, tapınak cepheleri ve sonradan eklenen Bizans kaya kiliseleriyle katmanlı bir tarih barındırır. Peri bacalarını andıran oluşumları ve gizemli kaya yapılarıyla açık hava müzesi gibidir.' },
    { name: 'Termal Kaplıcalar', desc: 'Afyonkarahisar, yer altından çıkan zengin mineralli sıcak su kaynaklarıyla Türkiye’nin en önemli termal turizm merkezlerinden biridir. Şifalı olduğuna inanılan kaplıcaları ve modern termal tesisleriyle sağlık ve dinlenme arayanları çeker.' },
    { name: 'Zafer Anıtı & Kocatepe', desc: 'Kurtuluş Savaşı’nın kaderini belirleyen Büyük Taarruz’un 26 Ağustos 1922’de başladığı Kocatepe, Atatürk’ün taarruzu yönettiği tarihî komuta noktasıdır. Şehir merkezindeki Zafer Anıtı ile birlikte bu topraklar Türk zaferinin simgesidir.' },
  ],
  kutahya: [
    { name: 'Çini Atölyeleri & Müzesi', desc: 'Kütahya, 14. yüzyıldan beri süregelen ve İznik geleneğini yaşatan çini-seramik sanatının Türkiye’deki başkentidir. Rengârenk desenli çinilerin üretildiği atölyeler ve müzeleriyle bu asırlık zanaat, kentin kimliğini oluşturan yaşayan bir mirastır.' },
    { name: 'Kütahya Kalesi', desc: 'Kökeni Bizans dönemine uzanan bu kale, şehre tepeden bakan surları ve burçlarıyla kentin savunma tarihine tanıklık eder. Zirvesindeki döner restoranıyla ziyaretçilere Kütahya’nın panoramik manzarasını sunar.' },
    { name: 'Aizanoi Antik Kenti', desc: 'Çavdarhisar’daki bu antik kent, Anadolu’nun en iyi korunmuş Zeus Tapınağı’na ev sahipliği yapmasıyla ünlüdür. Ayrıca dünyanın bilinen ilk borsa binası (macellum) ve stadyum-tiyatro kompleksiyle Roma dönemi mimarisinin görkemli örneklerini barındırır.' },
    { name: 'Germiyan Sokağı', desc: 'Kütahya’nın tarihî merkezinde restore edilen bu sokak, cumbalı ve rengârenk boyanmış geleneksel Osmanlı-Germiyan evleriyle geçmişi bugüne taşır. Butik dükkânları ve çini süslemeleriyle kentin en fotojenik ve nostaljik güzergâhıdır.' },
  ],
  tekirdag: [
    { name: 'Rákóczi Müzesi', desc: 'Osmanlı’ya sığınan Macar bağımsızlık kahramanı Prens II. Ferenc Rákóczi’nin 18. yüzyılda sürgün yıllarını geçirdiği evden dönüştürülen bu müze, Türk-Macar dostluğunun simgesidir. Dönemin eşyalarıyla döşenmiş odaları prensin yaşamına ışık tutar.' },
    { name: 'Uçmakdere', desc: 'Marmara Denizi’ne dik inen yamaçlarıyla Uçmakdere, Türkiye’nin en gözde yamaç paraşütü ve uçurtma sörfü noktalarından biridir. Bağları, zeytinlikleri ve eşsiz deniz manzarasıyla hem maceracıları hem de doğaseverleri kendine çeker.' },
    { name: 'Tekirdağ Sahili', desc: 'Marmara kıyısı boyunca uzanan geniş sahil bandı, yürüyüş yolları, çınar ağaçları ve balık restoranlarıyla kentin en canlı buluşma noktasıdır. Dünyaca ünlü Tekirdağ köftesini tadabileceğiniz sahil durakları, bölgenin lezzet kültürünün simgesidir.' },
    { name: 'Ganos (Işıklar) Dağı', desc: 'Marmara kıyısı boyunca yükselen Ganos Dağı, verimli bağları, çam ormanları ve doğa yürüyüşü rotalarıyla tanınır. Bölgenin köklü şarapçılık geleneğine kaynaklık eden yamaçları ve panoramik manzarasıyla huzurlu bir doğa alanıdır.' },
  ],
  adana: [
    { name: 'Sabancı Merkez Camii', desc: '1998’de tamamlanan bu görkemli cami, altı minaresi ve devasa kubbesiyle Türkiye’nin en büyük ibadethanelerinden biridir. Seyhan Nehri kıyısındaki beyaz mermer yapısı, klasik Osmanlı mimarisini modern ölçekte yorumlayan bir başyapıttır.' },
    { name: 'Taşköprü', desc: 'Seyhan Nehri üzerinde Roma İmparatoru Hadrianus döneminde inşa edilen bu taş köprü, dünyanın hâlâ kullanılan en eski köprülerinden biridir. Yaklaşık on sekiz asırdır ayakta duran kemerleriyle Adana’nın köklü tarihinin sessiz tanığıdır.' },
    { name: 'Misis Mozaik Müzesi', desc: 'Antik Mopsuestia kentinin kalıntıları üzerine kurulan bu müze, olağanüstü korunmuş Roma ve erken Bizans dönemi taban mozaiklerini yerinde sergiler. Nuh’un Gemisi’ni betimleyen ünlü mozaiğiyle bölgenin sanat mirasını gözler önüne serer.' },
    { name: 'Varda Köprüsü', desc: 'Almanlar tarafından 20. yüzyıl başında Bağdat Demiryolu için inşa edilen bu görkemli köprü, derin bir vadiyi 98 metre yükseklikte aşar. Zarif kemerleri ve nefes kesici yüksekliğiyle mühendislik harikası olarak ünlüdür ve bir James Bond filmine de sahne olmuştur.' },
    { name: 'Anavarza Antik Kenti', desc: 'Kilikya bölgesinin önemli merkezlerinden olan Anavarza, anıtsal zafer takı, sütunlu caddesi ve tepesindeki heybetli kalesiyle dikkat çeker. Bir dönem bölgenin başkenti olan kent, geniş kalıntılarıyla görkemli geçmişini yansıtır.' },
  ],
  kahramanmaras: [
    { name: 'Kahramanmaraş Kalesi', desc: 'Kent merkezindeki bir tepeye kurulu bu kale, kökeni Hititlere uzanan ve Bizans ile Osmanlı dönemlerinde kullanılan katmanlı bir tarihe sahiptir. Şehre hâkim konumu ve içindeki müzesiyle Maraş’ın geçmişine açılan bir penceredir.' },
    { name: 'Tarihi Çarşı & Dondurma', desc: 'Maraş’ın kalbindeki bu tarihî çarşı, yüzyıllardır süregelen bakırcılık ve semercilik gibi geleneksel zanaatların merkezidir. Salep ve keçi sütüyle yapılan, bıçakla kesilebilen dünyaca ünlü dövme dondurması ise kentin küresel gastronomi simgesidir.' },
    { name: 'Ashab-ı Kehf', desc: 'İnananların zulümden kaçıp bir mağarada yıllarca uyuduğu “Yedi Uyurlar” (Ashab-ı Kehf) efsanesiyle özdeşleşen bu kutsal mekân, hem Hristiyanlar hem Müslümanlar için önemli bir ziyaret noktasıdır. Mağarası ve çevresindeki külliyesiyle manevi bir çekim merkezidir.' },
    { name: 'Yavşan Yaylası', desc: 'Ahır Dağı üzerindeki bu yüksek yayla, kaliteli karı sayesinde kayak imkânı sunan bir kış sporları merkezidir. Yaz aylarında ise serin havası, geniş çayırları ve doğa yürüyüşü rotalarıyla bölge halkının gözde dinlenme noktasıdır.' },
  ],
  aksaray: [
    { name: 'Ihlara Vadisi', desc: 'Melendiz Çayı’nın volkanik tüfü aşındırmasıyla oluşan bu 14 kilometrelik yeşil kanyon, duvarlarına oyulmuş yüzlerce erken Hristiyan kaya kilisesiyle ünlüdür. Freskli kiliseleri ve serin akarsuyuyla tarih ile doğayı birleştiren eşsiz bir yürüyüş rotasıdır.' },
    { name: 'Selime Katedrali', desc: 'Ihlara Vadisi’nin kuzey ucundaki bu devasa yapı, kayalara oyulmuş Kapadokya’nın en büyük dini kompleksidir. Katedral boyutundaki kilisesi, manastırı ve ahırlarıyla adeta bir kaya kentini andırır ve görkemli bir mimari başarıyı temsil eder.' },
    { name: 'Sultanhanı Kervansarayı', desc: '13. yüzyılda Selçuklu Sultanı I. Alâeddin Keykubad tarafından İpek Yolu üzerinde yaptırılan bu kervansaray, Anadolu’nun en büyüğüdür. Anıtsal taç kapısı ve avlusunun ortasındaki köşk mescidiyle Selçuklu ticaret mimarisinin görkemli bir örneğidir.' },
    { name: 'Aksaray Ulu Camii', desc: 'Karamanoğulları döneminden kalma bu tarihî cami, özellikle ceviz ağacından yapılmış, çivi kullanılmadan geçme tekniğiyle işlenmiş minberiyle ünlüdür. Sade taş mimarisi ve zarif işçiliğiyle kentin en değerli tarihî eserlerindendir.' },
  ],
  nigde: [
    { name: 'Aladağlar Milli Parkı', desc: 'Toros Dağları’nın en yüksek ve en sarp kesimini oluşturan Aladağlar, buzul gölleri, derin vadileri ve 3.700 metreyi aşan zirveleriyle Türkiye’nin en gözde dağcılık ve tırmanış merkezidir. El değmemiş doğası ve yaban keçileriyle bir doğa cennetidir.' },
    { name: 'Gümüşler Manastırı', desc: 'Kayaya oyulmuş bu Bizans manastırı, olağanüstü korunmuş fresklerinin yanı sıra “gülümseyen Meryem” tasviriyle ünlüdür; bu, dünyada Meryem’in gülümser resmedildiği bilinen tek eserdir. Geniş avlusu ve gizli geçitleriyle etkileyici bir kaya kompleksidir.' },
    { name: 'Niğde Kalesi & Alaaddin Camii', desc: 'Kent merkezindeki tepeye kurulu Selçuklu kalesi ve yanındaki 1223 tarihli Alâeddin Camii, Niğde’nin tarihî kalbini oluşturur. Caminin taç kapısındaki, gün ışığıyla kadın yüzü belirdiği söylenen taş işçiliği, incelikli Selçuklu sanatının simgesidir.' },
    { name: 'Narlıgöl Krater Gölü', desc: 'Sönmüş bir yanardağın kraterinde oluşan bu göl, dibindeki termal kaynaklar sayesinde ısınan şifalı sularıyla tanınır. Çevresindeki jeotermal alan ve dingin doğasıyla hem sağlık hem de huzur arayanların uğrak noktasıdır.' },
  ],
  tokat: [
    { name: 'Tokat Kalesi', desc: 'Şehre tepeden bakan bu kale, Pontus döneminden Osmanlı’ya uzanan katmanlı bir geçmişe sahiptir ve içindeki gizli tüneller ile zindanlarıyla ünlüdür. Rivayete göre Bizans kraliçesi Kleopatra’nın bir dönem burada tutulduğu söylenir.' },
    { name: 'Ballıca Mağarası', desc: 'Milyonlarca yılda oluşan bu devasa mağara, kat kat uzanan salonları, dev sütunları ve nadir “soğan sarkıt” oluşumlarıyla Türkiye’nin en görkemli mağaralarından biridir. İçindeki temiz havasının astım hastalarına iyi geldiğine inanılır.' },
    { name: 'Latifoğlu Konağı', desc: '18. yüzyıldan kalma bu görkemli konak, barok üslupta kalem işi süslemeleri, ahşap işçiliği ve “Paşa Odası”yla dönemin varlıklı yaşamını yansıtır. Bugün müze olarak Tokat’ın zengin sivil mimari mirasını ziyaretçilere sunar.' },
    { name: 'Sulusokak', desc: 'Tokat’ın en eski caddelerinden biri olan Sulusokak, boyunca sıralanan tarihî hanlar, hamamlar, camiler ve türbelerle adeta bir açık hava müzesidir. Farklı dönem ve kültürlerden yapılarıyla kentin çok katmanlı tarihini bir arada yaşatır.' },
  ],
  corum: [
    { name: 'Hattuşa (UNESCO)', desc: 'MÖ 2. binyılda Anadolu’ya hükmeden güçlü Hitit İmparatorluğu’nun başkenti olan Hattuşa, devasa surları, aslanlı ve sfenksli kapıları ve tapınaklarıyla eşsizdir. Tarihteki ilk yazılı barış antlaşması Kadeş’in imzalandığı bu kent, UNESCO Dünya Mirası’dır.' },
    { name: 'Yazılıkaya', desc: 'Hattuşa yakınlarındaki bu kaya tapınağı, kayalara oyulmuş yaklaşık doksan Hitit tanrı ve tanrıçasının geçit yaptığı görkemli kabartmalarıyla ünlüdür. Hititlerin en önemli açık hava kutsal alanı olan yapı, dönemin dini inançlarına ışık tutar.' },
    { name: 'Alacahöyük', desc: 'Hatti ve Hitit uygarlıklarının önemli bir merkezi olan bu höyük, anıtsal sfenksli kapısı ve buradan çıkan altın-bronz güneş kursları ile ünlüdür. Bu kurslar, günümüzde Anadolu medeniyetlerinin simgesi olarak kabul edilir.' },
    { name: 'İncesu Kanyonu', desc: 'Ortaköy yakınlarındaki bu vadi, içindeki tarihî kervansaray, kaya kilisesi ve el değmemiş doğasıyla dikkat çeker. Dik kaya duvarları arasından geçen kanyon, hem tarih hem de doğa yürüyüşü meraklıları için huzurlu bir kaçış noktasıdır.' },
  ],
  erzurum: [
    { name: 'Çifte Minareli Medrese', desc: '13. yüzyıldan kalma bu görkemli Selçuklu medresesi, iki tuğla minaresi ve zengin taş kabartmalarla bezeli anıtsal taç kapısıyla Erzurum’un simgesidir. Üzerindeki hayat ağacı ve çift başlı kartal motifleriyle Anadolu Selçuklu sanatının başyapıtlarındandır.' },
    { name: 'Yakutiye Medresesi', desc: '1310’da İlhanlı döneminde inşa edilen bu medrese, incelikli taş işçiliğiyle bezeli taç kapısı ve tek minaresiyle dikkat çeker. Bugün Türk-İslam Eserleri ve Etnografya Müzesi olarak bölgenin zengin kültürel mirasını sergiler.' },
    { name: 'Üç Kümbetler', desc: 'Erzurum’un en eski yapılarından olan bu üç anıt mezar, Selçuklu dönemi mezar mimarisinin zarif örnekleridir. Konik külahları ve taş süslemeleriyle, en büyüğünün kentin Selçuklu kurucusu Emir Saltuk’a ait olduğuna inanılır.' },
    { name: 'Palandöken', desc: 'Erzurum’un hemen yanı başındaki Palandöken Dağı, uzun ve dik pistleri ile tozlu kar kalitesi sayesinde Türkiye’nin en önemli kayak merkezlerinden biridir. Şehir merkezine yakınlığı ve gelişmiş tesisleriyle uluslararası yarışmalara da ev sahipliği yapar.' },
    { name: 'Tortum Şelalesi & Gölü', desc: 'Bir heyelanın vadinin önünü kapatmasıyla oluşan Tortum Gölü’nün taşan sularının meydana getirdiği bu şelale, yaklaşık 48 metre yüksekliğiyle Türkiye’nin en görkemli çağlayanlarından biridir. Çevresindeki dramatik doğasıyla nefes kesici bir manzara sunar.' },
  ],
  erzincan: [
    { name: 'Girlevik Şelalesi', desc: 'Munzur Dağları’nın karlarından beslenen bu çağlayan, yeşillikler içindeki basamaklı görünümüyle yaz aylarında serinletici bir doğa harikasıdır. Kış aylarında ise donarak devasa buz sarkıtlarına dönüşmesiyle görsel bir şölene ev sahipliği yapar.' },
    { name: 'Kemaliye (Eğin) & Karanlık Kanyon', desc: 'Fırat Nehri’nin oyduğu derin Karanlık Kanyon’un kıyısındaki Kemaliye, tarihî taş konakları ve dar sokaklarıyla büyüler. Köylülerin dağı 132 kişilik bir el emeğiyle deldiği efsanevi “Taş Yolu” tüneli, insan azminin çarpıcı bir anıtıdır.' },
    { name: 'Ergan Dağı', desc: 'Erzincan şehir merkezine yakınlığıyla öne çıkan Ergan Dağı, kaliteli karı ve modern tesisleriyle popüler bir kış sporları merkezidir. Yaz aylarında ise ova manzarası ve doğa yürüyüşü rotalarıyla dört mevsim ziyaretçi ağırlar.' },
    { name: 'Terzibaba Türbesi', desc: '19. yüzyılda yaşamış saygın mutasavvıf Terzi Baba’ya (Hayyat Vehbi) adanan bu türbe, Erzincan’ın en önemli manevi ziyaret noktalarından biridir. Kente gelenlerin sıkça uğradığı türbe, bölgenin köklü tasavvuf geleneğinin bir simgesidir.' },
  ],
  bartin: [
    { name: 'Amasra', desc: 'İki ayrı koyun ve bir adacığın çevrelediği bu şirin liman kasabası, antik çağdan beri süregelen tarihi ve dokusuyla “Karadeniz’in incisi” olarak anılır. Balık restoranları, ahşap oymacılığı ve romantik atmosferiyle bölgenin en sevilen tatil noktasıdır.' },
    { name: 'Amasra Kalesi & Kuşkayası', desc: 'Amasra’yı çevreleyen surlar, Roma temelleri üzerine Cenevizliler tarafından güçlendirilmiş ve kasabayı bir açık hava müzesine dönüştürmüştür. Yakınındaki Kuşkayası Yol Anıtı ise Romalıların kayaya oyduğu görkemli bir mühendislik eseridir.' },
    { name: 'Bartın Irmağı', desc: 'Türkiye’nin üzerinde ulaşım yapılabilen sayılı akarsularından biri olan Bartın Irmağı, bir zamanlar tekneyle deniz ticaretine imkân tanımıştır. Yeşilliklerle çevrili kıyıları boyunca yapılan tekne gezileri, huzurlu bir doğa deneyimi sunar.' },
    { name: 'İnkumu Plajı', desc: 'Amasra yakınlarındaki bu plaj, ince altın kumu ve sığ, berrak sularıyla ailelerin gözde tatil yeridir. Uzun sahil bandı ve çevresindeki tesisleriyle Batı Karadeniz’in en popüler deniz noktalarından biridir.' },
  ],
  // -- Türkiye: mütevazı cazibe (2-3 mekan) --
  osmaniye: [
    { name: 'Karatepe-Aslantaş', desc: 'Geç Hitit döneminden kalma bu açık hava müzesi, kral Azatiwada’nın yaptırdığı kabartmalar ve çift dilli (Hiyeroglif Luvice ve Fenike) yazıtlarıyla ünlüdür. Bu yazıtlar, Hitit hiyerogliflerinin çözülmesinde bir Rosetta Taşı işlevi görmüştür.' },
    { name: 'Kastabala (Hierapolis)', desc: 'Kilikya bölgesindeki bu antik kent, iki yanı sütunlarla bezeli görkemli caddesi, tiyatrosu ve tepesindeki ortaçağ kalesiyle etkileyicidir. Tanrıça Kybele kültünün önemli bir merkezi olan kentin sütunlu yolu, eski ihtişamı hâlâ hissettirir.' },
    { name: 'Zorkun Yaylası', desc: 'Amanos (Nur) Dağları’nın yüksek kesimlerindeki bu yayla, serin havası, çam ormanları ve pınarlarıyla bölge halkının yaz aylarındaki gözde sığınağıdır. Panoramik manzarası ve doğal güzelliğiyle huzurlu bir kaçış noktasıdır.' },
  ],
  kilis: [
    { name: 'Kilis Ulu Camii', desc: '16. yüzyılda inşa edilen bu cami, kentin en eski ve en görkemli Osmanlı ibadethanelerinden biridir. Kesme taş işçiliği ve zarif minaresiyle Kilis’in köklü tarihine tanıklık eden önemli bir mimari mirastır.' },
    { name: 'Ravanda Kalesi', desc: 'Kilis ovasına tepeden bakan bir dağın üzerine kurulu bu kale, Haçlı Seferleri ve sonrasında stratejik bir savunma noktası olmuştur. Ovaya hâkim heybetli konumu ve tarihî kalıntılarıyla bölgenin geçmişine açılan bir penceredir.' },
    { name: 'Oylum Höyük', desc: 'Güneydoğu Anadolu’nun en büyük höyüklerinden biri olan Oylum, Kalkolitik çağdan Demir Çağı’na uzanan kesintisiz bir yerleşim geçmişine sahiptir. Katman katman ortaya çıkarılan buluntularıyla bölgenin binlerce yıllık tarihine ışık tutar.' },
  ],
  burdur: [
    { name: 'Salda Gölü', desc: 'Beyaz kumu ve turkuaz sularıyla “Türkiye’nin Maldivleri” olarak anılan bu krater gölü, içerdiği hidromanyezit mineralleriyle dünyada eşi az bulunan bir doğa harikasıdır. NASA’nın Mars’taki yaşam izlerini araştırmak için incelediği göl, bilimsel açıdan da benzersizdir.' },
    { name: 'Sagalassos', desc: 'Toros Dağları’nda 1.500 metre yükseklikte kurulan bu antik kent, olağanüstü korunmuş anıtsal Antoninler Çeşmesi ve tiyatrosuyla ünlüdür. Bulutların arasındaki konumu ve görkemli kalıntılarıyla “Türkiye’nin en iyi korunmuş antik kentlerinden biri” kabul edilir.' },
    { name: 'İnsuyu Mağarası', desc: 'Türkiye’nin turizme açılan ilk mağarası olan İnsuyu, içindeki dokuz göleti, sarkıt ve dikitleriyle etkileyici bir yeraltı dünyası sunar. Sularının şifalı olduğuna inanılan mağara, aydınlatılmış yürüyüş yollarıyla kolayca gezilebilir.' },
  ],
  usak: [
    { name: 'Uşak Arkeoloji Müzesi', desc: 'Bu müze, Lidya Kralı Krezüs dönemine ait olağanüstü altın ve gümüş eserlerden oluşan ünlü “Karun Hazineleri”ne ev sahipliği yapar. Yurt dışına kaçırıldıktan sonra geri getirilen bu hazineler, antik Lidya’nın efsanevi zenginliğini gözler önüne serer.' },
    { name: 'Ulubey Kanyonu', desc: 'Yaklaşık 77 kilometre uzunluğuyla dünyanın en büyük ikinci kanyonu olan Ulubey, derin vadileri ve zengin doğasıyla nefes kesicidir. Uçurumun üzerine kurulu cam seyir terası, ziyaretçilere kanyonun boşluğu üzerinde yürüme heyecanı yaşatır.' },
    { name: 'Blaundus Antik Kenti', desc: 'Büyük İskender’in askerlerince kurulduğu düşünülen bu antik kent, Ulubey Kanyonu’na tepeden bakan bir yarımada üzerinde yer alır. Surları, tapınakları ve kaya mezarlarıyla dramatik bir doğal savunma konumuna sahiptir.' },
  ],
  kirklareli: [
    { name: 'İğneada Longoz Ormanları', desc: 'Karadeniz kıyısındaki bu milli park, mevsimsel olarak su altında kalan nadir “longoz” (su basar) ormanlarıyla dünya çapında ekolojik öneme sahiptir. Zengin biyoçeşitliliği ve el değmemiş doğasıyla eşsiz bir yaban hayatı barındırır.' },
    { name: 'Dupnisa Mağarası', desc: 'Istranca Dağları’ndaki bu üç katlı mağara, içinden akan yeraltı deresi, gölleri ve görkemli sarkıt-dikit oluşumlarıyla büyüler. Kuru ve sulu bölümleriyle farklı katmanlar sunan mağara, ziyarete açık etkileyici bir yeraltı dünyasıdır.' },
    { name: 'Kıyıköy', desc: 'Karadeniz kıyısındaki bu sakin balıkçı kasabası, kayalara oyulmuş görkemli Bizans dönemi Aya Nikola Manastırı ve tarihî surlarıyla dikkat çeker. İki nehir arasındaki konumu, bakir plajları ve huzurlu atmosferiyle keşfedilmeyi bekleyen bir cennettir.' },
  ],
  kocaeli: [
    { name: 'Kartepe', desc: 'Sapanca Gölü’ne tepeden bakan bu dağ, kış aylarında kaliteli karı ve göl manzaralı pistleriyle popüler bir kayak merkezidir. Zirvesinden gölün ve çevresindeki ormanların panoramasını sunan Kartepe, İstanbul’a yakınlığıyla dört mevsim ziyaretçi çeker.' },
    { name: 'Seka Park & Sahil', desc: 'Türkiye’nin ilk kâğıt fabrikası SEKA’nın arazisinin dönüştürülmesiyle oluşturulan bu geniş kıyı parkı, körfez manzaralı yürüyüş yolları ve rekreasyon alanlarıyla İzmit’in nefes alanıdır. Endüstriyel mirasın yeşil bir kamusal alana dönüşümünü simgeler.' },
    { name: 'Kerpe & Kefken', desc: 'Karadeniz kıyısındaki bu komşu sahil kasabaları, kendine özgü kırmızımsı kayalık koyları, berrak suları ve ince kumlu plajlarıyla ünlüdür. Doğal güzellikleri ve sakin atmosferiyle özellikle yaz aylarında sevilen bir kaçış noktasıdır.' },
  ],
  sakarya: [
    { name: 'Sapanca Gölü', desc: 'İstanbul ve Ankara’ya yakınlığıyla hafta sonu kaçamaklarının gözdesi olan bu tatlı su gölü, etrafını saran ormanlar ve göl kıyısı bungalovlarıyla huzurlu bir atmosfer sunar. Yürüyüş, bisiklet ve tekne turlarıyla dört mevsim ziyaret edilir.' },
    { name: 'Maşukiye', desc: 'Kartepe’nin eteklerindeki bu şirin belde, buz gibi akan dereleri, şelaleleri ve dere kenarındaki alabalık restoranlarıyla ünlüdür. Yemyeşil doğası ve serin havasıyla doğayla iç içe bir kaçış arayanların uğrak noktasıdır.' },
    { name: 'Acarlar Longozu', desc: 'Karadeniz kıyısındaki bu su basar orman, Avrupa’nın en büyük longozlarından biridir ve dişbudak ağaçlarıyla kaplı sulak alanıyla eşsizdir. Kano veya tekneyle sessizce gezilen bu doğal alan, zengin kuş çeşitliliğiyle bir yaban hayatı sığınağıdır.' },
  ],
  yalova: [
    { name: 'Termal Kaplıcaları', desc: 'Roma ve Bizans dönemlerinden beri kullanılan bu şifalı kaplıcalar, Atatürk’ün de sıkça ziyaret ettiği ve geliştirdiği tarihî bir sağlık merkezidir. Yeşillikler içindeki tarihî hamamları ve sıcak mineralli sularıyla asırlardır şifa dağıtır.' },
    { name: 'Yürüyen Köşk', desc: 'Atatürk’ün, dallarına zarar vereceği için bir çınar ağacının kesilmesini istememesi üzerine, köşkün raylar üzerinde birkaç metre kaydırılmasıyla ünlenen bu yapı, doğa sevgisinin bir simgesidir. Bugün müze olan köşk, bu ilginç hikâyesiyle ziyaretçi çeker.' },
    { name: 'Sudüşen Şelalesi', desc: 'Yalova’nın ormanlık tepelerinde yer alan bu şelale, yüksek kayalardan dökülen suyu ve çevresindeki yemyeşil doğasıyla serinletici bir kaçış noktasıdır. Yürüyüş rotaları ve doğal güzelliğiyle özellikle yaz aylarında sevilen bir mesire yeridir.' },
  ],
  bilecik: [
    { name: 'Söğüt', desc: 'Osmanlı Devleti’nin ilk beyliğinin kurulduğu topraklar olan Söğüt, hanedanın atası Ertuğrul Gazi’nin türbesine ev sahipliği yapar. Her yıl düzenlenen Ertuğrul Gazi’yi anma törenleriyle Osmanlı’nın altı asırlık serüveninin başladığı simgesel bir mekândır.' },
    { name: 'Şeyh Edebali Türbesi', desc: 'Osman Gazi’nin kayınpederi ve kuruluş döneminin manevi önderi olan Şeyh Edebali’ye adanan bu türbe, Bilecik’in en önemli ziyaret noktalarından biridir. Ona atfedilen “İnsanı yaşat ki devlet yaşasın” öğüdü, devletin kuruluş felsefesini yansıtır.' },
    { name: 'Osmaneli Tarihî Evleri', desc: 'Osmaneli ilçesi, Rum ve Osmanlı mimarisinin izlerini taşıyan cumbalı ahşap ve taş konaklarıyla korunmuş bir tarihî dokuya sahiptir. Dar sokakları ve restore edilen evleriyle geçmişin yaşam biçimini günümüze taşıyan nostaljik bir yerleşimdir.' },
  ],
  kirsehir: [
    { name: 'Cacabey Medresesi', desc: '1272 yılında bir astronomi medresesi ve gözlemevi olarak inşa edilen bu Selçuklu yapısı, döneminin bilimsel merkezlerinden biriydi. Görkemli taç kapısı ve içindeki gök cisimlerini gözlemlemeye yarayan düzeneğiyle Anadolu’da eşi az bulunan bir eserdir.' },
    { name: 'Ahi Evran Türbesi', desc: 'Anadolu’daki esnaf ve zanaatkâr dayanışma örgütü olan Ahilik teşkilatının kurucusu Ahi Evran’a adanan bu türbe, Kırşehir’in en önemli manevi merkezidir. Ahiliğin merkezi kabul edilen kent, bu köklü esnaf kültürünün doğduğu yer olarak anılır.' },
    { name: 'Terme Kaplıcaları', desc: 'Kırşehir’in yer altı zenginliklerinden beslenen bu şifalı termal kaynaklar, romatizma ve cilt rahatsızlıklarına iyi geldiğine inanılan sıcak sularıyla tanınır. Modern tesisleriyle bölgenin sağlık turizmine katkı sağlayan bir dinlenme merkezidir.' },
  ],
  karaman: [
    { name: 'Binbir Kilise (Madenşehir)', desc: 'Karadağ’ın eteklerinde yer alan bu bölge, erken Hristiyanlık döneminden kalma onlarca taş kilise kalıntısıyla ünlüdür ve bu bolluk nedeniyle “Binbir Kilise” olarak anılır. Bir zamanlar önemli bir dini merkez olan alan, dönemin manastır mimarisine ışık tutar.' },
    { name: 'Karaman Kalesi', desc: 'Karamanoğulları Beyliği döneminden kalma bu iç kale, kentin merkezinde yükselerek geçmişin savunma yapılarına tanıklık eder. Restore edilen surları ve kuleleriyle Karaman’ın beylik dönemi tarihine açılan bir penceredir.' },
    { name: 'Taşkale Tahıl Ambarları', desc: 'Taşkale köyünde bir kaya yamacına oyulmuş yüzlerce ambar gözü, asırlardır köylülerin tahıllarını doğal soğuk hava deposunda sakladığı benzersiz bir sistemdir. Hâlâ kullanılan bu ambarlar, geleneksel kırsal yaşamın yaratıcı bir mühendislik örneğidir.' },
  ],
  kirikkale: [
    { name: 'Kapulukaya Barajı', desc: 'Kızılırmak üzerinde kurulan bu baraj, arkasında oluşturduğu göl ve çevresindeki mesire alanlarıyla kentin gözde dinlenme noktasıdır. Göl manzarası ve yeşillikleriyle özellikle hafta sonu piknik ve doğa yürüyüşleri için tercih edilir.' },
    { name: 'Hasandede Camii', desc: 'Adını yörede saygın bir din âlimi olan Hasan Dede’den alan bu tarihî cami, ahşap işçiliği ve manevi atmosferiyle önemli bir ziyaret noktasıdır. Çevresindeki türbeyle birlikte bölge halkı için köklü bir inanç merkezi oluşturur.' },
    { name: 'Kaletepe', desc: 'Kırıkkale şehir merkezine hâkim bu tepe, üzerindeki rekreasyon alanları, seyir terasları ve yürüyüş yollarıyla kentlilerin nefes aldığı bir mekândır. Şehrin panoramik manzarasını sunan konumuyla sevilen bir buluşma noktasıdır.' },
  ],
  cankiri: [
    { name: 'Çankırı Tuz Mağarası', desc: 'Binlerce yıldır işletilen bir kaya tuzu madeninin içinde açılan bu dev galeri, tuzlu havasının astım gibi solunum rahatsızlıklarına iyi geldiği düşünülen bir sağlık turizmi merkezidir. Tuz bloklarından oyulmuş salonları ve heykelleriyle etkileyici bir yeraltı dünyasıdır.' },
    { name: 'Taşmescit (Darüşşifa)', desc: '13. yüzyılda Selçuklular tarafından inşa edilen bu şifahane, taç kapısındaki çift başlı yılan (şifanın simgesi) kabartmasıyla ünlüdür. Dönemin en gelişmiş sağlık kurumlarından biri olan yapı, tıp tarihi açısından büyük değer taşır.' },
    { name: 'Çankırı Kalesi', desc: 'Roma döneminden kalma temelleri olan bu kale, şehre hâkim bir tepe üzerinde yükselerek kentin savunma geçmişine tanıklık eder. Zirvesinden Çankırı’nın panoramasını sunan konumu ve tarihî dokusuyla önemli bir uğrak noktasıdır.' },
  ],
  yozgat: [
    { name: 'Çamlık Milli Parkı', desc: '1958’de ilan edilen bu alan, Türkiye’nin ilk milli parkı olma özelliğini taşır ve asırlık karaçam ormanıyla ünlüdür. Bozkırın ortasında bir yeşil vaha oluşturan park, doğa yürüyüşü ve piknik için sevilen bir dinlenme alanıdır.' },
    { name: 'Kerkenes', desc: 'Demir Çağı’na tarihlenen bu antik kent, yaklaşık 7 kilometrelik surlarıyla Anadolu’nun bilinen en büyük tek dönem yerleşimlerinden biridir. Kısa bir süre yaşamış olsa da devasa ölçeğiyle dönemin şehircilik anlayışına ışık tutan önemli bir arkeolojik alandır.' },
    { name: 'Sarıkaya Roma Hamamı', desc: 'Antik Aquae Sarvenae kentindeki bu Roma hamamı, yer altından çıkan şifalı termal suyla beslenen sütunlu havuzuyla (Basilica Therma) dikkat çeker. İyi korunmuş yapısıyla Roma dönemi sağlık ve hamam kültürünün Anadolu’daki değerli bir örneğidir.' },
  ],
  gumushane: [
    { name: 'Karaca Mağarası', desc: 'Türkiye’nin en görkemli mağaralarından biri olan Karaca, içindeki farklı minerallerin oluşturduğu rengârenk sarkıt, dikit ve traverten oluşumlarıyla büyüler. Havasının astım hastalarına iyi geldiğine inanılan mağara, aydınlatılmış yürüyüş yollarıyla ziyarete açıktır.' },
    { name: 'Santa Harabeleri', desc: 'Ormanların içinde terk edilmiş bu eski Rum yerleşimi, taştan yapılma kiliseleri, çeşmeleri ve konaklarıyla adeta bir hayalet köyü andırır. 20. yüzyılda nüfus mübadelesiyle boşalan mahalleleri, geçmişin izlerini taşıyan hüzünlü ama etkileyici bir atmosfer sunar.' },
    { name: 'Zigana & Limni Gölü', desc: 'Karadeniz’i iç bölgelere bağlayan tarihî Zigana Geçidi, sık ormanları ve sisli manzarasıyla ünlüdür. Yakınındaki Limni Gölü ise çevresini saran yeşilliği sularına yansıtan dingin atmosferiyle huzurlu bir doğa kaçamağı sunar.' },
  ],
  bayburt: [
    { name: 'Bayburt Kalesi', desc: 'Şehre tepeden bakan bu heybetli kale, Anadolu’nun en büyük kalelerinden biri olup kökeni antik çağlara uzanır. Ünlü seyyah Marco Polo ve Evliya Çelebi’nin de söz ettiği yapı, yüzyıllar boyunca İpek Yolu’ndaki stratejik konumunu korumuştur.' },
    { name: 'Baksı Müzesi', desc: 'Sanatçı Hüsamettin Koçan’ın kurduğu bu müze, Çoruh Vadisi’ne bakan bir dağ tepesindeki eşsiz konumuyla çağdaş sanatı geleneksel el sanatlarıyla buluşturur. Avrupa Konseyi Müze Ödülü’nü kazanan bu yenilikçi mekân, kırsal ile modern sanatı harmanlar.' },
    { name: 'Aydıntepe Yeraltı Şehri', desc: 'Tüf kayalara oyulmuş bu antik yeraltı şehri, birbirine tünellerle bağlı geniş galerileri ve odalarıyla dikkat çeker. Roma ve Bizans dönemlerinde sığınak olarak kullanıldığı düşünülen yapı, bölgenin gizli tarihine ışık tutar.' },
  ],
  zonguldak: [
    { name: 'Gökgöl Mağarası', desc: 'Yaklaşık 3 kilometre uzunluğuyla Türkiye’nin en uzun mağaralarından biri olan Gökgöl, içindeki yeraltı suları, gölleri ve görkemli sarkıt-dikit oluşumlarıyla büyüler. Düzenlenmiş yürüyüş yollarıyla ziyaretçilere etkileyici bir yeraltı yolculuğu sunar.' },
    { name: 'Cehennemağzı Mağaraları', desc: 'Antik çağda mitolojik öneme sahip bu mağaralar, efsaneye göre yer altı dünyasına açılan kapılardan biri olarak görülüyordu. İçlerinde bulunan erken Hristiyanlık dönemine ait kilise kalıntıları, bölgenin katmanlı dini geçmişine ışık tutar.' },
    { name: 'Filyos (Tios) Antik Kenti', desc: 'Karadeniz kıyısındaki bu antik liman kenti, tiyatrosu, hamamı ve sur kalıntılarıyla bölgenin köklü tarihine tanıklık eder. Deniz ticaretinin canlı bir merkezi olan Tios, kazılarla gün yüzüne çıkarılan zengin kalıntılarıyla dikkat çeker.' },
  ],
  duzce: [
    { name: 'Güzeldere Şelalesi', desc: 'Sık bir ormanın içinde yüksek kayalardan dökülen bu görkemli çağlayan, çevresindeki yürüyüş yolları ve seyir terasıyla doğaseverlerin gözdesidir. Yemyeşil manzarası ve serinletici atmosferiyle bölgenin en etkileyici doğa harikalarındandır.' },
    { name: 'Samandere Şelalesi', desc: 'Tabiat anıtı olarak koruma altına alınan bu şelale, ahşap merdivenlerle inilen yosunlu kayaları ve berrak sularıyla masalsı bir görünüm sunar. Çevresindeki asırlık ağaçları ve dingin atmosferiyle huzur arayanların uğrak noktasıdır.' },
    { name: 'Akçakoca', desc: 'Karadeniz kıyısındaki bu şirin sahil ilçesi, tepesindeki Ceneviz kalesi kalıntıları, fındık bahçeleri ve altın kumlu plajlarıyla ünlüdür. Balık restoranları ve sakin atmosferiyle özellikle yaz aylarında sevilen bir tatil noktasıdır.' },
  ],
  bingol: [
    { name: 'Yüzen Adalar', desc: 'Bingöl’ün yüksek yaylalarındaki bu buzul göllerinde, kopan turba parçalarının üzerinde bitki örtüsü oluşarak rüzgârla suyun üstünde hareket eden minik adacıklar meydana gelir. Dünyada nadir görülen bu doğa olayı, göllere büyüleyici bir gizem katar.' },
    { name: 'Kös Kaplıcası', desc: 'Bingöl’ün yer altı zenginliklerinden beslenen bu doğal termal kaynaklar, şifalı olduğuna inanılan sıcak sularıyla bölge halkının sağlık ve dinlenme merkezidir. Doğal ortamdaki konumuyla geleneksel bir kaplıca deneyimi sunar.' },
    { name: 'Buzul (Kral Kızı) Gölleri', desc: 'Bingöl Dağları’nın yüksek kesimlerinde buzul aşındırmasıyla oluşan bu berrak göller, çevrelerini saran alpin çayırlar ve el değmemiş doğasıyla büyüler. Efsanelerle anılan bu göller, doğa yürüyüşçüleri için ulaşılması güç ama ödüllendirici bir hedeftir.' },
  ],
  mus: [
    { name: 'Muş Kalesi', desc: 'Şehre hâkim bir tepe üzerinde yükselen bu kale, kökeni Urartulara uzanan ve çeşitli medeniyetlerce kullanılan stratejik bir savunma yapısıdır. Tarihî kalıntıları ve Muş Ovası’na bakan panoramik konumuyla kentin geçmişine tanıklık eder.' },
    { name: 'Murat Nehri Kanyonu', desc: 'Fırat’ın önemli kollarından Murat Nehri’nin oyduğu bu derin kanyon, coşkulu akan suları ve dramatik kaya duvarlarıyla rafting tutkunlarının gözdesidir. El değmemiş doğası ve zorlu rotalarıyla hem macera hem de eşsiz manzaralar sunar.' },
    { name: 'Menekşe Ovaları', desc: 'Muş Ovası, ilkbaharda milyonlarca yabani menekşenin açmasıyla mora boyanan geniş düzlükleriyle ünlüdür. Bu görsel şölen, bölgenin bereketli toprakları ve doğal güzelliğinin en çarpıcı ifadesi olarak her yıl tekrarlanır.' },
  ],
  hakkari: [
    { name: 'Cilo-Sat Dağları & Buzullar', desc: 'Türkiye’nin en yüksek ikinci zirvesini (Reşko, 4.135 m) barındıran bu sarp dağlar, Alpler dışında Avrupa’nın nadir aktif buzullarına ev sahipliği yapar. Buzul gölleri ve keskin zirveleriyle bir milli park olan bölge, dağcılık tutkunlarının rüyasıdır.' },
    { name: 'Meydan Medresesi', desc: 'Hakkâri’nin merkezindeki bu tarihî taş medrese, bölgede yüzyıllarca süren köklü ilim ve eğitim geleneğinin önemli bir merkeziydi. Kesme taş işçiliği ve mimarisiyle kentin en değerli tarihî yapılarından biridir.' },
    { name: 'Zap Vadisi', desc: 'Büyük Zap Suyu’nun oluşturduğu bu derin ve sarp kanyon, coşkulu akarsuyu ve dramatik kaya duvarlarıyla nefes kesici manzaralar sunar. Bölgenin en etkileyici doğal oluşumlarından biri olan vadi, rafting ve doğa fotoğrafçılığı için idealdir.' },
  ],
  siirt: [
    { name: 'Ulu Camii', desc: '12. yüzyılda Selçuklu-Artuklu döneminde inşa edilen bu cami, süslemeli tuğla minaresi ve ahşap işçilikli minberiyle Siirt’in en eski ve en değerli tarihî yapılarından biridir. Yüzyıllara meydan okuyan mimarisiyle bölgenin köklü geçmişini yansıtır.' },
    { name: 'Tillo (Aydınlar)', desc: 'Osmanlı döneminde önemli bir ilim ve tasavvuf merkezi olan bu tarihî belde, ünlü âlim İbrahim Hakkı’nın yaşadığı yer olarak bilinir. Yılda iki kez güneşin bir tepedeki türbenin penceresinden içeri düşüp bir mezarı aydınlattığı astronomik “ışık olayı” ile ünlüdür.' },
    { name: 'Botan Vadisi', desc: 'Botan Çayı’nın oyduğu bu görkemli vadi, sarp kanyonları, berrak suları ve termal kaynaklarıyla eşsiz bir doğa alanıdır. Zengin biyoçeşitliliği ve dramatik manzaralarıyla milli park statüsündeki vadi, doğa turizminin gözde noktalarındandır.' },
  ],
  sirnak: [
    { name: 'Cizre', desc: 'Dicle kıyısındaki bu köklü kent, ünlü mucit El-Cezeri’nin memleketi olup Kırmızı Medrese, Nuh Peygamber Türbesi ve tarihî köprüsüyle zengin bir mirasa sahiptir. Farklı inanç ve kültürlerin buluştuğu Cizre, binlerce yıllık katmanlı tarihiyle dikkat çeker.' },
    { name: 'Cudi Dağı', desc: 'Yerel inanışa ve bazı kutsal metinlere göre Nuh’un Gemisi’nin tufandan sonra karaya oturduğu yer olarak kabul edilen bu dağ, üç semavi din için manevi öneme sahiptir. Efsaneleri ve zirvesindeki kalıntılarıyla kutsal bir çekim merkezidir.' },
    { name: 'Faraşin Yaylası', desc: 'Cudi ve Gabar dağlarının yüksek kesimlerindeki bu geniş yayla, uçsuz bucaksız yeşil otlakları ve serin havasıyla yüzyıllardır göçerlerin gözde otlağı olmuştur. Doğal güzelliği ve panoramik manzarasıyla bölgenin en görkemli yaylalarındandır.' },
  ],
  ardahan: [
    { name: 'Çıldır Gölü', desc: 'Türkiye’nin ikinci büyük tektonik gölü olan Çıldır, kışın tamamen donarak üzerinde atlı kızak turları ve Eskimo usulü buz balıkçılığı yapılan büyülü bir manzaraya dönüşür. Buz tutan yüzeyi ve karlı dağ manzarasıyla eşsiz bir kış turizmi merkezidir.' },
    { name: 'Şeytan Kalesi', desc: 'Derin bir vadinin üzerindeki sarp kayalıklara kurulan bu ortaçağ kalesi, ulaşılmaz konumu ve dramatik manzarasıyla adını hak eder. Urartu dönemine uzanan kökeni ve çevresindeki nefes kesici doğasıyla gizemli bir tarih atmosferi sunar.' },
    { name: 'Atatürk Silüeti (Cıncırlı)', desc: 'Ardahan yakınlarındaki bir dağ sırtının, belli bir açıdan bakıldığında Atatürk’ün profilini andıran doğal oluşumu, bölgenin ilginç bir görsel merakıdır. Doğanın şekillendirdiği bu silüet, ziyaretçilerin ilgisini çeken simgesel bir noktadır.' },
  ],
  igdir: [
    { name: 'Ağrı Dağı Manzarası', desc: 'Iğdır Ovası, Türkiye’nin en yüksek zirvesi olan Ağrı Dağı’na en yakın ve en görkemli bakış açısını sunar. Karlı zirvesiyle ovaya tepeden bakan bu heybetli dağ, kentin her noktasından görülebilen etkileyici bir doğa anıtıdır.' },
    { name: 'Meteor Çukuru', desc: 'Iğdır’da bir göktaşının çarpmasıyla oluştuğu düşünülen bu çukur, dünyanın en büyük meteor çarpma kraterlerinden biri olarak kabul edilir. Türkiye-Ermenistan sınırındaki bu ilginç jeolojik oluşum, bilimsel merak uyandıran bir noktadır.' },
    { name: 'Karakoyunlu Kalıntıları', desc: 'Iğdır bölgesi, adını da veren Karakoyunlu devletinden ve daha eski medeniyetlerden kalma höyükler ile tarihî yapı kalıntılarını barındırır. Bu izler, Doğu Anadolu’nun kavşak noktasındaki bölgenin köklü ve katmanlı geçmişine ışık tutar.' },
  ],
  agri: [
    { name: 'Ağrı Dağı (5137 m)', desc: '5.137 metrelik zirvesiyle Türkiye’nin en yüksek dağı olan bu sönmüş volkan, üç semavi dine göre Nuh’un Gemisi’nin karaya oturduğu yer olarak kutsal kabul edilir. Karlı zirvesi ve efsaneleriyle dağcılar ve inanç turizmi için eşsiz bir çekim merkezidir.' },
    { name: 'İshak Paşa Sarayı', desc: 'Doğubayazıt’ta 18. yüzyılda tamamlanan bu görkemli saray, Selçuklu, Osmanlı, Gürcü ve Fars mimarisini harmanlayan eşsiz üslubuyla ünlüdür. Ağrı Dağı’na bakan konumu, merkezi ısıtma sistemi ve zarif taş işçiliğiyle bir masal sarayını andırır.' },
    { name: 'Nuh’un Gemisi (Üzengili)', desc: 'Üzengili köyü yakınlarındaki bu gemi biçimli jeolojik oluşum, bazı araştırmacılara göre Nuh’un Gemisi’nin kalıntılarıdır. Ağrı Dağı’nın eteklerindeki bu ilginç formasyon, hem bilimsel merak hem de dini inanç açısından ziyaretçi çeken bir noktadır.' },
    { name: 'Balık Gölü', desc: 'Yaklaşık 2.250 metre yükseklikteki bir platoda yer alan bu berrak krater gölü, adını bol miktarda barındırdığı alabalıklarından alır. Çevresini saran yeşil çayırlar ve dingin atmosferiyle huzurlu bir yüksek dağ cennetidir.' },
    { name: 'Diyadin Kaplıcaları', desc: 'Murat Nehri’nin oyduğu bir kanyon içinde yer alan bu termal kaynaklar, sıcak sularının oluşturduğu travertenler ve doğal buhar manzarasıyla eşsizdir. Şifalı olduğuna inanılan suları ve dramatik kanyon ortamıyla benzersiz bir kaplıca deneyimi sunar.' },
  ],

  // --- Avustralya & Okyanusya ---
  sydney: [
    { name: 'Opera Binası', desc: 'Yelkenleri veya deniz kabuklarını andıran eşsiz çatısıyla bu yapı, 20. yüzyıl mimarisinin en özgün başyapıtlarından biridir. Sydney Limanı’na uzanan bu simge, Avustralya’nın dünyaca tanınan yüzü ve UNESCO Dünya Mirası’dır.' },
    { name: 'Liman Köprüsü', desc: '“Askı” (Coathanger) lakabıyla anılan bu devasa çelik kemer köprü, 1932’de tamamlandığında bir mühendislik harikasıydı. Zirvesine yapılan tırmanış (BridgeClimb), Opera Binası ve limanın nefes kesen panoramasını sunar.' },
    { name: 'Bondi Plajı', desc: 'Sydney’in altın kumlu bu ünlü plajı, sörfçüleri, canlı atmosferi ve plaj kültürüyle Avustralya yaşam tarzının simgesidir. Kayalıklar boyunca uzanan Bondi-Coogee sahil yürüyüşü, muhteşem okyanus manzaraları sunar.' },
    { name: 'The Rocks', desc: 'Sydney’in ilk Avrupa yerleşiminin kurulduğu bu tarihî mahalle, dar arnavut kaldırımlı sokakları ve eski taş binalarıyla kentin doğduğu yerdir. Sömürge dönemi geçmişini yaşatan hafta sonu pazarları ve tarihî pub’larıyla ünlüdür.' },
    { name: 'Darling Harbour', desc: 'Bir zamanlar sanayi limanı olan bu alan, bugün Sydney’in en canlı eğlence ve dinlence merkezidir. Dev akvaryumu, müzeleri, restoranları ve su kenarı promenadıyla ailelerin ve ziyaretçilerin gözde noktasıdır.' },
    { name: 'Manly & Feribot', desc: 'Sydney merkezinden Manly’ye yapılan feribot yolculuğu, Opera Binası ve Liman Köprüsü manzarası eşliğinde başlı başına bir deneyimdir. Varış noktasındaki Manly, hem okyanus hem de liman plajlarıyla sevilen bir sahil beldesidir.' },
    { name: 'Blue Mountains', desc: 'Sydney yakınlarındaki bu milli park, adını okaliptüs ağaçlarının yaydığı yağın havaya verdiği mavimsi pustan alır. Efsaneleşmiş “Üç Kızkardeş” kaya oluşumu, derin vadileri ve ormanlarıyla nefes kesen bir doğa harikasıdır.' },
    { name: 'Queen Victoria Building', desc: '19. yüzyıl sonunda inşa edilen bu görkemli Victoria dönemi yapısı, zarif kubbesi, vitrayları ve tarihî saatiyle bir alışveriş sarayıdır. Mimar Pierre Cardin’in “dünyanın en güzel alışveriş merkezi” dediği bu bina, kentin zarafetini yansıtır.' },
  ],
  melbourne: [
    { name: 'Federation Square', desc: 'Melbourne’ün çağdaş kalbi olan bu meydan, cesur ve modern mimarisiyle dikkat çeken bir kültür ve etkinlik merkezidir. Müzeleri, galerileri ve kafeleriyle kentin en önemli buluşma noktası ve sosyal yaşamının odağıdır.' },
    { name: 'Hosier Lane', desc: 'Melbourne, dünyaca ünlü sokak sanatı sahnesiyle tanınır ve Hosier Lane bunun en canlı sergi alanıdır. Duvarları sürekli değişen grafiti ve muralarla kaplı bu ara sokak, kentin yaratıcı ve alternatif ruhunu yansıtan bir açık hava galerisidir.' },
    { name: 'Queen Victoria Market', desc: '1878’den beri faaliyet gösteren bu tarihî pazar, güney yarımkürenin en büyük açık hava pazarıdır. Taze ürünler, yerel lezzetler ve el sanatları sunan yüzlerce tezgâhıyla Melbourne’ün canlı bir kültür ve gastronomi simgesidir.' },
    { name: 'Great Ocean Road', desc: 'Dünyanın en görkemli sahil yollarından biri olan bu güzergâh, I. Dünya Savaşı gazileri tarafından inşa edilmiştir. Okyanustan yükselen kireçtaşı sütunları “Oniki Havari” ve dramatik kıyı manzaralarıyla unutulmaz bir yolculuk sunar.' },
    { name: 'Royal Botanic Gardens', desc: 'Yarra Nehri kıyısındaki bu geniş botanik bahçesi, dünyanın dört bir yanından getirilen binlerce bitki türünü barındıran huzurlu bir vahadır. Gölleri, çimenlikleri ve zengin bitki örtüsüyle kentlilerin en sevdiği yeşil dinlenme alanıdır.' },
  ],
  cairns: [
    { name: 'Büyük Set Resifi', desc: 'Uzaydan bile görülebilen dünyanın en büyük mercan resif sistemi olan bu doğa harikası, Cairns’in başlıca cazibesidir. Binlerce mercan türü ve rengârenk deniz canlısına ev sahipliği yapan bu resif, dalış ve şnorkel için bir cennettir.' },
    { name: 'Daintree Yağmur Ormanı', desc: 'Yaklaşık 180 milyon yıllık geçmişiyle dünyanın yaşayan en eski tropik yağmur ormanı olan Daintree, benzersiz bir ekosistemdir. Nadir bitki ve hayvan türlerine ev sahipliği yapan bu orman, ormanın denizle buluştuğu eşsiz bir alandır.' },
    { name: 'Kuranda', desc: 'Yağmur ormanının içindeki bu şirin dağ köyüne, tarihî ve manzaralı bir demiryolu treni ile ya da orman üzerinden geçen bir teleferik (Skyrail) ile ulaşılır. Sanatçı pazarları ve doğa parklarıyla popüler bir gezi noktasıdır.' },
    { name: 'Esplanade Lagoon', desc: 'Cairns sahil şeridi boyunca uzanan bu ücretsiz halka açık yüzme lagünü, tropik iklimde serinlemek için ideal bir mekândır. Çevresindeki yürüyüş yolları, barbekü alanları ve deniz manzarasıyla kentin canlı bir buluşma noktasıdır.' },
  ],
  uluru: [
    { name: 'Uluru Gün Doğumu/Batımı', desc: 'Avustralya’nın kızıl çölünün ortasında yükselen bu devasa kutsal kaya, gün doğumu ve batımında güneş ışığıyla akkordan mora dönen büyüleyici renk değişimleriyle ünlüdür. Yerli Anangu halkı için kutsal olan bu anıt, benzersiz bir doğa gösterisidir.' },
    { name: 'Base Walk', desc: 'Uluru’nun çevresini saran yaklaşık 10 kilometrelik bu yürüyüş rotası, kayanın devasa boyutlarını yakından deneyimletir. Yol boyunca antik Aborjin kaya resimleri, su birikintileri ve kutsal alanlar görülerek yerli kültürüne dair bilgiler edinilir.' },
    { name: 'Kata Tjuta', desc: 'Uluru’nun yakınındaki bu 36 devasa kubbeli kaya oluşumu, adının anlamı olan “çok başlı” tanımını hak eder. Rüzgârlı Vadi (Valley of the Winds) gibi yürüyüş rotalarıyla, yerli halk için Uluru kadar kutsal olan bir başka doğa harikasıdır.' },
    { name: 'Field of Light', desc: 'Sanatçı Bruce Munro’nun çöle yerleştirdiği bu devasa enstalasyon, karanlık çöktüğünde yumuşak bir ışıkla parlayan binlerce cam küreden oluşur. Yıldızlı gökyüzü altında Uluru manzarası eşliğinde büyüleyici bir ışık deneyimi sunar.' },
  ],
  auckland: [
    { name: 'Sky Tower', desc: '328 metre yüksekliğiyle güney yarımkürenin en yüksek serbest duran yapısı olan bu kule, Auckland siluetine hâkimdir. Gözlem terasından şehrin ve iki limanın panoraması izlenirken, cesur ziyaretçiler kuleden atlayış (SkyJump) yapabilir.' },
    { name: 'Waiheke Adası', desc: 'Auckland’dan kısa bir feribot yolculuğuyla ulaşılan bu ada, ödüllü üzüm bağları, zeytinlikleri ve altın kumlu koylarıyla ünlüdür. Şarap tadımı, sanat galerileri ve huzurlu plajlarıyla popüler bir kaçış noktasıdır.' },
    { name: 'Mt Eden', desc: 'Auckland’ın üzerine kurulduğu volkanik alandaki bu sönmüş volkan, zirvesindeki çim kaplı kraterle dikkat çeker. Kentin en yüksek doğal noktalarından biri olarak, şehrin ve limanlarının 360 derecelik muhteşem manzarasını sunar.' },
    { name: 'Auckland Müzesi', desc: 'Görkemli neoklasik binasıyla bu müze, Yeni Zelanda’nın yerli Maori halkının kültürüne dair dünyanın en önemli koleksiyonlarından birini barındırır. Geleneksel bir savaş kanosu ve düzenlenen canlı Maori kültür gösterileriyle (haka) büyüler.' },
  ],
  queenstown: [
    { name: 'Kawarau Bungee', desc: 'Queenstown yakınlarındaki Kawarau Köprüsü, 1988’de dünyanın ilk ticari bungee jumping merkezinin kurulduğu yerdir. 43 metre yükseklikten nehre atlayışın doğduğu bu nokta, kentin “dünyanın macera başkenti” unvanını simgeler.' },
    { name: 'Skyline Gondola', desc: 'Bob’s Peak’e çıkan bu dik teleferik, Queenstown’ın, Wakatipu Gölü’nün ve karlı “The Remarkables” dağ silsilesinin nefes kesen panoramasını sunar. Zirvedeki restoran, kızak parkuru (luge) ve macera aktiviteleriyle popülerdir.' },
    { name: 'Milford Sound', desc: 'Yazar Kipling’in “dünyanın sekizinci harikası” dediği bu görkemli fiyort, dik kayalıklardan dökülen şelaleleri ve dramatik manzarasıyla büyüler. Tekne turlarıyla keşfedilen bu doğa harikası, Yeni Zelanda’nın en ünlü noktalarındandır.' },
    { name: 'TSS Earnslaw', desc: '1912’de suya indirilen bu tarihî buharlı gemi, güney yarımkürede hâlâ faal olan nadir buharlı yolcu gemilerindendir. “Göllerin Leydisi” lakaplı bu zarif gemiyle Wakatipu Gölü’nde yapılan tur, nostaljik bir deneyim sunar.' },
  ],

  // --- Amerika ---
  newyork: [
    { name: 'Özgürlük Heykeli & Ellis Island', desc: 'Fransa’nın ABD’ye armağan ettiği Özgürlük Heykeli, milyonlarca göçmeni karşılayan özgürlük ve demokrasi simgesidir. Yanındaki Ellis Island ise bir zamanlar Amerika’ya gelen göçmenlerin ilk durağı olan tarihî giriş kapısıydı.' },
    { name: 'Central Park', desc: 'Manhattan’ın gökdelenleri arasında uzanan bu devasa park, 19. yüzyılda tasarlanmış bir kentsel vahadır. Gölleri, çayırları ve yürüyüş yollarıyla New Yorkluların nefes aldığı, sayısız filme sahne olmuş dünyanın en ünlü şehir parkıdır.' },
    { name: 'Times Square', desc: 'Devasa dijital reklam panoları ve ışıklarıyla hiç uyumayan bu meydan, New York’un enerjisinin simgesidir. Broadway tiyatrolarının kalbindeki bu alan, özellikle yılbaşı kutlamalarıyla dünya çapında tanınır.' },
    { name: 'Empire State Building', desc: '1931’de tamamlanan bu 102 katlı art deco gökdelen, uzun yıllar dünyanın en yüksek binası olarak New York siluetinin simgesi olmuştur. Gözlem teraslarından şehrin nefes kesen 360 derecelik panoraması izlenir.' },
    { name: '9/11 Memorial & One WTC', desc: 'İkiz Kuleler’in yıkıldığı yere kurulan bu anıt, kulelerin temellerine yerleştirilen iki devasa yansıma havuzuyla hayatını kaybedenleri anar. Yanında yükselen One World Trade Center ise kentin dirilişini ve umudu simgeler.' },
    { name: 'Metropolitan Müzesi', desc: 'Dünyanın en büyük ve en kapsamlı sanat müzelerinden biri olan “The Met”, beş bin yıllık insanlık tarihini kucaklayan iki milyondan fazla eser barındırır. Antik Mısır tapınaklarından Avrupa resmine uzanan koleksiyonu bir kültür hazinesidir.' },
    { name: 'Brooklyn Köprüsü & DUMBO', desc: '1883’te açılan bu neo-gotik taş kuleli asma köprü, bir mühendislik harikası olarak Manhattan ve Brooklyn’i birleştirir. Üzerinde yürünen köprü ve karşısındaki DUMBO semti, Manhattan silüetinin en ikonik manzaralarını sunar.' },
    { name: 'High Line & Chelsea', desc: 'Kullanılmayan yüksek bir demiryolu hattından dönüştürülen High Line, şehrin üzerinde uzanan yeşil bir yürüyüş parkıdır. Geçtiği sanatsal Chelsea semtiyle birlikte, kentsel dönüşümün yaratıcı ve başarılı bir örneğidir.' },
    { name: 'Rockefeller Center (Top of the Rock)', desc: 'Bu art deco yapılar topluluğu, kışın buz pisti ve dev Noel ağacıyla ünlüdür. Tepesindeki “Top of the Rock” gözlem terası, Central Park ve Empire State Building manzarasını bir arada sunan en gözde bakış noktalarındandır.' },
  ],
  sanfrancisco: [
    { name: 'Golden Gate Köprüsü', desc: '1937’de tamamlanan bu görkemli kızıl asma köprü, San Francisco Körfezi’ni okyanusa bağlayan boğazın üzerinde yükselir. Zarif mimarisi ve sıkça sisle kaplanan atmosferiyle dünyanın en tanınan ve en çok fotoğraflanan köprülerindendir.' },
    { name: 'Alcatraz', desc: 'San Francisco Körfezi’nin ortasındaki bu ada, bir zamanlar Al Capone gibi ünlü suçluların tutulduğu, kaçılması imkânsız kabul edilen federal hapishaneye ev sahipliği yapıyordu. Bugün ürpertici hücreleriyle popüler bir müze-adadır.' },
    { name: 'Fisherman’s Wharf', desc: 'San Francisco’nun tarihî balıkçı limanı olan bu bölge, taze deniz ürünleri, özellikle de meşhur Dungeness yengeci ile ünlüdür. Pier 39 iskelesindeki güneşlenen deniz aslanları kolonisi, buranın en sevilen cazibesidir.' },
    { name: 'Cable Car', desc: '19. yüzyıldan beri hizmet veren bu tarihî halatlı tramvaylar, San Francisco’nun ünlü dik tepelerini tırmanan dünyanın son manuel işletilen sistemidir. Kentin hareketli bir simgesi olan bu tramvaylar, nostaljik bir yolculuk sunar.' },
    { name: 'Lombard Street', desc: 'Sarp bir yamaçta yer alan bu sokağın bir bölümü, sekiz keskin virajıyla “dünyanın en dolambaçlı sokağı” olarak ünlüdür. Çiçek tarhlarıyla süslü bu zikzaklı yol, San Francisco’nun en pitoresk ve en çok ziyaret edilen noktalarındandır.' },
  ],
  losangeles: [
    { name: 'Hollywood & Walk of Fame', desc: 'Dünya sinemasının başkenti olan Hollywood, tepedeki ikonik beyaz tabelasıyla hayal dünyasının simgesidir. Kaldırımlarına gömülü yıldızlarla ünlüleri onurlandıran Şöhret Yolu (Walk of Fame), sinema tutkunlarının uğrak yeridir.' },
    { name: 'Griffith Gözlemevi', desc: 'Hollywood Tepeleri’nde yer alan bu art deco gözlemevi, ücretsiz teleskopları ve bilim sergileriyle popülerdir. Ancak asıl ünü, Los Angeles şehrinin ve ünlü Hollywood tabelasının en muhteşem panoramasını sunmasından gelir.' },
    { name: 'Santa Monica & Venice', desc: 'Efsanevi Route 66 karayolunun bittiği Santa Monica İskelesi, lunaparkı ve plajıyla ünlüdür. Komşu Venice Beach ise vücut geliştirmecileri, sokak sanatçıları ve kanallarıyla Kaliforniya sahil kültürünün en renkli yüzüdür.' },
    { name: 'Getty Center', desc: 'Bir tepenin üzerinde yükselen bu görkemli sanat müzesi, beyaz travertenden yapılmış modern mimarisi ve bahçeleriyle büyüler. Van Gogh’un “İrisler”i gibi başyapıtları ve şehrin panoramasını ücretsiz olarak sunmasıyla ünlüdür.' },
    { name: 'Universal Studios', desc: 'Hem faal bir film stüdyosu hem de bir eğlence parkı olan bu kompleks, ziyaretçilere sinema dünyasının kulisini deneyimletir. Popüler filmlere dayanan hız trenleri ve stüdyo turuyla Hollywood büyüsünü yaşatan bir cazibe merkezidir.' },
  ],
  lasvegas: [
    { name: 'The Strip', desc: 'Las Vegas’ın kalbi olan bu yaklaşık 7 kilometrelik bulvar, dünyanın en büyük ve en gösterişli temalı otel-kumarhanelerine ev sahipliği yapar. Paris’ten Venedik’e dünya şehirlerini canlandıran devasa yapılarıyla bir eğlence ve ışık cümbüşüdür.' },
    { name: 'Bellagio Fountains', desc: 'Bellagio Oteli’nin önündeki devasa yapay gölde sergilenen bu su gösterisi, müzik eşliğinde 140 metre yüksekliğe fışkıran fıskiyeleriyle büyüler. Las Vegas’ın en ikonik ve ücretsiz gösterilerinden biri olarak izleyicileri hayran bırakır.' },
    { name: 'Fremont Street', desc: 'Las Vegas’ın kumar tarihinin başladığı bu eski cadde, üzerini tamamen kaplayan devasa bir LED ışık ve ses gösterisiyle (Viva Vision) ünlüdür. Tarihî kazinoları ve canlı atmosferiyle “Eski Vegas”ın nostaljik ruhunu yaşatır.' },
    { name: 'Grand Canyon Turu', desc: 'Las Vegas, dünyanın en görkemli doğa harikalarından biri olan Grand Canyon’a düzenlenen turlar için ideal bir başlangıç noktasıdır. Milyonlarca yılda Colorado Nehri’nin oyduğu bu devasa kanyon, uçak, helikopter veya araçla ulaşılan nefes kesici bir hedeftir.' },
  ],
  washington: [
    { name: 'National Mall', desc: 'ABD başkentinin kalbindeki bu geniş yeşil tören alanı, Capitol binasından Lincoln Anıtı’na uzanır. Ulusal anıtları, müzeleri ve büyük gösterilere ev sahipliği yapan konumuyla Amerikan demokrasisinin sembolik merkezidir.' },
    { name: 'Capitol & Beyaz Saray', desc: 'Görkemli kubbesiyle Capitol binası, ABD Kongresi’nin toplandığı yasama merkezidir. Yakınındaki Beyaz Saray ise iki yüzyıldan uzun süredir ABD başkanlarının hem ikametgâhı hem de çalışma ofisi olan yürütmenin kalbidir.' },
    { name: 'Lincoln Anıtı', desc: 'Bir Yunan tapınağını andıran bu anıt, Başkan Abraham Lincoln’ün devasa oturan heykelini barındırır. Önündeki uzun yansıma havuzuyla, Martin Luther King’in ünlü “Bir Hayalim Var” konuşmasına sahne olan ikonik bir mekândır.' },
    { name: 'Smithsonian Müzeleri', desc: 'National Mall çevresinde toplanan bu müze topluluğu, dünyanın en büyük müze ve araştırma kompleksidir. Hava-Uzay’dan Doğa Tarihi’ne uzanan ve tamamı ücretsiz olan bu müzeler, insanlık ve bilim tarihinin bir hazinesidir.' },
    { name: 'Arlington Mezarlığı', desc: 'ABD’nin savaşlarda hayatını kaybeden askerlerinin ve önemli devlet adamlarının gömüldüğü bu ulusal anıt mezarlık, sonsuz beyaz mezar taşlarıyla dokunaklı bir manzara sunar. Meçhul Asker Anıtı’ndaki nöbet değişimi töreni saygıyla izlenir.' },
  ],
  toronto: [
    { name: 'CN Tower', desc: '553 metre yüksekliğiyle uzun yıllar dünyanın en yüksek serbest duran yapısı olan bu kule, Toronto’nun simgesidir. Cam zeminli gözlem terası ve döner restoranıyla şehrin ve Ontario Gölü’nün baş döndürücü manzarasını sunar.' },
    { name: 'Niagara Şelalesi', desc: 'Toronto yakınlarındaki bu dünyaca ünlü şelaleler, muazzam su hacmi ve gücüyle nefes kesen bir doğa harikasıdır. At Nalı Şelalesi başta olmak üzere, tekne turları ve seyir noktalarıyla milyonlarca ziyaretçiyi kendine çeker.' },
    { name: 'Distillery District', desc: 'Bir zamanlar Kuzey Amerika’nın en büyük içki damıtımevi olan bu bölge, korunmuş Viktorya dönemi kırmızı tuğla binalarıyla büyüler. Bugün sanat galerileri, butikleri ve restoranlarıyla araç trafiğine kapalı canlı bir kültür ve sanat semtidir.' },
    { name: 'Toronto Islands', desc: 'Şehir merkezinden kısa bir feribot yolculuğuyla ulaşılan bu göl adaları, araçsız yolları, plajları ve parklarıyla huzurlu bir kaçış sunar. Adalardan, Toronto siluetinin ve CN Tower’ın en muhteşem manzarası izlenir.' },
    { name: 'Royal Ontario Museum', desc: 'Kanada’nın en büyük müzelerinden biri olan ROM, tarihî binasına eklenen çarpıcı kristal biçimli modern cephesiyle dikkat çeker. Dünya kültürleri ve doğa tarihine adanmış devasa koleksiyonuyla, dinozorlardan mumyalara uzanan bir hazinedir.' },
  ],
  vancouver: [
    { name: 'Stanley Park', desc: 'Vancouver’ın yarımadasını kaplayan bu devasa park, New York’un Central Park’ından bile büyüktür ve deniz kıyısı yürüyüş yolu (seawall) ile çevrilidir. Yağmur ormanları, plajları ve yerli halkın totem direkleriyle kentin doğal bir mücevheridir.' },
    { name: 'Capilano Asma Köprüsü', desc: 'Bir nehir vadisinin 70 metre üzerinde ve 140 metre boyunca uzanan bu asma köprü, adım attıkça sallanarak heyecan verici bir deneyim sunar. Çevresindeki dev ağaçlar arasında uzanan yürüyüş yollarıyla bir orman macerasıdır.' },
    { name: 'Granville Island', desc: 'Eski bir sanayi bölgesinden dönüştürülen bu yarımada, ünlü halk pazarı, sanatçı stüdyoları ve tiyatrolarıyla canlı bir kültür merkezidir. Taze yerel ürünler sunan pazarı ve su kenarı atmosferiyle kentin en sevilen mekânlarındandır.' },
    { name: 'Grouse Mountain', desc: 'Vancouver’a tepeden bakan bu dağa, “Skyride” adı verilen büyük bir teleferikle çıkılır ve şehrin muhteşem panoraması izlenir. Kışın kayak merkezi, yazın ise yürüyüş ve yaban hayatı gözlemiyle dört mevsim popülerdir.' },
    { name: 'Gastown', desc: 'Vancouver’ın doğduğu yer olan bu en eski mahalle, arnavut kaldırımlı sokakları ve Viktorya dönemi mimarisiyle büyüler. Her 15 dakikada bir buhar püskürterek çalan ünlü buharlı saati, semtin en tanınan ve en çok fotoğraflanan simgesidir.' },
  ],
  montreal: [
    { name: 'Eski Montreal & Notre-Dame', desc: 'Şehrin tarihî çekirdeği olan Eski Montreal, arnavut kaldırımlı sokakları ve Avrupa esintili mimarisiyle büyüler. Merkezindeki görkemli neo-gotik Notre-Dame Bazilikası, göz kamaştıran mavi ve altın rengi iç mekânıyla nefes kesicidir.' },
    { name: 'Mont Royal', desc: 'Şehre adını veren bu ağaçlıklı tepe, Central Park’ı da tasarlayan mimar tarafından düzenlenen geniş bir kent parkıdır. Zirvesindeki bakış terasından, Montreal’in ve Saint Lawrence Nehri’nin muhteşem panoraması izlenir.' },
    { name: 'Jean-Talon Market', desc: 'Kuzey Amerika’nın en büyük açık hava pazarlarından biri olan bu canlı merkez, Quebec bölgesinin taze ürünlerini, peynirlerini ve yerel lezzetlerini sunar. Renkli tezgâhları ve hareketli atmosferiyle kentin gastronomi kültürünün kalbidir.' },
    { name: 'Yeraltı Şehri', desc: 'Montreal’in sert kışlarına karşı geliştirilen bu devasa yeraltı ağı (RÉSO), 32 kilometreyi aşan tünellerle mağazaları, otelleri ve metro istasyonlarını birbirine bağlar. Dünyanın en büyük yeraltı komplekslerinden biri olarak korunaklı bir yaşam sunar.' },
  ],
  mexicocity: [
    { name: 'Zócalo & Katedral', desc: 'Dünyanın en büyük şehir meydanlarından biri olan Zócalo, Aztek başkenti Tenochtitlan’ın kalbi üzerine kuruludur. Kenarındaki Metropolitan Katedrali ise Amerika kıtasının en büyük ve en eski katedrali olarak sömürge döneminin görkemini yansıtır.' },
    { name: 'Teotihuacan', desc: 'Aztekler’den bile önce kurulan bu görkemli antik kent, devasa Güneş ve Ay Piramitleri’yle bir zamanlar Amerika’nın en büyük yerleşimlerindendi. “Tanrıların Şehri” anlamına gelen bu UNESCO alanı, gizemli kurucularıyla hayranlık uyandırır.' },
    { name: 'Antropoloji Müzesi', desc: 'Meksika’nın zengin Kolomb öncesi mirasına adanan bu müze, dünyanın en önemli arkeoloji müzelerindendir. Ünlü Aztek Güneş Taşı (takvim) ve devasa yerli uygarlık eserleriyle ülkenin tarihini büyüleyici bir şekilde sergiler.' },
    { name: 'Frida Kahlo Evi', desc: 'Ünlü ressam Frida Kahlo’nun doğduğu, yaşadığı ve öldüğü bu “Mavi Ev” (Casa Azul), bugün onun hayatına ve sanatına adanmış bir müzedir. Sanatçının kişisel eşyaları ve eserleriyle onun renkli ve trajik dünyasına bir pencere açar.' },
    { name: 'Xochimilco', desc: 'Aztek döneminden kalma bu kanal ağı, üzerinde rengârenk boyalı “trajinera” adı verilen düz teknelerle gezilir. Müzisyenler ve yüzen yemek satıcılarıyla dolu bu neşeli su yolları, kentin canlı ve geleneksel yüzünü yansıtır.' },
    { name: 'Chapultepec & Kale', desc: 'Latin Amerika’nın en büyük şehir parklarından olan Chapultepec, müzeleri ve gölleriyle kentin akciğeridir. Bir tepenin üzerindeki Chapultepec Kalesi ise, bir zamanlar İmparator Maximilian’ın ikametgâhı olan görkemli bir saraydır.' },
    { name: 'Coyoacán', desc: 'Bir zamanlar ayrı bir köy olan Coyoacán, arnavut kaldırımlı sokakları, renkli evleri ve canlı meydanlarıyla kentin en bohem semtlerindendir. Frida Kahlo ve Diego Rivera’nın yaşadığı bu mahalle, güçlü bir sanatsal atmosfere sahiptir.' },
    { name: 'Palacio de Bellas Artes', desc: 'Beyaz mermeri ve art nouveau ile art deco üsluplarını birleştiren bu görkemli kültür sarayı, Mexico City’nin en güzel yapısıdır. Diego Rivera gibi ünlü sanatçıların devasa duvar resimlerini (mural) barındırır ve operaya ev sahipliği yapar.' },
  ],
  cancun: [
    { name: 'Chichén Itzá', desc: 'Maya uygarlığının en görkemli şehirlerinden olan bu antik alan, merkezindeki dev El Castillo (Kukulkán) piramidiyle ünlüdür. Ekinoks günlerinde piramidin basamaklarına düşen yılan gölgesiyle astronomik bir harika olan bu alan, dünyanın yeni yedi harikasındandır.' },
    { name: 'Tulum', desc: 'Turkuaz Karayip Denizi’ne bakan bir uçurumun üzerine kurulu bu antik Maya kenti, dünyanın en pitoresk arkeolojik alanlarından biridir. Bir zamanlar önemli bir liman ve ticaret merkezi olan bu surlu kent, tarih ve doğayı birleştirir.' },
    { name: 'Cenoteler', desc: 'Yucatán Yarımadası’na özgü bu doğal su kuyuları (cenote), yer altındaki kireçtaşının çökmesiyle oluşan berrak tatlı su havuzlarıdır. Mayalar için kutsal sayılan bu gizemli oluşumlar, yüzme ve dalış için büyüleyici bir deneyim sunar.' },
    { name: 'Isla Mujeres', desc: 'Cancún’dan kısa bir feribot yolculuğuyla ulaşılan “Kadınlar Adası”, turkuaz suları, beyaz kumlu plajları ve rahat atmosferiyle büyüler. Golf arabalarıyla gezilen bu şirin ada, şnorkel ve dinlenme için popüler bir kaçış noktasıdır.' },
    { name: 'Riviera Maya Plajları', desc: 'Cancún’dan güneye uzanan bu ünlü sahil şeridi, pudra gibi beyaz kumu ve inanılmaz turkuaz Karayip sularıyla dünyanın en güzel plajlarına ev sahipliği yapar. Lüks tatil köyleri ve doğal güzellikleriyle tam bir tropik cennettir.' },
  ],
  havana: [
    { name: 'Habana Vieja (Eski Havana)', desc: 'Havana’nın tarihî çekirdeği, rengârenk (çoğu solmuş) sömürge dönemi binaları, meydanları ve dar sokaklarıyla adeta zamanda donmuş bir açık hava müzesidir. Bu benzersiz atmosfer ve mimari, bölgeyi UNESCO Dünya Mirası listesine sokmuştur.' },
    { name: 'Klasik Araba Turu', desc: 'Havana’nın sokakları, 1950’lerden kalma bakımı yapılmış rengârenk klasik Amerikan arabalarıyla doludur. Üstü açık bu vintage otomobillerle yapılan şehir turu, kentin nostaljik ruhunu deneyimlemenin en ikonik ve keyifli yoludur.' },
    { name: 'Malecón', desc: 'Havana’nın okyanus kıyısı boyunca 8 kilometre uzanan bu ünlü set ve bulvar, kentin sosyal yaşamının kalbidir. Akşamları müzik çalan, sohbet eden ve gün batımını izleyen Havanalılarla dolan bu şerit, şehrin canlı bir buluşma noktasıdır.' },
    { name: 'El Capitolio', desc: 'Washington’daki ABD Kongre Binası’na benzerliğiyle dikkat çeken bu görkemli yapı, bir zamanlar Küba hükümetine ev sahipliği yapıyordu. Devasa kubbesi ve zarif mimarisiyle Havana’nın en tanınan ve en etkileyici simgelerinden biridir.' },
    { name: 'Havana Kalesi (Morro)', desc: 'Havana Limanı’nın girişini koruyan bu görkemli 16. yüzyıl kalesi, kenti korsan ve düşman saldırılarından korumak için inşa edilmiştir. Deniz fenerine ev sahipliği yapan kaleden, şehrin ve limanın nefes kesen manzarası izlenir.' },
    { name: 'Katedral Meydanı', desc: 'Eski Havana’nın en güzel meydanlarından biri olan bu alan, arnavut kaldırımlı zemini ve görkemli barok Havana Katedrali ile çevrilidir. Asimetrik iki kulesiyle dikkat çeken katedral, dönemin sömürge mimarisinin bir başyapıtıdır.' },
    { name: 'Fusterlandia', desc: 'Sanatçı José Fuster’in kendi mahallesini adım adım rengârenk mozaik ve seramiklerle bir sanat eserine dönüştürdüğü bu benzersiz semt, Gaudí’nin çalışmalarını andırır. Evleri ve sokakları süsleyen bu canlı işçilik, coşkulu bir hayal gücünün ürünüdür.' },
    { name: 'Vedado & Callejón de Hamel', desc: 'Havana’nın daha modern semti Vedado, geniş bulvarları ve tarihî otelleriyle kentin bir başka yüzünü sunar. Callejón de Hamel ise Afro-Küba kültürüne adanmış, duvarlarını süsleyen sanat ve canlı rumba müziğiyle tanınan renkli bir ara sokaktır.' },
  ],
  rio: [
    { name: 'Kurtarıcı İsa', desc: 'Corcovado Dağı’nın zirvesinde kollarını açmış duran bu 38 metrelik dev İsa heykeli, Rio’nun ve Brezilya’nın simgesidir. Art deco üslubundaki bu anıt, dünyanın yeni yedi harikasından biri olup şehrin nefes kesen panoramasına hâkimdir.' },
    { name: 'Şeker Somunu (Pão de Açúcar)', desc: 'Guanabara Körfezi’nin girişinde denizden yükselen bu ikonik granit tepeye, iki aşamalı bir teleferikle çıkılır. Zirvesinden Rio’nun plajlarının, dağlarının ve Kurtarıcı İsa heykelinin muhteşem manzarası izlenir.' },
    { name: 'Copacabana & Ipanema', desc: 'Rio’nun bu iki komşu plajı, dalgalı kaldırım desenleri, hareketli atmosferi ve ünlü şarkılarıyla dünya çapında meşhurdur. Voleybol oynayan, güneşlenen ve yürüyüş yapan kalabalıklarıyla Brezilya’nın plaj kültürünün kalbidir.' },
    { name: 'Selarón Merdivenleri', desc: 'Şilili sanatçı Jorge Selarón’un dünyanın her yerinden getirilen 2.000’den fazla rengârenk çiniyle kapladığı bu merdivenler, canlı bir sanat eseridir. Sanatçının Brezilya halkına adadığı bu 215 basamak, kentin en fotojenik noktalarındandır.' },
    { name: 'Maracanã', desc: '1950 Dünya Kupası için inşa edilen bu efsanevi stadyum, bir zamanlar dünyanın en büyük futbol arenasıydı ve Brezilya futbol tarihinin unutulmaz anlarına sahne oldu. Pelé’nin ünlü golleriyle özdeşleşen bu tapınak, futbol tutkunları için kutsaldır.' },
    { name: 'Santa Teresa & Escadaria', desc: 'Bir tepeye kurulu bu bohem mahalle, dar dolambaçlı sokakları, tarihî tramvayı (bonde) ve sanatçı stüdyolarıyla büyüler. Kolonyal konakları ve sanatsal atmosferiyle Rio’nun en özgün ve romantik semtlerinden biridir.' },
    { name: 'Lapa Kemerleri', desc: 'Beyaz kemerleriyle dikkat çeken bu görkemli yapı (Arcos da Lapa), aslında 18. yüzyıldan kalma bir Roma tarzı su kemeridir. Bugün üzerinden tarihî tramvay geçen bu kemerlerin çevresi, Rio’nun en canlı gece hayatı ve samba merkezidir.' },
    { name: 'Jardim Botânico', desc: '1808’de Portekiz kralı tarafından kurulan bu görkemli botanik bahçesi, sıra sıra dikilmiş görkemli imparatorluk palmiyeleriyle ünlüdür. Binlerce bitki türü, orkideleri ve zengin yaban hayatıyla kentin ortasında huzurlu bir tropik vahadır.' },
  ],
  saopaulo: [
    { name: 'MASP', desc: 'Paulista Caddesi’nde iki dev kırmızı kirişe asılı gibi duran cam gövdesiyle bu müze, modern mimarinin bir ikonudur. Latin Amerika’nın en önemli sanat koleksiyonlarından birini, cam panolar üzerinde sergilenen benzersiz bir düzenle sunar.' },
    { name: 'Paulista Caddesi', desc: 'São Paulo’nun finansal ve kültürel kalbi olan bu geniş bulvar, gökdelenleri, müzeleri ve kültür merkezleriyle kentin en canlı arteridir. Pazar günleri araç trafiğine kapatılarak sanatçılar ve halkla dolan bu cadde, şehrin enerjisini yansıtır.' },
    { name: 'Ibirapuera Parkı', desc: 'São Paulo’nun en önemli şehir parkı olan Ibirapuera, gölleri ve yeşil alanlarının yanı sıra ünlü mimar Oscar Niemeyer’in tasarladığı ikonik yapıları barındırır. Müzeleri ve dinlence alanlarıyla kentin kültürel ve doğal bir vahasıdır.' },
    { name: 'Mercado Municipal', desc: 'Şehrin bu tarihî kapalı pazarı, görkemli vitray pencereleri ve devasa kubbesiyle bir mimari şaheserdir. Egzotik meyveleri ve ünlü “mortadella sandviçi” gibi lezzetleriyle São Paulo’nun gastronomi kültürünün canlı bir merkezidir.' },
    { name: 'Beco do Batman', desc: 'Vila Madalena semtindeki bu ara sokak, duvarlarını baştan başa kaplayan sürekli değişen renkli grafiti ve muralarıyla São Paulo’nun sokak sanatı merkezidir. Dünyanın dört bir yanından sanatçıların eserlerini barındıran bir açık hava galerisidir.' },
  ],
  buenosaires: [
    { name: 'La Boca & Caminito', desc: 'İtalyan göçmenlerin kurduğu bu liman mahallesi, gemilerden artan boyalarla rengârenk boyanmış sac evleriyle ünlüdür. Açık hava müzesi Caminito sokağı, sokakta dans eden tango çiftleri ve sanatçılarıyla Buenos Aires’in en canlı simgesidir.' },
    { name: 'Recoleta Mezarlığı', desc: 'Bu görkemli mezarlık, Arjantin’in en önemli şahsiyetlerine ait heykeller ve anıtlarla süslü, adeta minyatür bir saraylar şehridir. Ünlü Eva Perón’un (Evita) mezarını barındırması nedeniyle en çok ziyaret edilen noktalarındandır.' },
    { name: 'Plaza de Mayo & Casa Rosada', desc: 'Buenos Aires’in ve Arjantin siyasetinin kalbi olan bu tarihî meydan, kentin kuruluşundan bu yana önemli olaylara sahne olmuştur. Meydana hâkim pembe renkli Casa Rosada, ünlü balkonuyla devlet başkanlığının çalışma sarayıdır.' },
    { name: 'Teatro Colón', desc: '1908’de açılan bu görkemli opera binası, olağanüstü akustiği sayesinde dünyanın en iyi üç opera evinden biri kabul edilir. İhtişamlı iç mimarisi ve tarihiyle Buenos Aires’in kültürel gururu ve bir sanat tapınağıdır.' },
    { name: 'Tango Gösterisi', desc: 'Buenos Aires, tutkulu bir dans olan tangonun doğduğu şehirdir. Özellikle tarihî San Telmo mahallesindeki gösteriler ve “milonga” adı verilen dans salonları, bu tutkulu Arjantin sanatını canlı olarak deneyimlemenin en iyi yoludur.' },
    { name: 'El Ateneo Grand Splendid', desc: 'Bir zamanlar görkemli bir tiyatro ve opera binası olan bu yapı, özgün mimarisi korunarak dünyanın en güzel kitapçısına dönüştürülmüştür. Sahne locaları, freskli tavanı ve zarafetiyle kitapseverler için büyüleyici bir mekândır.' },
    { name: 'Palermo & Bosques', desc: 'Buenos Aires’in en büyük ve en şık semti olan Palermo, ağaçlıklı sokakları, butikleri, kafeleri ve canlı gece hayatıyla ünlüdür. İçindeki geniş “Bosques de Palermo” parkları, gölleri ve gül bahçeleriyle kentin yeşil ciğeridir.' },
    { name: 'Puerto Madero', desc: 'Eski liman depolarının dönüştürüldüğü bu semt, modern gökdelenleri, şık restoranları ve nehir kıyısı yürüyüş yollarıyla kentin en yeni yüzüdür. Zarif “Kadın Köprüsü” (Puente de la Mujer), bir tango çiftini simgeleyen tasarımıyla semtin ikonudur.' },
  ],
  cusco: [
    { name: 'Machu Picchu', desc: 'And Dağları’nın zirvesinde, sıklıkla bulutların arasında saklı bu görkemli İnka şehri, 15. yüzyıldan kalma bir mühendislik harikasıdır. Yüzyıllarca dış dünyaca bilinmeyen bu “kayıp şehir”, dünyanın yeni yedi harikasından biri ve bir UNESCO mirasıdır.' },
    { name: 'Kutsal Vadi', desc: 'Cusco yakınlarındaki Urubamba Nehri boyunca uzanan bu bereketli vadi, İnka İmparatorluğu için tarımsal ve dini açıdan hayati öneme sahipti. Pisac’ın teraslı kalıntıları ve Ollantaytambo’nun görkemli tapınak-kalesiyle İnka mühendisliğini sergiler.' },
    { name: 'Sacsayhuamán', desc: 'Cusco’ya tepeden bakan bu devasa İnka kalesi, harç kullanılmadan kusursuz bir şekilde birbirine geçirilen dev taş bloklarıyla hayranlık uyandırır. Bazıları yüzlerce ton ağırlığındaki bu taşların nasıl taşındığı ve yerleştirildiği hâlâ bir gizemdir.' },
    { name: 'Plaza de Armas', desc: 'Cusco’nun kalbi olan bu görkemli meydan, bir zamanlar İnka başkentinin de merkeziydi. İnka temelleri üzerine inşa edilen görkemli sömürge katedrali ve kiliseleriyle çevrili meydan, iki uygarlığın iç içe geçtiği katmanlı tarihi yansıtır.' },
    { name: 'Gökkuşağı Dağı', desc: 'Cusco yakınlarındaki Vinicunca, farklı minerallerin oluşturduğu kırmızı, sarı, yeşil ve mor renkli katmanlarıyla “Gökkuşağı Dağı” olarak ünlüdür. 5.000 metreyi aşan yüksekliğiyle zorlu ama nefes kesici manzaralı bir doğa harikasıdır.' },
  ],
  lima: [
    { name: 'Miraflores & Malecón', desc: 'Lima’nın en modern ve şık semti Miraflores, Pasifik Okyanusu’na bakan uçurumların üzerine kuruludur. Kıyı boyunca uzanan yeşil parklar ve yürüyüş yolundan (Malecón) yamaç paraşütçüleri ve muhteşem gün batımı izlenir.' },
    { name: 'Tarihî Merkez & Katedral', desc: 'İspanyol fatih Francisco Pizarro tarafından kurulan Lima’nın tarihî merkezi, görkemli sömürge dönemi mimarisiyle UNESCO Dünya Mirası listesindedir. Ana meydanı, başkanlık sarayı ve Pizarro’nun mezarını barındıran katedraliyle ülkenin köklü geçmişini yansıtır.' },
    { name: 'Larco Müzesi', desc: 'Bir 18. yüzyıl konağında yer alan bu müze, Peru’nun 5.000 yıllık Kolomb öncesi tarihini kapsayan olağanüstü bir koleksiyona sahiptir. Zengin altın ve gümüş eserleri ile ünlü çömlek koleksiyonuyla And uygarlıklarına ışık tutar.' },
    { name: 'Barranco', desc: 'Lima’nın en bohem ve sanatsal semti olan Barranco, rengârenk konakları, sokak sanatları ve ünlü “İç Çekişler Köprüsü” ile büyüler. Sanat galerileri, butik kafeleri ve canlı gece hayatıyla kentin yaratıcı kalbidir.' },
    { name: 'Huaca Pucllana', desc: 'Modern Miraflores semtinin tam ortasında yükselen bu görkemli piramit, İnka öncesi Lima kültürüne ait 1.500 yıllık bir adobe (kerpiç) tapınağıdır. Milyonlarca el yapımı tuğladan inşa edilen bu yapı, kentin katmanlı tarihinin çarpıcı bir kanıtıdır.' },
  ],
  santiago: [
    { name: 'Cerro San Cristóbal', desc: 'Santiago’ya tepeden bakan bu tepe, zirvesindeki dev Bakire Meryem heykeliyle taçlanır ve bir teleferikle çıkılır. Şehrin ve arkasında yükselen karlı And Dağları’nın nefes kesen panoramasını sunan kentin en büyük yeşil alanıdır.' },
    { name: 'Plaza de Armas & Katedral', desc: 'Santiago’nun kuruluşundan bu yana kentin kalbi olan bu tarihî ana meydan, görkemli Metropolitan Katedrali ve sömürge dönemi binalarıyla çevrilidir. Sanatçıları, satıcıları ve halkıyla şehrin canlı sosyal yaşamının merkezidir.' },
    { name: 'La Moneda', desc: 'Bu görkemli neoklasik saray, Şili Cumhurbaşkanlığı’nın makamıdır. 1973’teki askeri darbe sırasında bombalanmasıyla ülkenin çalkantılı yakın tarihine tanıklık etmiş, bugün ise demokrasinin bir simgesi olarak ayaktadır.' },
    { name: 'Bellavista', desc: 'Cerro San Cristóbal’in eteğindeki bu renkli ve bohem semt, sokak sanatları, restoranları ve canlı gece hayatıyla ünlüdür. Nobel ödüllü şair Pablo Neruda’nın özgün ve yaratıcı evi “La Chascona” da bu mahallede yer alır.' },
    { name: 'Şarap Vadileri', desc: 'Santiago, dünyaca ünlü Şili şaraplarının üretildiği Maipo ve Casablanca gibi bereketli vadilere çok yakındır. And Dağları’nın eteklerindeki bu bağlar, tadım turları ve manzaralarıyla şarapseverler için ideal bir kaçış noktasıdır.' },
  ],
  cartagena: [
    { name: 'Surlu Eski Şehir', desc: 'Kalın taş surlarla çevrili Cartagena’nın eski şehri, rengârenk sömürge konakları, çiçekli balkonları ve arnavut kaldırımlı sokaklarıyla büyüler. Karayip’in en iyi korunmuş tarihî merkezi olarak UNESCO Dünya Mirası listesindedir.' },
    { name: 'Castillo San Felipe', desc: 'İspanyolların şehri korsan ve düşman saldırılarından korumak için inşa ettiği bu devasa kale, Amerika kıtasındaki en büyük İspanyol istihkâmıdır. Karmaşık tünel sistemi ve stratejik konumuyla dönemin askeri mühendislik dehasını sergiler.' },
    { name: 'Getsemaní', desc: 'Bir zamanlar gözden uzak bir mahalle olan Getsemaní, bugün her köşesini süsleyen rengârenk sokak sanatları, canlı meydanları ve müziğiyle Cartagena’nın en otantik ve enerjik semtidir. Yerel yaşamın kalbinin attığı bohem bir merkezdir.' },
    { name: 'Rosario Adaları', desc: 'Cartagena açıklarındaki bu mercan takımadaları, berrak turkuaz suları, beyaz kumlu plajları ve zengin deniz yaşamıyla bir Karayip cennetidir. Tekne turlarıyla ulaşılan bu adalar, şnorkel ve dinlenme için ideal bir kaçış sunar.' },
  ],

  // --- Asya ---
  tokyo: [
    { name: 'Shibuya Kavşağı', desc: 'Her yeşil ışıkta yüzlerce insanın aynı anda her yönden karşıya geçtiği bu meydan, dünyanın en yoğun yaya geçidi olarak Tokyo’nun enerjisinin simgesidir. Dev ekranları ve neon ışıklarıyla modern Japon şehir yaşamının ikonik bir görüntüsüdür.' },
    { name: 'Senso-ji (Asakusa)', desc: '7. yüzyıla dayanan geçmişiyle Tokyo’nun en eski ve en önemli Budist tapınağı olan Senso-ji, dev kırmızı fenerli Kaminarimon kapısıyla ünlüdür. Tapınağa uzanan tarihî Nakamise alışveriş sokağı, geleneksel el sanatları ve atıştırmalıklarla doludur.' },
    { name: 'Meiji Jingu', desc: 'Şehrin merkezindeki devasa ve sakin bir ormanın içinde yer alan bu Şinto tapınağı, İmparator Meiji ve eşine adanmıştır. Görkemli ahşap torii kapıları ve huzurlu atmosferiyle, metropolün ortasında manevi bir sığınak sunar.' },
    { name: 'Tokyo Skytree', desc: '634 metre yüksekliğiyle dünyanın en yüksek kulelerinden biri olan bu yayın kulesi, geleneksel Japon estetiğini modern tasarımla birleştirir. Gözlem güvertelerinden, uçsuz bucaksız Tokyo metropolünün ve açık havada Fuji Dağı’nın panoraması izlenir.' },
    { name: 'Shinjuku & Golden Gai', desc: 'Shinjuku, dev gökdelenleri, neon ışıklı caddeleri ve dünyanın en yoğun tren istasyonuyla Tokyo’nun kalbidir. İçindeki Golden Gai bölgesi ise, dar sokaklara sıkışmış yüzlerce minik bara ev sahipliği yapan nostaljik ve özgün bir gece hayatı merkezidir.' },
    { name: 'Toyosu/Tsukiji', desc: 'Dünyanın en büyük balık ve deniz ürünleri ticaretinin yapıldığı bu pazarlar, Japon mutfağının kalbidir. Ünlü ton balığı açık artırmaları ve taze suşi lokantalarıyla, gastronomi tutkunları için bir cazibe merkezidir.' },
    { name: 'Harajuku & Takeshita', desc: 'Harajuku, Japonya’nın avangart gençlik modasının ve sokak stilinin doğduğu merkezdir. Rengârenk butikleri, konsept mağazaları ve dev pamuk şekerleriyle ünlü Takeshita Caddesi, kentin en canlı ve en yaratıcı bölgesidir.' },
    { name: 'Ueno Parkı & Müzeleri', desc: 'Tokyo’nun en büyük halka açık parklarından biri olan Ueno, ilkbaharda kiraz çiçekleriyle (sakura) bir cennete dönüşür. Ayrıca Tokyo Ulusal Müzesi başta olmak üzere ülkenin en önemli müzelerine ve bir hayvanat bahçesine ev sahipliği yapar.' },
    { name: 'Akihabara', desc: '“Elektronik Şehir” olarak da bilinen Akihabara, teknoloji mağazalarının yanı sıra anime, manga ve video oyunu kültürünün küresel merkezidir. Rengârenk tabelaları, oyun salonları ve temalı kafeleriyle Japon pop kültürünün kalbidir.' },
    { name: 'teamLab & Odaiba', desc: 'Odaiba, Tokyo Körfezi’nde yapay bir ada olup alışveriş merkezleri, Özgürlük Heykeli replikası ve manzarasıyla ünlüdür. Buradaki teamLab dijital sanat müzeleri ise, ziyaretçileri sınırsız ışık ve renk enstalasyonlarının içine alan büyüleyici bir deneyim sunar.' },
  ],
  kyoto: [
    { name: 'Kinkaku-ji (Altın Pavyon)', desc: 'Üst iki katı tamamen altın varakla kaplı bu görkemli Zen tapınağı, önündeki gölete yansıyan görüntüsüyle büyüler. Bir şogunun emeklilik villası olarak yaptırılan bu yapı, Kyoto’nun en ikonik ve en çok fotoğraflanan simgesidir.' },
    { name: 'Fushimi Inari', desc: 'Pirinç tanrısı Inari’ye adanan bu tapınak, bir dağın yamacı boyunca uzanan binlerce parlak turuncu torii kapısıyla dünyaca ünlüdür. Bağışçılar tarafından dikilen bu kapıların oluşturduğu tüneller, büyüleyici ve manevi bir yürüyüş rotası sunar.' },
    { name: 'Arashiyama Bambu Ormanı', desc: 'Göğe doğru uzanan dev bambu saplarının oluşturduğu bu patika, rüzgârda hışırdayan sesleri ve süzülen yeşilimsi ışığıyla dünyanın başka bir yerinde bulunmayan huzurlu bir atmosfer sunar. Kyoto’nun en dingin ve en fotojenik noktalarından biridir.' },
    { name: 'Kiyomizu-dera', desc: 'Bir yamacın üzerinde tek bir çivi kullanılmadan inşa edilen görkemli ahşap terasıyla ünlü bu Budist tapınağı, Kyoto’nun panoramasını sunar. Adını (“Saf Su Tapınağı”) şifalı olduğuna inanılan Otowa şelalesinden alır.' },
    { name: 'Gion', desc: 'Kyoto’nun en ünlü geyşa (geiko) semti olan Gion, geleneksel ahşap çay evleri ve arnavut kaldırımlı sokaklarıyla eski Japonya’nın atmosferini yaşatır. Akşamları bir randevuya giden zarif geyşaları görme şansının olduğu bu semt, kültürel bir hazinedir.' },
    { name: 'Nishiki Pazarı', desc: '“Kyoto’nun Mutfağı” olarak anılan bu beş asırlık dar ve üstü kapalı çarşı, yüzlerce dükkânıyla bölgeye özgü yiyecekleri sunar. Taze deniz ürünleri, turşular ve geleneksel tatlılarıyla Kyoto’nun köklü gastronomi kültürünün kalbidir.' },
    { name: 'Nijo Kalesi', desc: 'Tokugawa şogunlarının Kyoto’daki ikametgâhı olan bu görkemli kale, savunma amacıyla üzerine basıldığında bülbül sesi çıkaran “ötücü zeminleriyle” ünlüdür. Süslü salonları ve zarif bahçeleriyle şogunluk döneminin gücünü sergiler.' },
    { name: 'Ginkaku-ji & Felsefe Yolu', desc: '“Gümüş Pavyon” olarak bilinen bu zarif Zen tapınağı, özenle taranmış kum bahçeleri ve yosun bahçeleriyle sade bir güzellik sunar. Tapınağa uzanan, kanal boyunca kiraz ağaçlarıyla süslü “Felsefe Yolu” ise düşünceli bir yürüyüş için idealdir.' },
  ],
  osaka: [
    { name: 'Osaka Kalesi', desc: '16. yüzyılda Japonya’yı birleştiren Toyotomi Hideyoshi tarafından yaptırılan bu görkemli kale, ülkenin en önemli tarihî yapılarındandır. Altın süslemeli ana kulesi bir müze işlevi görür ve çevresindeki geniş park, ilkbaharda kiraz çiçekleriyle bezenir.' },
    { name: 'Dotonbori', desc: 'Osaka’nın canlı eğlence ve gastronomi merkezi olan bu bölge, kanal boyunca uzanan dev neon tabelaları (ünlü Glico koşucusu gibi) ve hareketli atmosferiyle büyüler. Takoyaki ve okonomiyaki gibi meşhur sokak lezzetlerinin merkezidir.' },
    { name: 'Universal Studios Japan', desc: 'Asya’nın en popüler tema parklarından biri olan bu kompleks, sinema dünyasından ilham alan hız trenleri ve gösterileriyle doludur. Özellikle “Harry Potter’ın Büyülü Dünyası” bölümüyle her yaştan ziyaretçiyi kendine çeker.' },
    { name: 'Shinsekai & Tsutenkaku', desc: 'Adı “Yeni Dünya” anlamına gelen bu retro semt, 20. yüzyıl başındaki nostaljik atmosferini korur. Merkezindeki Tsutenkaku Kulesi ve çevresindeki geleneksel “kushikatsu” (şişte kızarmış yiyecek) lokantalarıyla eski Osaka’nın ruhunu yaşatır.' },
    { name: 'Kuromon Pazarı', desc: '“Osaka’nın Mutfağı” olarak anılan bu 190 yıllık üstü kapalı çarşı, taze deniz ürünleri, meyveler ve yerel lezzetler sunan yüzlerce dükkânıyla doludur. Yemek tutkunu olarak bilinen Osakalıların gastronomi kültürünün canlı bir merkezidir.' },
  ],
  hiroshima: [
    { name: 'Barış Anıtı & Müze', desc: 'Bu park ve müze, 1945’te dünyanın ilk atom bombası saldırısına maruz kalan Hiroşima’nın acısını anar ve barış çağrısı yapar. Etkileyici sergileri ve anıtlarıyla nükleer silahların yıkıcılığını gözler önüne seren dokunaklı bir mekândır.' },
    { name: 'Genbaku Dome', desc: 'Atom bombasının patlama merkezine çok yakın olmasına rağmen ayakta kalabilen bu binanın iskeleti, “Atom Bombası Kubbesi” olarak bilinir. Yıkımın sessiz bir tanığı ve barışın bir simgesi olarak olduğu gibi korunmuş, UNESCO Dünya Mirası’dır.' },
    { name: 'Miyajima & Itsukushima', desc: 'Hiroşima yakınlarındaki bu kutsal ada, denizin içinde yükselen ve gelgitle birlikte adeta suda yüzüyormuş gibi görünen ünlü turuncu torii kapısıyla dünyaca meşhurdur. Bu ikonik manzara, Japonya’nın en çok fotoğraflanan noktalarından biridir.' },
    { name: 'Hiroşima Kalesi', desc: '“Sazan Kale” olarak da bilinen bu görkemli yapı, atom bombasıyla yıkıldıktan sonra özgün haline sadık kalınarak yeniden inşa edilmiştir. Bugün kentin feodal dönem tarihini anlatan bir müze olarak hizmet vermektedir.' },
  ],
  nara: [
    { name: 'Todai-ji', desc: 'İçinde 15 metre yüksekliğinde dev bir bronz Buda heykeli (Daibutsu) barındıran bu tapınak, dünyanın en büyük ahşap yapılarından biridir. 8. yüzyıldan kalma bu görkemli anıt, Japonya’nın en önemli Budist merkezlerindendir.' },
    { name: 'Nara Parkı Geyikleri', desc: 'Bu geniş parkta özgürce dolaşan yüzlerce evcil geyik, kutsal sayılır ve kentin sembolüdür. Ziyaretçilerden özel kraker (shika senbei) almak için nazikçe eğilerek “selam veren” bu sevimli geyikler, Nara’ya özgü unutulmaz bir deneyim sunar.' },
    { name: 'Kasuga Taisha', desc: 'Nara’nın en önemli Şinto tapınağı olan Kasuga Taisha, bağışçılar tarafından adanan üç bine yakın bronz ve taş feneriyle ünlüdür. Yılda iki kez bu fenerlerin tümünün yakıldığı büyülü festival, tapınağa mistik bir atmosfer katar.' },
    { name: 'Isuien Bahçesi', desc: 'Nara’nın bu klasik Japon bahçesi, göletleri, çay evleri ve özenle düzenlenmiş peyzajıyla huzur sunar. Arka plandaki Todai-ji tapınağının kapısını ve dağları manzarasına dahil eden “ödünç manzara” tekniğiyle tasarlanmıştır.' },
  ],
  pekin: [
    { name: 'Yasak Şehir', desc: 'Beş asır boyunca Çin imparatorlarının sarayı ve yönetim merkezi olan bu devasa kompleks, dünyanın en büyük saray topluluğudur. 980 binası ve altın çatılı görkemli salonlarıyla imparatorluk Çin’inin gücünü ve ihtişamını yansıtan bir UNESCO mirasıdır.' },
    { name: 'Çin Seddi (Mutianyu)', desc: 'Çin’i kuzeyden gelen istilalara karşı korumak için yüzyıllar boyunca inşa edilen bu devasa savunma hattı, insanlık tarihinin en büyük mühendislik projesidir. Mutianyu bölümü, dağların sırtında kıvrılarak uzanan restore edilmiş surlarıyla nefes kesici manzaralar sunar.' },
    { name: 'Cennet Tapınağı', desc: 'Ming ve Qing hanedanlığı imparatorlarının bereketli hasat için dua ettiği bu görkemli tapınak kompleksi, mimari kusursuzluğuyla ünlüdür. Tek bir çivi kullanılmadan inşa edilen dairesel mavi çatılı ana yapısı, Çin kozmolojisini simgeler.' },
    { name: 'Tiananmen Meydanı', desc: 'Dünyanın en büyük şehir meydanlarından biri olan bu alan, Çin’in modern tarihindeki önemli olaylara sahne olmuştur. Yasak Şehir’in girişindeki Mao portresi ve çevresindeki anıtsal binalarla ülkenin siyasi kalbini oluşturur.' },
    { name: 'Yaz Sarayı', desc: 'İmparatorluk ailesinin sıcak yaz aylarından kaçmak için kullandığı bu görkemli saray-bahçe, geniş Kunming Gölü ve Uzun Ömür Tepesi çevresine kuruludur. Köprüleri, pavyonları ve uzun koridoruyla klasik Çin bahçe sanatının bir başyapıtıdır.' },
    { name: 'Hutong’lar', desc: 'Pekin’in eski dokusunu oluşturan bu dar sokaklar ve geleneksel avlulu evler (siheyuan), kentin geçmişteki gündelik yaşamını yaşatır. Bisiklet taksileriyle (riksha) gezilen bu labirentimsi mahalleler, modern metropolün ortasında nostaljik bir dünya sunar.' },
    { name: 'Lama Tapınağı', desc: 'Pekin’in en önemli Tibet Budist tapınağı olan Yonghegong, tek bir sandal ağacı gövdesinden yontulmuş 18 metrelik dev bir Buda heykeliyle ünlüdür. Görkemli mimarisi ve manevi atmosferiyle önemli bir ibadet ve ziyaret merkezidir.' },
    { name: '798 Sanat Bölgesi', desc: 'Kullanılmayan bir askeri elektronik fabrika kompleksinden dönüştürülen bu bölge, bugün Pekin’in çağdaş sanat merkezidir. Endüstriyel binalardaki galeriler, stüdyolar ve kafeleriyle Çin’in modern sanat sahnesinin canlı kalbidir.' },
    { name: 'Ming Mezarları', desc: 'Pekin yakınlarındaki bu alan, Ming Hanedanlığı’nın on üç imparatorunun görkemli türbelerini barındırır. Türbelere uzanan ve taş hayvan heykelleriyle çevrili anıtsal “Kutsal Yol”, dönemin defin geleneklerinin etkileyici bir örneğidir.' },
  ],
  sanghay: [
    { name: 'The Bund', desc: 'Huangpu Nehri’nin batı yakasındaki bu ünlü sahil şeridi, 20. yüzyıl başından kalma görkemli Avrupa tarzı sömürge binalarıyla dizilidir. Karşı yakadaki fütüristik gökdelen manzarasıyla birlikte, Şanghay’ın geçmişini ve geleceğini bir arada sunar.' },
    { name: 'Pudong & Oriental Pearl', desc: 'Bir zamanlar bataklık olan Pudong, bugün Çin’in ekonomik gücünü simgeleyen göz kamaştırıcı gökdelenlerle doludur. Pembe küreli Oriental Pearl TV Kulesi ve dünyanın en yüksek binaları arasındaki Şanghay Kulesi, kentin fütüristik siluetini oluşturur.' },
    { name: 'Yu Bahçesi', desc: 'Ming Hanedanlığı döneminde bir yetkili tarafından ailesi için yaptırılan bu klasik Çin bahçesi, göletleri, kaya bahçeleri ve zarif pavyonlarıyla huzurlu bir vahadır. Çevresindeki geleneksel çarşı, el sanatları ve yerel atıştırmalıklarla doludur.' },
    { name: 'Nanjing Road', desc: 'Dünyanın en uzun ve en yoğun alışveriş caddelerinden biri olan Nanjing Yolu, ışıltılı neon tabelaları ve mağazalarıyla Şanghay’ın ticari kalbidir. Yaya bölgesi, hem lüks markaları hem de tarihî mağazaları barındıran hareketli bir merkezdir.' },
    { name: 'Fransız Konsesyonu', desc: 'Şanghay’ın bu tarihî bölgesi, 20. yüzyıl başındaki Fransız yönetiminden kalma çınar ağaçlı sokakları ve Avrupa tarzı villalarıyla büyüler. Şık kafeleri, butikleri ve nostaljik atmosferiyle kentin en zarif ve romantik semtidir.' },
  ],
  xian: [
    { name: 'Terracotta Ordusu', desc: 'Çin’in ilk imparatoru Qin Shi Huang’ı öbür dünyada korumak için yaratılan bu ordu, her biri farklı yüz hatlarına sahip binlerce gerçek boyutlu pişmiş toprak asker, at ve savaş arabasından oluşur. 1974’te tesadüfen bulunan bu hazine, arkeolojinin en büyük keşiflerindendir.' },
    { name: 'Şehir Surları', desc: 'Ming Hanedanlığı döneminden kalma bu devasa surlar, Çin’in en eksiksiz korunmuş antik şehir savunma sistemidir. Yaklaşık 14 kilometre uzunluğundaki bu surların üzeri bisikletle turlanabilir ve eski İpek Yolu başkentinin panoramasını sunar.' },
    { name: 'Büyük Yaban Kazı Pagodası', desc: 'Tang Hanedanlığı döneminde, Hindistan’dan getirilen kutsal Budist yazmalarını korumak için inşa edilen bu görkemli pagoda, döneminin dini ve kültürel öneminin bir simgesidir. Sağlam yapısı ve tarihiyle Xi’an’ın önemli bir mirasıdır.' },
    { name: 'Müslüman Çarşısı', desc: 'Xi’an’ın yüzyıllardır süregelen Hui Müslüman topluluğunun kalbi olan bu canlı çarşı, İpek Yolu’nun mirasını yaşatır. Dumanı tüten sokak lezzetleri ve çin-islam mimarisini birleştiren tarihî Büyük Cami’siyle eşsiz bir kültürel deneyim sunar.' },
  ],
  guilin: [
    { name: 'Li Nehri Tekne Turu', desc: 'Guilin’den Yangshuo’ya uzanan bu nehir seyahati, gökyüzüne yükselen sisli karst tepeleri arasında büyüleyici bir yolculuk sunar. Geleneksel Çin resimlerine ilham veren bu manzara, dünyanın en güzel doğa güzergâhlarından biri kabul edilir.' },
    { name: 'Yangshuo & Batı Sokağı', desc: 'Karst tepelerinin çevrelediği bu şirin kasaba, çarpıcı doğası ve canlı atmosferiyle ünlüdür. Kasabanın kalbindeki tarihî Batı Sokağı (West Street), kafeleri, dükkânları ve hareketli gece hayatıyla yerli ve turistlerin buluşma noktasıdır.' },
    { name: 'Longji Pirinç Terasları', desc: 'Adı “Ejderhanın Belkemiği” anlamına gelen bu görkemli teraslar, yüzyıllar boyunca dağ yamaçlarına oyulmuş basamaklı pirinç tarlalarından oluşur. Mevsime göre yeşil, altın veya suyla dolu haliyle nefes kesici bir insan-doğa harikasıdır.' },
    { name: 'Reed Flute Mağarası', desc: 'Girişindeki kamışlardan flüt yapıldığı için bu adı alan mağara, milyonlarca yılda oluşan görkemli sarkıt ve dikitlerle doludur. Rengârenk yapay ışıklandırmayla aydınlatılan bu oluşumlar, adeta yeraltında büyülü bir masal dünyası yaratır.' },
  ],
  delhi: [
    { name: 'Kızıl Kale', desc: 'Babür İmparatoru Şah Cihan tarafından 17. yüzyılda yaptırılan bu görkemli kırmızı kumtaşı kale, iki asır boyunca imparatorluğun ana ikametgâhı oldu. Hindistan bağımsızlığının ilan edildiği bu UNESCO mirası, ulusal bir simge olarak önemini korur.' },
    { name: 'Kutub Minar', desc: '73 metre yüksekliğiyle dünyanın en yüksek tuğla minaresi olan bu zafer kulesi, 12. yüzyılda Delhi Sultanlığı’nın kuruluşunu kutlamak için inşa edildi. İnce oymalarla ve Kuran ayetleriyle bezeli yapısı, erken İslam mimarisinin bir başyapıtıdır.' },
    { name: 'Humayun Türbesi', desc: 'Babür İmparatoru Humayun için yaptırılan bu görkemli türbe, Hint alt kıtasındaki ilk büyük bahçe-türbedir. Simetrik dört bölümlü bahçesi ve kubbesiyle, yaklaşık bir asır sonra yapılacak olan Tac Mahal’a doğrudan ilham vermiştir.' },
    { name: 'Jama Camii & Chandni Chowk', desc: 'Şah Cihan’ın yaptırdığı Jama Mescidi, 25.000 kişiyi ağırlayabilen kapasitesiyle Hindistan’ın en büyük camilerindendir. Hemen yanındaki tarihî Chandni Chowk çarşısı ise dar sokakları, baharatları ve kaotik canlılığıyla eski Delhi’nin kalbidir.' },
    { name: 'Hindistan Kapısı', desc: 'I. Dünya Savaşı’nda ve Afgan savaşlarında hayatını kaybeden Hint askerlerinin anısına dikilen bu 42 metrelik anıtsal zafer takı, Yeni Delhi’nin merkezindedir. Çevresindeki geniş çim alanlar, akşamları halkın toplandığı popüler bir mekândır.' },
    { name: 'Lotus Tapınağı', desc: 'Açan bir nilüfer çiçeğini andıran 27 beyaz mermer “yaprağından” oluşan bu çarpıcı yapı, bir Bahai ibadet evidir. Her din ve inançtan insana açık olan bu tapınak, sessizliği ve zarif modern mimarisiyle huzurlu bir mekân sunar.' },
    { name: 'Akshardham', desc: 'Geleneksel Hindu mimarisiyle inşa edilen bu devasa tapınak kompleksi, binlerce oyma heykel, sütun ve fil figürüyle hayranlık uyandırır. Görkemli ölçeği ve incelikli işçiliğiyle Hint kültürünü ve maneviyatını kutlayan modern bir başyapıttır.' },
    { name: 'Raj Ghat & Chandni Chowk', desc: 'Raj Ghat, Hindistan’ın bağımsızlık lideri Mahatma Gandhi’nin yakıldığı yerdeki sade siyah mermer anıttır. Yakınındaki tarihî Chandni Chowk çarşısı ise sokak lezzetleri, kuyumcuları ve kalabalığıyla eski Delhi’nin canlı ticaret merkezidir.' },
  ],
  agra: [
    { name: 'Tac Mahal', desc: 'Babür İmparatoru Şah Cihan’ın, ölen sevgili eşi Mümtaz Mahal’in anısına yaptırdığı bu beyaz mermer türbe, dünyanın en büyük aşk anıtı kabul edilir. Kusursuz simetrisi ve zarafetiyle dünyanın yeni yedi harikasından biri ve bir UNESCO mirasıdır.' },
    { name: 'Agra Kalesi', desc: 'Yamuna Nehri kıyısındaki bu görkemli kızıl kumtaşı kale, Babür imparatorlarının ana ikametgâhıydı. İmparator Şah Cihan’ın oğlu tarafından hapsedildiği ve Tac Mahal’i uzaktan seyrettiği bu UNESCO mirası, saraylar ve camiler barındırır.' },
    { name: 'Fatehpur Sikri', desc: 'İmparator Ekber tarafından kısa süreliğine Babür başkenti olarak inşa edilen bu görkemli kızıl taş şehir, su kıtlığı nedeniyle terk edilmiştir. Olağanüstü korunmuş sarayları ve camisiyle donmuş bir zaman kapsülü gibidir.' },
    { name: 'Mehtab Bagh', desc: 'Yamuna Nehri’nin karşı kıyısındaki bu bahçe, Tac Mahal ile mükemmel bir hizada yer alır ve anıtın en güzel manzarasını sunar. Özellikle gün batımında ve kalabalıktan uzak, huzurlu bir açıdan Tac Mahal’i izlemek için idealdir.' },
  ],
  jaipur: [
    { name: 'Amber Kalesi', desc: 'Bir tepenin üzerinde yükselen bu görkemli kale-saray, kızıl kumtaşı ve mermer yapısıyla Racput mimarisinin bir başyapıtıdır. İçindeki, binlerce küçük aynayla süslü “Ayna Sarayı” (Sheesh Mahal), tek bir mumun ışığında yıldızlı bir gökyüzüne dönüşür.' },
    { name: 'Hawa Mahal', desc: 'Adı “Rüzgâr Sarayı” anlamına gelen bu beş katlı yapı, 953 küçük pencereden (jharokha) oluşan pembe petek gibi cephesiyle ünlüdür. Bu pencereler, kraliyet kadınlarının görünmeden sokaktaki şenlikleri izlemesini ve sarayın serin kalmasını sağlıyordu.' },
    { name: 'Şehir Sarayı', desc: 'Jaipur’un kurucusu tarafından yaptırılan ve hâlâ kraliyet ailesinin bir bölümünde yaşadığı bu görkemli saray kompleksi, Racput ve Babür mimarisini birleştirir. Avluları, bahçeleri ve müzeleriyle kentin kraliyet tarihinin kalbidir.' },
    { name: 'Jantar Mantar', desc: '18. yüzyılda astronom-kral II. Jai Singh tarafından inşa edilen bu gözlemevi, dünyanın en büyük taş güneş saati de dahil olmak üzere devasa astronomi aletlerinden oluşur. Bu bilimsel aletler, bugün bile zamanı ve gök cisimlerini büyük bir doğrulukla ölçer.' },
  ],
  varanasi: [
    { name: 'Ganj Ghat’ları', desc: 'Kutsal Ganj Nehri kıyısındaki bu basamaklı rıhtımlar (ghat), Hinduizm’in en kutsal ritüellerine sahne olur. Şafak vakti nehirde arınan hacılar ve tekneyle izlenen bu manevi atmosfer, dünyanın en eski yaşayan şehirlerinden birinin ruhunu yansıtır.' },
    { name: 'Ganga Aarti', desc: 'Her akşam Dashashwamedh Ghat’ta düzenlenen bu görkemli ateş töreni, kutsal Ganj Nehri’ni onurlandırır. Rahiplerin senkronize hareketlerle dev yağ lambalarını salladığı bu ritüel, ilahiler ve çanlar eşliğinde büyüleyici bir manevi gösteridir.' },
    { name: 'Kashi Vishwanath', desc: 'Tanrı Şiva’ya adanan bu tapınak, Hinduizm’in en kutsal mabetlerinden biridir ve “Altın Tapınak” olarak da bilinir. Kubbesi ve kulesi yaklaşık 800 kilogram altınla kaplı olan bu mabet, milyonlarca hacı için en önemli hac merkezidir.' },
    { name: 'Sarnath', desc: 'Varanasi yakınlarındaki bu kutsal yer, Buda’nın aydınlanmasının ardından ilk vaazını verdiği ve Budizm’i başlattığı noktadır. Antik stupaları ve manastır kalıntılarıyla, dünya çapında Budistler için en önemli hac merkezlerinden biridir.' },
  ],
  mumbai: [
    { name: 'Hindistan Kapısı', desc: 'İngiliz Kralı V. George’un ziyaretini anmak için 20. yüzyıl başında inşa edilen bu görkemli zafer takı, Arap Denizi’ne bakar. Bir zamanlar denizden gelenlerin şehre giriş kapısı olan bu anıt, bugün Mumbai’nin en tanınan simgesidir.' },
    { name: 'CST (Victoria Terminus)', desc: 'Viktorya dönemi gotik mimarisiyle Hint geleneklerini birleştiren bu görkemli tren garı, dünyanın en gösterişli istasyonlarından biridir. Her gün milyonlarca yolcunun kullandığı bu işlevsel başyapıt, UNESCO Dünya Mirası listesindedir.' },
    { name: 'Elephanta Mağaraları', desc: 'Mumbai limanının açığındaki bir adada yer alan bu mağaralar, kayaya oyulmuş görkemli Hindu tapınaklarından oluşur. Özellikle Tanrı Şiva’yı üç yüzüyle betimleyen devasa heykel (Trimurti), Hint kaya sanatının bir başyapıtıdır.' },
    { name: 'Marine Drive', desc: 'Arap Denizi kıyısı boyunca uzanan bu zarif bulvar, geceleri sokak lambalarının oluşturduğu kavisli ışık dizisi nedeniyle “Kraliçenin Kolyesi” olarak anılır. Kentlilerin gün batımını izlediği ve nefes aldığı en sevilen mekândır.' },
    { name: 'Dhobi Ghat', desc: 'Dünyanın en büyük açık hava çamaşırhanesi olan bu alan, yüzlerce beton yıkama teknesinde elle çamaşır yıkayan “dhobi” denen işçileriyle şaşırtıcı bir manzara sunar. Nesilden nesile aktarılan bu geleneksel meslek, Mumbai’nin özgün bir yüzüdür.' },
  ],
  dubai: [
    { name: 'Burj Khalifa', desc: '828 metre yüksekliğiyle dünyanın en yüksek binası olan bu görkemli gökdelen, Dubai’nin hırsının ve mühendislik gücünün simgesidir. 148. kattaki gözlem güvertesinden, çöl ile denizin buluştuğu kentin baş döndürücü panoraması izlenir.' },
    { name: 'Dubai Mall & Fountain', desc: 'Dünyanın en büyük alışveriş merkezlerinden biri olan Dubai Mall, bir akvaryum, buz pisti ve yüzlerce mağaza barındırır. Önündeki devasa yapay gölde sergilenen müzik ve ışık eşliğindeki Dubai Fıskiyesi gösterisi, her akşam büyüler.' },
    { name: 'Palm Jumeirah', desc: 'Denizin doldurulmasıyla bir palmiye ağacı biçiminde inşa edilen bu devasa yapay ada, insan yapımı bir mühendislik harikasıdır. Lüks otelleri, villaları ve plajlarıyla Dubai’nin sınır tanımayan modern lüksünün bir simgesidir.' },
    { name: 'Al Fahidi & Abra', desc: 'Al Fahidi tarihî mahallesi, rüzgâr kuleli geleneksel binaları ve dar sokaklarıyla petrol öncesi eski Dubai’nin ruhunu yaşatır. Dubai Deresi üzerinde geleneksel “abra” denen ahşap taksi teknelerine binmek, kentin ticari köklerini deneyimletir.' },
    { name: 'Çöl Safari', desc: 'Dubai’yi çevreleyen altın rengi kum tepelerinde (dune bashing) yapılan bu heyecanlı araç safarisi, deve turları ve çöl kamplarıyla tamamlanır. Kum tepeleri üzerindeki gün batımı ve yıldızlı gökyüzü altında yenen yemek, unutulmaz bir deneyim sunar.' },
    { name: 'Museum of the Future', desc: 'Üzeri Arapça hat sanatıyla bezeli halka (torus) biçimli çarpıcı yapısıyla bu müze, dünyanın en güzel binalarından biri kabul edilir. İçindeki interaktif sergilerle bilim, teknoloji ve insanlığın olası geleceğini keşfetmeye davet eder.' },
    { name: 'Dubai Frame', desc: 'Dev bir resim çerçevesi biçimindeki bu 150 metrelik altın rengi yapı, bir yandan eski Dubai’yi diğer yandan modern gökdelenleri “çerçeveler”. Camdan zeminli üst köprüsü, kentin geçmişi ile geleceği arasında sembolik bir bakış sunar.' },
    { name: 'Madinat Jumeirah & Souk', desc: 'Geleneksel Arap kasabasını canlandıran bu lüks tatil beldesi, yapay su kanalları (abra ile gezilen) ve rüzgâr kuleleriyle büyüler. İçindeki geleneksel çarşısı (souk) ve ünlü yelken biçimli Burj Al Arab oteli manzarasıyla ünlüdür.' },
  ],
  abudabi: [
    { name: 'Şeyh Zayed Camii', desc: 'BAE’nin kurucusu Şeyh Zayed’in vizyonuyla yaptırılan bu bembeyaz mermer cami, 40.000 kişiyi ağırlayabilen kapasitesiyle ülkenin en büyüğüdür. Dünyanın en büyük el dokuması halısı ve devasa avizeleriyle göz kamaştıran bir mimari şaheserdir.' },
    { name: 'Louvre Abu Dhabi', desc: 'Ünlü mimar Jean Nouvel’in tasarladığı bu müze, iç içe geçmiş katmanlardan oluşan devasa kubbesinden süzülen “ışık yağmuru” etkisiyle büyüler. Paris’teki Louvre ile ortaklık kuran müze, insanlık tarihini kültürler arası bir bakışla sergiler.' },
    { name: 'Qasr Al Watan', desc: 'Halka açılan bu görkemli başkanlık sarayı, İslam sanatı ve mimarisinin ihtişamını sergileyen bir kültür merkezidir. Devasa kubbesi, el yazması eserleri ve zengin süslemeleriyle Arap mirasını ve devlet geleneğini yansıtır.' },
    { name: 'Ferrari World', desc: 'Ünlü İtalyan otomobil markasına adanmış bu kapalı tema parkı, kırmızı dev çatısıyla dikkat çeker. İçindeki Formula Rossa, saatte 240 kilometreye ulaşan hızıyla dünyanın en hızlı hız treni olarak adrenalin tutkunlarını cezbeder.' },
  ],
  bangkok: [
    { name: 'Büyük Saray & Zümrüt Buda', desc: 'Bir buçuk asır boyunca Tayland krallarının ikametgâhı olan bu görkemli saray kompleksi, ışıltılı altın kuleleri ve süslemeleriyle büyüler. İçindeki tapınakta yer alan ve tek bir yeşim taşından yontulan Zümrüt Buda, ülkenin en kutsal dini objesidir.' },
    { name: 'Wat Arun', desc: 'Chao Phraya Nehri kıyısındaki bu görkemli tapınak, adını (“Şafak Tapınağı”) gün doğumunda üzerine düşen ışıkla parlamasından alır. Rengârenk porselen ve deniz kabuğu parçalarıyla süslü sivri kuleleri (prang), Bangkok’un en zarif simgelerindendir.' },
    { name: 'Wat Pho', desc: 'Bangkok’un en eski ve en büyük tapınaklarından biri olan Wat Pho, 46 metre uzunluğundaki devasa altın kaplama Yatan Buda heykeliyle ünlüdür. Aynı zamanda geleneksel Tay masajının doğduğu ve öğretildiği yer olarak da bilinir.' },
    { name: 'Chatuchak Pazarı', desc: 'Yaklaşık 15.000 tezgâhıyla dünyanın en büyük hafta sonu pazarlarından biri olan Chatuchak, adeta bir labirenttir. Kıyafetten antikaya, el sanatlarından yerel lezzetlere kadar akla gelen her şeyin bulunduğu canlı bir alışveriş cennetidir.' },
    { name: 'Chao Phraya & Tuk-tuk', desc: 'Bangkok’un yaşam damarı olan Chao Phraya Nehri, tapınaklara ve çarşılara ulaşan tekneleriyle şehri keşfetmenin en keyifli yoludur. Karada ise üç tekerlekli, rengârenk “tuk-tuk” taksileri, kentin kaotik trafiğinde ikonik bir deneyim sunar.' },
    { name: 'Wat Saket (Altın Dağ)', desc: 'Yapay bir tepenin üzerine kurulu bu tapınak, altın rengi stupasıyla “Altın Dağ” olarak bilinir. 300 basamaklık dairesel bir merdivenle çıkılan zirvesinden, düz bir arazide kurulu Bangkok’un ender panoramalarından biri izlenir.' },
    { name: 'Khao San Road', desc: 'Bir zamanlar bir pirinç pazarı olan bu kısa cadde, bugün dünyanın dört bir yanından gelen sırt çantalı gezginlerin uğrak noktasıdır. Ucuz konaklama, sokak lezzetleri ve hareketli barlarıyla Bangkok’un en canlı gece hayatı merkezlerindendir.' },
    { name: 'Jim Thompson Evi', desc: 'Tayland ipek endüstrisini canlandıran Amerikalı iş insanı Jim Thompson’ın geleneksel tik ağacından evlerden oluşturduğu bu ev, bir müzedir. Asya sanat koleksiyonu ve sahibinin gizemli kayboluş öyküsüyle büyüleyici bir mekândır.' },
  ],
  chiangmai: [
    { name: 'Doi Suthep', desc: 'Chiang Mai’ye tepeden bakan bir dağın zirvesindeki bu kutsal tapınak, altın kaplama stupasıyla büyüler. Efsaneye göre kutsal bir emaneti taşıyan beyaz bir filin durduğu yere kurulan tapınak, şehrin ve vadinin muhteşem manzarasını sunar.' },
    { name: 'Eski Şehir Tapınakları', desc: 'Chiang Mai’nin eski su hendeği ve surlarla çevrili tarihî merkezi, yüzyıllar öncesine dayanan yüzlerce Budist tapınağı (wat) barındırır. Antik Lanna Krallığı’nın başkenti olan bu bölge, keşşiflerin sokaklarda dolaştığı manevi bir atmosfere sahiptir.' },
    { name: 'Gece Pazarı', desc: 'Chiang Mai’nin ünlü gece pazarları, kuzey Tayland’ın zengin el sanatları geleneğini sergiler. Dağ kabilelerinin ürettiği tekstiller, gümüş takılar ve ahşap oymaların yanı sıra çeşitli sokak lezzetleriyle canlı bir alışveriş deneyimi sunar.' },
    { name: 'Etik Fil Kampı', desc: 'Chiang Mai çevresi, fillere binmek yerine onları doğal ortamlarında besleyip gözlemleme imkânı sunan etik ve sorumlu fil bakım merkezleriyle ünlüdür. Kötü muameleden kurtarılan filleri koruyan bu kamplar, doğayla saygılı bir buluşma sağlar.' },
  ],
  phuket: [
    { name: 'Phi Phi Adaları', desc: 'Phuket açıklarındaki bu takımada, yüksek kireçtaşı kayalıkları, turkuaz suları ve beyaz kumlu plajlarıyla bir tropik cennettir. Ünlü “The Beach” filmine sahne olan Maya Körfezi, tekne turlarıyla ulaşılan nefes kesici bir doğa harikasıdır.' },
    { name: 'Phang Nga (James Bond)', desc: 'Zümrüt yeşili sularından dimdik yükselen kireçtaşı kayalıklarıyla ünlü bu körfez, bir James Bond filminde yer aldığı için “James Bond Adası” olarak tanınır. Kano ve tekne turlarıyla keşfedilen bu benzersiz coğrafya, doğanın bir başyapıtıdır.' },
    { name: 'Büyük Buda', desc: 'Nakkerd Tepesi’nin zirvesinde yükselen 45 metre yüksekliğindeki bu beyaz mermer Buda heykeli, tüm adaya hâkimdir. Huzurlu atmosferi ve zirveden sunduğu 360 derecelik panoramik ada manzarasıyla önemli bir manevi ve turistik noktadır.' },
    { name: 'Phuket Eski Şehri', desc: 'Phuket’in tarihî merkezi, bir zamanlar kalay ticaretiyle zenginleşen kentin mirasını yansıtan renkli Çin-Portekiz (Sino-Portuguese) tarzı binalarla doludur. Şirin kafeleri, butikleri ve sokak sanatlarıyla adanın plajlardan farklı, kültürel bir yüzünü sunar.' },
    { name: 'Patong Plajı', desc: 'Phuket’in en ünlü ve en hareketli plajı olan Patong, geniş kumsalı ve su sporlarıyla gündüzleri, Bangla Yolu’ndaki barları ve kulüpleriyle geceleri canlanır. Adanın eğlence ve gece hayatının kalbi olarak kabul edilir.' },
  ],
  bali: [
    { name: 'Tegallalang Pirinç Terasları', desc: 'Ubud yakınlarındaki bu görkemli pirinç terasları, Bali’nin geleneksel “subak” sulama sistemiyle şekillendirilmiş yemyeşil basamaklardan oluşur. Vadiye doğru uzanan bu manzara, adanın tarım kültürünü ve doğal güzelliğini yansıtan ikonik bir noktadır.' },
    { name: 'Tanah Lot', desc: 'Deniz kıyısındaki bir kaya oluşumunun üzerine kurulu bu tapınak, Bali’nin en önemli deniz mabetlerinden ve en çok fotoğraflanan simgelerindendir. Gelgitle birlikte etrafı suyla çevrilen bu tapınak, özellikle gün batımında büyüleyici bir manzara sunar.' },
    { name: 'Uluwatu Tapınağı', desc: 'Okyanusa dik inen 70 metrelik bir uçurumun kenarına kurulu bu antik deniz tapınağı, nefes kesen bir konuma sahiptir. Her akşam gün batımında sahnelenen, ateş ve koro eşliğindeki geleneksel Kecak dansı, unutulmaz bir kültürel deneyimdir.' },
    { name: 'Ubud Maymun Ormanı', desc: 'Ubud’un kalbindeki bu kutsal orman, yüzlerce uzun kuyruklu makak maymununa ve antik yosun kaplı tapınaklara ev sahipliği yapar. Balililer için manevi öneme sahip bu doğal alan, doğa ile maneviyatı bir araya getirir.' },
    { name: 'Seminyak & Kuta Plajları', desc: 'Bali’nin batı kıyısındaki bu komşu plajlar, geniş kumsalları ve düzenli dalgalarıyla sörfçüler için idealdir. Kuta canlı ve hareketli atmosferiyle, Seminyak ise şık restoranları ve plaj kulüpleriyle adanın gün batımı ve eğlence merkezidir.' },
  ],
  yogyakarta: [
    { name: 'Borobudur', desc: '9. yüzyılda inşa edilen bu görkemli anıt, dünyanın en büyük Budist tapınağıdır ve devasa bir taş mandala biçimindedir. Binlerce kabartma paneli ve çan biçimli stupalarıyla, gün doğumunda sisin arasından yükselen manzarası büyüleyicidir.' },
    { name: 'Prambanan', desc: 'Borobudur ile aynı dönemden kalan bu görkemli Hindu tapınak kompleksi, göğe uzanan sivri ve zarif kuleleriyle ünlüdür. Tanrılar Şiva, Vişnu ve Brahma’ya adanan bu UNESCO mirası, Endonezya’nın en büyük ve en etkileyici Hindu tapınağıdır.' },
    { name: 'Kraton (Sultan Sarayı)', desc: 'Yogyakarta, hâlâ bir sultan tarafından yönetilen ve saray kültürünü yaşatan ender bir şehirdir. Bu görkemli saray kompleksi (Kraton), geleneksel Java mimarisi, dans gösterileri ve gölge oyunlarıyla (wayang) canlı bir kültür merkezidir.' },
    { name: 'Malioboro Caddesi', desc: 'Yogyakarta’nın en ünlü ve en canlı alışveriş caddesi olan Malioboro, kentin kalbi olarak kabul edilir. Geleneksel Java kumaşı “batik”, gümüş takılar, deri kuklalar ve sokak lezzetleri sunan sayısız tezgâh ve dükkânla doludur.' },
    { name: 'Taman Sari', desc: 'Adı “Güzel Bahçe” anlamına gelen bu tarihî kompleks, bir zamanlar Yogyakarta sultanının dinlenme ve meditasyon amacıyla kullandığı bir “su kalesiydi”. Havuzları, yeraltı geçitleri ve özgün mimarisiyle sarayın gizemli bir bölümüdür.' },
  ],
  hanoi: [
    { name: 'Eski Mahalle', desc: 'Hanoi’nin bin yıllık tarihî çekirdeği olan bu bölge, her biri belirli bir zanaata veya loncaya ayrılmış 36 dar sokaktan oluşur. Motosikletlerin, sokak satıcılarının ve kafelerin oluşturduğu kaotik canlılığıyla kentin en otantik yüzüdür.' },
    { name: 'Hoan Kiem & Ngoc Son', desc: 'Efsanevi bir kaplumbağa ve kutsal kılıç öyküsüne konu olan Hoan Kiem Gölü, Hanoi’nin huzurlu kalbidir. Göl ortasındaki adacıkta yer alan Ngoc Son Tapınağı’na, ikonik kırmızı ahşap “Doğan Güneş Köprüsü” ile ulaşılır.' },
    { name: 'Ho Chi Minh Mozolesi', desc: 'Vietnam’ın bağımsızlık lideri “Amca Ho”nun naaşının korunduğu bu görkemli granit anıt, ulusal bir saygı merkezidir. Çevresindeki geniş meydan, başkanlık sarayı ve müzeyle birlikte önemli bir tarihî kompleks oluşturur.' },
    { name: 'Edebiyat Tapınağı', desc: '1070’te Konfüçyüs’e adanarak kurulan bu tapınak, aynı zamanda Vietnam’ın ilk ulusal üniversitesine ev sahipliği yapmıştır. Mezun olan bilginlerin adlarının kazındığı taş tabletleri ve dingin avlularıyla ülkenin köklü eğitim geleneğini yansıtır.' },
    { name: 'Su Kuklası Tiyatrosu', desc: 'Kuzey Vietnam’ın pirinç tarlalarında doğan bu benzersiz geleneksel sanat, bel hizasına kadar suyla dolu bir sahnede sergilenir. Ahşap kuklaların su üstünde dans ettiği, canlı müzik eşliğindeki bu gösteri, köy yaşamı ve efsaneleri anlatır.' },
  ],
  hochiminh: [
    { name: 'Savaş Kalıntıları Müzesi', desc: 'Bu müze, Vietnam Savaşı’nın dehşetini ve insani sonuçlarını çarpıcı fotoğraflar, askeri araçlar ve sergilerle gözler önüne serer. Savaşın acılarını güçlü bir şekilde anlatan bu mekân, ziyaretçilere derin bir barış çağrısı yapar.' },
    { name: 'Notre-Dame & Merkez Postane', desc: 'Fransız sömürge döneminden kalma bu iki komşu yapı, kentin geçmişine tanıklık eder. Kızıl tuğlaları Fransa’dan getirilen Notre-Dame Katedrali ve Gustave Eiffel’in etkisini taşıyan görkemli Merkez Postane, dönemin zarafetini yansıtır.' },
    { name: 'Cu Chi Tünelleri', desc: 'Ho Chi Minh yakınlarındaki bu devasa yeraltı tünel ağı, Vietnam Savaşı sırasında gerillaların yaşadığı, saklandığı ve savaştığı stratejik bir üstü. Yüzlerce kilometre uzunluğundaki bu tüneller, dönemin çetin mücadelesinin bir kanıtıdır.' },
    { name: 'Ben Thanh Pazarı', desc: 'Ho Chi Minh’in ikonik simgesi olan bu tarihî kapalı çarşı, kentin en hareketli alışveriş ve gastronomi merkezidir. El sanatlarından tekstile, taze ürünlerden yerel lezzetlere kadar her şeyin bulunduğu, pazarlığın kuralı olduğu canlı bir mekândır.' },
    { name: 'Bağımsızlık Sarayı', desc: 'Bir Kuzey Vietnam tankının kapılarını yıkarak girmesiyle Vietnam Savaşı’nın sona erdiği tarihî yer olan bu saray, ülkenin birleşmesini simgeler. 1960’lar mimarisi ve dönemin eşyalarıyla korunan yapı, zamanda donmuş bir tarih anıtıdır.' },
  ],
  halong: [
    { name: 'Gecelemeli Cruise', desc: 'Halong Körfezi’ni deneyimlemenin en iyi yolu, denizden yükselen binlerce kireçtaşı ada arasında tekneyle konaklamaktır. Zümrüt yeşili sular üzerinde geçirilen gece, gün doğumu ve batımının büyülü manzarasını sunan unutulmaz bir deneyimdir.' },
    { name: 'Sung Sot Mağarası', desc: 'Adı “Sürprizler Mağarası” anlamına gelen bu devasa oluşum, körfezin en büyük ve en görkemli mağaralarından biridir. Aydınlatılmış dev odaları, sarkıt ve dikitleriyle ziyaretçilerini şaşırtan büyüleyici bir yeraltı dünyası sunar.' },
    { name: 'Ti Top Adası', desc: 'Halong Körfezi’ndeki bu küçük ada, hem yüzülebilen bir plaja hem de bir gözlem noktasına ev sahipliği yapar. Zirvesine çıkan yaklaşık 400 basamağın ardından, körfezin ve dağınık adaların 360 derecelik nefes kesici panoraması izlenir.' },
    { name: 'Kano & Yüzen Köyler', desc: 'Halong Körfezi’nin sarp kayalıkları arasındaki sessiz koyları ve gizli lagünleri keşfetmenin en yakın yolu kanodur. Körfez sularında yaşayan geleneksel yüzen balıkçı köyleri ise, bölgenin kendine özgü su üstü yaşam kültürünü yansıtır.' },
  ],
  siemreap: [
    { name: 'Angkor Wat', desc: '12. yüzyılda Khmer İmparatorluğu tarafından inşa edilen bu görkemli tapınak, dünyanın en büyük dini anıtıdır. Kamboçya’nın bayrağında da yer alan bu ulusal simge, özellikle beş kulesinin ardından yükselen gün doğumu manzarasıyla büyüler.' },
    { name: 'Bayon (Angkor Thom)', desc: 'Angkor Thom antik başkentinin merkezindeki bu tapınak, kulelerini süsleyen 200’den fazla devasa, huzurla gülümseyen taş yüzüyle ünlüdür. Her yöne bakan bu gizemli yüzler, ziyaretçilerde derin bir hayranlık uyandırır.' },
    { name: 'Ta Prohm', desc: 'Diğer tapınakların aksine kısmen doğaya bırakılan Ta Prohm, dev ipek pamuk ağaçlarının kökleri tarafından sarılmış ve içine işlemiş haliyle büyüler. Doğa ile mimarinin iç içe geçtiği bu tapınak, “Tomb Raider” filmine de sahne olmuştur.' },
    { name: 'Tonle Sap', desc: 'Güneydoğu Asya’nın en büyük tatlı su gölü olan Tonle Sap, mevsimsel olarak dramatik biçimde büyüyüp küçülür. Göl üzerinde kazıklar üstüne kurulu veya tamamen suda yüzen köyler, buranın kendine özgü su üstü yaşamını sergiler.' },
  ],
  singapur: [
    { name: 'Gardens by the Bay', desc: 'Bu fütüristik bahçe, geceleri ışık gösterisi sunan 50 metreye varan yükseklikteki yapay “Süper Ağaçlar”ıyla ünlüdür. İçindeki dev cam seralar, bulut ormanını ve dünyanın dört bir yanından bitkileri barındıran bir doğa harikasıdır.' },
    { name: 'Marina Bay Sands', desc: 'Üç gökdelenin üzerine oturtulmuş dev bir gemiyi andıran çatısıyla bu yapı, Singapur’un modern siluetinin simgesidir. Çatısındaki sonsuzluk havuzu ve körfezdeki gece ışık gösterisiyle dünyaca ünlü bir mimari harikadır.' },
    { name: 'Sentosa', desc: 'Singapur’un hemen açığındaki bu eğlence adası, plajları, tema parkları (Universal Studios dahil), akvaryumu ve golf sahalarıyla bir tatil cennetidir. Ailelerin ve eğlence arayanların gözde noktası olan bu ada, sürekli bir aktivite merkezidir.' },
    { name: 'Merlion Park', desc: 'Aslan başlı, balık gövdeli mitolojik bir yaratık olan Merlion, Singapur’un resmi simgesi ve turistik ikonudur. Ağzından körfeze su püskürten bu heykel, kentin denizcilik geçmişini ve “Aslan Şehri” adını temsil eder.' },
    { name: 'Chinatown & Little India', desc: 'Singapur’un çok kültürlü yapısını yansıtan bu iki canlı mahalle, farklı dünyalara açılan kapılardır. Tapınakları ve geleneksel dükkânlarıyla Chinatown ile rengârenk binaları ve baharat kokan sokaklarıyla Little India, kentin etnik zenginliğini sergiler.' },
    { name: 'Clarke Quay', desc: 'Singapur Nehri kıyısındaki bu tarihî rıhtım, bir zamanlar ticaret depolarının olduğu yerde bugün renkli restoranlar, barlar ve kulüplere ev sahipliği yapar. Işıl ışıl atmosferiyle kentin en canlı nehir kenarı eğlence merkezidir.' },
    { name: 'Singapore Flyer', desc: 'Asya’nın en büyük gözlem çarklarından biri olan bu dev tekerlek, Marina Körfezi’nin kenarında yükselir. Kapsüllerinden, Singapur’un fütüristik silüetinin ve açık havada komşu ülkelerin panoramik manzarası izlenir.' },
    { name: 'Botanik Bahçesi (Orkide)', desc: '1859’dan bu yana varlığını sürdüren bu tropik botanik bahçesi, Singapur’un ilk UNESCO Dünya Mirası alanıdır. İçindeki Ulusal Orkide Bahçesi, binlerce rengârenk orkide türüyle dünyanın en büyük orkide sergisini sunar.' },
  ],
  isfahan: [
    { name: 'Nakş-ı Cihan Meydanı', desc: 'Safevi Şahı I. Abbas döneminde 17. yüzyılda düzenlenen bu devasa meydan, dünyanın en büyük tarihî meydanlarından biridir. Dört bir yanı görkemli camiler, saray ve çarşıyla çevrili bu UNESCO alanı, “İsfahan dünyanın yarısıdır” deyişini doğrular.' },
    { name: 'Şah (İmam) Camii', desc: 'Nakş-ı Cihan Meydanı’na hâkim olan bu görkemli cami, Safevi mimarisinin doruk noktasıdır. Muhteşem turkuaz kubbesi, incelikli çini işçiliği ve olağanüstü akustiğiyle İran İslam sanatının bir başyapıtı kabul edilir.' },
    { name: 'Şeyh Lütfullah Camii', desc: 'Kraliyet ailesinin özel ibadeti için yaptırılan bu zarif cami, minaresiz ve avlusuz olmasıyla sıra dışıdır. İçindeki krem-pembe kubbesi, gün boyunca değişen ışıkla farklı renklere bürünerek büyüleyici bir tavus kuşu deseni oluşturur.' },
    { name: 'Ali Kapı Sarayı', desc: 'Meydana bakan bu altı katlı köşk, Safevi şahlarının meydandaki tören ve oyunları izlediği bir localardı. Üst katındaki, akustiği güçlendirmek için vazo biçiminde oyulmuş duvarlara sahip müzik odasıyla ünlüdür.' },
    { name: 'Si-o-se-pol Köprüsü', desc: 'Adı “otuz üç kemer” anlamına gelen bu görkemli köprü, Zayanderud Nehri üzerindeki en uzun ve en ünlü Safevi köprüsüdür. Hem bir geçit hem de bir bent işlevi gören yapı, akşamları ışıklandırılarak kentlilerin buluşma noktası olur.' },
  ],
  siraz: [
    { name: 'Nasır el-Mülk (Pembe Cami)', desc: '“Pembe Cami” olarak da bilinen bu 19. yüzyıl mabedi, cephesindeki bol pembe çini kullanımıyla ünlüdür. Ancak asıl büyüsü, sabah güneşinin renkli vitraylardan süzülerek iç mekânı bir renk ve ışık cümbüşüne dönüştürmesiyle ortaya çıkar.' },
    { name: 'Persepolis', desc: 'MÖ 6. yüzyılda kurulan bu görkemli şehir, Pers Ahameniş İmparatorluğu’nun tören başkentiydi. Devasa sütunları, kabartmalı merdivenleri ve saraylarıyla antik dünyanın en büyük imparatorluklarından birinin ihtişamını yansıtan bir UNESCO mirasıdır.' },
    { name: 'Hafız Türbesi', desc: 'İranlıların en çok sevdiği şair Hafız-ı Şirazi’nin bir gül bahçesi içindeki bu anıt mezarı, ülke için manevi bir merkezdir. İranlılar, şairin şiirlerinden fal bakmak ve ona saygı sunmak için bu huzurlu ve romantik mekânı ziyaret eder.' },
    { name: 'Vakil Çarşısı', desc: '18. yüzyıldan kalma bu tarihî kapalı çarşı, yüksek tuğla kubbeli tavanları ve serin atmosferiyle Şiraz’ın ticaret merkezidir. Halılar, baharatlar ve el sanatları sunan dükkânlarıyla İpek Yolu’nun ticaret geleneğini yaşatır.' },
    { name: 'Eram Bahçesi', desc: 'Adı “cennet” anlamına gelen bu görkemli bahçe, servi ağaçları, gül tarhları ve zarif bir köşküyle klasik Pers bahçe (çar bağ) sanatının en güzel örneklerindendir. Huzurlu atmosferi ve simetrik düzeniyle UNESCO Dünya Mirası listesindedir.' },
  ],
  tahran: [
    { name: 'Golestan Sarayı', desc: 'Kaçar Hanedanlığı’nın görkemli kraliyet sarayı olan bu kompleks, Tahran’ın en eski tarihî anıtlarındandır. Ayna işçiliğiyle bezeli salonları, çini kaplı cepheleri ve bahçeleriyle, Pers sanatını Avrupa etkileriyle birleştiren bir UNESCO mirasıdır.' },
    { name: 'Ulusal Mücevher Hazinesi', desc: 'Bir bankanın kasalarında sergilenen bu koleksiyon, İran şahlarının yüzyıllar boyunca biriktirdiği paha biçilmez mücevherleri barındırır. Dünyanın en büyük pembe elması “Derya-yı Nur” ve mücevherli taht, göz kamaştıran zenginlikler sunar.' },
    { name: 'Milad Kulesi', desc: '435 metre yüksekliğiyle İran’ın en yüksek kulesi olan Milad, Tahran’ın modern siluetinin simgesidir. Gözlem güvertesi ve döner restoranından, dev metropolün ve arka plandaki Elburz Dağları’nın panoraması izlenir.' },
    { name: 'Büyük Çarşı (Bazaar)', desc: 'Kilometrelerce uzanan üstü kapalı geçitleriyle Tahran’ın Büyük Çarşısı, sadece bir alışveriş merkezi değil, ülkenin ekonomik ve siyasi kalbidir. Halılar, altınlar ve baharatlarla dolu bu labirent, İran ticaret kültürünün canlı merkezidir.' },
  ],
  petra: [
    { name: 'Hazine (Al-Khazneh)', desc: 'Nabatilerin MÖ 1. yüzyılda kayaya oyduğu bu görkemli anıt, dar Siq kanyonunun sonunda aniden belirmesiyle nefes keser. Petra’nın simgesi olan bu incelikli cephe, aslında bir kral mezarı olup dünyanın yeni yedi harikasından biridir.' },
    { name: 'Siq', desc: 'Petra’ya girişi sağlayan bu 1,2 kilometrelik dar ve derin kanyon, iki yanında yükselen 80 metrelik kayalıklarla büyüler. Doğal bir fay hattının oluşturduğu bu görkemli geçit, sonunda beliren Hazine manzarasıyla dramatik bir giriş sunar.' },
    { name: 'Manastır (Ad-Deir)', desc: 'Petra’nın en büyük anıtı olan bu görkemli yapıya, kayalara oyulmuş yaklaşık 800 basamaklık bir yolun ardından ulaşılır. Hazine’ye benzese de ondan çok daha büyük olan bu anıt, zorlu tırmanışı ödüllendiren muhteşem manzaralar sunar.' },
    { name: 'Kraliyet Mezarları', desc: 'Petra’daki bir kaya duvarı boyunca sıralanan bu anıtsal mezarlar, Nabati krallarına ve soylularına aittir. Devasa cepheleri ve kayanın doğal renkli katmanlarıyla, antik kentin görkemli defin mimarisini gözler önüne serer.' },
    { name: 'Petra by Night', desc: 'Haftanın belirli geceleri düzenlenen bu özel etkinlikte, Siq kanyonu ve Hazine önü binlerce mumla aydınlatılır. Geleneksel müzik eşliğinde yaşanan bu büyülü deneyim, antik kenti tamamen farklı ve mistik bir atmosferde sunar.' },
  ],
  amman: [
    { name: 'Amman Citadel', desc: 'Şehrin en yüksek tepesindeki bu antik kale, Roma, Bizans ve Emevi dönemlerine ait kalıntılarıyla Amman’ın binlerce yıllık katmanlı tarihini yansıtır. Herkül Tapınağı ve Emevi Sarayı kalıntılarıyla kentin panoramasına hâkimdir.' },
    { name: 'Roma Tiyatrosu', desc: 'Amman’ın modern şehir merkezinin kalbinde yer alan bu görkemli tiyatro, MS 2. yüzyılda bir yamaca oyularak inşa edilmiştir. 6.000 kişilik kapasitesi ve olağanüstü akustiğiyle kentin Roma dönemindeki (Philadelphia) önemine tanıklık eder.' },
    { name: 'Rainbow Street', desc: 'Amman’ın en canlı caddelerinden biri olan Rainbow Street, kafeleri, restoranları ve butikleriyle kentin sosyal yaşamının merkezidir. Tarihî binaları ve şehre hâkim manzarasıyla, hem yerlilerin hem de ziyaretçilerin gözde uğrak noktasıdır.' },
    { name: 'Jerash', desc: 'Amman yakınlarındaki bu antik kent, dünyanın en iyi korunmuş Greko-Romen şehirlerinden biridir. Sütunlu caddeleri, oval forumu, tapınakları ve tiyatrolarıyla, bin yılı aşkın süre önce yaşanan görkemli kent yaşamını çarpıcı biçimde canlandırır.' },
  ],
  semerkand: [
    { name: 'Registan Meydanı', desc: 'Üç yanı görkemli ve devasa çinili medreselerle çevrili bu meydan, İpek Yolu’nun kalbindeki Semerkand’ın en ikonik simgesidir. Turkuaz kubbeleri ve altın süslemeleriyle bu topluluk, İslam mimarisinin en görkemli başyapıtlarından biridir.' },
    { name: 'Şah-ı Zinde', desc: 'Adı “Yaşayan Kral” anlamına gelen bu nekropol, bir yamaç boyunca sıralanan göz kamaştırıcı turkuaz kubbeli türbelerden oluşan kutsal bir sokaktır. Farklı dönemlere ait çini işçiliğinin gelişimini sergileyen bu alan, kutsal bir hac merkezidir.' },
    { name: 'Gur-i Emir', desc: 'Büyük fatih Timur (Tamerlan) ve ailesinin görkemli türbesi olan bu yapı, dilimli lacivert kubbesiyle ünlüdür. İçindeki muhteşem altın süslemeleriyle, sonraki dönem Babür mimarisine (Tac Mahal dahil) ilham veren bir başyapıttır.' },
    { name: 'Bibi-Hanım Camii', desc: 'Timur’un Hindistan seferinden dönüşte yaptırdığı bu devasa cami, döneminin en büyük ve en görkemli yapılarından biriydi. İddialı ölçeği ve anıtsal giriş kapısıyla, Timur İmparatorluğu’nun gücünü simgeleyen etkileyici bir eserdir.' },
    { name: 'Ulugbek Rasathanesi', desc: 'Timur’un torunu, astronom-kral Uluğ Bey’in 15. yüzyılda yaptırdığı bu rasathane, döneminin en gelişmiş bilim merkeziydi. Yıldızların konumunu olağanüstü bir doğrulukla ölçen dev sekstantı, ortaçağ İslam biliminin zirvesini temsil eder.' },
  ],
  buhara: [
    { name: 'Poi Kalyan & Minare', desc: 'Bu kompleksin merkezindeki 12. yüzyıldan kalma 47 metrelik Kalyan Minaresi, Cengiz Han’ın bile yıkmaya kıyamadığı görkemiyle ünlüdür. Bir dönem mahkûmların tepesinden atıldığı rivayet edildiği için “Ölüm Kulesi” olarak da anılır.' },
    { name: 'Ark Kalesi', desc: 'Buhara emirlerinin yüzyıllar boyunca ikametgâhı ve yönetim merkezi olan bu devasa toprak kale, kentin en eski yapısıdır. İçinde saraylar, camiler ve hazineler barındıran bu istihkâm, Buhara Emirliği’nin gücünün bir simgesiydi.' },
    { name: 'Lyabi-Hauz', desc: 'Etrafı asırlık dut ağaçları ve tarihî medreselerle çevrili bir havuzun oluşturduğu bu meydan, Buhara’nın en huzurlu ve en sevilen mekânıdır. Bir zamanlar kentin su ihtiyacını karşılayan bu havuz, bugün sosyal yaşamın kalbidir.' },
    { name: 'Çar Minar', desc: 'Adı “Dört Minare” anlamına gelen bu özgün yapı, dört köşesindeki turkuaz kubbeli kuleleriyle Buhara’nın diğer anıtlarından farklıdır. Bir medresenin giriş kapısı olarak inşa edilen bu şirin yapı, kentin en sevimli simgelerindendir.' },
    { name: 'Ticaret Kubbeleri', desc: 'Buhara’nın İpek Yolu üzerindeki ticaret merkezleri olan bu kubbeli çarşılar (tak), her biri kuyumculuk, takı veya börk gibi belirli bir zanaata ayrılmıştı. Yüzyıllardır ayakta duran bu serin geçitler, hâlâ el sanatları satan dükkânlarla doludur.' },
  ],
  katmandu: [
    { name: 'Durbar Meydanı', desc: 'Katmandu’nun eski kraliyet meydanı olan bu alan, incelikli ahşap oymalarla bezeli saraylar, tapınaklar ve avlularla çevrilidir. Nepal’in geleneksel Newar mimarisinin bir açık hava müzesi olan bu UNESCO alanı, kentin tarihî kalbidir.' },
    { name: 'Boudhanath', desc: 'Dünyanın en büyük stupalarından biri olan bu görkemli yapı, kubbesinin üzerindeki her yöne bakan Buda gözleriyle ünlüdür. Tibet Budizmi’nin önemli bir merkezi olan stupanın çevresinde dua çarkları döndüren hacılar ibadet eder.' },
    { name: 'Swayambhunath', desc: 'Katmandu’ya tepeden bakan bir tepenin üzerindeki bu antik stupa, çevresinde yaşayan maymunlar nedeniyle “Maymun Tapınağı” olarak da bilinir. Vadinin panoramasını sunan bu kutsal alan, Budist ve Hindu inançlarını bir arada barındırır.' },
    { name: 'Pashupatinath', desc: 'Kutsal Bagmati Nehri kıyısındaki bu görkemli tapınak, Nepal’in en önemli Hindu mabedi ve Tanrı Şiva’ya adanmıştır. Nehir kıyısında yapılan geleneksel açık hava ölü yakma törenleriyle, yaşamın ve ölümün döngüsüne dair güçlü bir manevi deneyim sunar.' },
    { name: 'Thamel', desc: 'Katmandu’nun bu hareketli semti, dar sokakları, dükkânları ve otelleriyle gezginlerin ve dağcıların uğrak noktasıdır. Trekking ekipmanlarından el sanatlarına kadar her şeyin satıldığı, canlı ve renkli atmosferiyle kentin turistik kalbidir.' },
  ],
  seul: [
    { name: 'Gyeongbokgung Sarayı', desc: 'Joseon Hanedanlığı’nın ana sarayı olan bu görkemli kompleks, Seul’ün en büyük ve en etkileyici kraliyet yapısıdır. Geleneksel kostümlü askerlerin canlandırdığı görkemli nöbet değişimi töreni, saray tarihini ziyaretçilere yaşatır.' },
    { name: 'Bukchon Hanok Köyü', desc: 'İki kraliyet sarayı arasında yer alan bu mahalle, yüzlerce geleneksel Kore evi (hanok) ile eski Seul’ün atmosferini yaşatır. Dar sokakları boyunca uzanan bu tarihî evler, kentin modern gökdelenleriyle çarpıcı bir tezat oluşturur.' },
    { name: 'N Seoul Tower', desc: 'Namsan Dağı’nın zirvesindeki bu ikonik kule, Seul’ün panoramasını sunan en gözde noktasıdır. Teleferikle çıkılan tepesi ve çevresindeki korkuluklara asılan sayısız “aşk kilidi” ile romantik bir buluşma mekânıdır.' },
    { name: 'Myeongdong', desc: 'Seul’ün en canlı alışveriş bölgesi olan Myeongdong, özellikle Kore kozmetik markaları ve moda mağazalarıyla ünlüdür. Akşamları kurulan yüzlerce sokak yemeği tezgâhıyla, hem alışveriş hem de gastronomi tutkunları için bir cennettir.' },
    { name: 'Changdeokgung & Gizli Bahçe', desc: 'Doğal araziyle uyumlu mimarisiyle öne çıkan bu Joseon sarayı, UNESCO Dünya Mirası listesindedir. Arkasındaki, yalnızca kraliyet ailesinin kullandığı göletleri ve pavyonlarıyla ünlü “Gizli Bahçe” (Huwon), huzurlu bir doğa şaheseridir.' },
  ],

  // --- Afrika ---
  kahire: [
    { name: 'Giza Piramitleri & Sfenks', desc: 'Yaklaşık 4.500 yıl önce firavunlara mezar olarak inşa edilen bu devasa piramitler, antik dünyanın yedi harikasından günümüze ulaşan tek yapıdır. Bekçileri gizemli Büyük Sfenks ile birlikte, insanlığın en görkemli mühendislik başarılarındandır.' },
    { name: 'Mısır Müzesi', desc: 'Tahrir Meydanı’ndaki bu tarihî müze, dünyanın en zengin antik Mısır eserleri koleksiyonuna ev sahipliği yapar. Genç firavun Tutankamon’un ünlü altın maskesi ve mumyalar salonuyla, firavunlar çağının hazinelerini gözler önüne serer.' },
    { name: 'Han el-Halili', desc: '14. yüzyıla dayanan geçmişiyle bu görkemli kapalı çarşı, dar ve labirentimsi sokaklarıyla Kahire’nin ticaret kalbidir. Baharatlar, altınlar, bakır işleri ve hediyelik eşyalarla dolu bu çarşı, tarihî kahvehaneleriyle otantik bir atmosfer sunar.' },
    { name: 'Salahaddin Kalesi & Muhammed Ali Camii', desc: 'Selahaddin Eyyubi’nin 12. yüzyılda Haçlılara karşı yaptırdığı bu görkemli kale, şehre asırlarca hâkim olmuştur. İçindeki, mermerle kaplı görkemli Muhammed Ali (Alabaster) Camii, Osmanlı üslubundaki kubbeleriyle Kahire siluetinin simgesidir.' },
    { name: 'Kıpti Kahire', desc: 'Kentin en eski bölgelerinden olan bu semt, Mısır’ın köklü Hristiyanlık geçmişini yaşatır. İki kule arasına asılı gibi görünen ünlü “Asılı Kilise” ve Kutsal Aile’nin sığındığına inanılan mekânlarla önemli bir dini merkezdir.' },
    { name: 'Büyük Mısır Müzesi (GEM)', desc: 'Giza Piramitleri’nin yakınına inşa edilen bu dev müze, dünyanın tek bir uygarlığa adanmış en büyük arkeoloji müzesidir. İlk kez Tutankamon’un tüm hazinesini bir arada sergileyen bu modern kompleks, Mısırbilim için yeni bir çağ açar.' },
    { name: 'Sultan Hasan & Rifai Camileri', desc: 'Karşılıklı duran bu iki anıtsal cami, Kahire’nin İslam mimarisinin görkemini sergiler. 14. yüzyıldan kalma devasa Sultan Hasan Camii bir Memlük başyapıtıyken, karşısındaki Rifai Camii Mısır kraliyet ailesinin mezarlarını barındırır.' },
    { name: 'El-Muizz Caddesi', desc: 'Fatımi döneminden kalma bu tarihî cadde, cami, medrese ve han gibi ortaçağ İslam anıtlarının en yoğun bulunduğu yer olarak bir açık hava müzesi gibidir. Restore edilen yapıları ve canlı atmosferiyle Kahire’nin altın çağını yaşatır.' },
    { name: 'Nil Feluka Turu', desc: 'Mısır uygarlığının can damarı olan Nil Nehri’nde, geleneksel yelkenli tekneler olan “feluka” ile yapılan gezi, kenti keşfetmenin en huzurlu yoludur. Özellikle gün batımında, şehrin siluetine karşı yapılan bu sessiz yolculuk büyüleyicidir.' },
  ],
  luksor: [
    { name: 'Karnak Tapınağı', desc: 'İki bin yıla yayılan bir sürede inşa edilen bu devasa tapınak kompleksi, dünyanın en büyük dini yapılarındandır. Özellikle 134 dev sütunun yükseldiği Büyük Sütunlu Salonu (Hipostil), antik Mısır mimarisinin nefes kesici bir başyapıtıdır.' },
    { name: 'Luksor Tapınağı', desc: 'Nil Nehri kıyısındaki bu görkemli tapınak, bir zamanlar bir yol boyunca uzanan sfenkslerle Karnak’a bağlıydı. Anıtsal giriş kapısı, dev heykelleri ve geceleri ışıklandırılan büyüleyici manzarasıyla kentin kalbindeki bir hazinedir.' },
    { name: 'Krallar Vadisi', desc: 'Antik Teb’in karşı kıyısındaki bu vadi, Tutankamon ve II. Ramses gibi Yeni Krallık dönemi firavunlarının kayaya oyulmuş görkemli mezarlarını barındırır. Duvarları canlı hiyeroglif ve resimlerle bezeli bu mezarlar, öbür dünya inancını yansıtır.' },
    { name: 'Hatşepsut Tapınağı', desc: 'Mısır’ın en güçlü kadın firavunu Hatşepsut için bir kayalığın eteğine oyulan bu teraslı anıt tapınak, çağının çok ötesinde modern bir mimariye sahiptir. Sütunlu terasları ve dramatik dağ manzarasıyla olağanüstü bir yapıdır.' },
    { name: 'Sıcak Hava Balonu', desc: 'Gün doğumunda Luksor semalarında yapılan sıcak hava balonu turu, antik Teb şehrini kuşbakışı deneyimlemenin en büyülü yoludur. Nil Nehri, tapınaklar ve Krallar Vadisi’nin altın renkli ışıkla aydınlanan manzarası unutulmazdır.' },
  ],
  asvan: [
    { name: 'Philae Tapınağı', desc: 'Tanrıça İsis’e adanan bu zarif tapınak, Asvan Barajı’nın yükselen suları altında kalmaması için özenle sökülüp yakın bir adaya taşınmıştır. Nil’in ortasındaki adacıkta yükselen bu yapı, romantik konumu ve incelikli kabartmalarıyla büyüler.' },
    { name: 'Abu Simbel', desc: 'Firavun II. Ramses’in bir kayalığa oydurduğu bu iki devasa tapınak, girişindeki 20 metrelik dört dev oturan heykeliyle hayranlık uyandırır. Baraj suları için milimetrik bir hassasiyetle taşınan bu anıtlar, mühendislik açısından da bir mucizedir.' },
    { name: 'Feluka & Elephantine', desc: 'Nil’in en güzel manzaralarına sahip Asvan’da, geleneksel yelkenli “feluka” ile yapılan tur huzur vericidir. Nehrin ortasındaki Elephantine Adası ise antik kalıntıları ve geleneksel Nubya köyleriyle bölgenin köklü tarihini yansıtır.' },
    { name: 'Nubya Köyü', desc: 'Asvan çevresindeki Nubya köyleri, canlı mavi, sarı ve pembeye boyanmış rengârenk evleriyle büyüler. Kendine özgü müziği, misafirperverliği ve gelenekleriyle Nubya halkı, antik Mısır’ın güneyindeki bu benzersiz kültürü yaşatır.' },
  ],
  iskenderiye: [
    { name: 'Bibliotheca Alexandrina', desc: 'Antik dünyanın en büyük bilgi merkezi olan efsanevi İskenderiye Kütüphanesi’nin anısına inşa edilen bu modern yapı, güneşi simgeleyen eğik disk biçimli çatısıyla dikkat çeker. Milyonlarca kitap kapasitesiyle bir bilgi ve kültür merkezidir.' },
    { name: 'Kaitbay Kalesi', desc: 'Bu görkemli kale, antik dünyanın yedi harikasından biri olan İskenderiye Feneri’nin (Faros) yıkıldığı yere, onun taşları kullanılarak 15. yüzyılda inşa edilmiştir. Akdeniz’e uzanan konumuyla kentin liman girişini korur.' },
    { name: 'Kom el-Shoqafa', desc: 'Roma döneminden kalma bu yeraltı mezarları, Mısır, Yunan ve Roma sanatını benzersiz bir şekilde harmanlamasıyla dünyanın en ilginç arkeolojik alanlarındandır. Spiral bir merdivenle inilen bu katmanlı yeraltı dünyası, dönemin çok kültürlü yapısını yansıtır.' },
    { name: 'Pompey Sütunu', desc: 'Antik Serapeum tapınağından günümüze ulaşan bu 27 metrelik dev granit sütun, İskenderiye’nin ayakta kalan en büyük antik anıtıdır. Yanlışlıkla Roma generali Pompey’e atfedilen sütun, aslında İmparator Diocletianus onuruna dikilmiştir.' },
  ],
  marakes: [
    { name: 'Jemaa el-Fnaa', desc: 'Marakeş’in binlerce yıllık kalbi olan bu meydan, gündüzleri yılan oynatıcıları ve müzisyenlerle, geceleri ise dumanı tüten sokak yemeği tezgâhlarıyla canlanan bir gösteri alanıdır. UNESCO’nun “sözlü miras” listesindeki bu meydan, kentin ruhudur.' },
    { name: 'Koutoubia Camii', desc: '12. yüzyıldan kalma bu görkemli cami, 77 metrelik zarif minaresiyle Marakeş’in en yüksek yapısı ve simgesidir. İspanya’daki Giralda’ya da ilham veren bu minare, kentin her yerinden görülebilen bir yön bulma noktasıdır.' },
    { name: 'Bahia Sarayı', desc: '19. yüzyılın sonunda bir vezir için yaptırılan bu görkemli saray, adı “parlaklık” anlamına gelir ve Fas mimarisinin zirvesini temsil eder. İncelikli çini, oyma alçı ve boyalı ahşap tavanlarıyla süslü odaları ve avluları büyüler.' },
    { name: 'Majorelle Bahçesi', desc: 'Ressam Jacques Majorelle’in yarattığı ve sonradan modacı Yves Saint Laurent’in kurtardığı bu egzotik bahçe, kobalt mavisi (Majorelle mavisi) villası ile ünlüdür. Kaktüsleri, palmiyeleri ve huzurlu atmosferiyle kentin ortasında bir sanat vahasıdır.' },
    { name: 'Medina Souk’ları', desc: 'Marakeş’in eski şehrindeki (medina) bu labirentimsi çarşılar (souk), her biri belirli bir zanaata ayrılmış canlı bir ticaret ağıdır. Baharatlar, halılar, deri ürünleri ve fener gibi el işleriyle dolu bu geçitler, duyulara hitap eden bir deneyim sunar.' },
    { name: 'Saadi Türbeleri', desc: '16. yüzyıl Saadi Hanedanlığı’na ait bu görkemli türbeler, yüzyıllarca gizli kaldıktan sonra 1917’de yeniden keşfedilmiştir. İtalyan mermeri ve altın süslemelerle bezeli “On İki Sütun Salonu”, dönemin en görkemli defin sanatını sergiler.' },
    { name: 'Ben Youssef Medresesi', desc: 'Bir zamanlar Kuzey Afrika’nın en büyük Kuran okulu olan bu 14. yüzyıl medresesi, olağanüstü çini işçiliği, oyma sedir ağacı ve alçı süslemeleriyle büyüler. Sakin avlusu ve incelikli detaylarıyla Fas-İslam mimarisinin bir başyapıtıdır.' },
    { name: 'Menara Bahçeleri', desc: '12. yüzyıldan kalma bu tarihî bahçe, geniş zeytinlikleri ortasındaki büyük bir sulama havuzu ve zarif köşküyle ünlüdür. Havuzun sularına yansıyan köşk ve arka plandaki karlı Atlas Dağları manzarası, Marakeş’in en dingin ve ikonik köşesidir.' },
  ],
  fes: [
    { name: 'Fes el-Bali Medina', desc: 'Fes’in 9. yüzyıla dayanan tarihî çekirdeği, 9.000’den fazla dar sokağıyla dünyanın en büyük araçsız kentsel alanıdır. Zamanda donmuş bu labirentimsi medina, atölyeleri ve çarşılarıyla ortaçağ yaşamını canlı tutan bir UNESCO Dünya Mirası’dır.' },
    { name: 'Al-Karaouine', desc: '859 yılında bir kadın olan Fatima el-Fihri tarafından kurulan bu kurum, Guinness tarafından dünyanın hâlâ faal en eski üniversitesi olarak kabul edilir. Görkemli camisi ve kütüphanesiyle asırlardır İslam dünyasının önemli bir ilim merkezidir.' },
    { name: 'Chouara Tabakhanesi', desc: 'Ortaçağdan beri aynı yöntemlerle deri işlenen bu asırlık tabakhane, taş kuyulardaki rengârenk doğal boya çukurlarıyla büyüleyici bir manzara sunar. Yakındaki teraslardan izlenen bu geleneksel zanaat, Fes’in en ikonik görüntüsüdür.' },
    { name: 'Bab Bou Jeloud', desc: 'Fes medinasının ana kapısı olan bu anıtsal geçit, bir yüzü mavi (Fes’in rengi), diğer yüzü yeşil (İslam’ın rengi) çinilerle bezelidir. İncelikli işçiliği ve kemerleriyle eski şehre görkemli bir giriş sunar.' },
    { name: 'Bou Inania Medresesi', desc: '14. yüzyıldan kalma bu görkemli medrese, olağanüstü oyma sedir ağacı, alçı işçiliği ve zellige çinileriyle Merini dönemi mimarisinin bir başyapıtıdır. Fes’te ziyaretçilere açık nadir dini yapılardan biri olarak zarafetiyle büyüler.' },
  ],
  safsavan: [
    { name: 'Mavi Medina Sokakları', desc: 'Şefşaven’in eski şehri, evlerinin, duvarlarının ve merdivenlerinin çeşitli mavi tonlarına boyanmasıyla dünyaca ünlüdür. Bu büyüleyici mavi labirent, kökeni farklı efsanelere dayanan atmosferi ve fotojenik köşeleriyle bir masal diyarını andırır.' },
    { name: 'Ras el-Maa Şelalesi', desc: 'Şefşaven medinasının kenarındaki bu şelale, Rif Dağları’ndan gelen berrak ve serin suyuyla kentin doğal buluşma noktasıdır. Yöre halkının çamaşır yıkadığı ve kafelerin sıralandığı bu su başı, canlı bir yerel yaşam sahnesi sunar.' },
    { name: 'İspanyol Camii Manzarası', desc: 'Şehrin karşısındaki bir tepede yer alan bu terk edilmiş cami, Şefşaven’in en muhteşem manzarasını sunan bakış noktasıdır. Özellikle gün batımında, mavi şehrin Rif Dağları’nın eteğine yayılmış panoraması buradan izlenir.' },
    { name: 'Kasbah', desc: 'Ana meydan Uta el-Hammam’daki bu tarihî kale, 15. yüzyılda kenti korumak için inşa edilmiştir. Kızıl duvarları, huzurlu bahçesi ve küçük müzesiyle, mavi şehrin ortasındaki bu yapı, kentin savunma geçmişine tanıklık eder.' },
  ],
  kazablanka: [
    { name: 'II. Hassan Camii', desc: 'Kısmen Atlas Okyanusu’nun üzerine inşa edilen bu görkemli cami, 210 metrelik minaresiyle dünyanın en yüksek minarelerinden birine sahiptir. Dünyanın en büyük camilerinden biri olan bu yapı, camdan zemini ve açılır çatısıyla bir mimari harikadır.' },
    { name: 'Corniche', desc: 'Kazablanka’nın Atlantik Okyanusu kıyısı boyunca uzanan bu modern sahil şeridi, restoranları, plajları ve yüzme havuzlarıyla kentin en canlı dinlence bölgesidir. Okyanus manzarası eşliğinde yürüyüş yapmak için gözde bir mekândır.' },
    { name: 'Eski Medina', desc: 'Kentin daha modern yüzünün aksine, bu eski surlu şehir dar sokakları ve geleneksel çarşılarıyla otantik bir atmosfer sunar. Yerel yaşamın nabzının attığı bu bölge, el sanatları ve baharat dükkânlarıyla eski Kazablanka’yı yaşatır.' },
    { name: 'Place Mohammed V', desc: 'Kazablanka’nın merkezindeki bu görkemli meydan, Fransız sömürge döneminden kalma etkileyici art deco ve “Mağribi” tarzı kamu binalarıyla çevrilidir. Merkezindeki büyük fıskiyesi ve çevresindeki mimariyle kentin idari kalbidir.' },
  ],
  capetown: [
    { name: 'Table Mountain', desc: 'Dümdüz zirvesiyle Cape Town’a hâkim olan bu ikonik dağ, dünyanın yeni yedi doğa harikasından biridir. Sık sık zirvesini örten “masa örtüsü” denilen bulutlarıyla ünlü dağa döner bir teleferikle çıkılır ve kentin muhteşem panoraması izlenir.' },
    { name: 'Ümit Burnu', desc: 'Cape Yarımadası’nın ucundaki bu dramatik kayalık burun, tarih boyunca denizciler için önemli bir dönüm noktası olmuştur. Sarp uçurumları, zengin bitki örtüsü ve iki okyanusun buluştuğu efsanevi konumuyla nefes kesici bir doğa harikasıdır.' },
    { name: 'V&A Waterfront', desc: 'Hâlâ faal olan tarihî bir limanın etrafına kurulu bu bölge, alışveriş merkezleri, restoranları ve akvaryumuyla kentin en canlı cazibe merkezidir. Table Mountain manzarası eşliğinde tekneler ve deniz aslanlarıyla hareketli bir atmosfer sunar.' },
    { name: 'Robben Island', desc: 'Cape Town açıklarındaki bu ada, apartheid rejimine karşı mücadele eden Nelson Mandela’nın 18 yıl hapsedildiği hapishaneyi barındırır. Bugün eski mahkûmların rehberlik ettiği bu müze-ada, özgürlük mücadelesinin dokunaklı bir simgesidir.' },
    { name: 'Boulders Plajı', desc: 'Devasa granit kayaların koruduğu bu şirin plaj, karadan yaşayan sevimli bir Afrika pengueni kolonisine ev sahipliği yapmasıyla ünlüdür. Ziyaretçiler, ahşap yürüyüş yollarından bu penguenleri çok yakından gözlemleyebilir.' },
    { name: 'Kirstenbosch', desc: 'Table Mountain’ın doğu yamacındaki bu görkemli botanik bahçesi, Güney Afrika’nın eşsiz ve zengin yerli bitki örtüsünü sergiler. Ağaçların tepesinden geçen yürüyüş köprüsü ve yaz konserleriyle dünyanın en güzel bahçelerinden biri kabul edilir.' },
    { name: 'Şaraphane Rotası (Stellenbosch)', desc: 'Cape Town yakınlarındaki bu bölge, dünyaca ünlü Güney Afrika şaraplarına kaynaklık eden tarihî bağları ve zarif kasabalarıyla ünlüdür. Meşe ağaçlı sokakları ve Hollanda sömürge mimarisiyle Stellenbosch, şarap tadımı için ideal bir kaçıştır.' },
    { name: 'Signal Hill & Lion’s Head', desc: 'Cape Town’a bakan bu iki komşu tepe, kentin en gözde bakış noktalarıdır. Signal Hill her gün öğle vakti atılan tarihî topuyla ve gün batımı manzarasıyla, Lion’s Head ise zirveye yapılan popüler tırmanış rotasıyla büyüler.' },
    { name: 'Bo-Kaap', desc: 'Table Mountain’ın eteğindeki bu tarihî mahalle, canlı renklere boyanmış evleri ve arnavut kaldırımlı sokaklarıyla büyüler. Cape Malay topluluğunun merkezi olan bu semt, kentin çok kültürlü mirasını ve özgün mutfağını yaşatır.' },
  ],
  johannesburg: [
    { name: 'Apartheid Müzesi', desc: 'Bu güçlü müze, Güney Afrika’daki ırk ayrımcılığı (apartheid) rejiminin yükselişini ve çöküşünü çarpıcı sergilerle anlatır. Ziyaretçilere girişte rastgele bir ırk kimliği vererek başlayan deneyim, ayrımcılığın acımasızlığını doğrudan hissettirir.' },
    { name: 'Soweto & Mandela Evi', desc: 'Apartheid’e karşı direnişin kalbi olan Soweto, önemli tarihî olaylara sahne olmuştur. Nelson Mandela’nın yaşadığı ev-müze ve iki Nobel ödüllü liderin (Mandela ve Tutu) aynı sokakta oturmasıyla ünlü Vilakazi Caddesi, özgürlük mücadelesinin simgesidir.' },
    { name: 'Constitution Hill', desc: 'Bir zamanlar Mandela ve Gandhi gibi isimlerin de tutulduğu kötü şöhretli bir askeri hapishane olan bu tepe, bugün Güney Afrika Anayasa Mahkemesi’ne ev sahipliği yapar. Baskı geçmişi ile demokratik geleceği birleştiren güçlü bir semboldür.' },
    { name: 'Cradle of Humankind', desc: 'Johannesburg yakınlarındaki bu UNESCO alanı, insanlığın evrimine ışık tutan en eski ve en önemli hominid fosillerinin bulunduğu mağaraları barındırır. “İnsanlığın Beşiği” olarak anılan bu bölge, kökenlerimize dair paha biçilmez kanıtlar sunar.' },
  ],
  zanzibar: [
    { name: 'Stone Town', desc: 'Zanzibar’ın tarihî kalbi olan bu şehir, Afrika, Arap, Hint ve Avrupa kültürlerinin harmanlandığı benzersiz bir mimariye sahiptir. İncelikle oyulmuş ahşap kapıları, dar sokakları ve çarşılarıyla bu UNESCO alanı, adanın çok kültürlü ticaret geçmişini yaşatır.' },
    { name: 'Baharat Turu', desc: 'Zanzibar, bir zamanlar dünya karanfil ticaretine hâkim olması nedeniyle “Baharat Adası” olarak anılır. Adadaki çiftliklere yapılan turlarda, vanilya, tarçın, hindistan cevizi ve karanfil gibi baharatların doğal ortamda yetişimi keşfedilir.' },
    { name: 'Prison Island', desc: 'Stone Town açıklarındaki bu ada, aslında hiç hapishane olarak kullanılmasa da bu adla anılır. Bugün, Seyşeller’den getirilen ve 100 yaşını aşan devasa Aldabra kaplumbağaları kolonisi ve berrak şnorkel sularıyla ünlüdür.' },
    { name: 'Nungwi & Kendwa Plajları', desc: 'Zanzibar’ın kuzey ucundaki bu plajlar, pudra gibi beyaz kumları ve turkuaz sularıyla adanın en güzel sahilleridir. Gelgitin daha az etkili olduğu bu bölgede, geleneksel yelkenli tekneler (dhow) manzaraya eşsiz bir güzellik katar.' },
  ],
  arusha: [
    { name: 'Serengeti Safari', desc: 'Uçsuz bucaksız savanlarıyla ünlü Serengeti Milli Parkı, dünyanın en görkemli doğa olayı olan iki milyondan fazla toynaklının “Büyük Göç”üne sahne olur. Aslanları, çitaları ve zengin vahşi yaşamıyla klasik bir Afrika safari deneyiminin kalbidir.' },
    { name: 'Ngorongoro Krateri', desc: 'Milyonlarca yıl önce çöken devasa bir yanardağın oluşturduğu bu dünyanın en büyük bozulmamış krateri, adeta bir doğal hayvanat bahçesidir. Nesli tükenmekte olan siyah gergedanlar dahil yoğun vahşi yaşamıyla “Afrika’nın Cenneti” olarak anılır.' },
    { name: 'Tarangire', desc: 'Kuru mevsimde yaşam kaynağı Tarangire Nehri’ne akın eden devasa fil sürüleriyle ünlü bu milli park, benzersiz bir manzara sunar. Ayrıca binlerce yıllık dev baobab ağaçlarıyla bezeli peyzajıyla da eşsizdir.' },
    { name: 'Kilimanjaro Manzarası', desc: 'Arusha bölgesi, Afrika’nın en yüksek dağı ve dünyanın en yüksek serbest duran dağı olan Kilimanjaro’ya (5.895 m) açılan bir kapıdır. Ekvatora yakınlığına rağmen karlı zirvesiyle savan üzerinde yükselen bu dağ, dağcılar için efsanevi bir hedeftir.' },
  ],
  nairobi: [
    { name: 'Nairobi Milli Parkı', desc: 'Bir başkentin hemen bitişiğindeki dünyadaki tek milli park olan bu alan, benzersiz bir deneyim sunar. Arka planda kentin gökdelenleri yükselirken, ön planda aslanların, gergedanların ve zürafaların özgürce dolaştığı bir safari yapmak mümkündür.' },
    { name: 'Fil Yetimhanesi (Sheldrick)', desc: 'Bu koruma merkezi, kaçak avcılık veya başka nedenlerle annelerini kaybeden yavru filleri kurtarıp bakar ve doğaya geri kazandırır. Ziyaretçiler, bu sevimli yavruların biberonla beslenişini ve çamur banyosunu izleyerek koruma çalışmalarına tanık olur.' },
    { name: 'Zürafa Merkezi', desc: 'Bu merkez, nesli tehlike altındaki Rothschild zürafalarını korumak amacıyla kurulmuştur. Yükseltilmiş bir platformdan bu zarif hayvanları elle besleme ve onlarla göz göze gelme fırsatı sunarak unutulmaz bir deneyim yaşatır.' },
    { name: 'Karen Blixen Müzesi', desc: 'Ünlü “Benim Afrikam” (Out of Africa) kitabının yazarı Karen Blixen’in 1917-1931 yılları arasında yaşadığı bu kahve çiftliği evi, bugün bir müzedir. Kitaba ve filme ilham veren bu ev, dönemin sömürge yaşamına bir pencere açar.' },
  ],
  tunus: [
    { name: 'Kartaca (Carthage)', desc: 'Bir zamanlar Roma’nın en büyük rakibi olan güçlü Fenike İmparatorluğu’nun başkenti olan bu antik kent, deniz kıyısındaki görkemli kalıntılarıyla ünlüdür. Kartaca generali Hannibal’in memleketi olan bu UNESCO alanı, Roma hamamlarını ve tapınaklarını barındırır.' },
    { name: 'Sidi Bou Said', desc: 'Bir tepenin üzerindeki bu şirin kasaba, tamamen mavi-beyaza boyanmış evleri, arnavut kaldırımlı sokakları ve begonvilleriyle büyüler. Akdeniz manzarasına hâkim bu sanatçı köyü, Tunus’un en romantik ve en fotojenik yeridir.' },
    { name: 'Medina (UNESCO)', desc: 'Tunus’un tarihî çekirdeği olan bu medina, dar sokakları, tarihî camileri ve canlı çarşılarıyla (souk) ortaçağ İslam kentinin en iyi korunmuş örneklerindendir. Zitouna Camii’nin çevresinde gelişen bu labirent, UNESCO Dünya Mirası listesindedir.' },
    { name: 'Bardo Müzesi', desc: 'Görkemli bir eski sarayda yer alan bu müze, dünyanın en zengin ve en kapsamlı Roma mozaik koleksiyonuna ev sahipliği yapar. Tunus’un antik kentlerinden toplanan bu olağanüstü mozaikler, Kuzey Afrika’nın Roma dönemi zenginliğini gözler önüne serer.' },
  ],
  lalibela: [
    { name: 'Bete Giyorgis', desc: 'Adı “Aziz George Kilisesi” anlamına gelen bu yapı, mükemmel bir haç planında, devasa tek bir kaya kütlesinin içine oyularak inşa edilmiştir. Lalibela’nın en ünlü ve en iyi korunmuş kilisesi olan bu şaheser, 12. yüzyıldan kalma bir mühendislik ve inanç anıtıdır.' },
    { name: 'Bete Medhane Alem', desc: 'Adı “Dünyanın Kurtarıcısı” anlamına gelen bu yapı, dünyanın en büyük tek parça kayadan (monolitik) oyulmuş kilisesidir. Dev sütunlarla çevrili bu görkemli yapı, Lalibela’nın “Yeni Kudüs” olma vizyonunun bir simgesidir.' },
    { name: 'Kuzey Kilise Grubu', desc: 'Lalibela’nın bu ilk kilise grubu, yer altında oyulmuş bir dizi tünel, geçit ve avluyla birbirine bağlanan kaya kiliselerinden oluşur. Kutsal metinlerdeki yerleri temsil eden bu labirentimsi kompleks, hâlâ aktif bir hac merkezidir.' },
    { name: 'Asheton Meryem Manastırı', desc: 'Lalibela’nın yukarısındaki yüksek bir dağın zirvesinde yer alan bu manastır, Etiyopya’nın en yüksek kiliselerinden biridir. Zorlu bir yürüyüş veya katır sırtında ulaşılan manastır, antik el yazmaları ve nefes kesici manzarasıyla ödüllendirir.' },
  ],

  // --- Avrupa ---
  paris: [
    { name: 'Eyfel Kulesi', desc: '1889 Dünya Fuarı için mühendis Gustave Eiffel tarafından inşa edilen bu 330 metrelik demir kule, başta eleştirilse de zamanla Paris’in ve romantizmin dünya çapındaki simgesi hâline gelmiştir. Üç katındaki seyir teraslarından şehrin eşsiz panoraması izlenir.' },
    { name: 'Louvre Müzesi', desc: 'Bir kral sarayından dünyanın en büyük ve en çok ziyaret edilen sanat müzesine dönüşen Louvre, Leonardo da Vinci’nin Mona Lisa’sı ve Venüs de Milo gibi başyapıtları barındırır. Avlusundaki cam piramit, tarihî yapıyla modern mimariyi birleştirir.' },
    { name: 'Notre-Dame Katedrali', desc: 'Seine Nehri’ndeki Île de la Cité adasında yükselen bu gotik başyapıt, uçan payandaları, gül pencereleri ve gargoyleleriyle sekiz asırdır Paris’in kalbidir. 2019 yangınında ağır hasar gören katedral, titiz bir restorasyonla yeniden ayağa kaldırılmıştır.' },
    { name: 'Champs-Élysées & Zafer Takı', desc: 'Dünyanın en ünlü bulvarlarından biri olan Champs-Élysées, lüks mağazaları ve kafeleriyle uzanır ve Napolyon’un zaferlerini anmak için diktirdiği görkemli Zafer Takı’nda son bulur. Takın altında Meçhul Asker Anıtı yer alır.' },
    { name: 'Montmartre & Sacré-Cœur', desc: 'Paris’in en yüksek tepesindeki Montmartre, bir zamanlar Picasso ve Van Gogh gibi sanatçılara ev sahipliği yapan bohem ruhunu korur. Tepeyi taçlandıran bembeyaz Sacré-Cœur Bazilikası, şehrin en geniş panoramalarından birini sunar.' },
    { name: 'Versay Sarayı', desc: 'Kral XIV. Louis’nin mutlak monarşinin gücünü sergilemek için yaptırdığı bu ihtişamlı saray, göz kamaştıran Aynalı Salon’u ve devasa simetrik bahçeleriyle Barok mimarinin zirvesidir. Fransız Devrimi’ne kadar kraliyetin merkezi olmuştur.' },
    { name: 'Musée d’Orsay', desc: 'Görkemli bir eski tren garının dönüştürülmesiyle oluşturulan bu müze, Monet, Van Gogh, Renoir ve Degas gibi ustaların empresyonist ve post-empresyonist başyapıtlarının dünyadaki en zengin koleksiyonunu barındırır. Dev saat penceresi ikonik bir simgedir.' },
    { name: 'Sainte-Chapelle', desc: '13. yüzyılda Kral IX. Louis tarafından kutsal emanetleri barındırmak için yaptırılan bu gotik şapel, duvarlarını âdeta bir mücevher kutusu gibi saran 15 devasa vitrayıyla büyüler. Güneş ışığında renklere boğulan iç mekânı nefes kesicidir.' },
    { name: 'Le Marais', desc: 'Paris’in en eski dokusunu koruyan bu şık mahalle, aristokrat konakları (hôtel particulier), sanat galerileri ve butikleriyle canlıdır. Merkezindeki simetrik Place des Vosges, kentin en eski planlı meydanı olarak zarafetiyle öne çıkar.' },
    { name: 'Panthéon & Latin Mahallesi', desc: 'Başlangıçta bir kilise olarak tasarlanan neoklasik Panthéon, bugün Voltaire, Rousseau ve Marie Curie gibi ünlü Fransızların gömülü olduğu ulusal bir anıt-mezardır. Çevresindeki Latin Mahallesi, Sorbonne’un asırlık öğrenci ve entelektüel ruhunu taşır.' },
  ],
  nice: [
    { name: 'Promenade des Anglais', desc: '19. yüzyılda kentte kışlayan İngiliz aristokratların finanse ettiği bu ünlü sahil yolu, Melek Körfezi’nin turkuaz suları boyunca uzanır. Palmiyeleri ve mavi sandalyeleriyle Fransız Rivierası’nın en tanınan ve en zarif gezinti güzergâhıdır.' },
    { name: 'Vieux Nice (Eski Şehir)', desc: 'Nice’in tarihî kalbi olan bu bölge, dar ve dolambaçlı sokakları, oker rengi binaları ve barok kiliseleriyle güçlü bir İtalyan esintisi taşır. Sardunyalı balkonları ve canlı pazarlarıyla kentin en otantik ve renkli semtidir.' },
    { name: 'Colline du Château', desc: 'Bir zamanlar ortaçağ kalesinin bulunduğu bu tepe, bugün yeşil bir park ve yapay bir şelaleye ev sahipliği yapar. Zirvesinden Nice’in kırmızı çatıları ve Melek Körfezi’nin muhteşem panoraması izlenir.' },
    { name: 'Cours Saleya Pazarı', desc: 'Eski Şehir’in ünlü bu meydanı, rengârenk çiçek pazarı, taze yerel ürünleri ve sokak lezzetleriyle canlı bir atmosfer sunar. Pazarların kurulmadığı günlerde antikacılara ev sahipliği yaparak kentin sosyal yaşamının merkezi olur.' },
    { name: 'Matisse Müzesi', desc: 'Hayatının son yıllarını Nice’te geçiren ünlü ressam Henri Matisse’in eserlerine adanan bu müze, 17. yüzyıldan kalma bir Cenova villasında yer alır. Sanatçının resimlerini, heykellerini ve ünlü kâğıt kesme çalışmalarını sergiler.' },
  ],
  lyon: [
    { name: 'Fourvière Bazilikası', desc: 'Lyon’un en yüksek tepesinde yükselen bu görkemli 19. yüzyıl bazilikası, süslü mozaikleri ve gösterişli mimarisiyle “ters çevrilmiş fil” lakabıyla anılır. Terasından şehrin, iki nehrinin ve açık havada Alpler’in panoraması izlenir.' },
    { name: 'Vieux Lyon & Traboules', desc: 'Avrupa’nın en büyük Rönesans mahallelerinden biri olan Vieux Lyon, binaların arasından geçen “traboule” adı verilen gizli üstü kapalı geçitleriyle ünlüdür. Bir zamanlar ipek tüccarlarının kullandığı bu geçitler, kente gizemli bir labirent havası katar.' },
    { name: 'Place Bellecour', desc: 'Avrupa’nın en büyük yaya meydanlarından biri olan bu geniş kızıl toprak alan, ortasındaki Kral XIV. Louis’nin atlı heykeliyle Lyon’un merkezini oluşturur. İki nehir arasındaki konumuyla kentin buluşma ve etkinlik noktasıdır.' },
    { name: 'Roma Tiyatroları', desc: 'Fourvière tepesinde yer alan bu antik tiyatrolar, Lyon’un Roma dönemindeki adı olan Lugdunum’un, üç Galya eyaletinin başkenti olarak taşıdığı önemi gözler önüne serer. MÖ 1. yüzyıla tarihlenen yapılar, bugün hâlâ konserlere ev sahipliği yapar.' },
    { name: 'Parc de la Tête d’Or', desc: 'Fransa’nın en büyük şehir parklarından biri olan bu geniş yeşil alan, büyük bir gölü, ücretsiz hayvanat bahçesi ve botanik bahçeleriyle Lyon halkının nefes aldığı mekândır. Kayık turları ve yürüyüş yollarıyla huzurlu bir kaçış sunar.' },
  ],
  marseille: [
    { name: 'Vieux-Port (Eski Liman)', desc: 'Yaklaşık 2.600 yıl önce Yunanlılar tarafından kurulan Marsilya’nın doğduğu bu tarihî liman, bugün de kentin canlı kalbidir. Yatları, balıkçı tekneleri ve her sabah kurulan taze balık pazarıyla şehrin Akdeniz ruhunu yansıtır.' },
    { name: 'Notre-Dame de la Garde', desc: 'Kentin en yüksek tepesinde yükselen bu neo-Bizans bazilikası, tepesindeki altın kaplama Meryem heykeliyle Marsilya’nın koruyucusu ve simgesidir. Denizcilerin “La Bonne Mère” (İyi Anne) dediği yapı, şehrin 360 derecelik panoramasını sunar.' },
    { name: 'Calanques', desc: 'Marsilya ile Cassis arasında uzanan bu milli park, yüksek beyaz kireçtaşı kayalıkların arasına gizlenmiş turkuaz renkli koylardan (calanque) oluşur. Yürüyüş ve tekne turlarıyla ulaşılan bu fiyort benzeri koylar, Akdeniz’in en el değmemiş güzelliklerindendir.' },
    { name: 'MuCEM', desc: 'Avrupa ve Akdeniz Medeniyetleri Müzesi, dantel gibi işlenmiş beton kabuğuyla çağdaş bir mimari başyapıttır ve bir köprüyle tarihî Saint-Jean Kalesi’ne bağlanır. Akdeniz kültürlerini ele alan sergileri ve deniz manzarasıyla kentin modern simgesidir.' },
    { name: 'Le Panier', desc: 'Marsilya’nın en eski mahallesi olan Le Panier, dar ve dik sokakları, renkli sokak sanatları ve butik atölyeleriyle bohem bir atmosfere sahiptir. Kentin çok kültürlü geçmişini yansıtan bu labirentimsi semt, keşfedilmeyi bekleyen sürprizlerle doludur.' },
  ],
  bordeaux: [
    { name: 'Place de la Bourse & Su Aynası', desc: '18. yüzyıl klasik mimarisinin zarif bir örneği olan bu meydan, önündeki dünyanın en büyük yansıtıcı havuzu “Su Aynası” ile birleşince büyüleyici bir manzara oluşturur. İnce bir su tabakasında yansıyan cepheler, Bordeaux’nun en ikonik görüntüsüdür.' },
    { name: 'Cité du Vin', desc: 'Şaraplı bir kadehteki girdabı andıran fütüristik mimarisiyle bu müze, dünya şarap kültürüne ve tarihine adanmıştır. İnteraktif sergileri ve tepesindeki tadım salonundan izlenen şehir manzarasıyla Bordeaux’nun şarapçılık kimliğini kutlar.' },
    { name: 'Saint-André Katedrali', desc: 'UNESCO korumasındaki bu görkemli gotik katedral, 1137’de Gelecekteki Fransa Kraliçesi Aquitaineli Eleanor’un evlendiği yer olmasıyla tarihe geçmiştir. Yanındaki ayrı duran Pey-Berland Kulesi, şehrin panoramasını sunar.' },
    { name: 'Garonne Rıhtımı', desc: 'Garonne Nehri boyunca uzanan bu geniş rıhtım, restore edilen 18. yüzyıl cepheleri, yürüyüş ve bisiklet yollarıyla kentin en canlı kamusal alanıdır. Nehir kıyısındaki bu güzergâh, Su Aynası ve tarihî binalarla Bordeaux’nun zarafetini sergiler.' },
  ],
  roma: [
    { name: 'Kolezyum', desc: 'MS 80 yılında tamamlanan bu devasa amfitiyatro, 50.000 seyircinin gladyatör dövüşlerini ve halka açık gösterileri izlediği antik dünyanın en büyük arenasıydı. Roma İmparatorluğu’nun mühendislik ve gücünün simgesi olarak bugün de kentin ikonik yapısıdır.' },
    { name: 'Vatikan & Aziz Petrus', desc: 'Dünyanın en küçük bağımsız devleti ve Katolik Kilisesi’nin merkezi olan Vatikan, dünyanın en büyük kilisesi Aziz Petrus Bazilikası’na ev sahipliği yapar. Michelangelo’nun tavan freskleriyle bezeli Sistine Şapeli, Rönesans sanatının zirvesidir.' },
    { name: 'Roma Forumu & Palatino', desc: 'Bir zamanlar antik Roma’nın siyasi, ticari ve dini yaşamının kalbi olan Forum, tapınakları, bazilikaları ve zafer taklarının kalıntılarını barındırır. Yanı başındaki Palatino Tepesi ise Roma’nın kurulduğu ve imparatorların saraylarını yaptırdığı yerdir.' },
    { name: 'Trevi Çeşmesi', desc: '18. yüzyılda tamamlanan bu görkemli Barok çeşme, okyanus tanrısı Neptün’ü betimleyen heykelleriyle Roma’nın en gösterişli eseridir. Efsaneye göre suya sırtı dönük atılan bir bozuk para, ziyaretçinin Roma’ya tekrar dönmesini sağlar.' },
    { name: 'Pantheon', desc: 'MS 2. yüzyılda İmparator Hadrianus döneminde tüm tanrılara adanarak inşa edilen bu tapınak, dünyanın en iyi korunmuş antik Roma yapısıdır. Tepesindeki açık göz (oculus) bulunan devasa betonarme kubbesi, hâlâ türünün en büyüğü olarak mühendislik harikasıdır.' },
    { name: 'İspanyol Merdivenleri', desc: '18. yüzyılda inşa edilen bu 135 basamaklı zarif merdiven, tepesindeki kilise ile altındaki meydanı birleştirir ve dünyanın en geniş merdivenidir. Çevresindeki lüks butikler ve şair Keats’in evi ile Roma’nın en zarif buluşma noktalarındandır.' },
    { name: 'Piazza Navona', desc: 'Antik bir Roma stadyumunun üzerine kurulan bu zarif meydan, uzun oval biçimini o stadyumdan korur ve Barok mimarinin bir açık hava galerisidir. Ortasındaki Bernini’nin görkemli Dört Nehirler Çeşmesi, meydanın gözbebeğidir.' },
    { name: 'Castel Sant’Angelo', desc: 'Başlangıçta İmparator Hadrianus için bir anıt mezar olarak inşa edilen bu silindirik yapı, sonradan papalık kalesine ve hapishaneye dönüştürülmüştür. Vatikan’a gizli bir geçitle bağlı olan yapının terasından Roma’nın panoraması izlenir.' },
    { name: 'Borghese Galerisi & Villa', desc: 'Kardinal Scipione Borghese’nin sanat koleksiyonunu barındıran bu galeri, Bernini’nin nefes kesici mermer heykelleri ve Caravaggio’nun tablolarıyla ünlüdür. Galeriyi çevreleyen geniş Villa Borghese parkı, kentin en sevilen yeşil alanıdır.' },
    { name: 'Trastevere', desc: 'Tiber Nehri’nin karşı yakasındaki bu bohem mahalle, dar arnavut kaldırımlı sokakları, sarmaşıklı binaları ve otantik atmosferiyle Roma’nın en cazibeli semtlerindendir. Geleneksel trattorialar ve canlı gece hayatıyla kentin gerçek ruhunu yaşatır.' },
  ],
  venedik: [
    { name: 'San Marco Meydanı & Bazilikası', desc: 'Napolyon’un “Avrupa’nın en güzel salonu” dediği San Marco Meydanı, Venedik’in kalbidir ve altın mozaikleriyle parıldayan Bizans üslubundaki San Marco Bazilikası ile çevrilidir. Bazilikanın çan kulesinden (Campanile) lagünün ve kentin eşsiz panoraması izlenir.' },
    { name: 'Doj Sarayı', desc: 'Venedik Cumhuriyeti’ni yüzyıllarca yöneten dojların ikametgâhı ve devlet merkezi olan bu görkemli gotik saray, süslü salonları ve devasa tablolarıyla cumhuriyetin gücünü yansıtır. Ünlü “İç Çekişler Köprüsü”, sarayı yanındaki eski hapishaneye bağlar.' },
    { name: 'Rialto Köprüsü', desc: 'Canal Grande üzerindeki en eski ve en ünlü köprü olan Rialto, 16. yüzyıl sonunda taştan inşa edilmiş, üzerinde dükkânlar bulunan zarif tek kemerli bir yapıdır. Kanal manzarası ve çevresindeki hareketli pazarıyla kentin simge noktalarından biridir.' },
    { name: 'Canal Grande & Gondol', desc: 'Venedik’i ters S biçiminde kat eden Canal Grande, kentin ana su yolu ve en görkemli sarayların sıralandığı “caddesidir”. Geleneksel gondol ya da vaporetto ile yapılan gezi, kentin su üstündeki büyüsünü en iyi yaşatan deneyimdir.' },
    { name: 'Murano & Burano', desc: 'Lagündeki Murano adası, yüzyıllardır süren dünyaca ünlü cam üfleme sanatının merkezidir; Burano ise rengârenk boyalı balıkçı evleri ve dantel işçiliğiyle ünlüdür. İkisi de vaporetto ile ulaşılan, fotojenik birer kaçış noktasıdır.' },
    { name: 'Accademia Galerisi', desc: 'Gallerie dell’Accademia, Venedik resim okulunun Bellini, Tiziano, Tintoretto ve Veronese gibi ustalarının başyapıtlarını barındıran dünyaca ünlü bir müzedir. Venedik sanatının altın çağını en kapsamlı biçimde sergiler.' },
    { name: 'Peggy Guggenheim Koleksiyonu', desc: 'Canal Grande kıyısındaki yarım kalmış bir sarayda, koleksiyoncu Peggy Guggenheim’ın yaşadığı evde kurulan bu müze, Picasso’dan Pollock’a 20. yüzyıl modern sanatının önemli eserlerini barındırır. Bahçesi ve kanal terasıyla da keyiflidir.' },
    { name: 'Santa Maria della Salute', desc: 'Canal Grande’nin ağzında yükselen bu görkemli barok kilise, 17. yüzyıldaki veba salgınının sona ermesi şükranıyla inşa edilmiştir. Devasa kubbesi ve beyaz siluetiyle Venedik’in en ikonik manzaralarından birini oluşturur.' },
    { name: 'Rialto Pazarı & Cannaregio', desc: 'Rialto Köprüsü’nün yanındaki asırlık balık ve sebze pazarı, kentin gündelik yaşamının en canlı köşesidir. Yakınındaki Cannaregio semti ise turist kalabalığından uzak, tarihî Yahudi Gettosu ve otantik meyhaneleriyle (bacaro) gerçek Venedik’i sunar.' },
  ],
  floransa: [
    { name: 'Duomo (Santa Maria del Fiore)', desc: 'Floransa’nın simgesi olan bu katedral, Brunelleschi’nin mühendislik dehasıyla iskeletsiz inşa ettiği dev kırmızı kubbesiyle Rönesans’ın doğuşunu müjdeler. Rengârenk mermer cephesi ve Giotto’nun çan kulesiyle kentin siluetine hâkimdir.' },
    { name: 'Uffizi Galerisi', desc: 'Medici ailesinin muazzam sanat koleksiyonunu barındıran bu galeri, dünyanın en önemli Rönesans müzelerindendir. Botticelli’nin “Venüs’ün Doğuşu”, da Vinci ve Michelangelo gibi ustaların başyapıtlarıyla sanat tarihinin en zengin kaynaklarından biridir.' },
    { name: 'Ponte Vecchio', desc: 'Arno Nehri üzerindeki bu ortaçağ köprüsü, üzerinde sıralı kuyumcu ve mücevher dükkânlarıyla dünyanın en özgün köprülerindendir. II. Dünya Savaşı’nda yıkımdan kurtulan tek Floransa köprüsü olarak kentin romantik simgesidir.' },
    { name: 'Accademia (David)', desc: 'Bu galeri, Michelangelo’nun tek bir mermer bloktan yonttuğu 5 metrelik ünlü “David” heykeline ev sahipliği yapmasıyla dünyaca meşhurdur. İnsan anatomisini kusursuz yansıtan bu başyapıt, Rönesans heykel sanatının zirvesi kabul edilir.' },
    { name: 'Piazzale Michelangelo', desc: 'Arno’nun karşı yakasındaki bir tepede yer alan bu meydan, Floransa’nın kırmızı çatılarını, Duomo’sunu ve köprülerini kucaklayan en ünlü panoramik terasıdır. Özellikle gün batımında şehir manzarasının en güzel izlendiği noktadır.' },
    { name: 'Palazzo Vecchio & Piazza della Signoria', desc: 'Çan kuleli bu görkemli ortaçağ sarayı, yüzyıllardır Floransa’nın siyasi kalbi ve belediye binası olmuştur. Önündeki Signoria Meydanı, David heykelinin bir kopyası ve Loggia dei Lanzi’deki heykellerle bir açık hava sanat galerisidir.' },
    { name: 'Pitti Sarayı & Boboli Bahçeleri', desc: 'Arno’nun karşı yakasındaki bu devasa Rönesans sarayı, bir zamanlar Medici hanedanının ikametgâhıydı ve bugün çeşitli müzeler barındırır. Arkasındaki teraslı Boboli Bahçeleri, heykelleri ve grottoları ile İtalyan bahçe sanatının bir örneğidir.' },
    { name: 'Santa Croce', desc: 'Dünyanın en büyük Fransisken kilisesi olan bu gotik yapı, Michelangelo, Galileo ve Machiavelli gibi büyük İtalyanların anıt mezarlarını barındırdığı için “İtalyan Şöhretlerinin Tapınağı” olarak anılır. Giotto’nun freskleriyle de ünlüdür.' },
    { name: 'San Lorenzo & Medici Şapelleri', desc: 'Medici ailesinin resmi kilisesi olan San Lorenzo, aile üyelerinin gömülü olduğu görkemli Medici Şapelleri’ne ev sahipliği yapar. Michelangelo’nun tasarladığı Yeni Vestiyer ve heykelleri, sanatçının mimari dehasını sergiler.' },
  ],
  milano: [
    { name: 'Milano Katedrali (Duomo)', desc: 'İnşası altı asır süren bu görkemli beyaz mermer katedral, binlerce heykeli, sivri kuleleri ve tepesindeki altın Madonna heykeliyle dünyanın en büyük gotik yapılarındandır. Çatı terasından şehrin ve açık havada Alpler’in manzarası izlenir.' },
    { name: 'Galleria Vittorio Emanuele II', desc: 'İtalya’nın hâlâ faal en eski alışveriş pasajı olan bu zarif galeri, cam ve demir kubbesi ile lüks mağazalarıyla “Milano’nun oturma odası” olarak anılır. Yerdeki boğa mozaiğinin üzerinde topuk çevirmenin şans getirdiğine inanılır.' },
    { name: 'Son Akşam Yemeği', desc: 'Leonardo da Vinci’nin Santa Maria delle Grazie Kilisesi’nin yemekhane duvarına yaptığı bu ünlü fresk, İsa’nın havarileriyle son yemeğindeki dramatik anı betimler. Kompozisyonu ve perspektifiyle dünyanın en tanınan sanat eserlerinden biridir.' },
    { name: 'Sforza Kalesi', desc: '15. yüzyılda Milano’yu yöneten Sforza hanedanı tarafından inşa edilen bu görkemli kale, bir zamanlar Avrupa’nın en büyük istihkâmlarındandı. Bugün Michelangelo’nun son eseri Rondanini Pietà’sı dahil çeşitli sanat müzelerine ev sahipliği yapar.' },
    { name: 'La Scala', desc: '1778’de açılan bu opera binası, dünyanın en prestijli sahnelerinden biri olarak kabul edilir ve Verdi ile Puccini gibi bestecilerin eserlerinin ilk kez sahnelendiği yerdir. Görkemli iç mekânı ve müzesiyle opera dünyasının kalbidir.' },
    { name: 'Brera Galerisi & Semti', desc: 'Milano’nun en önemli sanat müzesi olan Pinacoteca di Brera, Raffaello ve Caravaggio gibi ustaların İtalyan resim başyapıtlarını barındırır. Çevresindeki dar sokaklı Brera semti, sanat galerileri ve kafeleriyle kentin bohem kalbidir.' },
    { name: 'Navigli', desc: 'Bir zamanlar Leonardo da Vinci’nin de tasarımına katkıda bulunduğu bu tarihî kanallar bölgesi, bugün Milano’nun en canlı gece hayatı merkezidir. Kanal kıyısındaki barlar, İtalyan “aperitivo” geleneğinin en popüler yaşandığı yerlerdir.' },
    { name: 'Moda Dörtgeni (Montenapoleone)', desc: 'Via Montenapoleone’nin merkezinde olduğu bu bölge, dünyanın en önde gelen moda evlerinin butiklerini barındıran küresel bir lüks alışveriş merkezidir. Milano’nun moda başkenti kimliğini en iyi yansıtan zarif ve şık semttir.' },
  ],
  napoli: [
    { name: 'Spaccanapoli (Tarihî Merkez)', desc: 'Napoli’nin tarihî merkezini dümdüz ikiye bölen bu antik cadde, adını da bu “yarma” hareketinden alır ve Yunan-Roma kent planına dayanır. Kiliseleri, çarşıları ve canlı sokak yaşamıyla UNESCO korumasındaki kentin kaotik ve büyüleyici kalbidir.' },
    { name: 'Pompeii', desc: 'MS 79’da Vezüv Yanardağı’nın patlamasıyla kül ve lav altında kalarak zamanı donduran bu antik Roma kenti, sokakları, villaları ve freskleriyle olağanüstü korunmuştur. Kaçamayan halkın kalıntılarından alınan kalıplar, felaketin trajik anını yaşatır.' },
    { name: 'Napoli Yeraltı', desc: 'Kentin 40 metre altında uzanan bu labirent, antik Yunanlıların taş ocaklarından Roma su kemerlerine ve II. Dünya Savaşı sığınaklarına kadar katmanlı bir tarih barındırır. Napoli’nin görünmeyen yüzünü ortaya koyan büyüleyici bir yeraltı yolculuğudur.' },
    { name: 'Castel dell’Ovo', desc: 'Napoli’nin en eski kalesi olan bu deniz kalesi, adını (“Yumurta Kalesi”) şair Vergilius’un temeline sakladığı sihirli bir yumurta efsanesinden alır. Küçük bir yarımada üzerindeki konumu ve körfez manzarasıyla kentin simgelerindendir.' },
    { name: 'Kraliyet Sarayı & Plebiscito', desc: 'Napoli Krallığı’nı yöneten Bourbon hanedanının ikametgâhı olan bu görkemli saray, zengin daireleri ve kraliyet koleksiyonlarıyla dikkat çeker. Önündeki geniş Plebiscito Meydanı, sütunlu bazilikasıyla kentin en anıtsal alanıdır.' },
    { name: 'Ulusal Arkeoloji Müzesi', desc: 'Dünyanın en önemli arkeoloji müzelerinden biri olan bu kurum, Pompeii ve Herculaneum’dan çıkarılan olağanüstü mozaikleri, heykelleri ve gündelik eşyaları barındırır. Antik Roma yaşamına dair en zengin koleksiyonlardan birine sahiptir.' },
    { name: 'Cappella Sansevero', desc: 'Bu barok şapel, heykeltıraş Giuseppe Sanmartino’nun mermerden yontarak İsa’nın üzerine gerçek bir örtü serilmiş izlenimi veren “Örtülü İsa” başyapıtıyla ünlüdür. İnanılmaz gerçekçiliğiyle bu heykel, dünyanın en etkileyici sanat eserlerindendir.' },
    { name: 'Certosa di San Martino', desc: 'Vomero tepesinde yer alan bu eski Kartuziyen manastırı, görkemli barok kilisesi, manastır avlusu ve müzesiyle dikkat çeker. Napoli Körfezi ve Vezüv’ün en muhteşem panoramasını sunan konumuyla kentin en güzel bakış noktalarındandır.' },
  ],
  barselona: [
    { name: 'Sagrada Família', desc: 'Mimar Antoni Gaudí’nin 1882’de başlayıp hayatını adadığı bu devasa bazilika, doğadan ilham alan organik formları ve büyüleyici vitraylarıyla eşsizdir. Bir asırdan uzun süredir hâlâ inşa hâlinde olan yapı, UNESCO korumasındaki Barselona’nın simgesidir.' },
    { name: 'Park Güell', desc: 'Gaudí’nin tasarladığı bu masalsı park, rengârenk seramik mozaiklerle kaplı kıvrımlı bankları, ejderha heykeli ve organik yapılarıyla bir açık hava sanat eseridir. Tepeden Barselona’nın ve denizin panoramasını sunan büyülü bir bahçedir.' },
    { name: 'Casa Batlló & La Pedrera', desc: 'Passeig de Gràcia bulvarındaki bu iki Gaudí başyapıtı, düz çizgiden kaçınan dalgalı cepheleri ve fantastik detaylarıyla modernist mimarinin zirvesidir. Kemik benzeri balkonlu Casa Batlló ve taş ocağını andıran La Pedrera, kentin en özgün evleridir.' },
    { name: 'Gotik Mahalle & Katedral', desc: 'Barselona’nın en eski çekirdeği olan bu labirentimsi mahalle, Roma dönemi surları, dar ortaçağ sokakları ve gizli meydanlarıyla büyüler. Merkezindeki görkemli gotik katedral, kaz avlusu ve terası ile bölgenin manevi kalbidir.' },
    { name: 'La Rambla & Boqueria', desc: 'Kentin kalbini boydan boya geçen bu ağaçlıklı bulvar, sokak sanatçıları, çiçekçiler ve kalabalıklarıyla her daim canlıdır. Kenarındaki La Boqueria pazarı ise rengârenk meyve, deniz ürünü ve tapas tezgâhlarıyla bir gastronomi cennetidir.' },
    { name: 'Montjuïc & Sihirli Çeşme', desc: 'Şehre ve limana tepeden bakan bu tepe, ortaçağ kalesi, müzeleri ve 1992 Olimpiyat tesisleriyle geniş bir kültür alanıdır. Eteğindeki Sihirli Çeşme, akşamları müzik ve ışık eşliğindeki görkemli su gösterisiyle büyüler.' },
    { name: 'Picasso Müzesi', desc: 'El Born semtindeki ortaçağ saraylarında yer alan bu müze, Pablo Picasso’nun özellikle gençlik ve erken dönem eserlerinden oluşan en kapsamlı koleksiyonlardan birini barındırır. Sanatçının Barselona ile derin bağını yansıtır.' },
    { name: 'Park de la Ciutadella & Arc de Triomf', desc: 'Kentin merkezindeki bu geniş park, gölü, görkemli çeşmesi (yapımına genç Gaudí’nin de katkısı olan) ve İspanya Parlamentosu binasıyla huzurlu bir kaçıştır. Girişindeki kırmızı tuğlalı Zafer Takı, 1888 Dünya Fuarı’nın kapısıydı.' },
    { name: 'Barceloneta Plajı', desc: 'Bir zamanlar balıkçı mahallesi olan Barceloneta, bugün altın kumlu plajı, sahil promenadı ve deniz ürünü restoranlarıyla kentin en canlı sahilidir. Şehir ile denizi birleştiren bu semt, Akdeniz keyfinin merkezidir.' },
  ],
  madrid: [
    { name: 'Prado Müzesi', desc: 'Dünyanın en önemli sanat müzelerinden biri olan Prado, Velázquez’in “Las Meninas”ı ve Goya’nın “Kara Resimleri” başta olmak üzere İspanyol resminin başyapıtlarını barındırır. Avrupa resminin 12.–19. yüzyıl arası en zengin koleksiyonlarından birine sahiptir.' },
    { name: 'Kraliyet Sarayı', desc: '3.000’den fazla odasıyla Batı Avrupa’nın en büyük sarayı olan bu görkemli yapı, bir Mağribi kalesinin yerine 18. yüzyılda inşa edilmiştir. İspanya kraliyetinin resmi ikametgâhı olsa da bugün törenler ve ziyaretler için kullanılır.' },
    { name: 'Plaza Mayor', desc: '17. yüzyıldan kalma bu görkemli dikdörtgen meydan, üç katlı kemerli binalarla çevrilidir ve bir zamanlar boğa güreşlerine, törenlere ve engizisyon mahkemelerine sahne olmuştur. Bugün kafeleri ve canlı atmosferiyle Madrid’in tarihî kalbidir.' },
    { name: 'Retiro Parkı', desc: 'Bir zamanlar kraliyet ailesine ait olan bu görkemli park, güzel gölü, anıtsal heykelleri ve zarif Cam Sarayı (Palacio de Cristal) ile Madrid’in yeşil vahasıdır. Kayık turları ve gölgeli yürüyüş yollarıyla kentlilerin gözde dinlenme alanıdır.' },
    { name: 'Reina Sofía (Guernica)', desc: 'İspanya’nın önde gelen modern sanat müzesi olan Reina Sofía, en çok Picasso’nun İç Savaş’ın dehşetini betimleyen dev anti-savaş tablosu “Guernica”ya ev sahipliği yapmasıyla ünlüdür. Dalí ve Miró gibi ustaların eserlerini de barındırır.' },
    { name: 'Gran Vía', desc: '20. yüzyıl başında açılan bu görkemli bulvar, gösterişli binaları, tiyatroları, sinemaları ve mağazalarıyla Madrid’in en canlı caddesidir. “İspanyol Broadway’i” olarak da anılan cadde, kentin hiç durmayan enerjisini yansıtır.' },
    { name: 'Templo de Debod', desc: 'Mısır’ın Asvan Barajı yapımı sırasında sular altında kalmaktan kurtarılan ve İspanya’ya hediye edilen bu 2.200 yıllık antik tapınak, Madrid’in ortasında yer alır. Bir havuzun kıyısındaki konumu, özellikle gün batımında büyüleyici bir manzara sunar.' },
    { name: 'Mercado San Miguel', desc: 'Plaza Mayor yakınındaki bu tarihî cam ve demir yapılı pazar, geleneksel bir gıda çarşısından şık bir gastronomi merkezine dönüşmüştür. İspanya’nın dört bir yanından taze tapas, deniz ürünleri ve şaraplar sunan tezgâhlarıyla bir lezzet cennetidir.' },
  ],
  sevilla: [
    { name: 'Real Alcázar', desc: 'Hâlâ kullanılan Avrupa’nın en eski kraliyet sarayı olan bu görkemli kompleks, Mağribi (Mudéjar) ve Hristiyan mimarisini büyüleyici bir uyumla birleştirir. Süslü avluları ve nefis bahçeleriyle “Game of Thrones” dizisine de mekân olmuştur.' },
    { name: 'Katedral & Giralda', desc: 'Bir caminin yerine inşa edilen bu yapı, dünyanın en büyük gotik katedralidir ve Kristof Kolomb’un mezarını barındırır. Bir zamanlar minare olan Giralda kulesi ise, tepesinden şehrin panoramasını sunan zarif bir Mağribi mirasıdır.' },
    { name: 'Plaza de España', desc: '1929 İbero-Amerikan Fuarı için inşa edilen bu görkemli yarım daire meydan, çinili köprüleri, kanalı ve İspanya’nın illerini betimleyen seramik panolarıyla büyüler. Mudéjar ve Rönesans üslubunu harmanlayan yapı, kentin en gösterişli mekânıdır.' },
    { name: 'Metropol Parasol', desc: 'Halkın “Las Setas” (Mantarlar) dediği bu dev ahşap yapı, dünyanın en büyük ahşap strüktürlerinden biri olarak modern Sevilla’nın simgesidir. Altındaki Roma kalıntıları ve tepesindeki dalgalı gezinti terasıyla tarih ile çağdaşlığı birleştirir.' },
    { name: 'Triana', desc: 'Guadalquivir Nehri’nin karşı yakasındaki bu renkli mahalle, flamenko sanatının ve geleneksel seramik-çini üretiminin beşiği olarak tanınır. Canlı atmosferi, tapas barları ve özgün kimliğiyle Sevilla’nın ruhunu en iyi yansıtan semttir.' },
    { name: 'Altın Kule (Torre del Oro)', desc: 'Guadalquivir Nehri kıyısında 13. yüzyılda Mağribiler tarafından inşa edilen bu on iki köşeli savunma kulesi, bir zamanlar limanı korumak için kullanılıyordu. Adını bir dönem cephesini kaplayan altın rengi parıltıdan aldığı düşünülür.' },
    { name: 'Casa de Pilatos', desc: 'Sevilla’nın en güzel saraylarından biri olan bu 16. yüzyıl konağı, İtalyan Rönesansı ile İspanyol Mudéjar üslubunu zarif bir şekilde birleştirir. Çinili avluları, heykelleri ve bahçeleriyle Endülüs asalet mimarisinin bir başyapıtıdır.' },
    { name: 'Santa Cruz Mahallesi', desc: 'Sevilla’nın eski Yahudi mahallesi olan Santa Cruz, portakal ağaçlarıyla süslü dar ve dolambaçlı sokakları, gizli meydanları ve çiçekli avlularıyla büyüler. Katedralin hemen yanındaki bu romantik semt, kentin en pitoresk bölgesidir.' },
  ],
  granada: [
    { name: 'Elhamra & Generalife', desc: 'Endülüs Emevileri’nin son kalesi Nasri Hanedanı’nın yaptırdığı bu saray-kale kompleksi, İslam sanatının ve mimarisinin dünyadaki en görkemli örneğidir. İnce oyma stuko süslemeleri, avluları ve Generalife’nin su bahçeleriyle bir yeryüzü cenneti tasviridir.' },
    { name: 'Albaicín', desc: 'Granada’nın en eski Mağribi mahallesi olan Albaicín, dar ve dik arnavut kaldırımlı sokakları, beyaz badanalı evleri ve gizli avlularıyla İslami geçmişini korur. Karşı tepedeki Elhamra’nın en güzel manzarasını sunan UNESCO korumasındaki bir semttir.' },
    { name: 'Sacromonte', desc: 'Albaicín’in yamacındaki bu mahalle, geleneksel olarak Roman (Gitano) halkının yaşadığı ve dağa oyulmuş beyaz badanalı mağara evleriyle ünlüdür. Endülüs flamenkosunun coşkulu bir türü olan “zambra” gösterilerinin doğduğu yerdir.' },
    { name: 'Granada Katedrali & Kraliyet Şapeli', desc: 'Bir caminin üzerine inşa edilen bu görkemli Rönesans katedrali, aydınlık iç mekânı ve dairesel ana kapelasıyla dikkat çeker. Bitişiğindeki Kraliyet Şapeli, Granada’yı fetheden Katolik Kral ve Kraliçe Ferdinand ile Isabella’nın mezarlarını barındırır.' },
    { name: 'Mirador San Nicolás', desc: 'Albaicín mahallesindeki bu ünlü teras, Elhamra Sarayı’nın arkasındaki karlı Sierra Nevada dağlarıyla oluşturduğu eşsiz manzarayla dünyaca meşhurdur. Özellikle gün batımında altın rengine bürünen Elhamra manzarası büyüleyicidir.' },
    { name: 'El Bañuelo (Arap Hamamı)', desc: '11. yüzyıldan kalma bu hamam, İspanya’nın en iyi korunmuş Mağribi hamamlarından biridir. Tavanındaki yıldız şeklindeki menfezlerden süzülen ışıkla aydınlanan kemerli mekânları, Endülüs’ün günlük yaşam kültürüne ışık tutar.' },
    { name: 'Alcaicería Çarşısı', desc: 'Bir zamanlar Granada’nın büyük ipek ve baharat pazarı olan bu tarihî çarşı, dar ve labirentimsi sokaklarıyla Mağribi geçmişi yaşatır. Bugün seramik, baharat ve el sanatları satan renkli dükkânlarıyla otantik bir alışveriş deneyimi sunar.' },
  ],
  valensiya: [
    { name: 'Sanat ve Bilim Şehri', desc: 'Valensiyalı mimar Santiago Calatrava’nın tasarladığı bu göz alıcı yapı topluluğu, beyaz iskeletimsi formları ve mavi havuzlarıyla fütüristik bir manzara sunar. Avrupa’nın en büyük akvaryumunu, bir opera binasını ve interaktif bilim müzesini barındırır.' },
    { name: 'La Lonja (İpek Borsası)', desc: '15. yüzyılda inşa edilen bu görkemli gotik yapı, Valensiya’nın Akdeniz ticaretindeki altın çağının simgesidir. Burma sütunlu muhteşem ana salonu ve incelikli taş işçiliğiyle sivil gotik mimarinin bir başyapıtı olarak UNESCO korumasındadır.' },
    { name: 'Katedral (Kutsal Kâse)', desc: 'Farklı mimari üslupları birleştiren bu katedral, İsa’nın Son Akşam Yemeği’nde kullandığına inanılan “Kutsal Kâse”yi (Holy Grail) barındırmasıyla ünlüdür. Tırmanılabilen sekizgen çan kulesi Miguelete, şehrin panoramasını sunar.' },
    { name: 'Central Market', desc: 'Avrupa’nın en büyük taze gıda pazarlarından biri olan bu yapı, art nouveau üslubundaki cam kubbeleri ve seramik süslemeleriyle bir mimari şölendir. Bölgenin bereketli topraklarından gelen taze ürünler, deniz mahsulleri ve baharatlarla doludur.' },
    { name: 'Turia Bahçeleri', desc: 'Bir sel felaketi sonrası yatağı değiştirilen Turia Nehri’nin kuruyan yatağı, şehri boydan boya kesen 9 kilometrelik yemyeşil bir parka dönüştürülmüştür. Spor alanları, çeşmeleri ve yürüyüş yollarıyla Valensiya’nın nefes aldığı eşsiz bir yeşil koridordur.' },
  ],
  berlin: [
    { name: 'Brandenburg Kapısı', desc: '18. yüzyılda inşa edilen bu neoklasik zafer kapısı, bir zamanlar bölünmüş Berlin’in tam ortasında kalarak Soğuk Savaş’ın simgesi olmuştu. Bugün ise Almanya’nın yeniden birleşmesinin ve barışın en güçlü sembolü olarak kentin kalbinde yükselir.' },
    { name: 'Reichstag', desc: '1894’te açılan bu tarihî parlamento binası, Almanya’nın çalkantılı tarihine tanıklık etmiş ve birleşme sonrası restore edilmiştir. Mimar Norman Foster’ın eklediği cam kubbe, hem şehir manzarası sunar hem de demokratik şeffaflığı simgeler.' },
    { name: 'East Side Gallery', desc: 'Berlin Duvarı’nın ayakta kalan en uzun bölümü olan bu 1,3 kilometrelik kesim, duvarın yıkılmasının ardından dünyanın dört bir yanından sanatçılarca resmedilmiştir. Özgürlüğü kutlayan bu resimler, onu dünyanın en uzun açık hava galerisi yapar.' },
    { name: 'Müze Adası', desc: 'Spree Nehri üzerindeki bu adada toplanan beş dünya çapında müze, UNESCO Dünya Mirası listesindedir. Bergama Sunağı ve Babil’in İştar Kapısı gibi antik hazineleri barındıran ada, insanlık tarihinin görkemli bir koleksiyonunu sunar.' },
    { name: 'Checkpoint Charlie & Holokost Anıtı', desc: 'Checkpoint Charlie, Soğuk Savaş’ta Doğu ve Batı Berlin arasındaki en ünlü sınır kapısı olarak gerilimin simgesiydi. Yakınındaki Holokost Anıtı ise 2.711 beton bloktan oluşan dalgalı yapısıyla katledilen Yahudileri anan güçlü bir anma alanıdır.' },
    { name: 'Fernsehturm & Alexanderplatz', desc: 'Doğu Almanya döneminde inşa edilen 368 metrelik Televizyon Kulesi, Almanya’nın en yüksek yapısı olarak Berlin siluetine hâkimdir. Eteğindeki hareketli Alexanderplatz meydanı, dünya saati ve mağazalarıyla kentin canlı bir buluşma noktasıdır.' },
    { name: 'Charlottenburg Sarayı', desc: 'Berlin’in ayakta kalan en büyük sarayı olan bu görkemli barok yapı, 17. yüzyıl sonunda Prusya kraliyet ailesi için inşa edilmiştir. Zengin döşenmiş daireleri ve geniş simetrik bahçeleriyle kraliyet ihtişamını yaşatır.' },
    { name: 'Potsdamer Platz & Sony Center', desc: 'Bir zamanlar duvarla ikiye bölünmüş boş bir alan olan bu meydan, birleşmeden sonra göz alıcı cam ve çelik gökdelenlerle modern Berlin’in simgesine dönüşmüştür. Çadırı andıran çatısıyla Sony Center, bölgenin canlı merkezidir.' },
  ],
  munih: [
    { name: 'Marienplatz & Glockenspiel', desc: 'Münih’in 1158’den beri kalbi olan bu merkezi meydan, görkemli neogotik Yeni Belediye Sarayı’na (Rathaus) ev sahipliği yapar. Sarayın kulesindeki Glockenspiel adlı çan sistemi, her gün 32 figürüyle Bavyera tarihinden sahneler canlandırır.' },
    { name: 'Nymphenburg Sarayı', desc: 'Bavyera hükümdarlarının yazlık ikametgâhı olan bu görkemli barok saray, geniş kanalları ve simetrik bahçeleriyle Versailles’ı andırır. İçindeki ünlü “Güzeller Galerisi” ve zengin salonlarıyla Bavyera kraliyetinin ihtişamını sergiler.' },
    { name: 'English Garden', desc: 'Dünyanın en büyük şehir parklarından biri olan bu geniş yeşil alan, ismini İngiliz tarzı doğal peyzajından alır. Geleneksel bira bahçeleri, Çin Kulesi ve şaşırtıcı biçimde sörf yapılan yapay bir nehir dalgasıyla kentlilerin gözde mekânıdır.' },
    { name: 'Viktualienmarkt', desc: 'Marienplatz yakınındaki bu canlı açık hava pazarı, iki yüzyıldır taze ürünler, peynirler, baharatlar ve çiçekler sunan bir gastronomi merkezidir. Ortasındaki geleneksel bira bahçesi, Bavyera yemek kültürünün canlı bir örneğidir.' },
    { name: 'Neuschwanstein Şatosu', desc: 'Bavyera Kralı II. Ludwig’in 19. yüzyılda Alpler’in eteğinde yaptırdığı bu masalsı şato, Walt Disney’in ünlü Uyuyan Güzel şatosuna ilham vermiştir. Dramatik konumu ve romantik mimarisiyle dünyanın en çok fotoğraflanan yapılarındandır.' },
    { name: 'Deutsches Museum', desc: 'Bilim ve teknoloji alanında dünyanın en büyük müzesi olan bu kurum, uçaklardan denizaltılara, madenlerden uzay araçlarına kadar binlerce interaktif sergiyi barındırır. İnsanlığın teknolojik gelişimini kapsamlı biçimde gözler önüne serer.' },
    { name: 'BMW Welt & Müze', desc: 'Ünlü otomobil markası BMW’nin genel merkezinin yanındaki bu fütüristik yapılar, markanın tarihini ve en yeni modellerini sergileyen bir deneyim merkezidir. Silindir biçimli müzesi ve dinamik mimarisiyle Münih’in mühendislik gururunu yansıtır.' },
    { name: 'Olympiapark', desc: '1972 Yaz Olimpiyatları için inşa edilen bu park, dönemin devrimci sayılan dalgalı çadır çatılı stadyumu ve tesisleriyle ünlüdür. Bugün konserlere ev sahipliği yapan alan, gözlem kulesi ve gölüyle popüler bir rekreasyon merkezidir.' },
  ],
  koln: [
    { name: 'Köln Katedrali', desc: 'İnşası altı yüzyıldan uzun süren bu devasa gotik katedral, 157 metrelik ikiz kuleleriyle Almanya’nın en çok ziyaret edilen simgesidir. İçinde Üç Kral’ın kutsal emanetlerini barındırdığına inanılan yapı, UNESCO Dünya Mirası listesindedir.' },
    { name: 'Eski Şehir & Ren Rıhtımı', desc: 'Katedralin çevresindeki bu tarihî bölge, rengârenk cepheli evleri, meydanları ve geleneksel “Kölsch” birahaneleriyle canlıdır. Ren Nehri kıyısındaki rıhtım, yürüyüş ve nehir manzarasının tadını çıkarmak için idealdir.' },
    { name: 'Hohenzollern Köprüsü', desc: 'Ren Nehri üzerindeki bu görkemli demiryolu köprüsü, katedral manzarasıyla ünlüdür ve korkuluklarını kaplayan yüz binlerce “aşk kilidi” ile romantik bir simge hâline gelmiştir. Çiftler, sevgilerini bu kilitlerle ölümsüzleştirir.' },
    { name: 'Çikolata Müzesi', desc: 'Ren Nehri kıyısındaki bir yarımadada yer alan bu müze, çikolatanın kakao ağacından tabağa uzanan 5.000 yıllık yolculuğunu anlatır. Ziyaretçileri karşılayan sıcak çikolata pınarı ve üretim hattıyla tatlı bir keşif deneyimi sunar.' },
    { name: 'Ludwig Müzesi', desc: 'Katedralin hemen yanındaki bu müze, 20. yüzyıl ve çağdaş sanata odaklanır ve Avrupa’nın en büyük Pop Art koleksiyonlarından birine sahiptir. Picasso, Warhol ve dışavurumcu Alman sanatçıların önemli eserlerini barındırır.' },
  ],
  hamburg: [
    { name: 'Speicherstadt & Miniatur Wunderland', desc: 'Kanallar üzerine kurulu dünyanın en büyük bitişik nizam tuğla depo bölgesi olan Speicherstadt, UNESCO korumasındadır. İçindeki Miniatur Wunderland ise dünyanın en büyük model tren düzeneği olarak minyatür ülkeleri ve şehirleri hayranlıkla sergiler.' },
    { name: 'Elbphilharmonie', desc: 'Eski bir tuğla deponun üzerine dalgalı cam bir yapı olarak inşa edilen bu görkemli konser salonu, olağanüstü akustiğiyle dünyaca ünlüdür. Halka açık “Plaza” terası, Hamburg limanının ve şehrin 360 derecelik panoramasını sunar.' },
    { name: 'Reeperbahn (St. Pauli)', desc: 'Hamburg’un ünlü eğlence bölgesi olan Reeperbahn, “dünyanın en günahkâr mili” olarak anılan canlı gece hayatıyla tanınır. Bir zamanlar Beatles’ın üne kavuştuğu kulüpleriyle müzik tarihinde de özel bir yere sahiptir.' },
    { name: 'Landungsbrücken', desc: 'Elbe Nehri kıyısındaki bu tarihî yüzer iskeleler, Hamburg’un dünyaya açılan büyük limanının kalbidir. Buradan kalkan tekne turları, dev konteyner gemileri ve tersaneler arasında gezerek kentin denizcilik ruhunu deneyimletir.' },
    { name: 'Alster Gölü', desc: 'Şehrin tam ortasında bir baraj sayesinde oluşan bu geniş yapay göl, yelkenliler ve kürek tekneleriyle bezeli manzarasıyla Hamburg’a ferah bir hava katar. Çevresindeki yürüyüş yolları ve zarif villalarıyla kentlilerin gözde dinlenme alanıdır.' },
  ],
  atina: [
    { name: 'Akropolis & Parthenon', desc: 'Atina’nın üzerinde yükselen bu kutsal kaya, Batı uygarlığının ve demokrasinin sembolüdür. Zirvesindeki Parthenon, tanrıça Athena’ya adanan ve antik Yunan mimarisinin kusursuz oranlarını temsil eden görkemli bir mermer tapınaktır.' },
    { name: 'Antik Agora', desc: 'Antik Atina’nın ticari, siyasi ve toplumsal yaşamının merkezi olan bu meydan, Sokrates’in öğretilerini yaydığı ve demokrasinin filizlendiği yerdir. İçindeki olağanüstü korunmuş Hephaistos Tapınağı, dönemin en iyi durumdaki Yunan tapınağıdır.' },
    { name: 'Akropolis Müzesi', desc: 'Akropolis’in eteğindeki bu çağdaş müze, tepeden çıkarılan heykelleri ve kabartmaları doğal ışıkla aydınlanan modern salonlarında sergiler. Cam zemininin altında görülebilen antik kent kalıntıları, geçmiş ile bugünü büyüleyici biçimde birleştirir.' },
    { name: 'Plaka', desc: 'Akropolis’in eteğine yaslanan bu en eski Atina mahallesi, neoklasik evleri, dar sokakları ve bugainvilyalı avlularıyla adeta bir açık hava müzesidir. Tavernaları ve dükkânlarıyla “Tanrıların Mahallesi” olarak bilinen bu semt, kentin romantik kalbidir.' },
    { name: 'Syntagma & Nöbet Değişimi', desc: 'Atina’nın ana meydanı olan Syntagma, Yunan Parlamentosu’na ev sahipliği yapar ve önündeki Meçhul Asker Anıtı’yla dikkat çeker. Geleneksel “evzon” üniformalı askerlerin her saat başı yaptığı törensel nöbet değişimi, ziyaretçilerin ilgi odağıdır.' },
  ],
  selanik: [
    { name: 'Beyaz Kule', desc: '15. yüzyılda Osmanlılar tarafından deniz surlarının bir parçası olarak inşa edilen bu silindirik kule, bir dönem hapishane ve idam yeri olarak kullanıldığı için “Kanlı Kule” diye anılırdı. Bugün kentin simgesi ve şehir tarihini anlatan bir müze olarak Selanik siluetine hâkimdir.' },
    { name: 'Rotonda & Galerius Takı', desc: 'MS 4. yüzyılın başında İmparator Galerius için yaptırılan Rotonda, sırasıyla pagan tapınağı, kilise ve cami olarak kullanılmış, olağanüstü erken Hristiyan mozaikleriyle donatılmıştır. UNESCO Dünya Mirası listesindeki bu anıt, kentin katmanlı din tarihinin canlı bir belgesidir.' },
    { name: 'Ano Poli (Üst Şehir)', desc: 'Selanik’in 1917 büyük yangınından kurtulan tek mahallesi olan Ano Poli, dar arnavut kaldırımlı sokakları ve ahşap Osmanlı-Bizans evleriyle geçmişi bugüne taşır. Bizans surlarının ardından açılan manzara, kenti ve Ege Körfezi’ni kucaklar.' },
    { name: 'Aya Dimitrios Kilisesi', desc: 'Kentin koruyucu azizi Aziz Dimitrios’a adanan bu beş nefli Bizans bazilikası, azizin şehit edildiğine inanılan Roma hamamının üzerine kurulmuştur. Yangınlardan sonra yeniden inşa edilse de eşsiz 7. yüzyıl mozaikleriyle UNESCO korumasındadır.' },
    { name: 'Atatürk Evi', desc: 'Türkiye Cumhuriyeti’nin kurucusu Mustafa Kemal Atatürk’ün 1881’de doğduğu bu pembe boyalı üç katlı ev, Türk Konsolosluğu bahçesinde bir müze olarak korunur. Dönemin eşyalarıyla döşenmiş odalar, Atatürk’ün çocukluk yıllarına bir pencere açar.' },
    { name: 'Galerius Takı (Kamara)', desc: 'İmparator Galerius’un Perslere karşı kazandığı zaferi anmak için MS 298–299’da dikilen bu anıtsal zafer takı, savaş sahnelerini betimleyen kabartmalarıyla dikkat çeker. Halkın “Kamara” dediği yapı, bugün kentin en sevilen buluşma noktalarından biridir.' },
    { name: 'Ladadika', desc: 'Bir zamanlar zeytinyağı tüccarlarının depolarına ev sahipliği yapan bu renkli tarihî liman semti, adını Yunanca “yağ” anlamındaki ladi kelimesinden alır. Restore edilen neoklasik binalar bugün Selanik gece hayatının kalbini oluşturan meyhane ve restoranlarla doludur.' },
    { name: 'Arkeoloji Müzesi', desc: 'Antik Makedonya’nın en zengin buluntularını barındıran bu müze, Kral II. Filip’in mezarından çıkan altın çelenkler ve “Derveni Kraterı” gibi başyapıtlarıyla ünlüdür. Prehistoryadan Roma dönemine uzanan koleksiyonu, bölgenin görkemli geçmişini gözler önüne serer.' },
  ],
  santorini: [
    { name: 'Oia', desc: 'Santorini’nin en zarif kasabası olan Oia, uçurumlara asılı beyaz badanalı evleri, mavi kubbeli kiliseleri ve yel değirmenleriyle Ege’nin ikonik manzarasını sunar. Dünyanın en güzel gün batımlarından birine sahne olmasıyla ünlüdür.' },
    { name: 'Fira', desc: 'Adanın başkenti olan Fira, kaldera uçurumunun kenarına kurulu konumu ve panoramik manzarasıyla büyüler. Eski liman ile şehri birleştiren teleferiği, canlı sokakları ve butikleriyle Santorini’nin hareketli merkezidir.' },
    { name: 'Akrotiri', desc: 'MÖ 16. yüzyılda bir volkanik patlamanın külleri altında kalarak korunan bu Bronz Çağı Minos kenti, “Ege’nin Pompeii’si” olarak anılır. Çok katlı binaları ve canlı freskleriyle Atlantis efsanesine ilham verdiği düşünülen gelişmiş bir uygarlığa işaret eder.' },
    { name: 'Kırmızı & Siyah Plajlar', desc: 'Santorini’nin volkanik doğası, plajlarına eşsiz renkler kazandırmıştır; Kırmızı Plaj, çevresini saran kızıl lav kayalıklarıyla dramatik bir manzara sunar. Perissa ve Kamari’deki siyah kumlu plajlar ise adanın volkanik kimliğini yansıtır.' },
    { name: 'Kaldera Tekne Turu', desc: 'Santorini’nin, dev bir volkanik patlamayla oluşan su dolu krateri (kaldera) çevresinde yapılan tekne turları, hâlâ aktif olan volkan adasını ve sıcak su kaynaklarını keşfetme fırsatı sunar. Bu jeolojik harikayı denizden görmek eşsiz bir deneyimdir.' },
  ],
  amsterdam: [
    { name: 'Kanal Turu & Jordaan', desc: 'Amsterdam’ın 17. yüzyıl Altın Çağı’nda kazılan iç içe geçmiş kanal halkaları, UNESCO Dünya Mirası listesindedir ve kentin karakteristik dokusunu oluşturur. Tekneyle gezilen bu su yolları, dar cepheli tarihî kanal evlerini en iyi şekilde gösterir.' },
    { name: 'Van Gogh Müzesi', desc: 'Dünyanın en büyük Vincent van Gogh koleksiyonuna ev sahipliği yapan bu müze, sanatçının “Ayçiçekleri” ve “Patates Yiyenler” gibi başyapıtlarını kronolojik olarak sergiler. Van Gogh’un sanatsal ve kişisel yolculuğunu kapsamlı biçimde anlatır.' },
    { name: 'Rijksmuseum', desc: 'Hollanda’nın ulusal müzesi olan bu görkemli yapı, Altın Çağ resminin başyapıtlarını, özellikle de Rembrandt’ın devasa “Gece Devriyesi” tablosunu barındırır. Vermeer ve diğer Hollandalı ustaların eserleriyle sanat tarihinin zengin bir kaynağıdır.' },
    { name: 'Anne Frank Evi', desc: 'Nazi işgali sırasında Anne Frank ve ailesinin iki yıldan uzun süre saklandığı bu gizli ek bina, dünyaca ünlü günlüğün yazıldığı yerdir. Döner bir kitaplığın ardındaki bu mekân, Holokost’un dokunaklı bir tanığı olarak ziyaret edilir.' },
    { name: 'Vondelpark', desc: 'Amsterdam’ın en büyük ve en sevilen şehir parkı olan Vondelpark, İngiliz tarzı peyzajı, gölleri ve açık hava tiyatrosuyla kentlilerin buluşma noktasıdır. Bisikletçiler, koşucular ve piknikçilerle her mevsim canlı bir yeşil vahadır.' },
    { name: 'Dam Meydanı & Kraliyet Sarayı', desc: 'Kentin doğduğu ve adını aldığı baraj (dam) üzerine kurulu bu tarihî meydan, Amsterdam’ın sembolik kalbidir. Meydana hâkim olan görkemli Kraliyet Sarayı, Altın Çağ’da belediye binası olarak inşa edilmiş bir başyapıttır.' },
    { name: 'Begijnhof', desc: 'Kentin hareketli merkezinde gizlenmiş bu huzurlu avlu, bir zamanlar dindar kadınların (begijn) yaşadığı tarihî bir sığınaktır. İçinde Amsterdam’ın ayakta kalan en eski ahşap evini barındıran bu dingin mekân, geçmişe açılan bir kapı gibidir.' },
    { name: 'Bloemenmarkt', desc: 'Singel Kanalı üzerindeki dubalara kurulu bu benzersiz pazar, dünyanın tek yüzen çiçek pazarıdır. Hollanda’nın simgesi laleler başta olmak üzere rengârenk çiçekler, soğanlar ve hediyelik eşyalar sunan tezgâhlarıyla göz alıcıdır.' },
    { name: 'Jordaan & Dokuz Sokak', desc: 'Bir zamanlar işçi mahallesi olan Jordaan, bugün butik dükkânları, sanat galerileri ve şirin kafeleriyle Amsterdam’ın en cazip semtidir. Ünlü “Dokuz Sokak” (De Negen Straatjes), kanalları birbirine bağlayan özgün alışveriş rotalarıyla keşfedilmeyi bekler.' },
  ],
  rotterdam: [
    { name: 'Küp Evler (Cube Houses)', desc: 'Mimar Piet Blom’un 1980’lerde tasarladığı bu sarı küp evler, 45 derece eğimle bir direğin üzerine oturtulmuş sıra dışı yapılarıyla “soyut bir orman” izlenimi verir. II. Dünya Savaşı’nda yıkılan kentin cesur modern mimari kimliğinin simgesidir.' },
    { name: 'Markthal', desc: 'At nalı biçimindeki bu görkemli kapalı çarşı, hem bir gıda pazarı hem de bir konut bloğu işlevi görür. İç kubbesini kaplayan devasa ve rengârenk “Bereket Boynuzu” duvar resmi, dünyanın en büyük sanat eserlerinden biri olarak büyüler.' },
    { name: 'Erasmus Köprüsü', desc: 'Zarif eğimli tek pilonu nedeniyle “Kuğu” lakabıyla anılan bu asma köprü, Nieuwe Maas Nehri üzerinden kentin kuzey ve güneyini birleştirir. Modern mühendislik zarafetiyle Rotterdam’ın çağdaş siluetinin en tanınan simgesidir.' },
    { name: 'Euromast', desc: '1960’ta inşa edilen bu 185 metrelik gözlem kulesi, Rotterdam’ın devasa limanının ve şehir siluetinin panoramik manzarasını sunar. Tepesindeki döner asansör ve restoranıyla kenti kuş bakışı görmenin en gözde noktasıdır.' },
  ],
  lizbon: [
    { name: 'Belém Kulesi', desc: 'Tejo Nehri’nin ağzında 16. yüzyılda inşa edilen bu görkemli kule, Portekiz’in Keşifler Çağı’nda denizcilerin uğurlandığı ve karşılandığı bir savunma noktasıydı. Süslü Manuel üslubuyla bezeli yapı, ülkenin denizci geçmişinin UNESCO korumasındaki simgesidir.' },
    { name: 'Jerónimos Manastırı', desc: 'Vasco da Gama’nın Hindistan’a ulaşmasını anmak için baharat ticaretinin gelirleriyle inşa edilen bu manastır, Manuel gotik mimarisinin en görkemli örneğidir. İncelikli taş oymaları ve etkileyici kilisesiyle UNESCO Dünya Mirası listesindedir.' },
    { name: 'Alfama & Fado', desc: 'Lizbon’un depremden kurtulan en eski mahallesi olan Alfama, dar ve dik labirentimsi sokakları, avlularıyla Mağribi geçmişini yaşatır. Portekiz’in hüzünlü ruhunu anlatan geleneksel Fado müziğinin doğduğu ve tavernalarda hâlâ söylendiği yerdir.' },
    { name: '28 Numaralı Tramvay', desc: 'Lizbon’un dik tepelerini ve dar sokaklarını aşan bu tarihî sarı tramvay, kentin en ikonik simgelerinden biridir. Alfama’dan geçen rotasıyla, şehrin başlıca manzaralarını nostaljik bir yolculukla ziyaretçilerine sunar.' },
    { name: 'São Jorge Kalesi', desc: 'Lizbon’un en yüksek tepesinde yükselen bu Mağribi kalesi, kentin binlerce yıllık tarihine tanıklık etmiş stratejik bir istihkâmdır. Surlarından, kırmızı çatıların, Tejo Nehri’nin ve şehrin en muhteşem panoraması izlenir.' },
    { name: 'Praça do Comércio', desc: '1755 büyük depreminden sonra yeniden inşa edilen bu görkemli meydan, üç yanı sarı kemerli binalarla, dördüncü yanı ise Tejo Nehri’yle çevrilidir. Bir zamanlar kraliyet sarayının bulunduğu bu alan, kentin nehre açılan zarif kapısıdır.' },
    { name: 'Miradouro’lar', desc: 'Yedi tepe üzerine kurulu Lizbon, “miradouro” adı verilen çok sayıda panoramik teras noktasıyla ünlüdür. Senhora do Monte gibi bu teraslar, kentin kırmızı çatılarını, kalesini ve nehrini kucaklayan büyüleyici manzaralar sunar.' },
    { name: 'Time Out Market & LX Factory', desc: 'Time Out Market, Portekiz’in en iyi şeflerini ve lezzetlerini tek bir çatı altında toplayan popüler bir gastronomi merkezidir. Eski bir sanayi kompleksinden dönüşen LX Factory ise sanat galerileri, dükkânlar ve kafeleriyle kentin yaratıcı kalbidir.' },
  ],
  porto: [
    { name: 'Ribeira & Douro', desc: 'Douro Nehri kıyısındaki bu renkli ve tarihî mahalle, dar sokakları, üst üste dizilmiş rengârenk evleri ve canlı atmosferiyle Porto’nun kalbidir. UNESCO korumasındaki bu bölge, nehir kenarındaki kafeleri ve teraslarıyla büyüler.' },
    { name: 'Dom Luís I Köprüsü', desc: 'Eiffel’in bir öğrencisi tarafından tasarlanan bu görkemli iki katlı demir köprü, Douro Nehri’nin iki yakasını birleştirir. Üst katından geçen metro ve yayalara, hem nehrin hem de Porto’nun eşsiz panoramasını sunar.' },
    { name: 'Livraria Lello', desc: '1906’da açılan bu neo-gotik kitabevi, göz alıcı kıvrımlı kırmızı merdiveni ve vitray tavanıyla dünyanın en güzel kitapçılarından biri kabul edilir. Bir dönem kentte yaşayan J.K. Rowling’e Harry Potter için ilham verdiği söylenir.' },
    { name: 'Porto Şarap Mahzenleri (Gaia)', desc: 'Nehrin karşı yakasındaki Vila Nova de Gaia, dünyaca ünlü Porto şarabının yıllandırıldığı tarihî mahzenlere ev sahipliği yapar. Ziyaretçiler bu mahzenlerde şarabın üretim sürecini öğrenip çeşitli tadımlar yapabilir.' },
    { name: 'São Bento Garı', desc: 'Porto’nun ana tren garı olan bu yapı, giriş holünü kaplayan 20.000’den fazla mavi-beyaz azulejo çinisiyle bir sanat eseridir. Portekiz tarihinden sahneleri betimleyen bu görkemli çiniler, garı bir müzeye dönüştürür.' },
    { name: 'Clérigos Kulesi', desc: '18. yüzyıldan kalma bu barok çan kulesi, 76 metre yüksekliğiyle bir zamanlar kentin en yüksek yapısıydı ve denizciler için bir işaret noktasıydı. 240 basamağının tepesinden Porto’nun 360 derecelik panoraması izlenir.' },
    { name: 'Bolsa Sarayı', desc: '19. yüzyılda kentin tüccarlar birliği için inşa edilen bu neoklasik borsa binası, göz kamaştıran iç mekânlarıyla dikkat çeker. Özellikle Mağribi üslupla bezeli görkemli “Arap Salonu”, sarayın en etkileyici bölümüdür.' },
    { name: 'Foz & Atlantik Kıyısı', desc: 'Douro Nehri’nin Atlas Okyanusu’na döküldüğü Foz do Douro bölgesi, deniz fenerleri, kayalık plajları ve zarif sahil promenadıyla büyüler. Kentliler için okyanus manzarası eşliğinde yürüyüş yapmanın en gözde noktasıdır.' },
  ],
  londra: [
    { name: 'Big Ben & Parlamento', desc: 'Thames kıyısındaki görkemli neogotik Parlamento Binası (Westminster Sarayı), İngiliz demokrasisinin merkezidir. Köşesindeki, aslında içindeki çana verilen isim olan “Big Ben” saat kulesi, gür çan sesleriyle Londra’nın dünyaca tanınan simgesidir.' },
    { name: 'Londra Kulesi & Tower Bridge', desc: 'Neredeyse bin yıllık tarihiyle kale, saray ve hapishane olarak kullanılan Londra Kulesi, bugün paha biçilmez Kraliyet Mücevherleri’ni barındırır. Yanındaki ikonik Tower Bridge ise gemiler için açılan gotik kuleli mekanizmasıyla büyüler.' },
    { name: 'British Museum', desc: 'İnsanlık tarihine ve kültürüne adanmış bu devasa müze, Mısır hiyerogliflerinin çözülmesini sağlayan Rosetta Taşı ve Parthenon mermerleri gibi paha biçilmez eserleri barındırır. Kubbeli Büyük Avlusu ile mimari açıdan da etkileyicidir.' },
    { name: 'Buckingham Sarayı', desc: 'İngiliz hükümdarının resmi Londra ikametgâhı olan bu görkemli saray, monarşinin merkezidir. Sarayın önünde geleneksel kırmızı üniformalı ve siyah başlıklı muhafızların yaptığı Nöbet Değişimi töreni, ziyaretçilerin başlıca ilgi odağıdır.' },
    { name: 'London Eye', desc: 'Thames Nehri kıyısında yükselen bu 135 metrelik dev gözlem çarkı, Avrupa’nın en yüksek konsol yapılı dönme dolabıdır. Cam kapsüllerinden, açık havada Londra siluetinin 40 kilometreye varan panoramik manzarası izlenir.' },
    { name: 'Westminster Abbey', desc: 'Bin yılı aşkın süredir İngiliz kraliyetinin taç giyme, düğün ve cenaze törenlerine ev sahipliği yapan bu görkemli gotik kilise, ulusal öneme sahiptir. Newton ve Darwin gibi pek çok ünlü İngiliz’in de mezarını barındıran bir panteondur.' },
    { name: 'St Paul’s Katedrali', desc: 'Mimar Christopher Wren’in başyapıtı olan bu katedral, ikonik devasa kubbesiyle üç asırdır Londra siluetine hâkimdir. Fısıltıların duvar boyunca duyulduğu ünlü “Fısıltı Galerisi” ve kraliyet düğünleriyle tanınır.' },
    { name: 'Tate Modern & Millennium Bridge', desc: 'Eski bir enerji santralinin dönüştürülmesiyle oluşturulan bu müze, dünyanın en önemli modern ve çağdaş sanat koleksiyonlarından birini barındırır. Yalnızca yayalara ait zarif Millennium Köprüsü ile St Paul’s Katedrali’ne bağlanır.' },
    { name: 'Natural History Museum', desc: 'Görkemli katedral benzeri mimarisiyle dikkat çeken bu müze, dinozor iskeletleri, dev bir mavi balina modeli ve milyonlarca doğa tarihi örneğiyle her yaştan ziyaretçiyi büyüler. Ana holü başlı başına mimari bir şaheserdir.' },
    { name: 'Covent Garden & Soho', desc: 'Bir zamanlar bir sebze-meyve pazarı olan Covent Garden, bugün sokak sanatçıları, butikleri ve tarihî çarşısıyla canlı bir cazibe merkezidir. Komşusu Soho ise tiyatroları, restoranları ve hareketli gece hayatıyla Londra’nın eğlence kalbidir.' },
  ],
  edinburgh: [
    { name: 'Edinburgh Kalesi', desc: 'Sönmüş bir volkanın kayalık zirvesinde yükselen bu görkemli kale, yüzyıllar boyu İskoçya tarihinin merkezinde yer almıştır. İskoç Kraliyet Mücevherleri’ni ve her gün öğlen atılan topu barındıran kale, kentin siluetine hâkimdir.' },
    { name: 'Royal Mile', desc: 'Edinburgh Kalesi’ni Holyrood Sarayı’na bağlayan bu tarihî cadde, Eski Şehir’in ana omurgasını oluşturur. Ortaçağdan kalma dar ara sokakları (close), dükkânları ve sokak sanatçılarıyla kentin en canlı ve otantik damarıdır.' },
    { name: 'Arthur’s Seat', desc: 'Şehir merkezinin hemen yanında yükselen bu sönmüş volkan, zirvesine yapılan kısa bir yürüyüşle Edinburgh’un ve Forth Körfezi’nin muhteşem panoramasını sunar. Kent içindeki bu vahşi doğa parçası, yürüyüşçülerin gözdesidir.' },
    { name: 'Holyrood Sarayı', desc: 'Royal Mile’ın sonundaki bu saray, İngiliz hükümdarının İskoçya’daki resmi ikametgâhıdır ve trajik Kraliçe Mary Stuart’ın yaşamına tanıklık etmiştir. Tarihî daireleri ve yanındaki manastır kalıntılarıyla İskoç kraliyet tarihini yaşatır.' },
    { name: 'Dean Village', desc: 'Kentin hareketli merkezinden birkaç adım ötede, Leith Nehri kıyısındaki bu huzurlu vadi, bir zamanlar un değirmenlerine ev sahipliği yapıyordu. Şirin tarihî binaları ve yeşillikleriyle adeta bir kırsal cebi andıran romantik bir kaçış noktasıdır.' },
  ],
  zurih: [
    { name: 'Altstadt (Eski Şehir)', desc: 'Limmat Nehri’nin iki yakasına yayılan bu tarihî merkez, ortaçağdan kalma dar arnavut kaldırımlı sokakları, gizli avluları ve zarif kiliseleriyle büyüler. Butikleri ve kafeleriyle Zürih’in geçmişi ile bugününü buluşturan canlı bir bölgedir.' },
    { name: 'Bahnhofstrasse', desc: 'Zürih Gölü’ne uzanan bu zarif cadde, dünyanın en pahalı ve en şık alışveriş caddelerinden biri olarak ünlüdür. Lüks saat ve mücevher mağazalarının sıralandığı bulvar, İsviçre’nin refahını ve zarafetini simgeler.' },
    { name: 'Fraumünster', desc: '9. yüzyılda kurulan bu tarihî kilise, sanatçı Marc Chagall’ın 1970’lerde tasarladığı beş göz alıcı vitray penceresiyle dünyaca ünlüdür. İncil sahnelerini betimleyen bu rengârenk camlar, kiliseyi bir sanat hazinesine dönüştürür.' },
    { name: 'Zürih Gölü', desc: 'Şehrin güneydoğusuna doğru uzanan bu berrak göl, açık havada karlı Alpler’in manzarasını sunan popüler bir dinlenme alanıdır. Kıyısındaki promenadlar ve göl üzerinde yapılan vapur turları, kentlilere huzurlu bir kaçış imkânı verir.' },
    { name: 'Lindenhof', desc: 'Kentin doğduğu yer olan bu ağaçlıklı tarihî tepe, bir zamanlar Roma gümrük istasyonu ve kalesine ev sahipliği yapmıştır. Bugün ise satranç oynayan yerlileri ve Eski Şehir ile nehrin panoramasını izleyen ziyaretçileriyle huzurlu bir terastır.' },
  ],
  luzern: [
    { name: 'Kapellbrücke', desc: '14. yüzyıldan kalma bu üstü kapalı ahşap köprü, Avrupa’nın en eski ahşap köprüsü ve Luzern’in simgesidir. Çatısındaki tarihî tablolar ve yanındaki sekizgen su kulesiyle, çiçeklerle bezeli bu köprü şehrin en fotojenik noktasıdır.' },
    { name: 'Ağlayan Aslan', desc: 'Bir kaya yüzeyine oyulmuş bu dokunaklı anıt, Fransız Devrimi sırasında kralı korurken ölen İsviçreli paralı askerlerin anısına yapılmıştır. Amerikalı yazar Mark Twain’in “dünyanın en hüzünlü taş parçası” dediği bu heykel, derin bir duygu uyandırır.' },
    { name: 'Mt. Pilatus', desc: 'Efsanelere göre ejderhaların yaşadığı bu görkemli dağa, dünyanın en dik dişli demiryolu treniyle çıkılır. Zirvesinden Luzern Gölü’nün ve çevredeki Alp zirvelerinin nefes kesici bir panoraması izlenir.' },
    { name: 'Mt. Rigi', desc: '“Dağların Kraliçesi” olarak anılan Rigi, üç göl ve muhteşem Alp manzaralarıyla çevrili panoramik bir zirvedir. Avrupa’nın ilk dağ dişli treniyle ulaşılan bu dağ, yürüyüş ve dinlenme için popüler bir merkezdir.' },
    { name: 'Göl Vapuru', desc: 'Dört Kanton Gölü (Vierwaldstättersee) üzerinde yapılan tarihî yandan çarklı vapur turları, İsviçre’nin kuruluş efsanesinin geçtiği kıyıları ve Alp manzaralarını keşfetmenin en keyifli yoludur. Göl, dağlar ve şirin kasabalar arasında dingin bir yolculuk sunar.' },
  ],
  interlaken: [
    { name: 'Jungfraujoch', desc: '“Avrupa’nın Çatısı” olarak anılan bu nokta, 3.454 metre yükseklikteki kıtanın en yüksek tren istasyonudur. Kayalara oyulmuş bir demiryoluyla ulaşılan zirvede, devasa Aletsch Buzulu, bir buz sarayı ve karlı Alp manzaraları ziyaretçileri karşılar.' },
    { name: 'Harder Kulm', desc: '“Interlaken’in Tepesi” olarak bilinen bu bakış noktasına dik bir füniküler treniyle çıkılır. Zirvedeki panoramik terasından, Interlaken’i kucaklayan iki turkuaz gölün (Thun ve Brienz) ve Eiger, Mönch, Jungfrau zirvelerinin eşsiz manzarası izlenir.' },
    { name: 'Lauterbrunnen', desc: 'Dik kaya duvarları arasına gizlenmiş bu büyüleyici vadi, 72 şelalesiyle İsviçre’nin en etkileyici doğa harikalarındandır. Özellikle kayalardan dökülen ince Staubbach Şelalesi, Tolkien’e Yüzüklerin Efendisi’ndeki Ayrıkvadi için ilham vermiştir.' },
    { name: 'Grindelwald', desc: 'Kuzey yüzü dağcılık tarihine geçen efsanevi Eiger Dağı’nın eteğindeki bu şirin köy, yeşil çayırları ve nefes kesen manzaralarıyla Alp turizminin merkezidir. Yakınındaki First zirvesi, teleferik ve macera aktiviteleriyle popülerdir.' },
  ],
  bruksel: [
    { name: 'Grand-Place', desc: 'Brüksel’in görkemli ana meydanı olan Grand-Place, altın işlemeli barok lonca evleri, gotik belediye sarayı ve Kral Evi ile çevrilidir. Dünyanın en güzel meydanlarından biri kabul edilen bu UNESCO alanı, iki yılda bir dev çiçek halısıyla bezenir.' },
    { name: 'Manneken Pis', desc: 'Grand-Place yakınındaki bu 61 santimetrelik işeyen çocuk çeşmesi, mizahi ve isyankâr ruhuyla Brüksel’in sevilen simgesidir. Farklı vesilelerle giydirilen yüzlerce kostümü olan minik heykel, kentin en çok ziyaret edilen noktalarındandır.' },
    { name: 'Atomium', desc: '1958 Dünya Fuarı için inşa edilen bu 102 metrelik yapı, bir demir kristalinin 165 milyar kez büyütülmüş halini temsil eder. Birbirine tüplerle bağlı dokuz parlak küreden oluşan yapı, atom çağının iyimserliğini simgeleyen fütüristik bir Brüksel ikonudur.' },
    { name: 'Kraliyet Sarayı & Parkı', desc: 'Belçika hükümdarının resmi çalışma sarayı olan bu görkemli neoklasik yapı, ihtişamlı cephesi ve zengin salonlarıyla dikkat çeker. Karşısındaki simetrik Brüksel Parkı, kentin merkezindeki en zarif yeşil alandır.' },
    { name: 'Çikolata & Waffle Turu', desc: 'Belçika, dünyaca ünlü el yapımı çikolataları (pralin) ve tereyağlı waffle’larıyla bir gastronomi cennetidir. Brüksel’in dört bir yanına yayılmış tarihî çikolatacılar ve waffle tezgâhları, ülkenin bu tatlı mirasını deneyimlemenin en iyi yoludur.' },
  ],
  bruges: [
    { name: 'Markt & Belfort', desc: 'Bruges’ün canlı ana meydanı Markt, rengârenk lonca evleri ve at arabalarıyla ortaçağ atmosferini yaşatır. Meydana hâkim 83 metrelik Belfort çan kulesi, 366 basamağının tepesinden şehrin muhteşem panoramasını sunar.' },
    { name: 'Kanal Turu', desc: '“Kuzeyin Venedik’i” olarak anılan Bruges, şehri saran ve birbirine bağlayan pitoresk kanallarıyla ünlüdür. Tekneyle yapılan bu su yolu turu, ortaçağdan kalma binaları, taş köprüleri ve gizli köşeleri en romantik açıdan gösterir.' },
    { name: 'Begijnhof', desc: '13. yüzyılda kurulan bu huzurlu avlu, bir zamanlar dünyevi yaşamdan el etek çekmiş dindar kadınların (begijn) yaşadığı beyaz badanalı evlerden oluşur. Yüksek ağaçları ve nergis tarlalarıyla UNESCO korumasındaki dingin bir sığınaktır.' },
    { name: 'Basilica of the Holy Blood', desc: 'Bu bazilika, adını İkinci Haçlı Seferi’nden getirildiğine inanılan ve İsa’nın kanını taşıdığı düşünülen kutsal bir emanetten alır. Alt katı sade Roman, üst katı ise süslü gotik üslupta olan bu kilise, önemli bir hac merkezidir.' },
    { name: 'Minnewater (Aşk Gölü)', desc: 'Adı “Aşk Gölü” anlamına gelen bu dingin göl, zarif kuğuları, yeşil parkı ve kemerli köprüsüyle şehrin en romantik köşesidir. Efsaneye göre köprünün üzerinde sevgiliyle geçmek sonsuz aşkı getirir.' },
  ],
  krakow: [
    { name: 'Wawel Kalesi & Katedrali', desc: 'Vistül Nehri kıyısındaki bir tepeye kurulu bu görkemli kompleks, yüzyıllar boyunca Polonya krallarının ikametgâhı ve taç giyme yeri olmuştur. Kalesi, katedrali ve kral mezarlarıyla ulusun ruhani ve tarihî kalbini oluşturur.' },
    { name: 'Rynek Główny & Sukiennice', desc: 'Avrupa’nın en büyük ortaçağ meydanlarından biri olan Rynek Główny, canlı atmosferi ve tarihî binalarıyla Krakov’un kalbidir. Ortasındaki Rönesans üslubundaki Sukiennice (Kumaş Loncası), yüzyıllardır ticaretin sürdüğü kemerli bir çarşıdır.' },
    { name: 'St. Mary Bazilikası', desc: 'Ana meydandaki bu görkemli gotik kilise, dünyanın en büyük gotik ahşap sunağı olan Veit Stoss başyapıtıyla ünlüdür. Her saat başı kulesinden çalınan ve ortada yarıda kesilen trompet ezgisi (hejnał), bir ortaçağ efsanesini yaşatır.' },
    { name: 'Kazimierz', desc: 'Bir zamanlar ayrı bir şehir olan Kazimierz, yüzyıllarca Krakov Yahudilerinin merkezi olmuş tarihî bir mahalledir. Eski sinagogları, mezarlıkları ve bugünkü sanat galerileri, kafeleri ile geçmişin hüznünü çağdaş bir canlılıkla harmanlar.' },
    { name: 'Wieliczka Tuz Madeni', desc: 'Yüzyıllardır işletilen bu devasa tuz madeni, tamamen tuzdan yontulmuş şapelleri, heykelleri ve avizeleriyle bir yeraltı harikasıdır. Özellikle görkemli Aziz Kinga Şapeli, madencilerin sanatsal dehasını gözler önüne serer ve UNESCO korumasındadır.' },
    { name: 'Auschwitz-Birkenau', desc: 'Nazi Almanyası’nın en büyük toplama ve imha kampı olan bu alan, bir milyondan fazla insanın, çoğunlukla Yahudi’nin, katledildiği yerdir. Bugün bir anıt ve müze olarak Holokost’un dehşetini yaşatan ve “bir daha asla” diyen güçlü bir tanıktır.' },
    { name: 'Schindler Fabrikası Müzesi', desc: 'Oskar Schindler’in yüzlerce Yahudi işçisinin hayatını kurtardığı bu eski emaye fabrikası, bugün bir müzedir. Nazi işgali altındaki Krakov’un gündelik yaşamını ve trajedisini etkileyici sergilerle anlatır.' },
    { name: 'Planty & Barbakan', desc: 'Eski şehir surlarının yıkılmasıyla oluşturulan Planty, tarihî merkezi çevreleyen yemyeşil bir park kuşağıdır. Bu kuşağın ucundaki dairesel gotik kale kapısı Barbakan ise kentin ayakta kalan en önemli savunma yapılarındandır.' },
  ],
  varsova: [
    { name: 'Eski Şehir & Kraliyet Kalesi', desc: 'II. Dünya Savaşı’nda tamamen yerle bir edilen Varşova’nın tarihî merkezi, halkın azmiyle eski tablolara bakılarak birebir yeniden inşa edilmiştir. Bu benzersiz “yeniden doğuş”, onu UNESCO Dünya Mirası listesine sokan renkli meydanı ve kalesiyle büyüler.' },
    { name: 'Łazienki Parkı', desc: 'Varşova’nın en güzel parkı olan bu geniş yeşil alan, bir gölün üzerine kurulu zarif neoklasik “Su Üstü Saray”ıyla ünlüdür. Ünlü Polonyalı besteci Chopin’in anıtının bulunduğu park, yaz aylarında ücretsiz açık hava konserlerine ev sahipliği yapar.' },
    { name: 'Wilanów Sarayı', desc: 'Kral III. Jan Sobieski için inşa edilen bu görkemli barok saray, savaştan sağ çıkmayı başaran nadir yapılardan biridir. Zengin iç mekânları ve simetrik bahçeleriyle “Polonya’nın Versay’ı” olarak anılır.' },
    { name: 'Kültür ve Bilim Sarayı', desc: 'Sovyetler Birliği’nin Stalin döneminde “armağan” ettiği bu 237 metrelik yapı, Polonya’nın en yüksek binasıdır. Tartışmalı geçmişine rağmen kentin simgesi olan yapının terası, Varşova’nın panoramasını sunar.' },
    { name: 'POLIN Müzesi', desc: 'Bir zamanlar Varşova Gettosu’nun bulunduğu alanda yer alan bu ödüllü müze, Polonya Yahudilerinin bin yıllık zengin tarihini ve kültürünü anlatır. Etkileyici mimarisi ve interaktif sergileriyle bir halkın hikâyesini onurlandırır.' },
    { name: 'Kraliyet Yolu (Nowy Świat)', desc: 'Kraliyet Kalesi’nden başlayıp sarayları ve parkları birbirine bağlayan bu tarihî güzergâhın en canlı bölümü Nowy Świat caddesidir. Zarif binaları, kafeleri ve butikleriyle Varşova’nın en şık ve hareketli bulvarlarından biridir.' },
    { name: 'Varşova Ayaklanması Müzesi', desc: 'Bu etkileyici müze, Varşovalıların 1944’te Nazi işgaline karşı başlattığı ve trajik biçimde sonuçlanan kahramanca direnişi anlatır. Gerçekçi canlandırmaları ve dokunaklı hikâyeleriyle kentin özgürlük mücadelesinin ruhunu yaşatır.' },
    { name: 'Praga Semti', desc: 'Vistül Nehri’nin karşı yakasındaki Praga, savaşın yıkımından büyük ölçüde kurtulduğu için özgün eski binalarını koruyan bir semttir. Bir zamanlar kaba sayılan mahalle, bugün sanatçı stüdyoları, galerileri ve alternatif mekânlarıyla canlanmıştır.' },
  ],

  // --- Balkanlar & Orta Avrupa ---
  filibe: [
    { name: 'Antik Roma Tiyatrosu', desc: 'MS 1.–2. yüzyıllarda inşa edilen bu görkemli tiyatro, dünyanın en iyi korunmuş antik Roma tiyatrolarından biridir. Yaklaşık 6.000 kişilik kapasitesiyle bugün hâlâ konser ve gösterilere ev sahipliği yaparak antik ihtişamını sürdürür.' },
    { name: 'Eski Şehir (Stariyat Grad)', desc: 'Filibe’nin bir tepe üzerindeki tarihî çekirdeği, arnavut kaldırımlı sokakları ve rengârenk Bulgar Ulusal Uyanış dönemi konaklarıyla büyüler. Bu zarif evler, kentin 19. yüzyıldaki kültürel canlanmasını ve zenginliğini yansıtır.' },
    { name: 'Roma Stadyumu', desc: 'Kentin antik adı Philippopolis döneminden kalan bu stadyum, bir zamanlar 30.000 seyirciyi ağırlayan atletizm yarışlarına sahne oluyordu. Bugün modern caddenin altında kalan mermer tribünlerinin bir kısmı ziyarete açıktır.' },
    { name: 'Kapana Sanatçı Mahallesi', desc: 'Adı “tuzak” anlamına gelen bu labirentimsi eski zanaatkârlar mahallesi, bugün butik kafeler, sanat galerileri ve atölyelerle dolu canlı bir yaratıcı merkeze dönüşmüştür. Sokak sanatı ve festivalleriyle Filibe’nin genç ve modern yüzüdür.' },
    { name: 'Cuma (Dzhumaya) Camii', desc: '14. yüzyılda Osmanlı döneminde inşa edilen bu cami, Balkanlar’ın en eski ve en büyük camilerinden biridir. Kurşun kaplı kubbeleri ve kalem işi süslemeleriyle kent merkezindeki köklü Osmanlı mirasının bir simgesidir.' },
  ],
  sofya: [
    { name: 'Aleksandr Nevski Katedrali', desc: 'Rus-Türk Savaşı’nda ölen askerler anısına inşa edilen bu görkemli neo-Bizans katedrali, altın kaplama kubbeleriyle Sofya’nın simgesidir. Balkanlar’ın en büyük Ortodoks kiliselerinden biri olan yapı, 10.000 kişiyi ağırlayabilir.' },
    { name: 'Aziz Sofya Kilisesi', desc: 'Şehre adını veren bu kızıl tuğlalı bazilika, 6. yüzyılda Bizans İmparatoru Justinianus döneminde inşa edilmiştir. Sofya’nın en eski kiliselerinden biri olan yapının altında, Roma dönemi mezarlarını içeren bir nekropol yer alır.' },
    { name: 'Boyana Kilisesi (UNESCO)', desc: 'Vitoşa Dağı’nın eteğindeki bu küçük ortaçağ kilisesi, 1259 tarihli olağanüstü fresklerini barındırmasıyla dünyaca ünlüdür. Rönesans’a öncülük eden gerçekçi portreleriyle bu resimler, kiliseyi UNESCO Dünya Mirası listesine sokmuştur.' },
    { name: 'Banya Başı Camii', desc: '16. yüzyılda büyük mimar Mimar Sinan’ın ekolünde inşa edilen bu cami, Sofya’da hâlâ ibadete açık olan tek Osmanlı camisidir. Zarif tek kubbesi ve minaresiyle kentin çok kültürlü mirasının önemli bir parçasıdır.' },
    { name: 'Antik Serdica Kalıntıları', desc: 'Sofya’nın antik adı olan Serdica’ya ait Roma dönemi kalıntıları, metro inşaatı sırasında gün yüzüne çıkarılmış ve modern kentin altında sergilenmektedir. İmparator Konstantin’in çok sevdiği bu kentin sokakları ve yapıları görülebilir.' },
    { name: 'Vitosha Bulvarı', desc: 'Sofya’nın ana yaya ve alışveriş caddesi olan Vitoşa, arka planında yükselen görkemli Vitoşa Dağı manzarasıyla ünlüdür. Butikleri, kafeleri ve canlı atmosferiyle kentin en popüler sosyal ve ticari merkezidir.' },
  ],
  nis: [
    { name: 'Niš Kalesi', desc: '18. yüzyılda Osmanlılar tarafından eski Roma ve Bizans temelleri üzerine inşa edilen bu görkemli kale, Balkanlar’ın en iyi korunmuş istihkâmlarından biridir. Bugün İstanbul Kapısı, hamamı ve içindeki parkla kentin canlı bir kültür merkezidir.' },
    { name: 'Kafatası Kulesi (Ćele Kula)', desc: 'Osmanlılar tarafından 1809’daki bir Sırp ayaklanmasını bastırdıktan sonra bir gözdağı olarak inşa edilen bu ürpertici anıt, duvarlarına yerleştirilmiş asi askerlerin kafataslarından oluşur. Sırp direniş tarihinin çarpıcı bir simgesidir.' },
    { name: 'Mediana', desc: 'Niš, Roma İmparatoru Büyük Konstantin’in doğduğu kenttir ve Mediana, onun bu bölgede yaptırdığı görkemli bir imparatorluk villa kompleksidir. Olağanüstü taban mozaikleri ve kalıntılarıyla dönemin lüks Roma yaşamına ışık tutar.' },
    { name: 'Kızıl Haç Kampı (Crveni Krst)', desc: 'II. Dünya Savaşı sırasında Naziler tarafından işletilen ve Avrupa’nın nadir ayakta kalan toplama kamplarından biri olan bu alan, bugün bir müzedir. Buradaki tutsakların kitlesel bir firar girişimiyle tanınan kamp, savaşın acılarını yaşatır.' },
  ],
  belgrad: [
    { name: 'Kalemegdan Kalesi', desc: 'Sava ile Tuna nehirlerinin buluştuğu tepede yükselen Kalemegdan; Kelt, Roma, Bizans ve Osmanlı’dan izler taşıyan, yüzyıllarca stratejik önem taşımış görkemli bir kaledir. Bugün geniş bir park olarak iki nehrin panoramasını ve kentin en güzel gün batımını sunar.' },
    { name: 'Aziz Sava Tapınağı', desc: 'Sırp azizi Aziz Sava adına inşa edilen bu devasa mabet, dünyanın en büyük Ortodoks kiliselerinden biridir. Beyaz mermer cephesi, altın mozaikli iç kubbesi ve kenti taçlandıran silüetiyle Belgrad’ın en görkemli simgesidir.' },
    { name: 'Knez Mihailova Caddesi', desc: 'Belgrad’ın kalbindeki Knez Mihailova; 19. yüzyıl binalarıyla çevrili, kafeler, mağazalar ve sokak sanatçılarıyla dolu canlı bir yaya caddesidir. Kalemegdan’a uzanan bu bulvar, kentin sosyal yaşamının merkezidir.' },
    { name: 'Skadarlija', desc: 'Belgrad’ın bohem semti Skadarlija; arnavut kaldırımlı sokakları, geleneksel “kafana” lokantaları ve canlı müziğiyle kentin nostaljik ruhunu yaşatır. 19. yüzyıl sonundan beri sanatçıların ve şairlerin buluşma yeri olmuştur.' },
    { name: 'Zemun & Gardoš Kulesi', desc: 'Bir zamanlar Avusturya-Macaristan sınır kasabası olan Zemun, Tuna kıyısındaki renkli evleri ve balıkçı lokantalarıyla Belgrad’a özgün bir hava katar. Tepesindeki Gardoš (Millennium) Kulesi, nehrin ve kentin panoramasını sunar.' },
  ],
  budapeste: [
    { name: 'Buda Kalesi', desc: '13. yüzyılda Moğol istilalarına karşı kurulan ve yüzyıllar boyunca Macar krallarının ikametgâhı olan bu görkemli saray kompleksi, Tuna’ya tepeden bakar. Bugün Ulusal Galeri ve Budapeşte Tarih Müzesi’ni barındıran yapı, UNESCO Dünya Mirası listesindedir.' },
    { name: 'Balıkçı Tabyası & Matyas Kilisesi', desc: 'Yedi Macar kabilesini simgeleyen külahlı kuleleriyle masalsı bir görünüme sahip Balıkçı Tabyası, 20. yüzyıl başında panoramik bir teras olarak inşa edilmiştir. Yanındaki rengârenk çinili çatısıyla Matyas Kilisesi, Macar krallarının taç giydiği tarihî bir mekândır.' },
    { name: 'Parlamento Binası', desc: 'Tuna kıyısında yükselen bu neo-gotik başyapıt, 1904’te tamamlandığında dünyanın en büyük parlamento binalarından biriydi ve Macaristan’ın en tanınan simgesidir. 691 odalı yapı, Macar Kraliyet Tacı’nı ve göz kamaştırıcı iç mimarisini barındırır.' },
    { name: 'Zincir Köprü', desc: 'Buda ile Peşte’yi birleştiren ilk kalıcı köprü olan bu zarif asma köprü, 1849’da açıldığında bir mühendislik harikası sayılıyordu ve kentin birleşmesinde simgesel rol oynadı. İki yanındaki taş aslan heykelleriyle Budapeşte’nin en romantik yapılarından biridir.' },
    { name: 'Széchenyi Kaplıcası', desc: '1913’te açılan bu neo-barok termal kompleks, Avrupa’nın en büyük ilaçlı kaplıcalarından biridir ve derin kuyulardan çıkan sıcak mineralli suyla beslenir. Sarı cepheli görkemli binası ve açık havada satranç oynayan yerlileriyle şehrin ikonik bir deneyimidir.' },
    { name: 'Aziz István Bazilikası', desc: 'Macaristan’ın ilk kralı ve azizi Aziz István’a adanan bu neoklasik bazilika, kentin en büyük kilisesidir ve 96 metrelik kubbesi Parlamento ile aynı yüksekliktedir. İçinde kralın mumyalanmış sağ eli “Kutsal Sağ” olarak saygı görür.' },
  ],
  viyana: [
    { name: 'Schönbrunn Sarayı (UNESCO)', desc: '1.441 odalı bu görkemli sarı Barok saray, Habsburg hanedanının yazlık ikametgâhı olmuş ve İmparatoriçe Sisi ile küçük Mozart’ı ağırlamıştır. Versailles’a rakip olarak tasarlanan bahçeleri, Gloriette köşkü ve dünyanın en eski hayvanat bahçesiyle UNESCO korumasındadır.' },
    { name: 'Aziz Stephan Katedrali', desc: 'Rengârenk çini çatısı ve 136 metrelik güney kulesiyle Viyana’nın kalbinde yükselen bu gotik katedral, kentin manevi simgesidir. Yüzyıllara yayılan inşası, Habsburg mezarları ve panoramik kule manzarasıyla Avusturya’nın en önemli dini yapısıdır.' },
    { name: 'Belvedere Sarayı', desc: 'Prens Eugen von Savoyen için inşa edilen bu iki barok saraydan oluşan kompleks, göz alıcı bahçeleriyle çevrilidir. Bugün Gustav Klimt’in dünyaca ünlü “Öpücük” tablosunu barındıran koleksiyonuyla Avusturya sanatının en değerli hazinelerini sergiler.' },
    { name: 'Hofburg Sarayı', desc: 'Altı yüzyıl boyunca Habsburgların kışlık sarayı ve imparatorluğun yönetim merkezi olan bu devasa kompleks, bugün Avusturya cumhurbaşkanının makamıdır. İçindeki Sisi Müzesi, İmparatorluk Daireleri ve göz kamaştıran hazine dairesi görkemli geçmişi yaşatır.' },
    { name: 'Devlet Operası', desc: '1869’da Mozart’ın “Don Giovanni”siyle açılan bu neo-rönesans opera binası, dünyanın en prestijli sahnelerinden biridir. Her yıl düzenlenen görkemli Opera Balosu ve zengin repertuvarıyla Viyana’nın müzik başkenti kimliğinin simgesidir.' },
    { name: 'Prater & Dev Çark', desc: 'Bir zamanlar imparatorluk av alanı olan bu geniş park, 1766’dan beri halka açık olup Viyana’nın en sevilen yeşil alanıdır. 1897’de dikilen 65 metrelik Dev Çark (Riesenrad), “Üçüncü Adam” filmiyle ölümsüzleşen kentin ikonik simgelerindendir.' },
    { name: 'Kunsthistorisches Museum', desc: 'Habsburg hanedanının yüzyıllar boyunca topladığı olağanüstü sanat koleksiyonunu barındıran bu müze, Bruegel, Vermeer, Rafael ve Rubens gibi ustaların başyapıtlarıyla doludur. İhtişamlı iç mimarisi başlı başına bir sanat eseri gibidir.' },
    { name: 'Naschmarkt', desc: '16. yüzyıla uzanan köklü bir geçmişe sahip bu canlı açık pazar, Viyana’nın en büyük ve en renkli gıda çarşısıdır. Taze ürünler, egzotik baharatlar ve dünya mutfaklarından lezzetler sunan tezgâhlarıyla kentin kozmopolit ruhunu yansıtır.' },
    { name: 'Karlskirche', desc: '1713 veba salgınının sona ermesi şükranına adanan bu görkemli barok kilise, iki devasa spiral kabartmalı sütunu ve zümrüt yeşili kubbesiyle Viyana’nın en özgün yapılarından biridir. Kubbe içindeki fresklere çıkan asansör benzersiz bir deneyim sunar.' },
    { name: 'Hundertwasserhaus', desc: 'Sanatçı Friedensreich Hundertwasser’in tasarladığı bu rengârenk belediye konutu, düz çizgileri reddeden eğri cepheleri, çatısındaki ağaçları ve dalgalı zeminleriyle doğayla mimarinin sıra dışı bir birleşimidir. 1985’ten beri Viyana’nın en özgün simgelerinden biridir.' },
  ],
  hallstatt: [
    { name: 'Tuz Madeni & Skywalk', desc: '7.000 yıldır işletilen bu tuz madeni, dünyanın en eski tuz madeni olarak kabul edilir ve bölgeye adını da veren “beyaz altın” burada çıkarılmıştır. Madene inen ziyaretçiler tarih öncesi galerileri gezerken, 360 metre yükseklikteki Skywalk terası göl üzerine nefes kesen bir manzara sunar.' },
    { name: 'Göl & Köy Manzarası (Marktplatz)', desc: 'Alp göllerinin kıyısında dağların eteğine sıkışmış rengârenk ahşap evleriyle Hallstatt, dünyanın en çok fotoğraflanan köylerinden biridir. Kartpostallık Marktplatz meydanı ve yansımalı göl manzarası, kasabayı UNESCO Dünya Mirası kılan eşsiz güzelliğin kalbidir.' },
    { name: 'Kemik Şapeli (Beinhaus)', desc: 'Mezarlık alanının kısıtlı olması nedeniyle yüzyıllar boyunca çıkarılan kemiklerin saklandığı bu küçük şapel, üzerine çiçek ve isim motifleri boyanmış 600’den fazla kafatasıyla ürkütücü ama etkileyici bir gelenektir. Bölgenin ölümle kurduğu özgün ilişkiyi yansıtır.' },
    { name: 'Dachstein Buz Mağaraları', desc: 'Teleferikle çıkılan Dachstein masifinde yer alan bu dev mağaralar, yaz aylarında bile korunan görkemli buz oluşumları ve devasa yeraltı galerileriyle büyüler. Yakınındaki Mamut Mağarası, adını içindeki filgil boyutlardaki geçitlerinden alır.' },
    { name: 'Gosausee Gölü', desc: 'Dachstein buzulunun aynadaki yansımasıyla ünlü bu berrak alp gölü, çevresindeki yürüyüş rotaları ve huzurlu atmosferiyle doğa tutkunlarının gözdesidir. Hallstatt’a yakınlığıyla bölgenin en dingin kaçış noktalarından biridir.' },
  ],
  salzburg: [
    { name: 'Hohensalzburg Kalesi', desc: '1077’de inşa edilmeye başlanan bu devasa ortaçağ kalesi, hiç fethedilmemiş olmasıyla Orta Avrupa’nın en büyük ve en iyi korunan kalelerindendir. Kentin tepesinden Alp manzarasına hâkim yapı, prens-başpiskoposların gücünün görkemli bir simgesidir.' },
    { name: 'Mozart’ın Doğduğu Ev', desc: 'Getreidegasse’deki sarı binada 1756’da dünyaya gelen Wolfgang Amadeus Mozart’ın çocukluk yılları burada geçmiştir. Bugün müze olan evde bestecinin keman ve klavseni gibi kişisel eşyaları sergilenerek dâhinin yaşamına ışık tutulur.' },
    { name: 'Mirabell Sarayı & Bahçeleri', desc: 'Prens-Başpiskopos Wolf Dietrich’in 1606’da sevdiği kadın için yaptırdığı bu zarif barok saray, simetrik düzeni ve heykelli havuzlarıyla ünlü bahçeleriyle çevrilidir. “Sound of Music” filminin “Do-Re-Mi” sahnesiyle dünyaca tanınır.' },
    { name: 'Getreidegasse', desc: 'Salzburg’un en canlı ve tarihî alışveriş caddesi olan bu dar sokak, dükkânların üzerindeki zarif dövme demir tabelalarıyla ünlüdür. Mozart’ın doğduğu evi de barındıran cadde, ortaçağ atmosferini bugüne taşıyan yüksek dar binalarıyla büyüler.' },
    { name: 'Salzburg Katedrali', desc: 'Eski şehrin merkezinde yükselen bu görkemli erken barok katedral, iki kulesi ve devasa kubbesiyle kentin siluetine hâkimdir. Mozart’ın vaftiz edildiği bu yapı, olağanüstü orgları ve ihtişamlı iç mimarisiyle Salzburg’un manevi merkezidir.' },
  ],
  graz: [
    { name: 'Schlossberg & Saat Kulesi', desc: 'Kentin ortasında yükselen ağaçlıklı tepe Schlossberg, bir zamanlar Napolyon’a bile boyun eğdirmeyen güçlü bir kalenin bulunduğu yerdir. Tepenin zirvesindeki 28 metrelik Saat Kulesi (Uhrturm), dev kadranlarıyla Graz’ın en sevilen simgesidir.' },
    { name: 'Eggenberg Sarayı (UNESCO)', desc: 'Prens Eggenberg için 17. yüzyılda inşa edilen bu görkemli barok saray, yılın günlerini, haftalarını ve aylarını simgeleyen mimarisiyle bir “kozmik takvim” olarak tasarlanmıştır. Tavus kuşlarının dolaştığı bahçeleri ve ihtişamlı odalarıyla UNESCO korumasındadır.' },
    { name: 'Kunsthaus', desc: 'Mur Nehri kıyısında yükselen bu biyomorfik çağdaş sanat müzesi, mavi ve organik kabuğuyla halk arasında “dost uzaylı” lakabını almıştır. 2003’te Graz’ın Avrupa Kültür Başkenti oluşu için inşa edilen yapı, tarihî kentle fütüristik bir tezat oluşturur.' },
    { name: 'Murinsel', desc: 'Mur Nehri’nin ortasına yerleştirilen bu deniz kabuğu biçimli yapay ada, aynı yıl Kunsthaus ile birlikte Avrupa Kültür Başkenti projesi kapsamında tasarlandı. İçinde bir kafe, amfitiyatro ve çocuk oyun alanı barındıran zarif bir çelik köprü-adadır.' },
    { name: 'Landeszeughaus', desc: '17. yüzyılda Osmanlı ve diğer saldırılara karşı Stiria bölgesini savunmak için kurulan bu cephanelik, 32.000’den fazla tarihî silah ve zırhla dünyanın en büyük eksiksiz silah deposu-müzesidir. Zamanda donmuş katları, dönemin savaş kültürünü çarpıcı biçimde yansıtır.' },
  ],
  bratislava: [
    { name: 'Bratislava Kalesi', desc: 'Dört köşe kulesiyle ters çevrilmiş bir masaya benzetilen bu beyaz kale, tepesinden Tuna Nehri’ne ve komşu Avusturya’ya kadar uzanan manzaraya hâkimdir. Kökeni Büyük Moravya dönemine uzanan yapı, 1811’de yanıp 20. yüzyılda özgün haliyle yeniden inşa edilmiştir.' },
    { name: 'Aziz Martin Katedrali', desc: 'Bratislava’nın en büyük ve en eski kilisesi olan bu gotik katedralde, üç yüzyıl boyunca on bir Macar kralı ve kraliçesi taç giymiştir. Kulesinin tepesinde taç giyme törenlerini simgeleyen yaldızlı bir kral tacı yükselir.' },
    { name: 'Michael Kapısı', desc: 'Kentin ortaçağ surlarından günümüze kalan tek şehir kapısı olan bu 14. yüzyıl yapısı, sonradan eklenen barok kulesiyle eski şehrin simgesidir. Zirvesindeki gözlem terasından tarihî çatıların panoraması izlenir.' },
    { name: 'Mavi Kilise (Aziz Elizabeth)', desc: 'Macar mimar Ödön Lechner’in 1913’te tasarladığı bu art nouveau başyapıt, göz alıcı gök mavisi cephesi ve çinileriyle adeta bir pasta gibi görünür. Türünün en özgün örneklerinden biri olarak kentin en sevilen fotoğraf noktalarındandır.' },
    { name: 'UFO Köprüsü Seyir Terası', desc: 'Komünizm döneminde inşa edilen Yeni Köprü’nün 85 metre yüksekliğindeki tek pilonu, uçan daireyi andıran şekliyle bir restoran ve gözlem terasına ev sahipliği yapar. Buradan kale, eski şehir ve Tuna’nın kuş bakışı manzarası izlenir.' },
    { name: 'Devín Kalesi', desc: 'Tuna ile Morava nehirlerinin birleştiği kayalık bir uçurumun üzerinde yükselen bu dramatik kale harabesi, bölgenin en eski yerleşimlerinden birine işaret eder. Napolyon ordularınca yıkılan kale, Slovak ulusal tarihinde güçlü bir sembol olmayı sürdürür.' },
  ],
  saraybosna: [
    { name: 'Başçarşı (Baščaršija)', desc: 'Saraybosna’nın Osmanlı döneminden kalma tarihî çarşısı Başçarşı; bakırcıların çekiç seslerinin yankılandığı dar sokakları, hanları ve kahvehaneleriyle kentin kalbidir. Doğu ile Batı’nın buluştuğu bu meydan, Boşnak kahvesi ve el sanatlarıyla canlıdır.' },
    { name: 'Gazi Hüsrev Bey Camii', desc: '1531’de Osmanlı valisi Gazi Hüsrev Bey tarafından yaptırılan bu cami, Bosna’nın en büyük ve en görkemli Osmanlı yapısıdır. Medresesi, bezistanı ve saat kulesiyle birlikte kentin dört yüz yıllık İslam kültür merkezini oluşturur.' },
    { name: 'Latin Köprüsü', desc: 'Miljacka Nehri üzerindeki bu zarif Osmanlı köprüsü, 1914’te Avusturya-Macaristan veliahtı Franz Ferdinand’a düzenlenen ve I. Dünya Savaşı’nı ateşleyen suikaste tanıklık etmesiyle dünya tarihine geçmiştir. Yanındaki müze bu kader anını anlatır.' },
    { name: 'Sebilj Çeşmesi', desc: 'Başçarşı Meydanı’nın ortasında duran ahşap Sebilj Çeşmesi, Osmanlı dönemine ait, kentin en sevilen simgesidir. Etrafını saran güvercinler ve “bu sudan içen Saraybosna’ya döner” inancıyla ünlüdür.' },
    { name: 'Savaş Tüneli Müzesi', desc: '1992–1995 kuşatması sırasında Saraybosnalıların, ablukayı aşıp havaalanının altından açtığı bu yaşam tüneli, kente yiyecek ve silah taşıyan tek can damarıydı. Bugün müze olarak kuşatmanın acısını ve halkın direnişini anlatır.' },
    { name: 'Vijećnica (Belediye/Kütüphane)', desc: '1896’da Avusturya-Macaristan döneminde sözde-Mağribi üslupla inşa edilen görkemli Vijećnica, uzun süre Ulusal Kütüphane olarak hizmet verdi. Kuşatmada yakılıp yok olan yapı, titizlikle yeniden inşa edilerek kentin dirilişinin simgesi oldu.' },
  ],
  mostar: [
    { name: 'Stari Most (Eski Köprü)', desc: 'Mimar Sinan’ın öğrencisi Mimar Hayruddin’in 1566’da inşa ettiği Stari Most, Neretva Nehri üzerinde tek kemerle yükselen zarif bir Osmanlı köprüsüdür. Savaşta yıkılıp aslına uygun yeniden yapılan köprü (UNESCO), gençlerin sulara atladığı asırlık dalış geleneğiyle ünlüdür.' },
    { name: 'Koski Mehmed Paşa Camii', desc: '17. yüzyıldan kalma bu Osmanlı camisi, minaresine çıkıldığında Eski Köprü ve Neretva Vadisi’nin en güzel manzarasını sunmasıyla ünlüdür. Avlusu ve şadırvanıyla Mostar’ın Osmanlı dokusunun zarif bir parçasıdır.' },
    { name: 'Kujundžiluk Çarşısı', desc: 'Eski Köprü’nün iki yakasını birleştiren arnavut kaldırımlı Kujundžiluk; bakır işleri, el yapımı takılar ve hediyelik eşya dükkânlarıyla dolu tarihî bir çarşıdır. Osmanlı döneminden kalma bu sokaklar, kentin en renkli köşesidir.' },
    { name: 'Crooked Bridge (Kriva Ćuprija)', desc: 'Eski Köprü’den birkaç yıl önce, adeta onun “provası” olarak inşa edildiği düşünülen bu küçük eğri köprü, Radobolja deresi üzerinde zarif bir Osmanlı eseridir. Sel sonrası yeniden yapılan köprü, sakin bir köşede saklıdır.' },
    { name: 'Blagaj Tekkesi', desc: 'Mostar yakınında, dev bir kayanın dibinden fışkıran Buna Nehri’nin kaynağında kurulu Blagaj Tekkesi, 16. yüzyıla uzanan bir derviş tekkesidir. Zümrüt yeşili suları ve dramatik kayalığıyla huzur veren, kutsal bir mekândır.' },
  ],
  jajce: [
    { name: 'Pliva Şelalesi', desc: 'Pliva Nehri’nin Vrbas’a kavuştuğu yerde, şehir merkezinin tam ortasında yaklaşık 20 metre yükseklikten dökülen Pliva Şelalesi, Jajce’nin simgesi ve Avrupa’da kent içinde benzeri az görülen bir doğa harikasıdır. Alt taraftaki seyir terasından şelalenin ardında yükselen eski şehir ve surlar birlikte görülür.' },
    { name: 'Jajce Kalesi', desc: 'Kayalık tepenin zirvesinde yükselen ortaçağ kalesi, Bosna krallarının başkentini koruyan surların en üst noktasıdır. Giriş kapısının üzerindeki Hrvatinić hanedan arması hâlâ yerinde durur; burçlardan iki nehrin birleştiği vadi ve kırmızı çatılı eski şehir panoramik biçimde izlenir.' },
    { name: 'Katakomplar', desc: '15. yüzyıl başında Bosna Bân’ı Hrvoje Vukčić Hrvatinić’in kendi hanedanı için kayaya oydurduğu bu yer altı kilisesi ve türbe, hiç tamamlanmadan kalmıştır. Serin, çıplak taş mekânı ve oyulmuş sembolleriyle kentin en sıra dışı ortaçağ yapısıdır.' },
    { name: 'Aziz Luka Çan Kulesi', desc: 'Eski şehirdeki bu yalın taş kule, Bosna’da ayakta kalan en eski çan kulelerinden biridir. Adını, Aziz Luka’ya ait emanetlerin bir dönem burada saklandığına dair inanıştan alır; yanındaki kilise kalıntılarıyla birlikte gezilir.' },
    { name: 'Mithras Tapınağı', desc: 'MS 4. yüzyıla ait bu Roma dönemi Mithras tapınağı (Mithraeum), tanrı Mithras’ın boğa kurban ederken betimlendiği kabartmasıyla Avrupa’da iyi korunmuş az sayıdaki örnekten biridir. Küçük bir koruma yapısı içinde, şehrin Roma katmanını gösterir.' },
    { name: 'Pliva Gölleri ve Su Değirmenleri', desc: 'Şehrin batısındaki Büyük ve Küçük Pliva gölleri arasında, ahşap ve taştan yapılmış yirmi kadar minik su değirmeni (mlinčići) bir arada durur. Yüzyıllardır tahıl öğüten bu değirmen kümesi, Jajce’nin en çok fotoğraflanan kırsal manzarasıdır; göl kıyısı yüzme ve kano için de elverişlidir.' },
    { name: 'AVNOJ Müzesi', desc: '29 Kasım 1943’te ikinci AVNOJ oturumunun yapıldığı salon, sosyalist Yugoslavya’nın temellerinin atıldığı yer olarak müzeye dönüştürülmüştür. Toplantı düzeni, dönem afişleri ve fotoğraflarıyla 20. yüzyıl Balkan tarihinin kilit mekânlarından biridir.' },
    { name: 'Esma Sultan Camii', desc: 'Osmanlı döneminde Esma Sultan adına yaptırılan cami, savaşta yıkıldıktan sonra özgün biçimine uygun olarak yeniden inşa edilmiştir. Zarif minaresi ve avlusuyla eski şehrin Osmanlı katmanını temsil eder.' },
  ],
  uskup: [
    { name: 'Taş Köprü', desc: 'Vardar Nehri üzerinde 15. yüzyılda Sultan II. Murad döneminde inşa edilen Taş Köprü, Üsküp’ün simgesi ve eski çarşı ile modern meydanı birbirine bağlayan tarihî bağdır. Yüzyıllardır kentin kalbinde yer alan bu köprü, Makedonya bayrağında da yer alır.' },
    { name: 'Eski Çarşı (Čaršija)', desc: 'Vardar’ın kuzey yakasındaki Üsküp Eski Çarşısı, Balkanların İstanbul dışındaki en büyük Osmanlı çarşılarından biridir. Camileri, hanları, hamamları ve dar sokaklarındaki zanaatkârlarıyla yüzyıllık ticaret geleneğini yaşatır.' },
    { name: 'Skopje Kalesi (Kale)', desc: 'Üsküp’e tepeden bakan Kale, kökleri antik döneme uzanan, Bizans ve Osmanlı’da güçlendirilmiş tarihî bir savunma yapısıdır. Surlarından Vardar Nehri’nin böldüğü kentin ve dağların panoraması izlenir.' },
    { name: 'Rahibe Teresa Anı Evi', desc: 'Dünyaca ünlü Rahibe Teresa’nın 1910’da Üsküp’te doğduğu yerin yakınında kurulan bu anı evi, onun hayatını ve insani mirasını anlatır. Modern mimarisiyle kentin en çok ziyaret edilen noktalarından biridir.' },
    { name: 'Mustafa Paşa Camii', desc: '1492’de inşa edilen Mustafa Paşa Camii; tek kubbesi, zarif minaresi ve avlusundaki türbeyle Üsküp’ün en iyi korunmuş Osmanlı eserlerinden biridir. Kale eteğindeki konumu ve bahçesiyle huzurlu bir yapıdır.' },
    { name: 'Matka Kanyonu', desc: 'Üsküp’ün hemen dışındaki Matka Kanyonu, Treska Nehri’nin oyduğu sarp bir vadide göl, mağaralar ve kayalara tutunmuş ortaçağ manastırlarını barındırır. Tekne turları ve doğa yürüyüşleriyle kentliler için gözde bir kaçış noktasıdır.' },
  ],
  ohrid: [
    { name: 'Sveti Jovan Kaneo', desc: 'Ohrid Gölü’ne bakan bir kayalığın üzerinde yükselen 13. yüzyıl kilisesi Sveti Jovan Kaneo, Bizans ve Ermeni mimarisini birleştiren tasarımıyla Balkanların en ikonik manzaralarından birini oluşturur. Göl ve gün batımı manzarasıyla büyüleyici bir noktadır.' },
    { name: 'Çar Samuil Kalesi', desc: 'Ohrid’e ve göle tepeden bakan bu görkemli kale, 10.–11. yüzyılda Bulgar Çarı Samuil döneminde kentin başkent olduğu dönemden kalmadır. Surlarında yürüyüş, kentin kırmızı çatılarının ve gölün eşsiz panoramasını sunar.' },
    { name: 'Antik Tiyatro', desc: 'Ohrid’in Helenistik döneminden kalma açık hava tiyatrosu MÖ 2. yüzyıla uzanır ve Roma döneminde gladyatör dövüşlerine de sahne olmuştur. Göl manzaralı konumuyla bugün hâlâ yaz festivallerine ev sahipliği yapar.' },
    { name: 'Sveti Naum Manastırı', desc: 'Ohrid Gölü’nün güney ucunda, Aziz Naum tarafından 900’lerde kurulan bu manastır; freskleri, taş mimarisi ve etrafındaki pınarlarla huzurlu bir hac merkezidir. Göl kıyısındaki tavus kuşları ve berrak su kaynaklarıyla da ünlüdür.' },
    { name: 'Plaošnik', desc: 'Ohrid’in tepesindeki Plaošnik, Slav alfabesinin ve Ortodoks eğitiminin beşiği sayılan, Aziz Kliment’in kurduğu erken ortaçağ manastır ve okulunun bulunduğu alandır. Erken Hristiyan bazilikasının renkli zemin mozaikleriyle önemli bir arkeolojik alandır.' },
  ],
  prizren: [
    { name: 'Sinan Paşa Camii', desc: '1615 yılında inşa edilen bu görkemli cami, yüksek kubbesi ve zarif minaresiyle Prizren’in tarihî merkezine hâkimdir. İçindeki restore edilmiş kalem işi süslemeleri ve nehir kıyısındaki konumuyla kentin en tanınan Osmanlı eseri ve simgesidir.' },
    { name: 'Prizren Kalesi (Kaljaja)', desc: 'Kökeni Bizans dönemine uzanan ve Osmanlılar tarafından güçlendirilen bu tepe kalesi, yüzyıllarca şehri koruyan stratejik bir savunma noktasıydı. Zirvesinden kırmızı çatılar, cami ve kilise kuleleri ile Bistrica Nehri’nin oluşturduğu eşsiz panorama izlenir.' },
    { name: 'Taş Köprü', desc: 'Bistrica Nehri’nin iki yakasını birleştiren bu zarif kemerli Osmanlı köprüsü, Prizren’in en romantik ve en çok fotoğraflanan noktasıdır. 1979 selinde yıkıldıktan sonra özgün taşlarıyla yeniden inşa edilerek kentin simgelerinden biri olmayı sürdürmüştür.' },
    { name: 'Prizren Birliği Evi', desc: '1878’de kurulan ve Arnavut ulusal uyanışının doğduğu Prizren Birliği’ne ev sahipliği yapan bu tarihî yapı, bugün bir müze olarak korunur. Arnavut milliyetçiliğinin başlangıç noktası sayıldığı için bölge tarihinde büyük bir sembolik değer taşır.' },
    { name: 'Our Lady of Ljeviš (UNESCO)', desc: '14. yüzyılda Sırp Kralı Milutin döneminde inşa edilen bu beş kubbeli ortaçağ kilisesi, olağanüstü Bizans freskleriyle bezelidir. Osmanlı döneminde bir süre cami olarak kullanılan yapı, UNESCO Dünya Mirası listesindeki Kosova ortaçağ anıtlarındandır.' },
  ],
  dubrovnik: [
    { name: 'Şehir Surları', desc: 'Dubrovnik’i tümüyle çevreleyen, iki kilometreyi aşan görkemli taş surlar, kenti yüzyıllarca istilalardan koruyan Ragusa Cumhuriyeti’nin gücünün simgesidir. Surlar boyunca yapılan yürüyüş, kırmızı çatıların ve Adriyatik’in eşsiz manzarasını sunar.' },
    { name: 'Stradun', desc: 'Dubrovnik’in cilalı kireçtaşıyla parıldayan ana caddesi Stradun; eski şehri boydan boya kat eden, kafeleri ve tarihî çeşmeleriyle kentin canlı kalbidir. İki ucundaki meydanlar kule ve manastırlarla çevrilidir.' },
    { name: 'Rektör Sarayı', desc: 'Ragusa Cumhuriyeti’nin yöneticisinin (rektör) ikamet ettiği bu gotik-rönesans saray, cumhuriyetin siyasi merkeziydi; rektör görev süresince sarayı terk edemezdi. Bugün kentin tarihini anlatan bir müze olarak zarif avlusuyla dikkat çeker.' },
    { name: 'Lovrijenac Kalesi', desc: 'Denize dik bir kayalığın üzerinde yükselen Lovrijenac, Dubrovnik’i deniz ve kara saldırılarına karşı koruyan görkemli bir kaledir; “Dubrovnik’in Cebelitarık’ı” olarak anılır. Game of Thrones’ta “King’s Landing” sahnelerine ev sahipliği yapmıştır.' },
    { name: 'Srđ Teleferiği', desc: 'Kentin arkasındaki Srđ Tepesi’ne çıkan teleferik, eski şehrin surlarını, kırmızı çatılarını ve Adriyatik’teki adaları kuşbakışı gören nefes kesici bir panorama sunar. Zirvede bir restoran ve Vatan Savaşı müzesi bulunur.' },
    { name: 'Fransisken Manastırı & Eczane', desc: 'Stradun’un girişindeki Fransisken Manastırı, huzurlu romanesk avlusu ve içindeki, 1317’den beri işleyen Avrupa’nın en eski eczanelerinden biriyle ünlüdür. Manastırın kütüphanesi değerli el yazmalarını barındırır.' },
  ],
  zadar: [
    { name: 'Deniz Orgu', desc: 'Mimar Nikola Bašić’in 2005’te tasarladığı, sahildeki mermer basamakların altına gizlenmiş borularla dalgaların gücünü sürekli değişen doğal bir melodiye dönüştüren dünyanın ilk deniz orgudur. Zadar’ın simgesi hâline gelen bu eser, gün batımında müziği dinleyen kalabalıklarla adeta bir açık hava konser alanına döner.' },
    { name: 'Güneşe Selam', desc: 'Deniz Orgu’nun hemen yanındaki 22 metre çapında dairesel bir güneş paneli döşemesi, gün boyu depoladığı enerjiyle gece boyunca ışıltılı bir renk gösterisi sunar. Hitchcock’un “dünyanın en güzel gün batımı” dediği manzarayla birleşince kentin en sevilen buluşma noktasına dönüşür.' },
    { name: 'Roma Forumu', desc: 'MÖ 1. yüzyılda İmparator Augustus döneminde kurulan ve Adriyatik kıyısının en büyük antik meydanı olan forum, bir zamanlar kentin siyasi ve dini yaşamının merkeziydi. Bugün ayakta kalan sütunlar ve “utanç sütunu” olarak bilinen taş, Zadar’ın iki bin yıllık geçmişine tanıklık eder.' },
    { name: 'Aziz Donatus Kilisesi', desc: '9. yüzyılda Roma Forumu’nun taşları üzerine inşa edilen bu dairesel planlı Bizans-öncesi yapı, Hırvatistan’ın en etkileyici erken ortaçağ kiliselerinden biridir. Olağanüstü akustiği nedeniyle bugün klasik müzik konserlerine ev sahipliği yapar.' },
    { name: 'Aziz Anastasia Katedrali', desc: 'Zadar’ın en büyük kilisesi olan bu Roman üslubundaki katedral 12.–13. yüzyıllarda tamamlanmış ve şehrin baş azizesi Aziz Anastasia’ya adanmıştır. Çan kulesine tırmanan ziyaretçiler, kızıl çatıların ve masmavi Adriyatik’in eşsiz panoramasıyla ödüllendirilir.' },
  ],
  zagreb: [
    { name: 'Aziz Mark Kilisesi', desc: 'Yukarı Şehir’in kalbindeki bu 13. yüzyıl kilisesi, çatısında Zagreb şehri ile Hırvatistan Krallığı’nın armalarını betimleyen rengârenk çinileriyle dünyaca ünlüdür. Sade taş cephesi ve göz alıcı çatısıyla kentin en çok fotoğraflanan simgelerinden biridir.' },
    { name: 'Zagreb Katedrali', desc: '108 metrelik ikiz kuleleriyle Zagreb siluetine hâkim olan bu neo-gotik katedral, Hırvatistan’ın en yüksek yapısıdır. Kökeni 11. yüzyıla uzanan yapı, Tatar istilaları ve 1880 depreminden sonra defalarca yeniden inşa edilmiştir.' },
    { name: 'Ban Jelačić Meydanı', desc: '17. yüzyıldan beri kentin buluşma noktası olan bu geniş meydan, ortasında atının üstünde Ban Josip Jelačić heykeliyle Zagreb’in canlı kalbidir. Çevresindeki pastel renkli tarihî binalar ve tramvaylarla şehrin ritmini en iyi yansıtan yerdir.' },
    { name: 'Lotrščak Kulesi & Funiküler', desc: '13. yüzyıldan kalma bu savunma kulesinden her gün öğlen tam vaktinde atılan top, asırlık bir Zagreb geleneğidir. Kuleye çıkan kısacık funiküler dünyanın en dik ve en kısa toplu taşıma hatlarından biri olup Yukarı Şehir manzarasını ayaklarınıza serer.' },
    { name: 'Dolac Pazarı', desc: 'Ban Jelačić Meydanı’nın hemen üstünde 1930’dan beri kurulan bu açık hava pazarı, kırmızı şemsiyeleriyle “Zagreb’in göbeği” olarak anılır. Yerel çiftçilerin taze ürünleri, peynirleri ve çiçekleriyle kentin gerçek mutfak kültürünü yaşatan bir merkezdir.' },
    { name: 'Kopmuş İlişkiler Müzesi', desc: 'Sona ermiş aşkların bıraktığı eşyaları ve öykülerini sergileyen bu özgün konseptli müze, dünyada türünün ilk örneğidir. 2011’de Avrupa’nın En Yenilikçi Müzesi ödülünü kazanmış, ziyaretçilerini hem güldüren hem düşündüren duygusal bir yolculuğa çıkarır.' },
  ],
  prag: [
    { name: 'Charles Köprüsü', desc: 'İmparator IV. Karl’ın 1357’de yaptırdığı bu görkemli gotik taş köprü, Vltava Nehri üzerinde Eski Şehir ile Kale’yi birleştirir ve iki yanında 30 barok azize heykeliyle bezelidir. Sokak müzisyenleri ve ressamlarıyla Prag’ın en canlı ve romantik noktasıdır.' },
    { name: 'Prag Kalesi & Aziz Vitus', desc: 'Guinness rekorlar kitabına göre dünyanın en büyük antik kale kompleksi olan bu yapı, 9. yüzyıldan beri Bohemya krallarının ve bugün Çek cumhurbaşkanının makamıdır. İçindeki ihtişamlı gotik Aziz Vitus Katedrali, kraliyet mücevherlerini ve etkileyici vitraylarını barındırır.' },
    { name: 'Astronomik Saat (Orloj)', desc: '1410’da yapılan ve dünyanın hâlâ çalışan en eski astronomik saati olan Orloj, güneşin, ayın ve burçların konumunu gösterir. Her saat başı, iskeletin çanı çaldığı ve On İki Havari’nin geçit yaptığı figürlü gösterisiyle meydanı doldurur.' },
    { name: 'Eski Şehir Meydanı', desc: '12. yüzyıldan beri kentin kalbi olan bu meydan, pastel renkli barok cepheleri, iki sivri kuleli gotik Týn Kilisesi ve Astronomik Saat’le çevrilidir. Yüzyıllarca pazar ve tören alanı olan meydan, Prag’ın masalsı atmosferinin merkezidir.' },
    { name: 'Altın Sokak', desc: 'Prag Kalesi surlarına yaslanmış minik ve rengârenk evlerden oluşan bu şirin sokak, adını burada yaşadığı söylenen simyacılardan alır. Bir dönem yazar Franz Kafka’nın da çalıştığı 22 numaralı ev, sokağın en ünlü durağıdır.' },
    { name: 'Petřín Tepesi', desc: 'Vltava’nın batı yakasında yükselen bu yeşil tepe, üzerindeki Eyfel Kulesi’ni andıran gözlem kulesiyle Prag’ın en geniş panoramasını sunar. Gül bahçeleri, ayna labirenti ve funikülerıyla kentliler için sevilen bir kaçış noktasıdır.' },
    { name: 'Josefov (Yahudi Mahallesi)', desc: 'Avrupa’nın en iyi korunmuş Yahudi mahallelerinden biri olan Josefov, Avrupa’nın en eski faal sinagogu olan Eski-Yeni Sinagog’u ve on binlerce mezar taşının üst üste yığıldığı ürpertici tarihî mezarlığı barındırır. Golem efsanesinin de doğduğu yerdir.' },
    { name: 'Wenceslas Meydanı', desc: 'Aslında geniş bir bulvar olan bu meydan, tepesindeki Ulusal Müze ve Aziz Wenceslas atlı heykeliyle modern Çek tarihinin sahnesidir. 1989 Kadife Devrimi’nin kalabalık gösterilerine ev sahipliği yapmış, kentin ticari ve toplumsal kalbidir.' },
    { name: 'Dans Eden Ev', desc: 'Mimar Frank Gehry’nin tasarladığı bu sıra dışı yapı, birbirine sarılan bir dans çiftini andıran eğri cephesiyle “Ginger ve Fred” lakabıyla anılır. Prag’ın tarihî dokusuna cesur bir çağdaş dokunuş katan yapının çatısında panoramik bir teras bulunur.' },
    { name: 'Vyšehrad', desc: 'Vltava Nehri’ne tepeden bakan bu tarihî kale, Çek efsanelerine göre Prag’ın kuruluşuyla ilişkilendirilen kutsal bir yerdir. Neo-gotik Aziz Petrus ve Paulus Kilisesi ile ünlü Çeklerin gömülü olduğu mezarlığı, sakin ve panoramik bir kaçış sunar.' },
  ],
  budva: [
    { name: 'Eski Şehir (Stari Grad)', desc: 'Adriyatik kıyısında bir yarımadaya kurulu Budva’nın Eski Şehri; Venedik surlarıyla çevrili dar taş sokakları, meydanları ve kiliseleriyle 2.500 yıllık bir geçmişi barındırır. Deniz kıyısındaki bu ortaçağ dokusu, kentin en büyüleyici köşesidir.' },
    { name: 'Citadela', desc: 'Budva Eski Şehri’nin ucunda, denize hâkim bir kayalığa kurulu Citadela, kenti koruyan tarihî bir kaledir. Surlarından Adriyatik’in ve kırmızı çatıların panoraması izlenir; içinde bir kütüphane ve deniz müzesi bulunur.' },
    { name: 'Sveti Stefan', desc: 'Bir zamanlar balıkçı köyü olan, ince bir kum diliyle karaya bağlı Sveti Stefan adacığı, taş evleriyle bir lüks otele dönüşmüş, Karadağ’ın en ikonik manzarasıdır. Pembe kumlu plajları ve gül rengi çatılarıyla kartpostal gibidir.' },
    { name: 'Mogren Plajı', desc: 'Budva Eski Şehri’ne kısa bir kayalık yürüyüşle ulaşılan Mogren, kentin en sevilen plajıdır; iki koydan oluşur ve berrak suyu, kayalıkları ve gün batımıyla ünlüdür. Yol üzerindeki Balerin heykeli plaja eşlik eder.' },
    { name: 'Balerin Heykeli', desc: 'Budva sahilinde bir kayalığın üzerinde denize doğru uzanan zarif balerin heykeli, kentin romantik simgesidir. Denizini bekleyen bir kızın efsanesine dayanan heykel, gün batımında en çok fotoğraflanan noktadır.' },
  ],
  kotor: [
    { name: 'Kotor Surları & San Giovanni', desc: 'Kotor’un arkasındaki dik dağ yamacına tırmanan yaklaşık 1.350 basamaklı surlar, kenti koruyan Venedik dönemi savunma sisteminin bir parçasıdır. Zirvedeki San Giovanni Kalesi, Kotor Körfezi’nin (Boka) fiyort benzeri eşsiz panoramasını sunar.' },
    { name: 'Aziz Trifon Katedrali', desc: '1166’da kutsanan Aziz Trifon Katedrali, Kotor’un koruyucu azizine adanmış, iki çan kuleli görkemli bir Romanesk yapıdır. Değerli dinî hazineleri ve freskleriyle kentin bin yıllık Katolik mirasını yaşatır.' },
    { name: 'Eski Şehir Meydanları', desc: 'Kotor’un surlarla çevrili Eski Şehri; birbirine dar geçitlerle bağlı meydanları, saat kulesi, Venedik izli sarayları ve kiliseleriyle bir labirent gibidir. Sokaklardaki kediler kentin sevimli simgesi olmuştur.' },
    { name: 'Deniz Müzesi', desc: 'Bir Barok sarayda kurulu Kotor Deniz Müzesi, Boka Körfezi’nin yüzyıllara uzanan güçlü denizcilik geleneğini gemi maketleri, portreler ve deniz eşyalarıyla anlatır. Kentin denize bağlı zengin tarihine ışık tutar.' },
    { name: 'Our Lady of the Rocks', desc: 'Perast açığında, yüzyıllar boyunca denize atılan taşlarla oluşturulan yapay bir ada üzerine kurulu bu kilise, bölgenin en özgün mabetlerindendir. Tekneyle ulaşılan ada, denizcilerin adaklarını ve ünlü tablolarını barındırır.' },
  ],

  // --- Arnavutluk & İtalya & Yunanistan rota ek şehirleri ---
  tiran: [
    { name: 'Skanderbeg Meydanı', desc: 'Tiran’ın kalbindeki geniş Skanderbeg Meydanı, adını Osmanlı’ya karşı direnişiyle ünlü ulusal kahraman Skanderbeg’den alır; ortasında onun atlı heykeli yükselir. Çevresindeki tarihî binalar ve yeni düzenlemesiyle kentin buluşma ve tören merkezidir.' },
    { name: 'Et’hem Bey Camii', desc: '18. yüzyıl sonunda başlanıp 19. yüzyılda tamamlanan Et’hem Bey Camii, dış ve iç duvarlarını süsleyen doğa manzaralı ender freskleriyle Osmanlı cami sanatının özgün bir örneğidir. Komünist dönemde kapatılıp sonra yeniden ibadete açılmasıyla da simgeseldir.' },
    { name: 'Bunk’Art', desc: 'Enver Hoxha rejiminin nükleer saldırıya karşı inşa ettiği devasa yeraltı sığınağı, bugün Bunk’Art adıyla Arnavutluk’un komünist dönemini ve tarihini anlatan çarpıcı bir müze-sanat mekânıdır. Yüzlerce odası, o dönemin paranoyasını gözler önüne serer.' },
    { name: 'Dajti Dağı Teleferiği', desc: 'Tiran’ın hemen doğusundaki Dajti Dağı’na çıkan teleferik, Balkanların en uzun teleferik hatlarından biridir. Zirveden kentin, ovanın ve uzaktaki dağların panoraması izlenir; doğa yürüyüşleri için de gözde bir kaçış noktasıdır.' },
    { name: 'Piramit (Piramida)', desc: 'Diktatör Enver Hoxha’nın anısına 1988’de müze olarak yapılan bu brütalist piramit, komünizmin çöküşünden sonra farklı işlevler kazandı ve yenilenerek bir teknoloji-kültür merkezine dönüştü. Üzerine tırmanılabilen yapısıyla kentin tartışmalı bir simgesidir.' },
  ],
  shkoder: [
    { name: 'Rozafa Kalesi', desc: 'Shkodra’ya, göle ve üç nehrin birleştiği noktaya hâkim bir tepede yükselen Rozafa Kalesi, kökleri İliryalılara uzanan tarihî bir savunma yapısıdır. Kaleye adını veren, surlara örülen kadın Rozafa efsanesiyle ve panoramik manzarasıyla ünlüdür.' },
    { name: 'Marubi Fotoğraf Müzesi', desc: 'Shkodra’daki Marubi Ulusal Fotoğraf Müzesi, Balkanların en eski fotoğraf stüdyolarından birinin, 19. yüzyıldan bugüne uzanan yüz binlerce cam negatiften oluşan arşivini barındırır. Arnavutluk’un bir asırlık toplumsal tarihini görsel olarak belgeler.' },
    { name: 'Shkodra Gölü', desc: 'Arnavutluk ile Karadağ arasında uzanan Shkodra Gölü, Güney Avrupa’nın en büyük gölüdür ve zengin kuş yaşamıyla önemli bir doğa alanıdır. Tekne turları, kıyı köyleri ve pelikanlarıyla huzurlu bir doğa cennetidir.' },
    { name: 'Kurşunlu (Lead) Camii', desc: 'Göl kıyısında, kurşun kaplı kubbeleriyle dikkat çeken 18. yüzyıl camisi, minaresini yitirmiş olsa da zarif mimarisiyle bölgenin Osmanlı geçmişini yansıtır. Sakin konumu ve manzarasıyla huzurlu bir tarihî yapıdır.' },
  ],
  lezhe: [
    { name: 'Skanderbeg Anıt-Mezarı', desc: 'Arnavutluk’un ulusal kahramanı Skanderbeg’in 1468’de gömüldüğü Lezha’daki kilise-anıt, ülkenin en önemli hac ve anma noktalarından biridir. Kahramanın miğferi ve kılıcının simgesel kopyalarıyla bağımsızlık ruhunu yaşatır.' },
    { name: 'Lezha (Lissus) Kalesi', desc: 'Kente tepeden bakan Lezha Kalesi, kökleri MÖ 4. yüzyılda İliryalılara uzanan, Roma, Bizans ve Osmanlı’da kullanılmış çok katmanlı bir savunma yapısıdır. Surlarından ovanın ve Adriyatik’in manzarası izlenir.' },
    { name: 'Antik Lissus Kalıntıları', desc: 'Antik Lissus kenti; surları, agorası ve kalıntılarıyla bölgenin köklü geçmişine ışık tutar. Kaleyle bütünleşen bu antik doku, İliryalıların ve Roma’nın mirasını taşır.' },
  ],
  trieste: [
    { name: 'Piazza Unità d’Italia', desc: 'Denize doğrudan açılan görkemli Piazza Unità d’Italia, Avrupa’nın deniz kıyısındaki en büyük meydanlarından biridir. Avusturya-Macaristan döneminin anıtsal saray ve binalarıyla çevrili meydan, akşam aydınlatmasıyla büyüleyici bir atmosfer sunar.' },
    { name: 'Miramare Şatosu', desc: 'Trieste körfezine bakan bir burnun ucunda, Habsburg Arşidükü Maximilian için 19. yüzyılda inşa edilen bembeyaz Miramare Şatosu; zarif odaları ve deniz manzaralı botanik bahçeleriyle ünlüdür. Trajik kaderiyle de anılan romantik bir yapıdır.' },
    { name: 'Canal Grande & Borsa', desc: 'Trieste’nin merkezindeki Canal Grande, neoklasik binalar ve kafelerle çevrili, teknelerin girebildiği bir kanaldır. Çevresindeki eski borsa binası ve meydanlarıyla kentin Orta Avrupa esintili zarafetini yansıtır.' },
    { name: 'San Giusto Kalesi & Katedrali', desc: 'Trieste’ye tepeden bakan San Giusto Tepesi’nde yükselen kale ve yanındaki katedral, kentin en eski dokusunu oluşturur. Katedralin Bizans mozaikleri ve kalenin surlarından izlenen körfez panoraması etkileyicidir.' },
    { name: 'Tarihî Kahvehaneler', desc: 'Trieste, Orta Avrupa’nın kahve başkenti sayılır; James Joyce ve Italo Svevo gibi yazarların uğrağı olan Caffè San Marco ve Caffè degli Specchi gibi tarihî kahvehaneleri ünlüdür. Bu mekânlar kentin edebî ruhunu yaşatır.' },
  ],
  treviso: [
    { name: 'Piazza dei Signori', desc: 'Treviso’nun tarihî kalbindeki Piazza dei Signori, ortaçağdan kalma Palazzo dei Trecento ve çevresindeki kemerli yapılarla çevrili canlı bir meydandır. Kafeleri ve buluşma noktalarıyla kentin sosyal merkezidir.' },
    { name: 'Su Kanalları & Buranelli', desc: 'Treviso’yu bölen Sile ve Cagnan sularının oluşturduğu kanallar, üzerlerindeki köprüler ve su değirmenleriyle kente “Küçük Venedik” lakabını kazandırır. Buranelli semtindeki kanal kıyısı sokaklar en fotojenik köşelerdir.' },
    { name: 'Şehir Surları & Kapıları', desc: 'Treviso’yu çevreleyen 16. yüzyıl Venedik surları ve Porta San Tomaso gibi anıtsal kapıları, kentin savunma geçmişini yansıtır. Surların çevresi bugün yürüyüş ve bisiklet için yeşil bir kuşaktır.' },
    { name: 'Prosecco Yolu', desc: 'Treviso’nun kuzeyindeki Conegliano-Valdobbiadene tepeleri, dünyaca ünlü Prosecco köpüklü şarabının anavatanıdır ve UNESCO Dünya Mirası Listesi’ndedir. Bağlarla kaplı yamaçlarda şarap tadımı ve manzara turları yapılır.' },
  ],
  pisa: [
    { name: 'Eğik Kule', desc: 'Pisa Katedrali’nin çan kulesi olarak 12. yüzyılda inşasına başlanan kule, zeminin çökmesiyle daha yapım aşamasındayken eğilmeye başladı ve dünyaca ünlü “Eğik Kule” oldu. Mermer kemerli katları ve tepesine çıkan merdiveniyle mühendislik tarihinin sevilen bir kazasıdır.' },
    { name: 'Piazza dei Miracoli', desc: '“Mucizeler Meydanı” olarak anılan bu yeşil alan; Eğik Kule, katedral, vaftizhane ve anıtsal mezarlığı bir arada barındıran görkemli bir dinî komplekstir. Beyaz mermer yapılarıyla UNESCO Dünya Mirası Listesi’ndedir.' },
    { name: 'Duomo & Vaftizhane', desc: 'Pisa Katedrali (Duomo), alacalı mermer cephesi ve tunç kapılarıyla Pisan-Romanesk mimarinin başyapıtıdır; yanındaki dairesel vaftizhane ise olağanüstü akustiğiyle ünlüdür. Rehberlerin söylediği notaların yankısı büyüleyicidir.' },
    { name: 'Camposanto', desc: 'Meydandaki anıtsal mezarlık Camposanto, efsaneye göre Kudüs’ten getirilen kutsal toprak üzerine kurulmuştur. Gotik kemerli galerileri ve bir zamanlar duvarlarını kaplayan görkemli fresklerle sessiz, etkileyici bir mekândır.' },
    { name: 'Arno Rıhtımı & Lungarni', desc: 'Pisa’yı ikiye bölen Arno Nehri’nin kıyısındaki Lungarni, renkli cepheli sarayları ve köprüleriyle kentin daha sakin, otantik yüzünü sunar. Nehir kıyısındaki minik gotik kilise Santa Maria della Spina bir mücevher gibidir.' },
  ],
  bari: [
    { name: 'Bari Vecchia', desc: 'Bari’nin labirent gibi eski şehri Bari Vecchia, dar sokaklarında kadınların kapı önünde el yapımı orecchiette makarnası açtığı, canlı ve otantik bir mahalledir. Kiliseleri, meydanları ve gündelik yaşamıyla kentin ruhunu yansıtır.' },
    { name: 'San Nicola Bazilikası', desc: '1087’de, Aziz Nikolaos’un (Noel Baba’nın esin kaynağı) Myra’dan getirilen kutsal emanetlerini barındırmak için inşa edilen bu Romanesk bazilika, hem Katolikler hem Ortodokslar için önemli bir hac merkezidir. Puglia Romanesk mimarisinin öncü örneğidir.' },
    { name: 'Svevo Kalesi', desc: 'Kutsal Roma İmparatoru II. Frederick’in 13. yüzyılda güçlendirdiği bu Norman-Sveb kalesi; hendekleri ve kuleleriyle Bari’nin denize bakan görkemli savunma yapısıdır. Bugün sergilere ev sahipliği yapar.' },
    { name: 'Lungomare & Liman', desc: 'Bari’nin deniz boyunca uzanan geniş Lungomare bulvarı, anıtsal binaları ve Adriyatik manzarasıyla keyifli bir yürüyüş güzergâhıdır. Kentin limanı ise Yunanistan ve Balkanlar’a feribot seferlerinin kalkış noktasıdır.' },
  ],
  kavala: [
    { name: 'Panagia Eski Mahallesi', desc: 'Kavala’nın denize uzanan yarımadasındaki Panagia mahallesi; renkli evleri, dar taş sokakları ve deniz manzarasıyla kentin en pitoresk köşesidir. Bizans surları içindeki bu tarihî semt, huzurlu bir gezinti sunar.' },
    { name: 'Kamares Su Kemeri', desc: 'Kentin üzerinden geçen görkemli Kamares Su Kemeri, 16. yüzyılda Kanuni Sultan Süleyman döneminde yarımadaya su taşımak için inşa edilmiştir. Çok katlı kemerleriyle Kavala’nın en çarpıcı Osmanlı eseridir.' },
    { name: 'İmaret (Mehmet Ali Paşa Külliyesi)', desc: 'Mısır’ın kurucusu, Kavala doğumlu Mehmet Ali Paşa’nın 19. yüzyıl başında yaptırdığı İmaret, kubbeleriyle dikkat çeken görkemli bir Osmanlı külliyesidir. Bir zamanlar medrese ve aşevi olan yapı, bugün lüks bir otel olarak hizmet verir.' },
    { name: 'Mehmet Ali Paşa’nın Evi', desc: 'Modern Mısır’ın kurucusu Mehmet Ali Paşa’nın doğduğu bu korunmuş konak; dönemin yaşam biçimini yansıtan odaları ve harem bölümüyle ziyarete açıktır. Bahçesindeki atlı heykeli, paşanın anısını yaşatır.' },
    { name: 'Kavala Kalesi', desc: 'Panagia yarımadasının tepesindeki Kavala Kalesi, Bizans ve Osmanlı dönemlerinden kalma surlarıyla limanı ve şehri korumuştur. Zirvesinden Kavala Körfezi’nin, adaların ve kentin panoraması izlenir.' },
  ],
  igumenitsa: [
    { name: 'Feribot Limanı', desc: 'İgumenitsa Limanı; İtalya’nın Bari, Brindisi ve Ancona limanlarına ve Korfu Adası’na feribot seferlerinin kalkış noktasıdır. Yunanistan ile Batı Avrupa arasındaki en işlek deniz geçiş kapılarından biri olarak hareketli bir liman kentidir.' },
    { name: 'Drepano Plajı', desc: 'İgumenitsa’ya yakın Drepano, uzun kumsalı ve sığ, berrak sularıyla çevredeki en geniş plajlardan biridir. Sakin atmosferi ve gün batımı manzarasıyla liman kentinin dinlence köşesidir.' },
    { name: 'Syvota Koyları', desc: 'İgumenitsa’nın güneyindeki Syvota; turkuaz koyları, minik adacıkları ve çam ağaçlarıyla çevrili plajlarıyla İyon kıyısının en güzel köşelerinden biridir. “Yunanistan’ın Karayipleri” denen berrak sularıyla ünlüdür.' },
  ],
  ljubljana: [
    { name: 'Ljubljana Kalesi', desc: 'Kente tepeden bakan bir tepede yükselen Ljubljana Kalesi, kökleri ortaçağa uzanan, fünikülerle çıkılan tarihî bir yapıdır. Surlarından ve kulesinden başkentin kırmızı çatılarının ve Alplerin panoraması izlenir.' },
    { name: 'Üç Köprü & Prešeren Meydanı', desc: 'Mimar Jože Plečnik’in tek bir köprüyü üçe genişleterek yarattığı özgün Üç Köprü (Tromostovje), Ljubljanica Nehri’ni pembe Fransisken Kilisesi’nin bulunduğu canlı Prešeren Meydanı’na bağlar. Kentin en sevilen buluşma noktasıdır.' },
    { name: 'Ejderha Köprüsü', desc: 'Kentin simgesi olan ejderhanın dört bronz heykeliyle süslü bu art nouveau köprü, 20. yüzyıl başında inşa edilmiştir. Ljubljana’nın efsanevi ejderhasını yaşatan zarif bir yapıdır.' },
    { name: 'Merkez Pazar (Plečnik Kolonadı)', desc: 'Plečnik’in tasarladığı, nehir kıyısı boyunca uzanan üstü kapalı sütunlu çarşı; yerel peynir, sebze ve el ürünlerinin satıldığı canlı bir pazardır. Kentin mimari zarafetiyle gündelik yaşamını birleştirir.' },
    { name: 'Tivoli Parkı', desc: 'Ljubljana’nın en büyük yeşil alanı olan Tivoli Parkı; ağaçlıklı yürüyüş yolları, çiçek bahçeleri ve bir malikâneyle kent merkezine bitişik huzurlu bir sığınaktır. Kentlilerin dinlence ve piknik köşesidir.' },
  ],
  bled: [
    { name: 'Bled Adası & Meryem Kilisesi', desc: 'Bled Gölü’nün tam ortasındaki minik adada yükselen Meryem Ana Hac Kilisesi, Slovenya’nın kartpostal simgesidir. Adaya geleneksel pletna tekneleriyle geçilir; kilisedeki “dilek çanı”nı çalmanın dilekleri gerçekleştirdiğine inanılır.' },
    { name: 'Bled Kalesi', desc: 'Gölün kıyısındaki sarp bir uçurumun tepesinde yükselen Bled Kalesi, Slovenya’nın en eski kalesidir. Teraslarından göl, ada ve karlı Julian Alpleri’nin nefes kesici panoraması izlenir.' },
    { name: 'Pletna Tekne Turu', desc: 'Bled Gölü’ne özgü, düz tabanlı ve rengârenk tenteli geleneksel pletna tekneleri, ayakta kürek çekilen bir yöntemle ziyaretçileri adaya taşır. Bu asırlık gelenek, göl gezisinin en otantik parçasıdır.' },
    { name: 'Vintgar Boğazı', desc: 'Bled’in birkaç kilometre kuzeyindeki Vintgar Boğazı, Radovna Nehri’nin oyduğu kanyon boyunca ahşap patikalar üzerinde yürünen turkuaz sulu bir doğa harikasıdır. Şelaleleri ve berrak akıntısıyla büyüleyicidir.' },
    { name: 'Bled Kreması (Kremšnita)', desc: 'Bled’in simge tatlısı kremšnita, çıtır milföy arasında vanilyalı krema ve kaymaktan oluşan ünlü bir pastadır. Göl kıyısındaki tarihî otelde doğduğu söylenen bu tatlı, manzara eşliğinde tadılır.' },
  ],
  sirmione: [
    { name: 'Scaliger Kalesi', desc: 'Garda Gölü’ne uzanan yarımadanın girişini koruyan Scaliger Kalesi, 13. yüzyılda Verona’yı yöneten Scaliger ailesi tarafından inşa edilmiş, ender görülen bir su hendekli kaledir. Kuleleri ve göl manzarasıyla Sirmione’nin masalsı girişini oluşturur.' },
    { name: 'Grotte di Catullo', desc: 'Yarımadanın en ucunda, zeytinlikler arasında uzanan Grotte di Catullo, Kuzey İtalya’daki en büyük Roma villası kalıntısıdır. Şair Catullus’a atfedilen bu görkemli villa, göl manzaralı terasları ve antik kalıntılarıyla büyüler.' },
    { name: 'Garda Gölü & Jamaica Plajı', desc: 'Sirmione’nin ucundaki Jamaica Plajı, düz kaya platformları ve berrak, sığ turkuaz sularıyla İtalya’nın en güzel göl plajlarından biridir. Grotte di Catullo’nun hemen yanındaki bu köşe, yüzmek ve manzara için idealdir.' },
    { name: 'Termal Kaplıcalar (Aquaria)', desc: 'Sirmione, gölün dibindeki kaynaktan çıkan kükürtlü termal sularıyla antik çağdan beri şifa merkezidir. Göl kıyısındaki Aquaria spa, açık havuzları ve manzarasıyla dinlendirici bir mola sunar.' },
    { name: 'Eski Kasaba Sokakları', desc: 'Scaliger Kalesi’nin ardındaki dar taş sokaklar; dondurmacıları, butikleri ve göl manzaralı meydanlarıyla Sirmione’nin şirin merkezini oluşturur. Otomobilsiz bu tarihî çekirdek, keyifli bir gezinti için idealdir.' },
  ],

  // --- İtalya ara/geçiş durakları ---
  verona: [
    { name: 'Arena di Verona', desc: 'MS 1. yüzyıldan kalma Arena di Verona, Kolezyum’dan daha eski, olağanüstü korunmuş bir Roma amfitiyatrosudur. 20 bini aşan kapasitesiyle bugün hâlâ dünyaca ünlü yaz opera festivaline ev sahipliği yapar.' },
    { name: 'Juliet’in Evi & Balkonu', desc: 'Shakespeare’in “Romeo ve Juliet”ine ithafen Juliet’in evi olarak kabul edilen bu ortaçağ konağı, ünlü balkonu ve avlusundaki Juliet heykeliyle her yıl milyonlarca romantiği çeker. Duvarları âşıkların notlarıyla doludur.' },
    { name: 'Piazza delle Erbe', desc: 'Bir zamanlar Roma forumunun bulunduğu Piazza delle Erbe; freskli sarayları, çeşmesi ve pazar tezgâhlarıyla Verona’nın en canlı tarihî meydanıdır. Kafeleri ve kuleleriyle kentin sosyal kalbidir.' },
    { name: 'Castelvecchio & Köprüsü', desc: 'Adige Nehri kıyısındaki Castelvecchio, 14. yüzyılda Scaliger ailesinin yaptırdığı mazgallı bir ortaçağ kalesidir ve bugün bir sanat müzesi olarak hizmet verir. Kırlangıç kuyruğu mazgallı köprüsü, nehir üzerinde zarif bir geçit sunar.' },
    { name: 'Piazza dei Signori & Lamberti Kulesi', desc: 'Zarif saraylarla çevrili Piazza dei Signori, ortasındaki Dante heykeliyle Verona’nın en soylu meydanıdır. Bitişiğindeki 84 metrelik Lamberti Kulesi’nin tepesinden kentin kırmızı çatılarının panoraması izlenir.' },
  ],
  padova: [
    { name: 'Scrovegni Şapeli', desc: 'Padova’daki Scrovegni Şapeli, ressam Giotto’nun 1305 civarında tamamladığı, İncil sahnelerini canlandıran çığır açıcı fresk döngüsüyle Batı sanat tarihinin dönüm noktalarından biridir. Rönesans’a giden yolu açan bu freskler UNESCO korumasındadır.' },
    { name: 'Aziz Antonio Bazilikası', desc: 'Padovalı Aziz Antonio’ya adanan bu görkemli bazilika, çok sayıda kubbesi ve minareyi andıran kuleleriyle Doğu-Batı mimarisini birleştirir. Azizin mezarını barındırması nedeniyle önemli bir hac merkezidir.' },
    { name: 'Prato della Valle', desc: 'Padova’nın merkezindeki Prato della Valle, ortasındaki kanalın ve 78 heykelin çevrelediği elips biçimli meydanıyla İtalya’nın en büyük meydanlarından biridir. Pazarları ve yürüyüş alanıyla kentlilerin gözdesidir.' },
    { name: 'Orto Botanico', desc: '1545’te kurulan Padova Botanik Bahçesi, dünyanın hâlâ özgün yerinde duran en eski üniversite botanik bahçesidir ve tıbbi bitki araştırmalarının beşiğidir. Bu öncü bilimsel miras nedeniyle UNESCO Dünya Mirası Listesi’ndedir.' },
    { name: 'Palazzo della Ragione', desc: 'Padova’nın ortaçağ adalet sarayı olan bu görkemli yapı, üstündeki tek parça dev çatısı ve freskli iç salonuyla ünlüdür. Alt katındaki tarihî çarşı, yüzyıllardır kentin ticaret hayatını yaşatır.' },
  ],
  vicenza: [
    { name: 'Teatro Olimpico', desc: 'Mimar Andrea Palladio’nun tasarlayıp 1585’te tamamlanan Teatro Olimpico, dünyanın ayakta kalan en eski kapalı sahne tiyatrosudur. Sahne arkasındaki, derinlik yanılsaması yaratan ahşap perspektif dekorlarıyla bir başyapıttır.' },
    { name: 'Basilica Palladiana', desc: 'Vicenza’nın ana meydanındaki bu yapı, genç Palladio’nun ortaçağ belediye sarayına eklediği zarif çift katlı revaklarla ünlüdür. Bakır çatısı ve klasik cephesiyle kentin simgesi ve UNESCO mirasının bir parçasıdır.' },
    { name: 'Villa La Rotonda', desc: 'Palladio’nun tasarladığı en ünlü villa olan La Rotonda, dört cephesi de aynı, merkezî kubbeli kusursuz simetrisiyle dünya mimarisini derinden etkilemiştir. Vicenza dışındaki bu villa, Palladyan üslubun saf bir örneğidir.' },
    { name: 'Corso Palladio', desc: 'Vicenza’nın ana caddesi Corso Palladio, boyunca sıralanan Palladio ve öğrencilerinin tasarladığı görkemli saraylarla adeta açık hava bir Rönesans mimarisi müzesidir. Kentin kalbindeki bu bulvar keyifli bir yürüyüş sunar.' },
  ],
  bologna: [
    { name: 'Piazza Maggiore & San Petronio', desc: 'Bologna’nın kalbindeki geniş Piazza Maggiore, çevresindeki ortaçağ saraylarıyla kentin sosyal ve siyasi merkezidir. Meydana bakan devasa San Petronio Bazilikası, dünyanın en büyük tuğla kiliselerinden biri olup cephesi bugün de yarım kalmıştır.' },
    { name: 'İki Kule (Asinelli & Garisenda)', desc: 'Ortaçağda soylu ailelerin güç göstergesi olarak yükselttiği kulelerden bugüne kalan Asinelli ve Garisenda, Bologna’nın simgesidir. Yaklaşık 100 metrelik eğik Asinelli Kulesi’nin tepesine çıkan basamaklar, kentin kırmızı çatılarının panoramasını sunar.' },
    { name: 'Portici (Kemerli Yollar)', desc: 'Bologna’yı benzersiz kılan, toplam kırk kilometreyi aşan tarihî kemer altı revaklar (portici), kenti yağmurdan ve güneşten korurken zarif bir yürüyüş dokusu oluşturur. Bu eşsiz kentsel öğe UNESCO Dünya Mirası Listesi’ndedir.' },
    { name: 'Quadrilatero Çarşısı', desc: 'San Petronio’nun arkasındaki Quadrilatero, ortaçağdan beri esnaf loncalarının bulunduğu; taze makarna, peynir, şarküteri ve balık tezgâhlarıyla dolu canlı bir lezzet semtidir. Bologna’nın “bereketli” mutfak kimliğinin kalbidir.' },
    { name: 'Archiginnasio', desc: '1088’de kurulan, Batı’nın en eski üniversitesinin tarihî binası olan Archiginnasio; armalarla süslü avlusu ve tümüyle ahşaptan yapılmış çarpıcı Anatomi Tiyatrosu’yla ünlüdür. Bilim ve eğitim tarihinin önemli bir simgesidir.' },
  ],
  bergamo: [
    { name: 'Città Alta (Üst Şehir)', desc: 'Bergamo’nun bir tepeye kurulu tarihî üst şehri, kendisini çevreleyen görkemli Venedik surlarıyla adeta bir açık hava müzesidir. Dar taş sokakları, meydanları ve ortaçağ atmosferiyle kentin en büyüleyici bölümüdür.' },
    { name: 'Piazza Vecchia & Campanone', desc: 'Üst Şehir’in kalbindeki bu zarif Rönesans meydanı, tarihî binaları ve çeşmesiyle mimar Le Corbusier’nin övgüsünü kazanmıştır. Meydana hâkim Campanone (Civic) çan kulesi, her akşam ortaçağdaki sokağa çıkma yasağını hatırlatan 100 çan sesiyle çalar.' },
    { name: 'Cappella Colleoni', desc: 'Paralı asker komutanı Bartolomeo Colleoni için yaptırılan bu şapel, rengârenk mermer cephesi ve incelikli oymalarıyla Lombardiya Rönesans mimarisinin bir başyapıtıdır. İçindeki görkemli lahdi ve freskleriyle büyüler.' },
    { name: 'Funicular & Surlar', desc: 'Bergamo’nun alt ve üst şehrini birbirine bağlayan tarihî füniküler, dik yamacı tırmanarak keyifli bir yolculuk sunar. UNESCO korumasındaki Venedik surlarının üzerinde yapılan yürüyüş ise ovaya ve açık havada Alpler’e hâkim manzaralar sağlar.' },
  ],
  como: [
    { name: 'Como Katedrali (Duomo)', desc: 'İnşası dört asır süren bu görkemli katedral, gotik, Rönesans ve barok üslupların uyumlu bir karışımını sergiler. İncelikli cephesi, devasa kubbesi ve içindeki değerli goblenleriyle Como Gölü bölgesinin en önemli dini yapısıdır.' },
    { name: 'Brunate Funicular', desc: 'Como şehrini yamaçtaki Brunate köyüne bağlayan bu tarihî füniküler, dik bir tırmanışla göl ve Alpler’in panoramik manzarasını sunar. Zirvedeki bakış terasları, gölün ünlü ters Y şeklini kuşbakışı görmek için idealdir.' },
    { name: 'Bellagio', desc: 'Como Gölü’nün üç kolunun birleştiği noktadaki bu zarif kasaba, “gölün incisi” olarak anılır. Dik taş merdivenleri, lüks villaları ve zarif bahçeleriyle ünlü olan kasaba, tekneyle ulaşılan romantik bir cazibe merkezidir.' },
    { name: 'Villa Olmo & Göl Turu', desc: 'Como şehrindeki bu görkemli neoklasik villa, göl kıyısındaki bahçeleri ve sanat sergileriyle dikkat çeker. Como Gölü’nde vapurla yapılan turlar ise ünlülerin villalarını, şirin kasabaları ve nefes kesen dağ manzaralarını keşfetmenin en iyi yoludur.' },
  ],
  bolzano: [
    { name: 'Ötzi (Güney Tirol Arkeoloji Müzesi)', desc: 'Bu müze, 1991’de Alpler’de bir buzulda bulunan ve “Buz Adam Ötzi” olarak bilinen 5.300 yıllık doğal mumyayı sergilemesiyle dünyaca ünlüdür. Mükemmel korunmuş bedeni ve eşyaları, Bakır Çağı yaşamına dair eşsiz bilgiler sunar.' },
    { name: 'Piazza Walther & Katedral', desc: 'Ortaçağ şairi Walther von der Vogelweide’nin anıtının bulunduğu bu meydan, Bolzano’nun canlı kalbidir ve kafeleriyle sosyal yaşamın merkezidir. Yanındaki, rengârenk çatısı ve zarif kulesiyle gotik katedral, kentin simgesidir.' },
    { name: 'Renon Teleferiği', desc: 'Bolzano’dan Renon (Ritten) yaylasına çıkan bu modern teleferik, kısa sürede vadi tabanından Alp otlaklarına ulaştırır. Zirvedeki eşsiz Dolomitler manzarası ve “toprak piramitleri” adı verilen ilginç jeolojik oluşumlar ziyaretçileri büyüler.' },
    { name: 'Eski Çarşı (Via dei Portici)', desc: 'Bolzano’nun en eski caddesi olan bu kemerli sokak, Avusturya ve İtalyan kültürlerinin kesiştiği bir alışveriş merkezidir. Üstü kapalı arkadları, tarihî tüccar evleri ve dükkânlarıyla kentin canlı ticari geçmişini yansıtır.' },
  ],
  trento: [
    { name: 'Castello del Buonconsiglio', desc: 'Yüzyıllar boyunca kenti yöneten piskopos-prenslerin ikametgâhı olan bu görkemli kale, Trento’nun en önemli anıtıdır. Özellikle “Kartallar Kulesi”ndeki ayları betimleyen gotik freskler, ortaçağ saray yaşamının nadir ve büyüleyici bir tasviridir.' },
    { name: 'Piazza Duomo & Neptün Çeşmesi', desc: 'Trento’nun kalbi olan bu tarihî meydan, Katolik Kilisesi tarihinde dönüm noktası olan Trento Konsili’nin toplandığı katedrale ev sahipliği yapar. Ortasındaki barok Neptün Çeşmesi ve çevresindeki freskli evlerle zarif bir atmosfer sunar.' },
    { name: 'MUSE Bilim Müzesi', desc: 'Ünlü mimar Renzo Piano’nun tasarladığı bu modern bilim müzesi, Alpler’in profilini yansıtan çarpıcı mimarisiyle dikkat çeker. Dağların zirvesinden buzullara, ormanlardan tropik sera katına uzanan interaktif sergileriyle doğayı ve bilimi kutlar.' },
    { name: 'Sardagna Teleferiği', desc: 'Trento şehir merkezinden kalkan bu teleferik, birkaç dakika içinde Monte Bondone’nin yamaçlarındaki Sardagna köyüne ulaştırır. Yolculuk sırasında ve varış noktasında, şehrin ve Adige Vadisi’nin nefes kesici panoramik manzarası izlenir.' },
  ],
  siena: [
    { name: 'Piazza del Campo & Palio', desc: 'Dokuz dilime ayrılmış kabuk biçimli bu eğimli meydan, dünyanın en güzel ortaçağ meydanlarından biri kabul edilir. Yılda iki kez düzenlenen ve mahalleler arası çekişmeli Palio at yarışının nefes kesici sahnesi olmasıyla ünlüdür.' },
    { name: 'Siena Katedrali (Duomo)', desc: 'Alacalı beyaz ve yeşil mermer şeritleriyle bezeli bu görkemli gotik katedral, İtalya’nın en etkileyici kiliselerindendir. Michelangelo ve Donatello’nun eserlerini ve olağanüstü işlenmiş mozaik zeminini barındırır.' },
    { name: 'Torre del Mangia', desc: 'Palazzo Pubblico’nun 88 metrelik bu zarif çan kulesi, inşa edildiği dönemde İtalya’nın en yüksek kulelerindendi. 400 basamağının tepesinden Siena’nın kırmızı çatılarının ve Toskana kırsalının eşsiz panoraması izlenir.' },
    { name: 'Palazzo Pubblico & Müze', desc: 'Piazza del Campo’daki bu gotik belediye sarayı, yüzyıllardır Siena’nın yönetim merkezidir ve bir müze barındırır. İçindeki Ambrogio Lorenzetti’nin “İyi ve Kötü Yönetimin Alegorisi” freskleri, ortaçağ siyasi düşüncesinin bir başyapıtıdır.' },
  ],
  sangimignano: [
    { name: 'Ortaçağ Kuleleri', desc: 'San Gimignano, zengin ailelerin güç gösterisi olarak inşa ettiği ve bugün 14 tanesi ayakta kalan taş kuleleriyle ünlüdür. “Ortaçağın Manhattan’ı” olarak anılan bu benzersiz siluet, kasabayı UNESCO Dünya Mirası listesine sokmuştur.' },
    { name: 'Piazza della Cisterna', desc: 'Adını ortasındaki tarihî su sarnıcından (cisterna) alan bu üçgen meydan, ortaçağ kuleleri ve saraylarıyla çevrilidir. Arnavut kaldırımlı zemini ve kafeleriyle kasabanın en canlı ve pitoresk buluşma noktasıdır.' },
    { name: 'Collegiata', desc: 'Sade dış cephesinin ardında, iç duvarları baştan başa 14. yüzyıl freskleriyle kaplı bu Romanesk kilise büyüleyicidir. Eski ve Yeni Ahit’ten sahneleri canlı renklerle betimleyen bu resimler, adeta bir “fakir İncili” işlevi görür.' },
    { name: 'Vernaccia Şarabı & Dondurma', desc: 'San Gimignano, İtalya’nın ilk kalite güvenceli beyaz şarabı olan altın renkli Vernaccia ile ünlüdür. Ayrıca ana meydanındaki, dünya şampiyonlukları kazanmış Gelateria Dondoli, ödüllü el yapımı dondurmalarıyla bir gastronomi durağıdır.' },
  ],
  lucca: [
    { name: 'Rönesans Surları', desc: 'Lucca’yı çevreleyen 16.–17. yüzyıl surları, hiç savaşta kullanılmadığı için olağanüstü korunmuştur ve bugün üzeri ağaçlıklı bir yürüyüş ve bisiklet parkuruna dönüşmüştür. Kenti kesintisiz saran bu 4 kilometrelik yeşil kuşak, dünyada eşine az rastlanır.' },
    { name: 'Piazza Anfiteatro', desc: 'Bu benzersiz oval meydan, bir zamanlar burada bulunan Roma amfitiyatrosunun tam biçimini koruyan binaların oluşturduğu bir mekândır. Antik arenanın hayaletini yaşatan bu kapalı meydan, kafeleri ve canlı atmosferiyle Lucca’nın kalbidir.' },
    { name: 'Guinigi Kulesi', desc: 'Lucca’nın en tanınan simgesi olan bu ortaçağ kulesi, tepesinde bir asma bahçe gibi yetişen meşe ağaçlarıyla dünyada eşsizdir. 230 basamağının tepesindeki bu yeşil bahçeden, kentin ve çevredeki tepelerin panoraması izlenir.' },
    { name: 'San Martino Katedrali', desc: 'Bu görkemli katedral, İsa’nın yüzünü taşıdığına inanılan “Volto Santo” adlı kutsal ahşap haç heykeliyle önemli bir hac merkezidir. Her sütunu farklı işlenmiş asimetrik Romanesk cephesi ve içindeki İlaria del Carretto’nun lahdiyle ünlüdür.' },
  ],
  cinqueterre: [
    { name: 'Vernazza & Manarola', desc: 'Cinque Terre’nin bu iki köyü, kayalıklara asılı gibi duran rengârenk evleri ve minik limanlarıyla bölgenin en fotojenik noktalarıdır. Doğal güzellikleri ve pitoresk atmosferleriyle İtalyan Rivierası’nın simgesi hâline gelmişlerdir.' },
    { name: 'Sentiero Azzurro', desc: '“Mavi Patika” anlamına gelen bu ünlü yürüyüş yolu, Cinque Terre’nin beş köyünü Ligurya Denizi’ne bakan uçurumlar boyunca birbirine bağlar. Üzüm bağları ve zeytinlikler arasından geçen bu rota, nefes kesen deniz manzaraları sunar.' },
    { name: 'Riomaggiore Limanı', desc: 'Cinque Terre köylerinin en güneydekisi olan Riomaggiore, dik kayalıklar arasına sıkışmış minik balıkçı limanı ve renkli evleriyle büyüler. Kayalık koyu ve teknelerle dolu manzarası, özellikle gün batımında büyüleyici bir tabloya dönüşür.' },
    { name: 'Monterosso Plajı', desc: 'Cinque Terre’nin en büyük ve en geniş kumsalına sahip köyü olan Monterosso, şezlonglarla dolu plajı ve gezinti yoluyla tatilcilerin gözdesidir. Diğer köylerin aksine daha düz bir araziye sahip olması, onu bölgedeki başlıca deniz tatili noktası yapar.' },
    { name: 'Bölge Treni', desc: 'Cinque Terre’nin sarp coğrafyasında köyleri birbirine bağlayan en pratik yol, kayalıkları delen tüneller içinden geçen bölgesel trendir. Köyler arasında birkaç dakikada ulaşım sağlayan bu hat, bölgeyi keşfetmenin en kolay ve hızlı yoludur.' },
  ],
  rimini: [
    { name: 'Rimini Plajları', desc: 'Kilometrelerce uzanan ince kumlu sahilleri ve düzenli plaj tesisleriyle Rimini, İtalya’nın en popüler ve en canlı deniz tatili merkezlerinden biridir. Şezlongları, gece hayatı ve hareketli atmosferiyle Adriyatik kıyısının eğlence başkentidir.' },
    { name: 'Tiberius Köprüsü', desc: 'İmparator Augustus döneminde başlanıp Tiberius zamanında MS 21’de tamamlanan bu görkemli taş köprü, iki bin yıldır ayakta durmakta ve hâlâ kullanılmaktadır. Sağlam beyaz taş kemerleriyle Roma mühendisliğinin dayanıklılığının bir kanıtıdır.' },
    { name: 'Augustus Takı', desc: 'MÖ 27’de İmparator Augustus onuruna dikilen bu zafer takı, İtalya’da ayakta kalan en eski Roma zafer takıdır. Önemli bir Roma yolunun (Via Flaminia) sonunu simgeleyen anıt, kentin görkemli antik geçmişine tanıklık eder.' },
    { name: 'Borgo San Giuliano', desc: 'Bir zamanlar balıkçıların yaşadığı bu şirin mahalle, rengârenk boyalı evleri ve dar sokaklarıyla büyüler. Duvarlarını süsleyen ve Rimini’de doğan ünlü yönetmen Federico Fellini’ye adanan duvar resimleriyle sanatsal bir atmosfere sahiptir.' },
    { name: 'San Marino', desc: 'Rimini’ye yakın bir dağın tepesinde yer alan San Marino, dünyanın en eski cumhuriyeti ve en küçük ülkelerinden biridir. Zirvedeki üç tarihî kalesi ve ortaçağ surlarıyla, çevre ovalara ve Adriyatik’e hâkim nefes kesici bir manzara sunar.' },
  ],

  // --- Slovenya / Hırvatistan / Adriyatik ---
  maribor: [
    { name: 'Yaşlı Asma (Stara Trta)', desc: 'Maribor’un Lent semtinde, bir evin cephesini süsleyen Stara Trta, dünyanın kayıtlı en yaşlı üzüm asmasıdır ve 400 yılı aşkın süredir üzüm verir. Yanındaki müze, bölgenin köklü şarap kültürünü anlatır.' },
    { name: 'Lent Semti', desc: 'Drava Nehri kıyısındaki tarihî Lent semti; eski su kulesi, meydanları ve nehir boyu kafeleriyle Maribor’un en canlı köşesidir. Her yaz düzenlenen ünlü Lent Festivali’ne ev sahipliği yapar.' },
    { name: 'Ana Meydan & Veba Anıtı', desc: 'Maribor’un ana meydanı, gotik-rönesans belediye sarayı ve ortasındaki barok Veba Anıtı’yla (18. yüzyıl salgınının anısına dikilen sütun) çevrilidir. Kentin tarihî ve sosyal merkezidir.' },
    { name: 'Pohorje', desc: 'Maribor’un hemen üzerinde yükselen Pohorje Dağı, teleferikle çıkılan bir kayak, bisiklet ve doğa yürüyüşü merkezidir. Ormanları, gölleri ve şelaleleriyle dört mevsim kentlilerin kaçış noktasıdır.' },
  ],
  postojna: [
    { name: 'Postojna Mağarası', desc: 'Slovenya’nın karst bölgesindeki Postojna Mağarası, milyonlarca yılda oluşan devasa sarkıt ve dikit salonlarıyla Avrupa’nın en görkemli yeraltı dünyalarından biridir. Ziyaretçiler mağaranın içine özel bir yeraltı treniyle girer.' },
    { name: 'Predjama Kalesi', desc: 'Postojna yakınında, bir uçurum mağarasının ağzına oyulmuş Predjama Kalesi, dünyanın en büyük mağara kalesidir. Efsanevi şövalye Erazem’in hikâyesiyle anılan bu 800 yıllık yapı, dramatik konumuyla büyüler.' },
    { name: 'İnsan Balığı (Proteus)', desc: 'Postojna Mağarası’nda yaşayan, kör ve solgun pembe renkli “insan balığı” (proteus), yüzyıllarca ejder yavrusu sanılan endemik bir mağara semenderidir. On yıllarca yemeden yaşayabilen bu canlı, mağaranın gizemli simgesidir.' },
  ],
  piran: [
    { name: 'Tartini Meydanı', desc: 'Piran’ın kalbindeki zarif mermer Tartini Meydanı, kentte doğan ünlü barok besteci ve kemancı Giuseppe Tartini’ye adanmıştır; ortasında onun heykeli yükselir. Bir zamanlar iç liman olan meydan, Venedik izli binalarla çevrilidir.' },
    { name: 'Aziz George Kilisesi', desc: 'Piran’a tepeden bakan Aziz George Kilisesi ve çan kulesi, Venedik’teki San Marco Campanile’den esinlenmiştir. Terasından kasabanın kızıl çatılarının ve Adriyatik’in eşsiz panoraması izlenir.' },
    { name: 'Deniz Surları', desc: 'Piran’ı çevreleyen ortaçağ deniz surları, kasabayı korsan ve düşman saldırılarına karşı korumuştur. Surların üzerinde yürüyüş, yarımadanın ve denizin en güzel manzarasını sunar.' },
    { name: 'Piran Rıhtımı & Deniz Ürünleri', desc: 'Piran’ın ucundaki fenerli rıhtım ve liman kıyısı, kasabanın en romantik köşesidir. Kıyı boyunca sıralanan balık lokantaları, taze Adriyatik deniz ürünleriyle ünlüdür.' },
  ],
  rovinj: [
    { name: 'Aziz Euphemia Kilisesi', desc: 'Rovinj’in en yüksek tepesinde denizden yükselen çan kulesiyle Aziz Euphemia Kilisesi, kentin simgesidir. Barok yapı, koruyucu azize Euphemia’nın lahdini barındırır ve kulesinden İstria kıyısının panoraması izlenir.' },
    { name: 'Eski Şehir Sokakları', desc: 'Rovinj’in eski şehri; denize inen dar ve dik arnavut kaldırımlı sokakları, renkli evleri ve çamaşır asılı balkonlarıyla İstria’nın en fotojenik dokusudur. Venedik izli bu labirent, adım başı sürprizlerle doludur.' },
    { name: 'Grisia Sokağı', desc: 'Rovinj’in tepedeki kiliseye çıkan Grisia Sokağı, iki yanına dizili sanatçı atölyeleri ve galerileriyle ünlüdür. Her yaz sokağın açık hava sanat sergisine dönüştüğü, kentin yaratıcı kalbidir.' },
    { name: 'Balbi Takı & Liman', desc: 'Eski şehrin girişindeki barok Balbi Takı, bir zamanların kent kapısının yerinde yükselir. Yanındaki hareketli balıkçı limanı, tekneleri ve kıyı kafeleriyle Rovinj’in denize açılan yüzüdür.' },
  ],
  pula: [
    { name: 'Pula Arenası', desc: 'Pula’nın simgesi olan bu devasa Roma amfitiyatrosu, MS 1. yüzyıldan kalma ve dünyanın en iyi korunmuş altı arenasından biridir. 20 bin kişilik kapasitesiyle bir zamanlar gladyatör dövüşlerine sahne olan yapı, bugün konser ve festivallere ev sahipliği yapar.' },
    { name: 'Augustus Tapınağı', desc: 'Pula’nın antik forum meydanındaki Augustus Tapınağı, MÖ 1. yüzyılda imparator Augustus adına inşa edilmiş zarif bir Roma tapınağıdır. İnce sütunları ve korunmuş cephesiyle antik kentin ihtişamını yansıtır.' },
    { name: 'Herkül Kapısı & Surlar', desc: 'Pula’nın antik surlarından kalan Herkül Kapısı, üzerindeki Herkül başı kabartmasıyla kentin en eski Roma anıtlarından biridir. Zafer takları ve surlarıyla kentin iki bin yıllık geçmişini bugüne taşır.' },
    { name: 'Brijuni Adaları', desc: 'Pula açıklarındaki Brijuni Takımadaları, bir milli park olup zengin doğası, Roma villası kalıntıları ve bir zamanlar Yugoslav lideri Tito’nun devlet konuğu ağırladığı safari parkıyla ünlüdür. Tekneyle ulaşılan bu adalar dinlendirici bir kaçış sunar.' },
  ],
  plitvice: [
    { name: 'Aşağı Göller & Büyük Şelale', desc: 'Plitvice Milli Parkı’nın aşağı gölleri, kanyon içinde birbirine dökülen çağlayanlarıyla en gösterişli bölümüdür. Ahşap patikalar üzerinde yürünen bu alanda, parkın en yüksek çağlayanı Büyük Şelale (Veliki Slap) görülür.' },
    { name: 'Yukarı Göller', desc: 'Parkın yukarı gölleri, ormanla çevrili, turkuazdan zümrüte tonlarda birbirine teraslar hâlinde bağlanan daha sakin bir göl dizisidir. Kireçtaşı barajların oluşturduğu bu manzara, doğa yürüyüşü için büyüleyicidir.' },
    { name: 'Kozjak Gölü Tekne Turu', desc: 'Plitvice’nin en büyük gölü Kozjak, aşağı ve yukarı gölleri birbirine bağlar ve elektrikli teknelerle sessizce geçilir. Bu göl gezisi, parkı keşfetmenin en huzurlu yollarından biridir.' },
    { name: 'Panoramik Tren', desc: 'Plitvice’nin geniş alanındaki bölümler arasında ulaşımı sağlayan panoramik tren (elektrikli araç), ziyaretçileri orman içinden taşır. Yürüyüş rotalarını birbirine bağlayarak parkı gezmeyi kolaylaştırır.' },
  ],
  split: [
    { name: 'Diocletianus Sarayı', desc: 'Roma İmparatoru Diocletianus’un MS 4. yüzyılda emeklilik için yaptırdığı devasa saray, bugün içinde evlerin, dükkânların ve kafelerin bulunduğu yaşayan bir kent merkezidir. Bu benzersiz yapı, dünyanın en iyi korunmuş Roma saraylarından biri olarak UNESCO korumasındadır.' },
    { name: 'Katedral & Çan Kulesi', desc: 'Split Katedrali, ilginç biçimde İmparator Diocletianus’un mozolesinden dönüştürülmüş, dünyanın en eski katedral yapılarından biridir. Sonradan eklenen Romanesk çan kulesinin tepesinden kentin ve adaların panoraması izlenir.' },
    { name: 'Riva', desc: 'Diocletianus Sarayı’nın deniz cephesi boyunca uzanan palmiyeli Riva promenadı, Split’in en canlı buluşma ve gezinti noktasıdır. Kafeleri ve deniz manzarasıyla kentin sosyal kalbidir.' },
    { name: 'Marjan Tepesi', desc: 'Split’in hemen batısındaki çam ormanlarıyla kaplı Marjan Tepesi, kente ve Adriyatik adalarına bakan bir yeşil vahadır. Yürüyüş yolları, seyir noktaları ve kayaya oyulmuş şapelleriyle kentlilerin doğa köşesidir.' },
    { name: 'Ada Feribotları (Hvar/Brač)', desc: 'Split’in limanı, Dalmaçya’nın en güzel adalarına (Hvar, Brač, Vis, Korčula) açılan ana feribot kapısıdır. Turkuaz koylara ve tarihî ada kasabalarına yapılan geziler buradan başlar.' },
  ],
  sibenik: [
    { name: 'Aziz Yakup Katedrali', desc: 'Šibenik’in Aziz Yakup Katedrali, hiç harç kullanılmadan tümüyle taş bloklarının birbirine geçirilmesiyle inşa edilen benzersiz bir yapıdır. Kubbesi ve dış cephesindeki 71 gerçek kişi portresi kabartmasıyla UNESCO Dünya Mirası Listesi’ndedir.' },
    { name: 'Aziz Mihail Kalesi', desc: 'Šibenik’e tepeden bakan Aziz Mihail Kalesi, kenti yüzyıllarca koruyan tarihî bir savunma yapısıdır. Bugün Adriyatik manzaralı açık hava sahnesi olarak konser ve etkinliklere ev sahipliği yapar.' },
    { name: 'Aziz John Kalesi', desc: 'Kentin en yüksek noktasındaki Aziz John (Barone) Kalesi, 17. yüzyılda Osmanlı kuşatmalarına karşı hızla inşa edilmiştir. Panoramik surlarından Šibenik’in, adaların ve kanalın en geniş manzarası izlenir.' },
    { name: 'Krka Milli Parkı', desc: 'Šibenik yakınındaki Krka Milli Parkı, Krka Nehri’nin oluşturduğu basamaklı şelaleler ve turkuaz göletlerle ünlüdür. Ahşap patikalar üzerinde yürünen park, doğa ve serinlik arayanlar için gözde bir duraktır.' },
  ],
  trogir: [
    { name: 'Aziz Lawrence Katedrali', desc: 'Trogir’in Aziz Lawrence Katedrali, özellikle usta Radovan’ın 1240’ta yaptığı, İncil sahneleriyle bezeli olağanüstü taş oyma portalıyla ünlüdür. Romanesk-gotik yapı, kentin UNESCO korumalı dokusunun kalbidir.' },
    { name: 'Kamerlengo Kalesi', desc: 'Trogir’in liman ağzındaki Kamerlengo Kalesi, 15. yüzyılda Venedik döneminde inşa edilmiş bir savunma yapısıdır. Surlarından kentin ve denizin panoraması izlenir; bugün yaz etkinliklerine ev sahipliği yapar.' },
    { name: 'Eski Şehir Adası', desc: 'Trogir’in tarihî merkezi, köprülerle karaya bağlı küçük bir ada üzerindedir; dar taş sokakları, meydanları ve Romanesk-gotik saraylarıyla adeta bir açık hava müzesidir. Bütünüyle UNESCO Dünya Mirası Listesi’ndedir.' },
    { name: 'Rıhtım (Riva)', desc: 'Trogir’in adayı çevreleyen deniz kıyısı promenadı Riva, yat limanı boyunca palmiyeler, kafeler ve restoranlarla uzanır. Eski şehrin surları eşliğindeki bu kıyı, keyifli bir gezinti sunar.' },
  ],
  opatija: [
    { name: 'Lungomare', desc: 'Opatija’dan komşu kasabalara kadar deniz boyunca yaklaşık 12 kilometre uzanan Lungomare (Franz Joseph) sahil yolu, belle époque döneminden kalma zarif bir yürüyüş güzergâhıdır. Villalar, koylar ve deniz manzarasıyla kentin simgesidir.' },
    { name: 'Denizkızı Heykeli (Maiden)', desc: 'Opatija sahilinde bir kayalığın üzerinde denize bakan “Martı Kayalıklı Kız” heykeli, kentin romantik simgesidir. Belle époque tatil kasabasının zarif atmosferini yansıtır.' },
    { name: 'Villa Angiolina & Parkı', desc: 'Opatija’nın turizm çağını başlatan tarihî Villa Angiolina, egzotik bitkilerle dolu görkemli bahçesiyle çevrilidir. Bugün turizm müzesi olarak kentin belle époque geçmişini anlatır.' },
    { name: 'Učka Dağı', desc: 'Opatija’nın arkasında yükselen Učka Dağı, bir doğa parkı olup Kvarner Körfezi’ne tepeden bakan zirvesiyle ünlüdür. Yürüyüş ve bisiklet rotalarıyla açık hava tutkunlarının gözde noktasıdır.' },
  ],

  // --- Almanya ara/geçiş durakları ---
  regensburg: [
    { name: 'Taş Köprü', desc: '12. yüzyılda Tuna Nehri üzerine inşa edilen bu köprü, döneminin bir mühendislik harikası olarak yüzyıllarca Haçlıların ve tüccarların kullandığı önemli bir geçitti. Ortaçağdan kalma bu köprü, kentin iyi korunmuş eski şehrine görkemli bir giriş sunar.' },
    { name: 'Aziz Peter Katedrali', desc: 'Regensburg’un siluetine hâkim olan bu görkemli yapı, Bavyera gotik mimarisinin en önemli başyapıtıdır. İncelikli ikiz kuleleri ve olağanüstü ortaçağ vitraylarıyla, ünlü çocuk korosu “Regensburger Domspatzen”e de ev sahipliği yapar.' },
    { name: 'Eski Şehir (UNESCO)', desc: 'II. Dünya Savaşı’ndan büyük ölçüde zarar görmeden kurtulan Regensburg’un eski şehri, İtalyan etkili patrici kuleleri ve dar sokaklarıyla Almanya’nın en iyi korunmuş ortaçağ merkezlerindendir. Bu benzersiz doku, UNESCO Dünya Mirası listesindedir.' },
    { name: 'Walhalla', desc: 'Bavyera Kralı I. Ludwig’in Tuna Nehri’ne bakan bir tepeye yaptırdığı bu görkemli neoklasik yapı, antik bir Yunan tapınağı biçimindedir. İçinde, önemli tarihî Alman şahsiyetlerinin büstlerini barındıran bir “şeref salonu” olarak tasarlanmıştır.' },
  ],
  nurnberg: [
    { name: 'İmparatorluk Kalesi (Kaiserburg)', desc: 'Şehrin üzerindeki kayalıklara kurulu bu görkemli kale, Kutsal Roma İmparatorluğu’nun önemli bir merkeziydi ve tüm imparatorların en az bir kez konakladığı bir mekândı. Surları ve kuleleriyle Nürnberg’in ortaçağdaki gücünü simgeler.' },
    { name: 'Eski Şehir & Schöner Brunnen', desc: 'Savaştan sonra özenle onarılan Nürnberg’in eski şehri, ana pazar meydanı çevresinde canlanır. Meydandaki 14. yüzyıldan kalma gotik “Güzel Çeşme” (Schöner Brunnen) ve döndürüldüğünde şans getirdiğine inanılan altın halkası ünlüdür.' },
    { name: 'Nazi Rally Belgeleme Merkezi', desc: 'Nazi Partisi’nin devasa mitinglerini düzenlediği alanda kurulan bu müze, rejimin propagandasını ve terörünü eleştirel bir gözle belgeler. Nürnberg Mahkemeleri’ne de ev sahipliği yapan kentin bu karanlık geçmişiyle yüzleşmesini sağlar.' },
    { name: 'Germanisches Nationalmuseum', desc: 'Almanca konuşulan bölgenin kültür tarihine adanmış bu müze, ülkenin en büyüğüdür ve tarih öncesinden günümüze uzanan devasa bir koleksiyona sahiptir. Dürer’in eserleri ve tarihî bilimsel aletleriyle Alman sanat ve kültürünün bir hazinesidir.' },
    { name: 'Handwerkerhof', desc: 'Kentin ana kapısının hemen içindeki bu şirin avlu, geleneksel el sanatlarının sürdürüldüğü küçük atölye ve dükkânlardan oluşan bir ortaçağ kasabasını canlandırır. Ünlü ızgara Nürnberg sosislerini tatmak için de gözde bir noktadır.' },
  ],
  wurzburg: [
    { name: 'Würzburg Residenz', desc: 'Piskopos-prensler için inşa edilen bu görkemli barok saray, UNESCO Dünya Mirası listesindedir ve Avrupa’nın en güzel saraylarından biri kabul edilir. Ana merdivenini süsleyen, ressam Tiepolo’nun dünyanın en büyük tavan freski, benzersiz bir başyapıttır.' },
    { name: 'Marienberg Kalesi', desc: 'Main Nehri’nin karşı yakasındaki bir tepede yükselen bu kale, yüzyıllar boyunca piskopos-prenslerin ikametgâhı olmuştur. Bağlarla çevrili konumu, surları ve müzeleriyle şehrin ve nehrin muhteşem panoramasını sunar.' },
    { name: 'Alte Mainbrücke', desc: 'Main Nehri üzerindeki bu tarihî köprü, üzerini süsleyen görkemli aziz heykelleriyle Prag’ın Charles Köprüsü’nü andırır. Yerlilerin ve ziyaretçilerin bir kadeh yerel Frank şarabı eşliğinde manzarayı izlediği sevilen bir buluşma noktasıdır.' },
    { name: 'Katedral & Şapel', desc: 'Almanya’nın en büyük Romanesk kiliselerinden biri olan Würzburg Katedrali (Dom), piskoposların anıt mezarları ve zengin sanat eserleriyle doludur. Yakınındaki zarif gotik Marienkapelle ise Riemenschneider’in heykelleriyle bezelidir.' },
  ],
  rothenburg: [
    { name: 'Şehir Surları & Kuleler', desc: 'Rothenburg, Almanya’nın tam olarak korunmuş nadir ortaçağ şehir surlarına sahip olmasıyla ünlüdür. Üzerinde kesintisiz yürünebilen bu surlar ve kuleleri, kasabayı bir masal diyarına dönüştürür ve tarihte bir yolculuk sunar.' },
    { name: 'Plönlein', desc: 'İki farklı yükseklikteki sokağın, bir çeşme ve iki kulenin oluşturduğu bu pitoresk köşe, Almanya’nın en çok fotoğraflanan noktalarından biridir. Rengârenk yarım ahşap evleriyle bu manzara, ortaçağ Almanya’sının romantik ruhunu simgeler.' },
    { name: 'Marktplatz & Belediye Kulesi', desc: 'Kasabanın canlı kalbi olan bu pazar meydanı, görkemli Rönesans belediye binası ve tarihî evlerle çevrilidir. Belediye binasının 60 metrelik kulesinin tepesinden, kırmızı çatıların ve çevredeki kırsalın nefes kesen panoraması izlenir.' },
    { name: 'Noel Müzesi', desc: 'Käthe Wohlfahrt’ın bu ünlü mağazası ve müzesi, yılın 365 günü Alman Noel geleneğini yaşatır. Süslenmiş dev bir ağaç ve el yapımı süsleriyle, Almanya’nın zengin Noel kültürünün büyülü atmosferini ziyaretçilere sunar.' },
  ],
  fussen: [
    { name: 'Neuschwanstein Şatosu', desc: 'Bavyera Kralı II. Ludwig’in bir dağ zirvesine yaptırdığı bu görkemli masalsı şato, Walt Disney’in ünlü şatosuna ilham vermiştir. Besteci Wagner’e adanan romantik iç mekânları ve dramatik konumuyla dünyanın en tanınan yapılarındandır.' },
    { name: 'Hohenschwangau Şatosu', desc: 'Kral II. Ludwig’in çocukluğunu geçirdiği bu sarı neo-gotik şato, babası Kral Maximilian tarafından inşa ettirilmiştir. Karşısındaki Neuschwanstein’ın manzarasına sahip olan bu şato, kraliyet ailesinin özgün eşyalarını korur.' },
    { name: 'Marienbrücke', desc: 'Pöllat Boğazı’nın derin uçurumu üzerine kurulu bu narin asma köprü, Neuschwanstein Şatosu’nun en ünlü ve en etkileyici manzarasını sunar. Bir şelalenin üzerindeki bu köprü, kartpostallık şato fotoğrafları için gözde bir noktadır.' },
    { name: 'Alpsee & Füssen Eski Şehri', desc: 'Şatoların eteğindeki Alpsee, dağların yansıdığı berrak suları ve çevresindeki yürüyüş yollarıyla huzurlu bir doğa harikasıdır. Yakınındaki Füssen kasabası ise renkli barok binaları ve tarihî sokaklarıyla Romantik Yol’un güzel bir bitiş noktasıdır.' },
  ],
  heidelberg: [
    { name: 'Heidelberg Kalesi', desc: 'Neckar Nehri’ne ve şehre tepeden bakan bu kızıl kumtaşı kale harabesi, Alman Romantizminin bir simgesidir. Kısmen yıkık hali, görkemli Rönesans mimarisi ve dünyanın en büyük şarap fıçısıyla ünlü olup şehrin en tanınan manzarasını oluşturur.' },
    { name: 'Eski Köprü (Karl Theodor)', desc: 'Neckar Nehri üzerindeki bu zarif 18. yüzyıl taş köprüsü, kale ve eski şehir manzarasıyla büyüler. Köprü başındaki, dokunmanın şans getirdiğine inanılan bronz “Köprü Maymunu” heykeli, ziyaretçilerin en sevdiği duraktır.' },
    { name: 'Filozoflar Yolu', desc: 'Nehrin karşı yakasındaki yamaçta uzanan bu ünlü yürüyüş yolu, adını buradan yürüyerek düşünen üniversite profesörlerinden ve filozoflardan alır. Kale ve eski şehrin en güzel panoramik manzarasını sunan romantik bir güzergâhtır.' },
    { name: 'Hauptstrasse & Üniversite', desc: 'Yaklaşık bir kilometre uzunluğundaki bu yaya caddesi, Almanya’nın en uzunlarından biri olup dükkânları ve kafeleriyle canlıdır. Almanya’nın en eski üniversitesine ev sahipliği yapan kentte, itaatsiz öğrencilerin kapatıldığı tarihî “öğrenci hapishanesi” de gezilebilir.' },
  ],
  dresden: [
    { name: 'Frauenkirche', desc: 'II. Dünya Savaşı’nın yıkıcı bombardımanında yerle bir olan bu ikonik barok kilise, birleşme sonrası orijinal taşları kullanılarak yeniden inşa edilmiştir. Görkemli kubbesiyle bu yapı, bugün barışın ve uzlaşmanın güçlü bir simgesidir.' },
    { name: 'Zwinger Sarayı', desc: 'Saksonya elektörleri için inşa edilen bu görkemli barok yapı, süslü avlusu, bahçeleri ve pavyonlarıyla büyüler. İçinde, Raffaello’nun “Sistine Madonnası” dahil dünya çapında başyapıtları barındıran Eski Ustalar Resim Galerisi yer alır.' },
    { name: 'Semperoper', desc: 'Saksonya Devlet Operası’na ev sahipliği yapan bu görkemli neo-Rönesans yapı, Wagner ve Strauss’un eserlerinin prömiyerlerine sahne olmuştur. Yıkım ve yeniden inşaların ardından, olağanüstü akustiği ve mimarisiyle Dresden’in kültürel simgesidir.' },
    { name: 'Brühl Terası & Fürstenzug', desc: 'Elbe Nehri kıyısındaki bu zarif teras, “Avrupa’nın Balkonu” olarak anılan panoramik manzarasıyla ünlüdür. Yakınındaki Fürstenzug ise Saksonya hükümdarlarını betimleyen, 23.000 Meissen porseleni karodan oluşan dünyanın en büyük porselen duvar resmidir.' },
  ],
  leipzig: [
    { name: 'Thomaskirche (Bach)', desc: 'Büyük besteci Johann Sebastian Bach’ın 27 yıl boyunca kilise korosunu yönettiği ve bugün mezarının bulunduğu bu kilise, müzik tarihi açısından kutsal bir mekândır. Dünyaca ünlü çocuk korosu Thomanerchor’a hâlâ ev sahipliği yapar.' },
    { name: 'Uluslar Savaşı Anıtı', desc: 'Napolyon’un yenilgiye uğratıldığı 1813 Leipzig Muharebesi’ni anmak için dikilen bu devasa anıt, Avrupa’nın en büyük anıtlarından biridir. 91 metrelik yapının tepesindeki gözlem terası, şehrin geniş panoramasını sunar.' },
    { name: 'Pasajlar (Mädlerpassage)', desc: 'Leipzig, tarihî ticari geçmişinden kalma zarif ve üstü camla örtülü alışveriş pasajlarıyla ünlüdür. Bunların en güzeli olan Mädlerpassage, Goethe’nin “Faust” eserine konu olan efsanevi Auerbachs Keller restoranını barındırır.' },
    { name: 'Barış Devrimi (Nikolaikirche)', desc: 'Bu tarihî kilise, 1989’da Doğu Almanya rejimine karşı düzenlenen ve “Barış Devrimi”ni ateşleyen kitlesel barışçıl gösterilerin merkeziydi. Duvarın yıkılmasına giden süreçte oynadığı rolle özgürlük mücadelesinin sembolü hâline gelmiştir.' },
  ],
  badenbaden: [
    { name: 'Friedrichsbad & Caracalla', desc: 'Baden-Baden, Roma döneminden beri süregelen şifalı termal su geleneğiyle ünlüdür. 19. yüzyıldan kalma görkemli Friedrichsbad’ın Roma-İrlanda banyo ritüeli ile modern Caracalla Termleri, bu köklü kaplıca kültürünü yaşatan iki farklı deneyim sunar.' },
    { name: 'Kurhaus & Kumarhane', desc: 'Baden-Baden’in zarif sosyal yaşamının merkezi olan bu görkemli 19. yüzyıl yapısı, ihtişamlı salonlarıyla bir kür ve etkinlik merkezidir. İçindeki, yazar Dostoyevski’ye de ilham veren tarihî kumarhane, Almanya’nın en eski ve en gösterişlilerindendir.' },
    { name: 'Lichtentaler Allee', desc: 'Oos Deresi boyunca uzanan bu zarif park ve ağaçlı gezinti yolu, iki yüzyıldır soyluların ve sanatçıların uğrak yeri olmuştur. Egzotik ağaçları, çiçek bahçeleri ve heykelleriyle kentin en zarif ve huzurlu yürüyüş güzergâhıdır.' },
    { name: 'Merkur Dağı Füniküleri', desc: 'Baden-Baden’e tepeden bakan Merkur Dağı’na çıkan bu dik füniküler, Almanya’nın en uzun ve en dik hatlarından biridir. Zirvedeki gözlem kulesinden, şehrin, Kara Orman’ın ve Ren ovasının nefes kesen panoraması izlenir.' },
  ],
  freiburg: [
    { name: 'Freiburg Münster', desc: 'Yaklaşık 116 metrelik zarif ve dantel gibi işlenmiş tek kulesiyle bu gotik katedral, sanat tarihçisi Burckhardt tarafından “Hristiyanlık âleminin en güzel kulesi” olarak nitelenmiştir. Her sabah ayaklarının dibinde canlı bir pazar kurulur.' },
    { name: 'Bächle', desc: 'Freiburg’un sokaklarında akan bu minik su kanalları (Bächle), bir zamanlar yangın söndürme ve hayvan sulama amacıyla kullanılan tarihî bir sistemdir. Yerel bir efsaneye göre, kazara bir Bächle’ye basan kişi bir Freiburglu ile evlenir.' },
    { name: 'Schlossberg', desc: 'Freiburg’un eski şehrine bakan bu ormanlık tepeye, tarihî bir füniküler veya yürüyüş yollarıyla çıkılır. Zirvesindeki gözlem kulesinden, kentin, katedral kulesinin ve çevredeki Kara Orman’ın panoramik manzarası izlenir.' },
    { name: 'Kara Orman Kapısı', desc: 'Freiburg, yemyeşil çam ormanları, guguklu saatleri ve şirin köyleriyle ünlü Kara Orman (Schwarzwald) bölgesine açılan ana kapıdır. Ünlü Titisee gölü ve doğa yürüyüşü rotaları için ideal bir başlangıç noktasıdır.' },
  ],

  // --- İsviçre & Doğu Fransa ---
  bern: [
    { name: 'Eski Şehir & Arkadlar', desc: 'İsviçre’nin başkenti Bern’in ortaçağdan kalma merkezi, altı kilometreyi bulan üstü kapalı kemerli alışveriş yollarıyla (arkad) ünlüdür. Kumtaşı binaları ve çeşmeleriyle olağanüstü korunmuş bu bölge, UNESCO Dünya Mirası listesindedir.' },
    { name: 'Zytglogge', desc: 'Bern’in simgesi olan bu ortaçağ saat kulesi, 15. yüzyıldan kalma astronomik saatiyle ünlüdür. Her saat başından birkaç dakika önce harekete geçen dönen ayılar, palyaço ve altın horoz gibi mekanik figürleri, asırlardır izleyicilerini büyüler.' },
    { name: 'Ayı Parkı & Aare', desc: 'Adını ayıdan (Bär) aldığına inanılan Bern, şehrin simgesi olan ayıları Aare Nehri kıyısındaki modern bir parkta barındırır. Kenti çevreleyen turkuaz renkli Aare Nehri ise yazın halkın akıntıya bırakıp yüzdüğü bir doğa harikasıdır.' },
    { name: 'Bern Katedrali (Münster)', desc: 'İsviçre’nin en yüksek çan kulesine (100 m) sahip bu görkemli gotik katedral, özellikle ana kapısındaki “Son Yargı” kabartmasıyla dikkat çeker. 344 basamağının tepesinden Bern’in kırmızı çatıları ve Alpler’in panoraması izlenir.' },
    { name: 'Rosengarten', desc: 'Eski Şehir’in karşısındaki bir tepede yer alan bu gül bahçesi, yüzlerce gül ve iris çeşidini barındırır. Ancak asıl ünü, Aare Nehri’nin kıvrımındaki tarihî kentin çatılarını ve kulelerini kucaklayan eşsiz panoramasından gelir.' },
  ],
  cenevre: [
    { name: 'Jet d’Eau', desc: 'Cenevre Gölü’nden gökyüzüne 140 metre yükselen bu devasa su fıskiyesi, saniyede 500 litre suyu fırlatarak kentin dünyaca tanınan simgesi hâline gelmiştir. Başlangıçta bir hidrolik sistemin güvenlik valfi olarak ortaya çıkmış, sonra bir gösteriye dönüşmüştür.' },
    { name: 'Eski Şehir & Aziz Pierre Katedrali', desc: 'Avrupa’nın en büyük ortaçağ eski şehirlerinden birine sahip Cenevre’nin merkezi, dar sokakları ve meydanlarıyla büyüler. Reform lideri Jean Calvin’in vaaz verdiği Aziz Pierre Katedrali, kulesinden şehir ve göl manzarası sunar.' },
    { name: 'Çiçek Saati', desc: 'Göl kıyısındaki İngiliz Bahçesi’nde yer alan bu ünlü saat, mevsimlere göre değişen binlerce canlı çiçekle döşenmiştir. Cenevre’nin saatçilik geleneğine ve hassasiyetine bir saygı duruşu olan bu saat, dünyanın en uzun saniye ibresine sahiptir.' },
    { name: 'BM & Kırık Sandalye', desc: 'Cenevre, Birleşmiş Milletler’in Avrupa merkezi olan görkemli Palais des Nations’a ev sahipliği yapan bir uluslararası diplomasi kentidir. Önündeki üç ayaklı dev “Kırık Sandalye” heykeli, kara mayınlarına karşı güçlü bir protesto anıtıdır.' },
    { name: 'Göl Kıyısı Promenadı', desc: 'Cenevre (Léman) Gölü’nün kıyısı boyunca uzanan bu zarif promenad, çiçek bahçeleri, parkları ve göl manzarasıyla kentlilerin gözde yürüyüş alanıdır. Karlı Alpler’in ve Jet d’Eau’nun manzarası eşliğinde tekne turları da yapılır.' },
  ],
  lausanne: [
    { name: 'Notre-Dame Katedrali', desc: '13. yüzyılda tamamlanan bu görkemli yapı, İsviçre’nin en güzel ve en büyük gotik katedrallerinden biri kabul edilir. Ortaçağdan bu yana süregelen bir gelenekle, her gece bir bekçinin kuleden saatleri yüksek sesle bağırarak duyurmasıyla ünlüdür.' },
    { name: 'Olimpiyat Müzesi', desc: 'Uluslararası Olimpiyat Komitesi’nin merkezi olan Lozan’daki bu müze, göl kıyısındaki konumu ve interaktif sergileriyle olimpiyat oyunlarının tarihini kutlar. Meşaleler, madalyalar ve sporcu eşyalarıyla olimpiyat ruhunu yaşatır.' },
    { name: 'Ouchy', desc: 'Lozan’ın Cenevre Gölü kıyısındaki eski liman mahallesi olan Ouchy, çiçekli promenadları, iskeleleri ve parklarıyla dinlenmek için idealdir. Göl manzarası ve karşı kıyıdaki Fransız Alpleri’yle huzurlu bir sahil atmosferi sunar.' },
    { name: 'Eski Şehir & Escaliers', desc: 'Tepelere kurulu Lozan’ın tarihî merkezi, dik sokakları ve “Escaliers du Marché” gibi üstü kapalı ahşap merdivenleriyle karakterizedir. Meydanları, pazarı ve butik dükkânlarıyla kentin canlı ve otantik kalbidir.' },
  ],
  montreux: [
    { name: 'Chillon Şatosu', desc: 'Cenevre Gölü kıyısındaki bir kaya adacığı üzerinde yükselen bu görkemli ortaçağ kalesi, İsviçre’nin en çok ziyaret edilen tarihî yapısıdır. Lord Byron’un “The Prisoner of Chillon” şiirine ilham veren zindanları ve göl manzarasıyla büyüler.' },
    { name: 'Sahil Promenadı', desc: 'Montreux’nün göl kıyısı boyunca uzanan bu subtropikal bitkilerle bezeli çiçekli promenad, kentin ünlü caz festivaline ev sahipliği yapar. Yıllarca burada yaşayan Queen solisti Freddie Mercury’nin anıt heykeli, promenadın en sevilen noktasıdır.' },
    { name: 'Rochers-de-Naye', desc: 'Montreux’den kalkan tarihî bir dişli treniyle 2.000 metre yüksekliğe çıkan Rochers-de-Naye, göle ve Alpler’e hâkim nefes kesici bir zirvedir. Alpin bahçesi ve panoramik manzarasıyla doğaseverlerin gözde bir kaçış noktasıdır.' },
    { name: 'Lavaux Bağları', desc: 'Cenevre Gölü’nün kuzey kıyısında dik yamaçlar boyunca uzanan bu teraslı bağlar, yüzyıllar süren emeğin ürünü olan bir kültürel peyzajdır. Göl, dağlar ve güneşin “üç güneşiyle” beslenen bu UNESCO korumasındaki bağlar, kaliteli beyaz şaraplarıyla ünlüdür.' },
  ],
  lugano: [
    { name: 'Göl Kıyısı & Parco Ciani', desc: 'İsviçre’nin İtalyanca konuşulan bölgesindeki Lugano, palmiyelerle bezeli göl kıyısı promenadı ve zarif Parco Ciani ile Akdeniz havası taşır. Çiçek bahçeleri, heykelleri ve göl manzarasıyla dinlenmek için idealdir.' },
    { name: 'Monte Brè / San Salvatore', desc: 'Lugano’yu çevreleyen bu iki dağ, füniküler trenlerle çıkılan panoramik zirveleriyle ünlüdür. Piramit biçimli San Salvatore ve İsviçre’nin en güneşli noktalarından Monte Brè, göle ve Alpler’e hâkim muhteşem manzaralar sunar.' },
    { name: 'Eski Şehir & Piazza della Riforma', desc: 'Lugano’nun tarihî merkezi, kemerli geçitleri, dar sokakları ve İtalyan tarzı meydanlarıyla büyüler. Kentin canlı kalbi olan geniş Piazza della Riforma, kafeleri ve neoklasik belediye binasıyla sosyal yaşamın merkezidir.' },
    { name: 'Gandria', desc: 'Lugano Gölü kıyısında, dağ yamacına asılı gibi duran bu şirin balıkçı köyü, arabaların giremediği dar sokakları ve göle inen basamaklarıyla otantik atmosferini korur. Tekneyle veya göl kıyısı yürüyüşüyle ulaşılan romantik bir kaçış noktasıdır.' },
  ],
  strasbourg: [
    { name: 'Notre-Dame Katedrali', desc: 'Pembe Vosges kumtaşından yapılmış bu görkemli gotik katedral, iki asır boyunca dünyanın en yüksek yapısıydı. İncelikli cephesi ve her öğle figürlerin harekete geçtiği devasa Rönesans astronomik saatiyle büyüler.' },
    { name: 'Petite France', desc: 'Strasbourg’un en pitoresk mahallesi olan bu bölge, bir zamanlar tabakçıların ve balıkçıların yaşadığı, kanal kıyısındaki çiçekli yarım ahşap evlerden oluşur. Su kanalları ve tarihî dokusuyla adeta bir masal diyarını andırır.' },
    { name: 'Barrage Vauban & Ponts Couverts', desc: 'Nehrin kollarını koruyan ortaçağ kuleli köprüleri (Ponts Couverts) ve 17. yüzyıl savunma barajı Vauban, kentin tarihî istihkâmlarındandır. Barajın panoramik terasından Petite France ve katedralin muhteşem manzarası izlenir.' },
    { name: 'Avrupa Parlamentosu', desc: 'Strasbourg, Fransa ile Almanya arasındaki barışın bir simgesi olarak Avrupa Parlamentosu’na ve diğer önemli Avrupa Birliği kurumlarına ev sahipliği yapar. Modern mimarili bu binalar, kentin uluslararası ve diplomatik kimliğini yansıtır.' },
    { name: 'Noel Pazarı', desc: 'Strasbourg’un “Christkindelsmärik” adlı Noel pazarı, 1570’ten beri sürdürülen Fransa’nın en eski ve en ünlü pazarıdır. Kenti bir ışık ve süs cümbüşüne çeviren bu gelenek, ona “Noel’in Başkenti” unvanını kazandırmıştır.' },
  ],
  colmar: [
    { name: 'La Petite Venise', desc: 'Colmar’ın en romantik bölgesi olan “Küçük Venedik”, Lauch Nehri boyunca sıralanan rengârenk yarım ahşap evleriyle büyüler. Kanallar üzerinde yapılan sandal turları, kasabanın masalsı atmosferini keşfetmenin en keyifli yoludur.' },
    { name: 'Maison Pfister', desc: '1537’de zengin bir şapkacı için inşa edilen bu ev, ahşap galerisi, çıkması ve resimli cephesiyle Colmar’daki Rönesans sivil mimarisinin en ünlü örneğidir. İncelikli detaylarıyla kentin geçmişteki zenginliğini yansıtır.' },
    { name: 'Unterlinden Müzesi', desc: 'Eski bir manastırda yer alan bu müze, dünyaca ünlü Grünewald’ın “Isenheim Sunağı”na ev sahipliği yapmasıyla meşhurdur. Yoğun duygusal gücüyle bilinen bu başyapıt, Alman Rönesans sanatının en etkileyici eserlerinden biridir.' },
    { name: 'Alsas Şarap Yolu', desc: 'Colmar, Fransa’nın en güzel köylerinden Riquewihr ve Eguisheim’i de içine alan ünlü Alsas Şarap Yolu’nun başkentidir. Üzüm bağlarıyla çevrili bu rota, çiçekli ortaçağ köyleri ve nefis beyaz şaraplarıyla büyüler.' },
  ],
  dijon: [
    { name: 'Dük Sarayı & Kule', desc: 'Bir zamanlar Avrupa’nın en güçlü hanedanlarından Burgonya düklerinin ikametgâhı olan bu görkemli saray, bugün bir güzel sanatlar müzesi barındırır. Philippe le Bon Kulesi’nin tepesinden şehrin panoraması izlenir.' },
    { name: 'Baykuş Rotası (Chouette)', desc: 'Dijon’un tarihî merkezini, kaldırıma yerleştirilmiş baykuş (chouette) işaretlerini takip ederek gezdiren bu rota, kentin başlıca yapılarını keşfettirir. Notre-Dame kilisesindeki, dokununca dilek tuttuğuna inanılan taş baykuş, şehrin uğurlu simgesidir.' },
    { name: 'Notre-Dame de Dijon', desc: '13. yüzyıldan kalma bu Burgonya gotik başyapıtı, cephesini süsleyen sıra sıra gargoyle heykelleri ve mekanik Jacquemart saatiyle dikkat çeker. Zarif mimarisi ve tarihî önemiyle kentin en sevilen kiliselerindendir.' },
    { name: 'Les Halles Pazarı', desc: 'Dijon’un bu tarihî kapalı pazarı, kentli hemşehrisi Gustave Eiffel tarafından tasarlanan zarif demir yapısıyla dikkat çeker. Burgonya’nın nefis peynirleri, şarapları ve dünyaca ünlü Dijon hardalını sunan tezgâhlarıyla bir gastronomi cennetidir.' },
  ],
  annecy: [
    { name: 'Palais de l’Isle', desc: 'Thiou Kanalı’nın ortasında bir gemi pruvası gibi yükselen bu üçgen yapı, 12. yüzyıldan beri saray, adliye ve hapishane olarak kullanılmıştır. Annecy’nin en çok fotoğraflanan simgesi olan bu tarihî bina, bugün bir müzedir.' },
    { name: 'Annecy Gölü & Pont des Amours', desc: 'Avrupa’nın en temiz göllerinden biri olan Annecy Gölü, turkuaz suları ve çevresini saran Alpler’le büyüler. Göle açılan “Aşıklar Köprüsü” (Pont des Amours), üzerinde öpüşen çiftlerin sonsuza dek birlikte olacağı efsanesiyle romantiktir.' },
    { name: 'Château d’Annecy', desc: 'Eski şehre tepeden bakan bu ortaçağ kalesi, bir zamanlar Cenova Kontları’nın ikametgâhıydı. Farklı yüzyıllara ait yapılardan oluşan kale, bugün bölgenin tarihini ve göl ekosistemini anlatan bir müzeye ev sahipliği yapar.' },
    { name: 'Vieille Ville Kanalları', desc: 'Annecy’nin “Alpler’in Venedik’i” olarak anılmasına neden olan eski şehri, kanallar, çiçeklerle bezeli köprüler ve pastel renkli arkadlı binalarla doludur. Bu pitoresk sokaklar, kentin en canlı ve büyüleyici bölümüdür.' },
  ],
  avignon: [
    { name: 'Papalık Sarayı', desc: '14. yüzyılda, papalığın Roma’dan Avignon’a taşındığı dönemde inşa edilen bu görkemli yapı, dünyanın en büyük gotik saraylarından biridir. Yedi papaya ev sahipliği yapan bu devasa kale-saray, dönemin dini gücünün bir simgesidir.' },
    { name: 'Pont Saint-Bénézet', desc: 'Halk arasında “Avignon Köprüsü” olarak bilinen bu yapı, Rhône Nehri’nin taşkınlarıyla yıkılıp bugün yarım kalmış haliyle ünlüdür. “Sur le pont d’Avignon” adlı dünyaca meşhur çocuk şarkısına konu olmasıyla efsaneleşmiştir.' },
    { name: 'Rocher des Doms', desc: 'Papalık Sarayı’nın yanındaki bu kayalık tepe bahçesi, Avignon’un kurulduğu ilk yerdir. Havuzları ve yeşillikleriyle huzurlu bir park olan bu teras, Rhône Nehri’nin ve ünlü köprünün en güzel manzarasını sunar.' },
    { name: 'Place de l’Horloge', desc: 'Avignon’un ana meydanı olan bu canlı alan, belediye binası ve 19. yüzyıldan kalma görkemli opera binasıyla çevrilidir. Çınar ağaçları altındaki kafeleri ve restoranlarıyla kentin sosyal yaşamının merkezidir.' },
  ],
  aix: [
    { name: 'Cours Mirabeau', desc: 'Aix-en-Provence’ın kalbi olan bu görkemli bulvar, gölge veren çınar ağaçları, tarihî çeşmeleri ve zarif konaklarıyla ünlüdür. Kafeleri ve canlı atmosferiyle kentin sosyal yaşamının merkezi ve en zarif gezinti alanıdır.' },
    { name: 'Cézanne Atölyesi', desc: 'Post-empresyonizmin öncüsü ünlü ressam Paul Cézanne’ın son yıllarını geçirdiği bu atölye, sanatçının bıraktığı gibi korunmuştur. Eşyaları ve doğal ışığıyla, dâhinin memleketi Aix’teki yaratıcı dünyasına bir pencere açar.' },
    { name: 'Saint-Sauveur Katedrali', desc: 'Bu ilginç katedral, Roman, gotik ve barok gibi farklı dönemlerin mimari üsluplarını tek bir yapıda birleştirmesiyle dikkat çeker. Antik bir Roma forumunun üzerine kurulan yapı, kentin katmanlı tarihini gözler önüne serer.' },
    { name: 'Provence Pazarları', desc: 'Aix, meydanlarını haftanın belirli günleri dolduran renkli ve kokulu geleneksel Provence pazarlarıyla ünlüdür. Taze çiçekler, lavanta, zeytin ve yerel lezzetler sunan bu tezgâhlar, Güney Fransa’nın canlı yaşam kültürünü yansıtır.' },
  ],

  // --- Orta Avrupa ara durakları ---
  brno: [
    { name: 'Špilberk Kalesi', desc: 'Brno’ya tepeden bakan bu görkemli kale, bir zamanlar Habsburg İmparatorluğu’nun en korkulan hapishanelerinden biriydi. Karanlık kazamatları ve tarihî surlarıyla bugün kentin panoramasını sunan bir müze ve kültür merkezidir.' },
    { name: 'Villa Tugendhat', desc: 'Mimar Mies van der Rohe’nin 1930’da tasarladığı bu villa, modernist mimarinin bir başyapıtı olarak UNESCO Dünya Mirası listesindedir. Açık planı, cam duvarları ve zarafetiyle işlevselci mimarinin öncü bir örneğidir.' },
    { name: 'Aziz Petrus ve Pavlus Katedrali', desc: 'Bir tepenin üzerinde yükselen zarif ikiz kuleleriyle bu gotik katedral, Brno’nun siluetine hâkimdir ve şehrin simgesidir. Kilise çanlarının, bir kuşatma efsanesi nedeniyle her gün öğle yerine saat 11’de çalması ilginç bir gelenektir.' },
    { name: 'Zelný trh & Yeraltı', desc: 'Adı “Lahana Pazarı” anlamına gelen bu tarihî meydan, sekiz yüzyıldır kesintisiz olarak taze ürün pazarına ev sahipliği yapar. Meydanın altında ise bir zamanlar mahzen ve sığınak olarak kullanılan geniş bir tarihî yeraltı geçit ağı uzanır.' },
  ],
  ceskykrumlov: [
    { name: 'Český Krumlov Kalesi', desc: 'Prag Kalesi’nden sonra Çekya’nın en büyük kale kompleksi olan bu yapı, 13. yüzyıldan kalma ve dünyada nadir ayakta kalan orijinal barok tiyatrosuyla ünlüdür. Devasa boyutu ve mimari zenginliğiyle kasabaya hâkimdir.' },
    { name: 'Kale Kulesi', desc: 'Kalenin rengârenk resimlerle süslü bu silindirik kulesi, kasabanın en tanınan simgesidir. Tepesindeki gözlem galerisinden, Vltava Nehri’nin sardığı eski şehrin kızıl çatılarının nefes kesen panoraması izlenir.' },
    { name: 'Eski Şehir Kıvrımı', desc: 'Vltava Nehri’nin bir at nalı gibi çevrelediği bu eski şehir, dar arnavut kaldırımlı sokakları ve Rönesans-barok binalarıyla adeta bir açık hava müzesidir. Bu olağanüstü korunmuş ortaçağ dokusu, UNESCO Dünya Mirası listesindedir.' },
    { name: 'Vltava Kano/Sal Turu', desc: 'Kasabayı çevreleyen Vltava Nehri, sakin akıntısıyla kano veya sal turları için idealdir. Suyun üzerinden yapılan bu keyifli yolculuk, kaleyi, köprüleri ve tarihî evleri bambaşka ve unutulmaz bir açıdan görme fırsatı sunar.' },
  ],
  melk: [
    { name: 'Melk Manastırı', desc: 'Tuna’ya bakan bir kaya çıkıntısında yükselen bu görkemli sarı Barok Benedikten manastırı, Avusturya’nın en büyük dini yapılarından biridir. Freskli tavanlı gösterişli kilisesi ve 100.000’den fazla cilt barındıran ihtişamlı kütüphanesiyle Umberto Eco’ya ilham vermiştir.' },
    { name: 'Wachau Vadisi', desc: 'Melk ile Krems arasında Tuna boyunca uzanan bu UNESCO korumalı vadi, teraslı üzüm bağları, kayısı bahçeleri ve ortaçağ köyleriyle bir açık hava müzesi gibidir. Ünlü beyaz şarapları ve pastoral manzarasıyla Avusturya’nın en romantik bölgelerindendir.' },
    { name: 'Dürnstein', desc: 'Mavi-beyaz kulesiyle Tuna kıyısında öne çıkan bu şirin kasaba, İngiltere Kralı Aslan Yürekli Richard’ın Haçlı Seferi dönüşü esir tutulduğu kale harabesiyle ünlüdür. Dar taş sokakları ve şarap bağları arasındaki yürüyüş rotalarıyla Wachau’nun incisidir.' },
    { name: 'Tuna Nehir Turu', desc: 'Melk ile Krems arasında Wachau Vadisi boyunca yapılan vapur gezisi, vadinin bağlarını, manastırlarını ve kalelerini nehirden izlemenin en keyifli yoludur. Yavaş akan Tuna üzerindeki bu yolculuk, bölgenin eşsiz manzarasını bir panorama gibi sunar.' },
  ],
  gyor: [
    { name: 'Barok Eski Şehir', desc: 'Üç nehrin buluştuğu Győr, Macaristan’ın en güzel barok kent merkezlerinden birine sahiptir. Cumbalı (köşe balkonlu) tarihî evleri, gizli avluları ve zarif meydanlarıyla “Nehirlerin Şehri” keşfedilmeyi bekleyen romantik bir atmosfer sunar.' },
    { name: 'Bazilika & Herm', desc: 'Kentin en eski bölümündeki bu bazilika, Macar Kralı Aziz László’nun altından yapılmış görkemli büstünü (herm) barındırmasıyla ünlüdür. Ortaçağ kuyumculuğunun bir başyapıtı olan bu röliker, önemli bir hac objesidir.' },
    { name: 'Püspökvár (Piskopos Kalesi)', desc: 'Rába Nehri’ne bakan bu tarihî kale, yüzyıllardır Győr piskoposlarının ikametgâhı olmuştur. Ortaçağ kulesi ve savunma yapılarıyla kentin en eski ve en önemli tarihî anıtlarından biridir.' },
    { name: 'Rába Termal', desc: 'Győr yakınlarındaki bu modern termal ve macera parkı, bölgenin yer altındaki zengin şifalı su kaynaklarından beslenir. Kapalı ve açık havuzları, kaydırakları ve sağlık merkeziyle dört mevsim popüler bir dinlenme noktasıdır.' },
  ],
  eger: [
    { name: 'Eger Kalesi', desc: 'Bu kale, 1552’de az sayıda Macar savunucunun çok daha kalabalık Osmanlı ordusuna karşı verdiği efsanevi direnişle Macar ulusal tarihinde önemli bir yere sahiptir. Bu kahramanlık öyküsü, bugün kaledeki müzede ve edebiyatta yaşatılır.' },
    { name: 'Minare', desc: '17. yüzyıldaki Osmanlı hâkimiyetinden kalan bu 40 metrelik zarif minare, Avrupa’da ayakta kalan en kuzeydeki Osmanlı minaresidir. Camisi yıkılmış olsa da 97 basamaklı dar merdiveniyle bu narin yapı, kentin çok kültürlü geçmişine tanıklık eder.' },
    { name: 'Güzel Kadınlar Vadisi', desc: 'Eger’in ünlü bu vadisi, kayalara oyulmuş onlarca şarap mahzeninin bir arada bulunduğu eşsiz bir tadım merkezidir. Bölgenin dünyaca ünlü kırmızı şarabı “Egri Bikavér” (Boğa Kanı), burada doğrudan üreticilerden tadılabilir.' },
    { name: 'Bazilika & Barok Merkez', desc: 'Eger, Macaristan’ın en görkemli barok kentlerinden biri olup ülkenin ikinci büyük kilisesi olan neoklasik bazilikasıyla taçlanır. Zarif meydanları, saraylar ve renkli binalarıyla kent merkezi, bir mimari zarafet sergiler.' },
  ],
  pecs: [
    { name: 'Erken Hristiyan Nekropolü', desc: 'Kentin antik Roma adı Sopianae döneminden kalan bu yeraltı mezar odaları, 4. yüzyıla ait olağanüstü erken Hristiyan freskleriyle bezelidir. Hem mezar hem şapel işlevi gören bu benzersiz yapılar, UNESCO Dünya Mirası listesindedir.' },
    { name: 'Gazi Kasım Paşa Camii', desc: 'Pécs’in ana meydanına hâkim olan bu kubbeli yapı, Osmanlı döneminden kalan ve sonradan kiliseye dönüştürülen bir camidir. Macaristan’daki en büyük ayakta duran Türk yapısı olarak, hem hilal hem haç taşıyan tepesiyle şehrin çok kültürlü simgesidir.' },
    { name: 'Zsolnay Mahallesi', desc: 'Pécs, dünyaca ünlü ve benzersiz parlaklıktaki (eozin) seramikleriyle tanınan Zsolnay porselen fabrikasının memleketidir. Eski fabrika alanından dönüştürülen bu kültür mahallesi, müzeleri ve atölyeleriyle bu görkemli çini geleneğini kutlar.' },
    { name: 'Katedral & Barbakan', desc: 'Dört köşe kulesiyle Pécs’in siluetine hâkim olan bu görkemli katedralin kökeni 11. yüzyıla uzanır. Yakınındaki dairesel Barbakan topu ise kentin ayakta kalan en önemli ortaçağ savunma yapısıdır.' },
  ],
  szentendre: [
    { name: 'Fő tér (Ana Meydan)', desc: 'Szentendre’nin bu şirin ana meydanı, rengârenk barok tüccar evleri ve ortasındaki tarihî veba haçıyla kasabanın kalbidir. Kafeleri, dükkânları ve canlı atmosferiyle bu sanatçı kasabasının en çok fotoğraflanan noktasıdır.' },
    { name: 'Belgrád Katedrali', desc: 'Kasabaya yüzyıllar önce yerleşen Sırp topluluğunun mirası olan bu görkemli Ortodoks katedrali, zengin ikonostasisi ve barok mimarisiyle dikkat çeker. Szentendre’nin çok kültürlü ve dini açıdan hoşgörülü geçmişini yansıtır.' },
    { name: 'Sanat Galerileri', desc: 'Uzun süredir bir sanatçı kolonisine ev sahipliği yapan Szentendre, dar sokakları boyunca sıralanan çok sayıda galeri, atölye ve müzeyle doludur. Ünlü Marzipan Müzesi de dahil olmak üzere bu mekânlar, kasabaya yaratıcı bir ruh katar.' },
    { name: 'Skanzen (Açık Hava Müzesi)', desc: 'Kasabanın hemen dışındaki Macaristan Açık Hava Etnografya Müzesi, ülkenin farklı bölgelerinden getirilen özgün köy evlerini, kiliseleri ve değirmenleri sergiler. Geleneksel Macar kırsal yaşamını canlandıran geniş bir zaman yolculuğu sunar.' },
  ],
  balaton: [
    { name: 'Tihany Manastırı', desc: 'Balaton Gölü’ne uzanan bir yarımadadaki bu görkemli barok manastır, ikiz kuleleriyle bölgenin simgesidir. 1055 tarihli kuruluş belgesi, en eski Macarca kelimeleri içermesiyle dilbilimsel açıdan paha biçilmez bir hazinedir.' },
    { name: 'Balatonfüred', desc: 'Balaton Gölü’nün en eski ve en zarif tatil kasabası olan Balatonfüred, tarihî sahil promenadı, marinaları ve şifalı su kaynaklarıyla ünlüdür. Bir zamanlar aristokratların ve sanatçıların uğrağı olan bu kasaba, gölün kültürel merkezidir.' },
    { name: 'Badacsony Bağları', desc: 'Balaton Gölü kıyısındaki sönmüş bir volkanın yamaçlarına kurulu Badacsony, bazalt toprağının verdiği karakteristik beyaz şaraplarıyla ünlüdür. Bağların arasındaki tadım evlerinden göl manzarası eşliğinde şarap tadımı yapılır.' },
    { name: 'Göl Plajları', desc: 'Orta Avrupa’nın en büyük gölü olan Balaton, sığ ve yaz aylarında ılıyan sularıyla “Macar Denizi” olarak anılır. Güvenli plajları, yelken ve yüzme imkânlarıyla ailelerin ve tatilcilerin gözde bir su sporları merkezidir.' },
  ],
  kosice: [
    { name: 'Aziz Elizabeth Katedrali', desc: 'Slovakya’nın en büyük kilisesi olan bu görkemli gotik katedral, aynı zamanda dünyanın en doğudaki gotik katedralidir. İncelikli mimarisi, altın sunağı ve kraliyet lahitleriyle Košice’nin en değerli tarihî anıtıdır.' },
    { name: 'Hlavná (Ana Cadde)', desc: 'Kentin kalbindeki bu geniş ve zarif ana cadde, tarihî saraylar, kiliseler ve pastel renkli binalarla çevrilidir. Ortasındaki müzikli “şarkı söyleyen çeşme” ve kafeleriyle Košice’nin sosyal yaşamının canlı merkezidir.' },
    { name: 'Urban Kulesi & Tiyatro', desc: 'Katedralin yanındaki bağımsız Urban Kulesi, tarihî bir çan kulesi olup bugün bir müze işlevi görür. Ana caddedeki görkemli neobarok Devlet Tiyatrosu ise kentin zengin sanat ve kültür yaşamının simgesidir.' },
    { name: 'Miklós Hapishanesi', desc: 'Kökeni ortaçağa uzanan bu tarihî bina, yüzyıllar boyunca hapishane ve cellat evi olarak kullanılmıştır. Bugün, hücreleri ve işkence aletlerinin sergilendiği bir şehir müzesi olarak Košice’nin karanlık geçmişine ışık tutar.' },
  ],

  // --- Yunanistan & Balkan ara durakları ---
  meteora: [
    { name: 'Büyük Meteoron Manastırı', desc: 'Göğe yükselen devasa kaya sütunlarının tepesine kurulan Meteora manastırlarının en büyüğü ve en eskisi olan bu yapı, 14. yüzyılda inşa edilmiştir. Bir zamanlar sadece iplerle ulaşılabilen manastır, bugün müzesi ve fresklerle büyüler.' },
    { name: 'Varlaam Manastırı', desc: 'Meteora’nın en etkileyici manastırlarından olan Varlaam, olağanüstü Bizans freskleri ve keşişlerin erzak ile insanları yukarı çektiği tarihî ağ-kule sistemiyle ünlüdür. Bu benzersiz konumuyla dünyadan el etek çekmenin bir sembolüdür.' },
    { name: 'Roussanou & Aziz Nikolaos', desc: 'Kaya sütunlarına adeta yapışmış gibi duran bu daha küçük manastırlar, ulaşılması güç konumları ve zarif mimarileriyle büyüler. Roussanou bugün bir kadın manastırı olup her ikisi de değerli dini fresklerini korur.' },
    { name: 'Gün Batımı Bakı Noktaları', desc: 'Meteora’nın dev kaya oluşumları ve tepelerindeki manastırlar, özellikle gün batımında altın bir ışığa bürünerek büyüleyici bir manzara sunar. Çeşitli bakış terasları, bu doğaüstü coğrafyayı fotoğraflamak için idealdir.' },
    { name: 'Kalambaka Kaya Kilisesi', desc: 'Meteora’nın eteğindeki Kalambaka kasabasında yer alan bu tarihî Meryem Ana kilisesi, kökeni erken Bizans dönemine uzanır. İçini kaplayan değerli fresklerle bölgenin köklü dini geçmişine tanıklık eder.' },
  ],
  delphi: [
    { name: 'Apollon Tapınağı', desc: 'Antik Yunanlıların dünyanın merkezi (omphalos) saydığı bu kutsal alan, geleceği bildiren ünlü Delphi kâhini Pythia’ya ev sahipliği yapıyordu. Krallar ve devletler önemli kararlar için bu tapınaktaki kehanetlere başvururdu.' },
    { name: 'Antik Tiyatro & Stadyum', desc: 'Parnassos Dağı’nın yamacındaki bu antik tiyatro, tapınağa ve vadiye hâkim muhteşem manzarasıyla büyüler. Daha yukarıdaki stadyum ise Olimpiyatlar’a öncülük eden Pythia Oyunları’na ev sahipliği yapan iyi korunmuş bir yapıdır.' },
    { name: 'Delphi Müzesi', desc: 'Bu müze, antik dünyanın en iyi korunmuş bronz heykellerinden biri olan ünlü “Delphi Arabacısı”nı barındırmasıyla meşhurdur. Kutsal alandan çıkarılan adak heykelleri ve hazinelerle Delphi’nin dini önemini gözler önüne serer.' },
    { name: 'Tholos (Athena Pronaia)', desc: 'Athena’ya adanan kutsal alandaki bu dairesel tapınak, zarif sütunları ve mükemmel oranlarıyla Delphi’nin en ikonik ve en çok fotoğraflanan yapısıdır. İşlevi tam bilinmese de antik Yunan mimarisinin bir başyapıtıdır.' },
  ],
  nafplio: [
    { name: 'Palamidi Kalesi', desc: 'Şehrin üzerindeki bir tepeye kurulan bu görkemli Venedik kalesi, mühendislik harikası istihkâmlarıyla ünlüdür. Efsaneye göre 999 basamakla çıkılan kalenin zirvesinden, Nafplio’nun ve Argolik Körfezi’nin nefes kesen panoraması izlenir.' },
    { name: 'Bourtzi', desc: 'Nafplio limanının ağzındaki küçük bir adacık üzerine kurulu bu zarif Venedik kalesi, kenti deniz saldırılarından korumak için inşa edilmiştir. Suyun ortasındaki bu masalsı yapı, şehrin en tanınan ve en romantik simgesidir.' },
    { name: 'Eski Şehir & Syntagma', desc: 'Yunanistan’ın ilk başkenti olan Nafplio’nun eski şehri, neoklasik konakları, begonvillerle bezeli dar sokakları ve zarif meydanlarıyla büyüler. Mermer döşeli Syntagma Meydanı, Venedik ve Osmanlı yapılarıyla çevrili tarihî kalbidir.' },
    { name: 'Akronafplia & Arvanitia', desc: 'Kentin en eski kalesi olan Akronafplia’nın surları boyunca yapılan yürüyüş, deniz ve şehir manzarası sunar. Bu yürüyüşün sonundaki Arvanitia, berrak sularıyla kentin en gözde kayalık deniz noktasıdır.' },
  ],
  ioannina: [
    { name: 'Ioannina Kalesi (Kastro)', desc: 'Pamvotida Gölü kıyısındaki bu tarihî kale, özellikle 19. yüzyılda bölgeyi yarı bağımsız yöneten güçlü Tepedelenli Ali Paşa dönemine damgasını vurmuştur. Surları içindeki Fethiye Camii ve müzeleriyle kentin Osmanlı geçmişini yaşatır.' },
    { name: 'Göl Adası (Nisi)', desc: 'Ioannina (Yanya) Gölü’nün ortasındaki bu şirin adaya tekneyle ulaşılır ve tarihî Bizans manastırlarını barındırır. Ünlü Tepedelenli Ali Paşa’nın öldürüldüğü manastır, bugün bu dramatik olayı anlatan bir müzedir.' },
    { name: 'Perama Mağarası', desc: 'Ioannina yakınlarındaki bu mağara, Yunanistan’ın en büyük ve en görkemli mağaralarından biridir. Milyonlarca yılda oluşan rengârenk ve çeşitli sarkıt-dikit formasyonlarıyla büyüleyici bir yeraltı dünyası sunar.' },
    { name: 'Gümüş İşçiliği Müzesi', desc: 'Yanya, yüzyıllardır süregelen ustalıklı gümüş işçiliği (telkâri) geleneğiyle ünlüdür. Kale içindeki bu müze, bölgenin bu köklü zanaatını, tarihî ve modern eserler sergileyerek gelecek nesillere aktarır.' },
  ],
  bitola: [
    { name: 'Şirok Sokak', desc: 'Bitola’nın “konsoloslar şehri” olarak anıldığı 19. yüzyılda pek çok Avrupa ülkesinin konsolosluğuna ev sahipliği yapan bu zarif yaya caddesi, neoklasik ve barok cepheli binalarıyla kentin en canlı damarıdır. Kafeleri ve tarihî mimarisiyle şehrin kozmopolit geçmişini yaşatır.' },
    { name: 'Heraklea Lynkestis', desc: 'MÖ 4. yüzyılda Makedonya Kralı II. Filip tarafından kurulan bu antik kent, Roma ve erken Bizans dönemlerinde önemli bir merkez olmuştur. Olağanüstü korunmuş renkli taban mozaikleri, antik tiyatrosu ve bazilikalarıyla bölgenin en değerli arkeolojik alanlarından biridir.' },
    { name: 'Saat Kulesi & Eski Çarşı', desc: '16. yüzyıla uzanan köklü Osmanlı çarşısı ve şehrin simgesi 30 metrelik Saat Kulesi, Bitola’nın yüzyıllar boyu bir ticaret merkezi olduğunu gösterir. Bezisten (kapalı çarşı) ve çevresindeki dükkânlar hâlâ geleneksel el sanatlarını ve pazar kültürünü sürdürür.' },
    { name: 'Pelister Milli Parkı', desc: 'Kuzey Makedonya’nın en eski milli parkı olan Pelister, buzul çağından kalma “Dağ Gözleri” adlı berrak göller ve endemik Molika çamı ormanlarıyla ünlüdür. Bitola’ya yakınlığıyla yürüyüş ve doğa tutkunları için eşsiz bir kaçış noktasıdır.' },
  ],
  trebinje: [
    { name: 'Arslanagić (Perović) Köprüsü', desc: '17. yüzyılda Osmanlı döneminde Trebišnjica Nehri üzerine inşa edilen bu zarif köprü, kendine özgü asimetrik kemerleriyle dikkat çeker. Bir baraj yapımı nedeniyle taş taş sökülüp bugünkü yerine taşınan köprü, kentin simgelerindendir.' },
    { name: 'Eski Şehir (Kastel)', desc: 'Trebišnjica Nehri kıyısındaki bu surlarla çevrili tarihî çekirdek, Osmanlı döneminden kalma dar sokakları, çınarlı meydanı ve camisiyle otantik bir atmosfer sunar. Kafeleri ve dükkânlarıyla kentin canlı kalbini oluşturur.' },
    { name: 'Hercegovačka Gračanica', desc: 'Bir tepenin üzerine kurulu bu görkemli Sırp Ortodoks manastırı, ünlü Kosova’daki Gračanica Manastırı’nın bir kopyasıdır. Şaire Jovan Dučić’in mezarını barındıran manastır, Trebinje ve çevresinin nefes kesen panoramasını sunar.' },
    { name: 'Şarap Mahzenleri', desc: 'Trebinje, güneşli iklimi ve bereketli topraklarıyla Hersek bölgesinin köklü şarap üretim merkezlerinden biridir. Çevredeki bağlar ve mahzenler, yerel Žilavka ve Vranac üzümlerinden yapılan şarapların tadımı için idealdir.' },
  ],
  ston: [
    { name: 'Ston Surları', desc: '14. yüzyılda Dubrovnik Cumhuriyeti’nin değerli tuzlalarını korumak için inşa edilen bu 5 kilometrelik savunma hattı, “Avrupa’nın Çin Seddi” olarak anılır. Tepeler boyunca yürünebilen surlar, çevresindeki tuz tarlaları ve körfez manzarasıyla eşsiz bir tarih yürüyüşü sunar.' },
    { name: 'Tuzlalar', desc: 'Ston’un varlığının kaynağı olan bu tuzlalar, güneş ve rüzgârla çalışan geleneksel yöntemlerle Avrupa’nın en eski faal tuz üretim tesisleri arasındadır. “Beyaz altın” denen bu tuz, bir zamanlar Dubrovnik Cumhuriyeti’ne büyük zenginlik kazandırmıştır.' },
    { name: 'Mali Ston & İstiridye', desc: 'Ston’un kardeş kasabası Mali Ston’un körfezi, Romalılar döneminden beri övülen dünyaca ünlü istiridyeleriyle tanınır. Tatlı ve tuzlu suyun buluştuğu bu berrak sularda taze toplanan istiridye ve midyeler, bölgeyi bir gastronomi durağına dönüştürür.' },
    { name: 'Pelješac Bağ Yolu', desc: 'Ston’dan uzanan Pelješac Yarımadası, güçlü Dingač ve Postup kırmızı şaraplarına kaynaklık eden dik ve güneşli bağlarıyla Hırvatistan’ın en ünlü şarap bölgelerinden biridir. Bağlar arasından geçen yol, tadım duraklarıyla Adriyatik manzarasını birleştirir.' },
  ],

  // --- İskandinavya: Norveç ---
  oslo: [
    { name: 'Opera Binası', desc: 'Oslo Fiyordu’ndan yükselen bir buzul gibi tasarlanan bu çarpıcı beyaz mermer ve cam yapı, ziyaretçilerin çatısına kadar yürüyebildiği eşsiz bir mimariye sahiptir. Norveç Operası’na ev sahipliği yapan bu bina, modern Oslo’nun simgesidir.' },
    { name: 'Vigeland Heykel Parkı', desc: 'Heykeltıraş Gustav Vigeland’ın hayatını adadığı bu park, insanın doğumdan ölüme yaşam döngüsünü betimleyen 200’den fazla bronz ve granit figürü barındırır. Ortasındaki insan bedenlerinden oluşan “Monolit” sütunu, dünyanın en büyük heykel parklarından birinin doruğudur.' },
    { name: 'Viking Gemisi & Fram Müzeleri', desc: 'Bygdøy Yarımadası’ndaki bu müzeler, Norveç’in denizcilik ruhunu kutlar. Olağanüstü korunmuş orijinal Viking gemileri ve kutup kâşiflerinin kullandığı efsanevi Fram gemisiyle, ülkenin keşif ve macera dolu geçmişini gözler önüne serer.' },
    { name: 'Munch Müzesi', desc: 'Norveç’in en ünlü ressamı Edvard Munch’a adanan bu modern müze, sanatçının başyapıtı ve dünyanın en tanınan resimlerinden “Çığlık”ın versiyonlarını barındırır. Munch’un tüm eserlerinin en kapsamlı koleksiyonuna ev sahipliği yapar.' },
    { name: 'Holmenkollen', desc: 'Oslo’ya tepeden bakan bu ünlü kayakla atlama kulesi, dünyanın en eski kayak yarışmalarına ev sahipliği yapar ve bir kayak müzesi barındırır. Modern ve göz alıcı yapısının tepesinden şehrin ve fiyordun panoraması izlenir.' },
  ],
  bergen: [
    { name: 'Bryggen', desc: 'Bergen’in tarihî limanındaki bu rengârenk ahşap binalar sırası, kentin bir zamanlar güçlü Hansa Birliği’nin önemli bir ticaret merkezi olduğu döneme tanıklık eder. Yangınlara rağmen özgün stilinde yeniden inşa edilen bu rıhtım, UNESCO Dünya Mirası listesindedir.' },
    { name: 'Fløibanen & Fløyen', desc: 'Bergen’i çevreleyen yedi dağdan biri olan Fløyen’in tepesine çıkan bu popüler füniküler, kısa sürede ferahlatıcı bir doğaya ulaştırır. Zirveden, kentin, limanının ve çevredeki adaların nefes kesen panoraması izlenir.' },
    { name: 'Balık Hali (Fisketorget)', desc: 'Bergen limanındaki bu tarihî açık hava balık pazarı, yüzyıllardır kentin sosyal ve ticari yaşamının merkezi olmuştur. Taze deniz ürünleri, yerel lezzetler ve canlı atmosferiyle şehrin denizle olan güçlü bağını yansıtır.' },
    { name: 'Ulriken Teleferiği', desc: 'Bergen’i çevreleyen dağların en yükseği olan Ulriken’e çıkan bu teleferik, hızlı bir tırmanışla 643 metre yüksekliğe ulaştırır. Zirvedeki restoran ve yürüyüş rotaları, şehrin ve fiyortların en geniş manzarasını sunar.' },
    { name: 'Fiyort Turları', desc: 'Norveç’in “Fiyortlara Açılan Kapısı” olarak anılan Bergen, ünlü doğa harikalarına yapılan tekne turları için ideal bir başlangıç noktasıdır. Buradan, UNESCO korumasındaki dar Nærøyfjord veya görkemli Hardangerfjord’a doğru büyüleyici yolculuklar yapılır.' },
  ],
  tromso: [
    { name: 'Kuzey Işıkları Turu', desc: 'Kutup Dairesi’nin çok kuzeyinde yer alan Tromsø, kış aylarında gökyüzünü saran büyülü Kuzey Işıkları’nı (aurora borealis) izlemek için dünyanın en iyi noktalarından biridir. Rehberli turlar, ışık avı için karanlık gökyüzü noktalarına götürür.' },
    { name: 'Arktik Katedrali', desc: 'Bir buzdağının veya kar örtüsünün formundan ilham alan bu çarpıcı beyaz modern kilise, Tromsø’nun mimari simgesidir. Dev vitray penceresi ve zarif üçgen yapısıyla, Arktik doğanın soğuk güzelliğini yansıtır.' },
    { name: 'Fjellheisen Teleferiği', desc: 'Tromsø kentinin karşısındaki Storsteinen dağına çıkan bu teleferik, birkaç dakikada nefes kesen bir bakış noktasına ulaştırır. Zirveden, adalara yayılmış şehrin, fiyortların ve dağların 360 derecelik manzarası izlenir.' },
    { name: 'Polaria & Kutup Müzesi', desc: 'Devrilmiş buz kütlelerini andıran mimarisiyle Polaria, Arktik doğayı ve yaban hayatını tanıtan bir deneyim merkezidir. Yakınındaki Kutup Müzesi ise Norveç’in cesur kutup kâşiflerinin ve avcılarının maceralı tarihini anlatır.' },
    { name: 'Gece Yarısı Güneşi', desc: 'Yaz aylarında, Tromsø’da güneşin haftalarca hiç batmadığı “Gece Yarısı Güneşi” fenomeni yaşanır. Bu benzersiz doğa olayı, gün boyu süren ışıkta yürüyüş, tekne turu ve diğer aktiviteler için eşsiz bir fırsat sunar.' },
  ],
  stavanger: [
    { name: 'Preikestolen', desc: 'Lysefjord’un 604 metre yukarısında yükselen bu dümdüz kaya platosu (“Vaiz Kürsüsü”), Norveç’in en ünlü doğa harikalarından biridir. Zorlu bir yürüyüşle ulaşılan bu uçurumun kenarı, fiyordun ve dağların baş döndürücü panoramasını sunar.' },
    { name: 'Gamle Stavanger', desc: '“Eski Stavanger”, 18.–19. yüzyıllardan kalma 170’ten fazla beyaz ahşap evin bulunduğu, Kuzey Avrupa’nın en iyi korunmuş ahşap yerleşimlerindendir. Dar arnavut kaldırımlı sokakları ve çiçekli avlularıyla nostaljik bir atmosfer sunar.' },
    { name: 'Lysefjord Turu', desc: 'Adı “Işık Fiyordu” anlamına gelen Lysefjord, dik granit duvarları ve Preikestolen ile Kjerag gibi ünlü kaya oluşumlarıyla büyüler. Tekneyle yapılan turlar, bu görkemli doğa harikasını su seviyesinden deneyimleme fırsatı sunar.' },
    { name: 'Petrol Müzesi', desc: 'Norveç ekonomisini kökten değiştiren Kuzey Denizi petrolünün keşfini ve teknolojisini anlatan bu interaktif müze, Stavanger’ın “petrol başkenti” kimliğini yansıtır. Gerçek ekipmanlar ve modelleriyle petrol endüstrisinin dünyasını tanıtır.' },
  ],
  alesund: [
    { name: 'Aksla Tepesi (Fjellstua)', desc: 'Kentin hemen üzerindeki bu bakış noktasına, şehir parkından geçen 418 basamaklı bir merdivenle çıkılır. Zirveden, Ålesund’un art nouveau mimarisinin, çevredeki adaların ve Sunnmøre Alpleri’nin nefes kesen panoraması izlenir.' },
    { name: 'Jugendstil Merkezi', desc: 'Ålesund, 1904’teki büyük bir yangının ardından tamamen o dönemin popüler art nouveau (Jugendstil) tarzında yeniden inşa edilmiştir. Bu merkez, kenti benzersiz bir mimari mücevhere dönüştüren bu üslubun tarihini ve zarafetini anlatır.' },
    { name: 'Atlantik Deniz Parkı', desc: 'Açık okyanus kıyısındaki bu kurum, İskandinavya’nın en büyük deniz akvaryumlarından biridir. Kuzey Atlantik’in zengin yaban hayatını doğal ortamlarına benzer devasa tanklarda sergileyerek denizin altındaki dünyayı ziyaretçilere tanıtır.' },
    { name: 'Geiranger Kapısı', desc: 'Ålesund, bir liman kenti olarak Norveç’in en ünlü doğa harikalarından biri olan UNESCO korumasındaki Geirangerfjord’a açılan önemli bir kapıdır. Buradan kalkan tekne turları, görkemli fiyort manzaralarına doğru yolculuklar sunar.' },
  ],
  geiranger: [
    { name: 'Yedi Kızkardeş Şelalesi', desc: 'Geirangerfjord’un dik duvarlarından yan yana dökülen yedi ayrı su koluyla oluşan bu ünlü şelale, adını da bu yapısından alır. Karşısındaki “Talip” adlı şelaleyle ilgili anlatılan folklorik hikâyesiyle fiyordun en büyüleyici doğa harikasıdır.' },
    { name: 'Dalsnibba Bakı Terası', desc: 'Deniz seviyesinden 1.500 metre yükseklikteki bu dağ platosu, Geirangerfjord’un ve çevresindeki karlı zirvelerin kuşbakışı manzarasını sunan Norveç’in en yüksek fiyort bakış noktasıdır. Manzara terasından tüm vadi ayaklar altına serilir.' },
    { name: 'Fiyort Tekne Turu', desc: 'UNESCO korumasındaki Geirangerfjord’da yapılan tekne turu, dik kayalıklara asılı terk edilmiş çiftlikleri ve görkemli şelaleleri yakından görme fırsatı sunar. Bu dar ve dramatik fiyort boyunca seyahat, unutulmaz bir doğa deneyimidir.' },
    { name: 'Ørnevegen (Kartal Yolu)', desc: 'Adı “Kartal Yolu” anlamına gelen bu ünlü dağ yolu, on bir keskin serpantin virajıyla dik yamacı tırmanır. Yolun tepesindeki bakış noktasından, Geiranger köyünün ve fiyordun kartal bakışı bir manzarası izlenir.' },
  ],
  lofoten: [
    { name: 'Reine & Hamnøy', desc: 'Lofoten Adaları’nın bu iki köyü, denizden dimdik yükselen sivri granit dağların eteğindeki kırmızı balıkçı kulübeleriyle dünyanın en fotojenik yerlerinden biridir. Bu dramatik doğa ve mütevazı yaşamın birleşimi, büyüleyici bir manzara oluşturur.' },
    { name: 'Rorbu Konaklama', desc: 'Bir zamanlar mevsimlik balıkçıların kaldığı geleneksel kırmızı ahşap kulübeler olan “rorbu”lar, bugün Lofoten’in en özgün konaklama deneyimini sunar. Genellikle su üzerinde kazıklar üstünde duran bu kulübeler, otantik bir Arktik atmosferi yaşatır.' },
    { name: 'Haukland & Kvalvika Plajları', desc: 'Kutup Dairesi’nin kuzeyinde olmasına rağmen Lofoten, bu iki plajın ince beyaz kumu ve şaşırtıcı turkuaz sularıyla tropik bir görünüm sunar. Karlı dağlarla çevrili bu Arktik kumsallar, doğanın eşsiz bir kontrastıdır.' },
    { name: 'Kuzey Işıkları / Gece Güneşi', desc: 'Lofoten Adaları, coğrafi konumu sayesinde iki büyülü doğa olayına ev sahipliği yapar. Kışın gökyüzünü saran Kuzey Işıkları ve yazın haftalarca hiç batmayan Gece Yarısı Güneşi, adalara mevsime göre değişen büyüleyici bir atmosfer katar.' },
  ],
  // --- İskandinavya: İsveç ---
  stockholm: [
    { name: 'Gamla Stan', desc: 'Stockholm’ün kendi üzerinde kurulduğu bu ortaçağ ada şehri, Avrupa’nın en iyi korunmuş eski kent merkezlerinden biridir. Dar arnavut kaldırımlı sokakları, oker rengi binaları ve tarihî meydanlarıyla İsveç’in kalbini yansıtır.' },
    { name: 'Vasa Müzesi', desc: 'Bu müze, 1628’de ilk seferinde batan ve 333 yıl sonra neredeyse eksiksiz olarak çıkarılan görkemli savaş gemisi Vasa’yı sergiler. Dünyanın ayakta kalan tek 17. yüzyıl gemisi olan bu eser, mühendislik hırsının bir anıtıdır.' },
    { name: 'Kraliyet Sarayı', desc: 'İsveç hükümdarının resmi ikametgâhı olan bu görkemli barok saray, 600’den fazla odasıyla dünyanın en büyük saraylarından biridir. Kraliyet dairelerini, hazineyi ve her gün yapılan görkemli nöbet değişimi törenini barındırır.' },
    { name: 'Skansen & Djurgården', desc: 'Yeşil Djurgården adasındaki Skansen, dünyanın en eski açık hava müzesidir ve İsveç’in dört bir yanından getirilen tarihî evleri canlandırır. Ada, müzeleri ve parklarıyla Stockholm’ün en sevilen kültür ve dinlenme merkezidir.' },
    { name: 'Belediye Sarayı (Stadshuset)', desc: 'Zarif kulesi ve kızıl tuğlalarıyla Stockholm siluetine hâkim olan bu görkemli yapı, her yıl Nobel Ödülü Töreni’nin ardından verilen görkemli baloya ev sahipliği yapmasıyla ünlüdür. Altın Salonu ve mimarisiyle büyüler.' },
  ],
  goteborg: [
    { name: 'Haga Semti', desc: 'Göteborg’un en eski işçi mahallelerinden biri olan Haga, restore edilmiş 19. yüzyıl ahşap binaları ve arnavut kaldırımlı sokaklarıyla büyüler. Kafeleri ve özellikle dev boyutlu tarçınlı çörekleriyle (kanelbulle) ünlü, sevilen bir semttir.' },
    { name: 'Liseberg', desc: 'İskandinavya’nın en büyük ve en popüler eğlence parkı olan Liseberg, hız trenleri, oyunları ve bahçeleriyle her yaştan ziyaretçiyi ağırlar. Özellikle Noel döneminde bir ışık cümbüşüne dönüşerek kentin en canlı cazibe merkezi olur.' },
    { name: 'Kanal & Paddan Turu', desc: 'Göteborg’un 17. yüzyılda Hollandalı mimarlar tarafından tasarlanan kanalları, kentin tarihini keşfetmek için eşsiz bir yol sunar. “Paddan” adı verilen düz teknelerle yapılan bu turlar, alçak köprülerin altından geçerek şehri gezdirir.' },
    { name: 'Feskekôrka (Balık Kilisesi)', desc: 'Gotik bir kiliseyi andıran benzersiz mimarisiyle bu bina, aslında 1874’ten beri hizmet veren canlı bir balık halidir. Adı “Balık Kilisesi” anlamına gelen bu yapı, Göteborg’un deniz ürünleri kültürünün özgün bir simgesidir.' },
    { name: 'Takımada (Skärgård)', desc: 'Göteborg’un hemen açığındaki güney takımadaları, araba trafiğine kapalı, sakin ve pitoresk adalardan oluşur. Feribotla kolayca ulaşılan bu adalar, kayalık kıyıları ve balıkçı köyleriyle huzurlu bir doğa kaçamağı sunar.' },
  ],
  malmo: [
    { name: 'Turning Torso', desc: 'Mimar Santiago Calatrava’nın tasarladığı bu 190 metrelik gökdelen, 90 derece burulan çarpıcı formuyla İskandinavya’nın en yüksek yapılarından biridir. İnsan bedeninin dönüşünden ilham alan bu bina, modern Malmö’nün simgesidir.' },
    { name: 'Stortorget & Lilla Torg', desc: 'Malmö’nün tarihî kalbini oluşturan bu iki komşu meydan, kentin geçmişini yansıtır. Görkemli belediye binasının bulunduğu geniş Stortorget ile yarım ahşap evlerle çevrili şirin Lilla Torg, kafeleri ve canlı atmosferiyle sosyal yaşamın merkezidir.' },
    { name: 'Malmöhus Kalesi', desc: '16. yüzyılda Danimarka kralı tarafından inşa edilen bu kale, İskandinavya’nın ayakta kalan en eski Rönesans kalelerindendir. Bir dönem hapishane olarak da kullanılan yapı, bugün kentin çeşitli müzelerine ev sahipliği yapar.' },
    { name: 'Öresund Köprüsü', desc: 'İsveç’i Danimarka’ya bağlayan bu olağanüstü mühendislik eseri, bir köprü ile bir denizaltı tünelinin yapay bir ada üzerinde birleşmesinden oluşur. İki ülkeyi ve başkenti Kopenhag’ı Malmö’ye bağlayan bu yapı, ünlü bir dizinin de adını taşır.' },
  ],
  uppsala: [
    { name: 'Uppsala Katedrali', desc: '118,7 metrelik ikiz kuleleriyle İskandinavya’nın en büyük ve en yüksek katedrali olan bu gotik yapı, İsveç Kilisesi’nin merkezidir. Kral Gustav Vasa ve botanikçi Carl Linnaeus gibi ünlü İsveçlilerin mezarlarını barındırır.' },
    { name: 'Uppsala Kalesi', desc: 'Şehre tepeden bakan bu görkemli pembe kale, 16. yüzyılda Kral Gustav Vasa tarafından inşa edilmiştir ve İsveç tarihinin önemli olaylarına sahne olmuştur. Bugün sanat müzesi ve valilik makamı olarak kullanılan yapı, kentin simgelerindendir.' },
    { name: 'Gamla Uppsala', desc: 'Adı “Eski Uppsala” anlamına gelen bu alan, İsveç’in en önemli tarih öncesi merkezlerinden biridir. Pagan dönemine ait devasa kraliyet defin höyükleri, İskandinav mitolojisi ve Viking tarihinin gizemli bir kutsal alanıydı.' },
    { name: 'Linnaeus Bahçesi', desc: 'Modern bitki sınıflandırma sisteminin babası olan ünlü botanikçi Carl Linnaeus’un çalıştığı bu tarihî bahçe, onun düzenlemesine göre yeniden canlandırılmıştır. Binlerce bitki türüyle, bilim tarihine ve doğaya adanmış huzurlu bir mekândır.' },
  ],
  kiruna: [
    { name: 'Icehotel (Jukkasjärvi)', desc: 'Kiruna yakınlarındaki bu otel, her kış Torne Nehri’nin buzundan tamamen yeniden inşa edilen ve baharda eriyip kaybolan dünyanın ilk ve en ünlü buz otelidir. Buzdan oyulmuş odaları, sanat eserleri ve barıyla eşsiz bir konaklama deneyimi sunar.' },
    { name: 'Abisko & Aurora Sky', desc: 'Kendine özgü mikro iklimi sayesinde sıklıkla açık gökyüzüne sahip olan Abisko Milli Parkı, dünyada Kuzey Işıkları’nı izlemek için en iyi yerlerden biri kabul edilir. Tepesindeki Aurora Sky İstasyonu, bu büyülü olayı gözlemlemek için idealdir.' },
    { name: 'Sami Kültürü', desc: 'Kiruna bölgesi, Avrupa’nın son yerli halkı olan ve geleneksel olarak ren geyiği çobanlığıyla geçinen Sami halkının anavatanıdır. Bölgede Sami kültürünü, geleneklerini ve ren geyikleriyle olan özel bağını yakından tanıma fırsatı bulunur.' },
    { name: 'Kebnekaise', desc: '2.096 metrelik zirvesiyle İsveç’in en yüksek dağı olan Kebnekaise, dağcıların ve doğa yürüyüşçülerinin gözde bir hedefidir. Buzulları ve çevresindeki el değmemiş vahşi doğasıyla İsveç Laponya’sının görkemini sergiler.' },
  ],
  visby: [
    { name: 'Ortaçağ Surları', desc: 'Gotland Adası’ndaki Visby’yi çevreleyen bu 3,4 kilometrelik sur, kuleleriyle Kuzey Avrupa’nın en iyi korunmuş ortaçağ kent surudur. Bir zamanlar zengin bir Hansa ticaret merkezi olan kentin bu istihkâmı, UNESCO Dünya Mirası listesindedir.' },
    { name: 'Kilise Kalıntıları', desc: 'Visby’nin altın çağında inşa edilen çok sayıda kilise, kentin ekonomik gerilemesiyle terk edilmiş ve bugün çatısız harabeler olarak ayakta durmaktadır. Bu romantik kalıntılar, kasabanın görkemli Hansa geçmişine tanıklık eder.' },
    { name: 'Gül Bahçeleri', desc: 'Visby, ılıman iklimi sayesinde sokaklarını ve avlularını süsleyen bol miktarda gülü ve ortaçağ harabeleriyle “Güller ve Harabeler Kenti” olarak anılır. Bu benzersiz atmosfer, kasabaya romantik ve masalsı bir hava katar.' },
    { name: 'Gotland Plaj & Rauk’lar', desc: 'Gotland Adası’nın kıyıları, “rauk” adı verilen ve deniz aşınmasıyla oluşan sıra dışı kireçtaşı sütunlarıyla ünlüdür. Bu doğal heykeller, adanın plajlarına ve kıyı şeridine dünyada eşine az rastlanır dramatik bir görünüm kazandırır.' },
  ],
  // --- İskandinavya: Danimarka ---
  kopenhag: [
    { name: 'Nyhavn', desc: 'Bir zamanlar hareketli bir liman olan bu 17. yüzyıl kanalı, kıyısındaki rengârenk tarihî evleri ve ahşap tekneleriyle Kopenhag’ın en tanınan simgesidir. Masal yazarı H. C. Andersen’in de yaşadığı bu semt, kafeleriyle canlı bir atmosfer sunar.' },
    { name: 'Küçük Deniz Kızı', desc: 'Danimarkalı yazar Hans Christian Andersen’in aynı adlı masalından esinlenerek yapılan bu bronz heykel, bir kaya üzerinde denize bakan bir deniz kızını betimler. 1913’ten beri Kopenhag limanında oturan bu mütevazı heykel, kentin dünyaca ünlü simgesidir.' },
    { name: 'Tivoli Bahçeleri', desc: '1843’te açılan Tivoli, dünyanın hâlâ faal olan en eski ikinci eğlence parkıdır ve Walt Disney’e Disneyland için ilham verdiği söylenir. Tarihî oyunları, bahçeleri ve masalsı atmosferiyle her yaştan ziyaretçiyi büyüler.' },
    { name: 'Rosenborg & Amalienborg', desc: 'Rönesans üslubundaki Rosenborg Şatosu, Danimarka Kraliyet Mücevherleri’ni ve tacını barındırmasıyla ünlüdür. Amalienborg ise kraliyet ailesinin bugünkü kışlık ikametgâhı olup görkemli nöbet değişimi töreniyle dikkat çeker.' },
    { name: 'Christiania & Christiansborg', desc: 'Christiania, 1971’de terk edilmiş bir askeri bölgede kurulan, kendi kurallarıyla yönetilen özerk ve alternatif bir “özgür kent”tir. Christiansborg Sarayı ise Danimarka Parlamentosu’na, Başbakanlık’a ve Yüksek Mahkeme’ye ev sahipliği yapan bir güç merkezidir.' },
  ],
  aarhus: [
    { name: 'ARoS Sanat Müzesi', desc: 'İskandinavya’nın en büyük sanat müzelerinden biri olan ARoS, çatısındaki sanatçı Olafur Eliasson’un tasarladığı gökkuşağı renklerindeki dairesel yürüyüş yoluyla dünyaca ünlüdür. Bu panoramik geçitten şehre her renkte bakmak eşsiz bir deneyimdir.' },
    { name: 'Den Gamle By', desc: 'Danimarka’nın dört bir yanından toplanan tarihî binalarla kurulan bu açık hava müzesi (“Eski Kent”), farklı dönemlerdeki kent yaşamını canlandırır. Kostümlü canlandırmacıları ve otantik dükkânlarıyla geçmişe canlı bir yolculuk sunar.' },
    { name: 'Katedral & Latin Mahallesi', desc: 'Aarhus Katedrali, 93 metre uzunluğuyla Danimarka’nın en uzun ve en yüksek kilisesidir ve değerli fresklerini korur. Çevresindeki Latin Mahallesi ise arnavut kaldırımlı sokakları, butikleri ve kafeleriyle kentin en şirin ve en eski bölgesidir.' },
    { name: 'Moesgaard Müzesi', desc: 'Üzerinde yürünebilen çim çatısıyla dikkat çeken bu modern arkeoloji müzesi, olağanüstü korunmuş 2.000 yıllık “Grauballe Adamı” bataklık cesediyle ünlüdür. Etkileyici sergileriyle bölgenin tarih öncesi ve Viking geçmişini anlatır.' },
  ],
  odense: [
    { name: 'H. C. Andersen Evi & Müzesi', desc: '“Küçük Deniz Kızı” ve “Çirkin Ördek Yavrusu” gibi dünyaca ünlü masalların yazarı Hans Christian Andersen’in 1805’te doğduğu bu şehir, ona adanmış modern bir müzeye ev sahipliği yapar. Yazarın büyülü dünyasını interaktif sergilerle canlandırır.' },
    { name: 'Eski Şehir', desc: 'Odense’nin tarihî merkezi, H. C. Andersen’in çocukluğunun geçtiği rengârenk yarım ahşap evleri ve arnavut kaldırımlı sokaklarıyla masalsı bir atmosfer sunar. İyi korunmuş bu dokusu, yazarın hikâyelerinin ilham kaynağını hissettirir.' },
    { name: 'Egeskov Şatosu', desc: 'Odense yakınlarındaki bu şato, bir gölün üzerine meşe kazıklar üstüne inşa edilmiş Avrupa’nın en iyi korunmuş su hendekli Rönesans kalesidir. Görkemli mimarisi, labirenti ve bahçeleriyle bir peri masalını andırır.' },
    { name: 'Nehir Yürüyüşü', desc: 'Odense Nehri boyunca uzanan yeşil yürüyüş rotası, şehir merkezini doğal güzelliklerle buluşturan huzurlu bir kaçış sunar. H. C. Andersen’in de esinlendiği bu güzergâh, parkları ve tarihî değirmeniyle keyifli bir gezinti imkânı verir.' },
  ],
  skagen: [
    { name: 'Grenen', desc: 'Danimarka’nın en kuzey ucu olan bu kum dili, Skagerrak ve Kattegat olmak üzere iki farklı denizin dalgalarının görünür biçimde çarpıştığı büyüleyici bir noktadır. Ziyaretçiler, bir ayağı bir denizde diğeri ötekinde olacak şekilde durabilir.' },
    { name: 'Skagen Müzesi', desc: 'Bu müze, 19. yüzyıl sonunda Skagen’in eşsiz ışığı ve doğasından etkilenerek buraya yerleşen ünlü “Skagen Ressamları”nın eserlerini sergiler. Balıkçıları ve deniz manzaralarını betimleyen bu tablolar, Danimarka sanatının altın çağını yansıtır.' },
    { name: 'Kum Altındaki Kilise', desc: 'Bir zamanlar bölgenin en büyük kilisesi olan bu 14. yüzyıl yapısı, 18. yüzyılda ilerleyen kum tepeleri tarafından yutulmuştur. Bugün sadece badanalı çan kulesi kumun üzerinde görünen bu kilise, doğanın gücünün çarpıcı bir anıtıdır.' },
    { name: 'Sarı Evler & Liman', desc: 'Skagen, kırmızı kiremitli çatıları ve beyaz süslemeleriyle karakteristik sarıya boyanmış evleriyle ünlüdür ve bu renk kentin simgesi olmuştur. Hâlâ faal olan hareketli balıkçı limanı, kasabaya otantik bir denizci ruhu katar.' },
  ],
  // --- İskandinavya: Finlandiya ---
  helsinki: [
    { name: 'Senato Meydanı & Katedral', desc: 'Helsinki’nin kalbindeki bu görkemli neoklasik meydan, yeşil kubbeli bembeyaz katedraliyle kentin en tanınan simgesidir. Mimar Carl Ludvig Engel’in tasarladığı bu uyumlu yapılar topluluğu, şehrin en fotojenik noktasıdır.' },
    { name: 'Temppeliaukio (Kaya Kilisesi)', desc: 'Doğal bir granit kayanın içine oyularak inşa edilen bu benzersiz kilise, bakır kubbesi ve olağanüstü akustiğiyle ünlüdür. Kayaların arasından süzülen doğal ışığı ve dingin atmosferiyle mimari bir başyapıttır ve sıkça konserlere ev sahipliği yapar.' },
    { name: 'Suomenlinna', desc: 'Helsinki açıklarındaki altı adaya yayılan bu görkemli deniz kalesi, 18. yüzyılda inşa edilmiş bir mühendislik harikasıdır. İsveç, Rus ve Fin dönemlerine tanıklık eden surları ve tarihiyle UNESCO Dünya Mirası listesindedir.' },
    { name: 'Pazar Meydanı & Esplanadi', desc: 'Helsinki limanındaki bu canlı meydan, taze ürünler, yerel yiyecekler ve el sanatları sunan tezgâhlarıyla kentin hareketli merkezidir. Buradan başlayan zarif ağaçlıklı Esplanadi bulvarı, parkı ve kafeleriyle sosyal yaşamın kalbidir.' },
    { name: 'Oodi Kütüphanesi & Tasarım', desc: 'Ahşap ve camdan oluşan çarpıcı mimarisiyle Oodi, bir kütüphaneden çok bir yaşam ve buluşma alanı olarak tasarlanmıştır. Çevresindeki Tasarım Semti (Design District) ise Helsinki’nin dünyaca ünlü tasarım ve mimari kimliğini yansıtır.' },
  ],
  rovaniemi: [
    { name: 'Noel Baba Köyü', desc: 'Fin Laponyası’ndaki Rovaniemi, resmi olarak Noel Baba’nın memleketi kabul edilir ve bu köyde onu yıl boyu ziyaret etmek mümkündür. Kutup Dairesi çizgisinin geçtiği köy, Noel Baba’nın ofisi ve dünyanın her yerine mektup gönderen postanesiyle ünlüdür.' },
    { name: 'Kuzey Işıkları', desc: 'Kutup Dairesi üzerindeki konumu sayesinde Rovaniemi, karanlık kış aylarında gökyüzünü saran büyülü Kuzey Işıkları’nı (aurora borealis) izlemek için ideal bir merkezdir. Bu doğa harikası, cam iglolar veya safariler eşliğinde deneyimlenir.' },
    { name: 'Ren Geyiği & Husky Safari', desc: 'Rovaniemi, karlı Laponya doğasında ren geyiği ve Sibirya kurdu (husky) çektiği kızaklarla yapılan geleneksel safarilerle ünlüdür. Bu heyecan verici turlar, Arktik vahşi doğayı ve yerel yaşamı deneyimlemenin en özgün yoludur.' },
    { name: 'Arktikum', desc: 'Rovaniemi’deki bu bilim merkezi ve müze, Laponya’nın tarihini, kültürünü ve Arktik bölgenin doğasını sergiler. Çarpıcı cam tünel mimarisiyle Kuzey Işıkları, Sami halkı ve kutup yaşamı hakkında kapsamlı bir bilgi sunar.' },
  ],
  turku: [
    { name: 'Turku Kalesi', desc: 'Finlandiya’nın en eski şehri Turku’daki bu görkemli kale, 13. yüzyıldan kalma olup İskandinavya’nın en büyük ayakta kalan ortaçağ yapılarındandır. Yüzyıllar boyunca yönetim merkezi ve hapishane olarak kullanılan kale, bugün bir tarih müzesidir.' },
    { name: 'Turku Katedrali', desc: 'Finlandiya’nın ulusal kutsal yapısı ve Evanjelik Lüteriyen Kilisesi’nin ana kilisesi olan bu görkemli katedralin kökeni 13. yüzyıla uzanır. Ülkenin en önemli ortaçağ eseri olarak Fin ulusal kimliğinin manevi bir simgesidir.' },
    { name: 'Nehir Kıyısı (Aura)', desc: 'Turku’yu ikiye bölen Aura Nehri’nin kıyıları, kentin sosyal yaşamının kalbidir. Nehir üzerinde demirlemiş tarihî gemilerden dönüştürülen restoran-barlar ve kıyıdaki kafelerle, özellikle yaz aylarında canlı bir atmosfer sunar.' },
    { name: 'Takımada Yolu', desc: 'Turku, dünyanın en büyük takımadalarından birine açılan bir kapıdır ve binlerce adayı birbirine bağlayan ünlü bir “Takımada Yolu” (Archipelago Trail) sunar. Feribotlar ve köprülerle adadan adaya geçilen bu rota, eşsiz bir doğa rotasıdır.' },
  ],
  tampere: [
    { name: 'Näsinneula Kulesi', desc: 'İki büyük gölün arasındaki Tampere’ye hâkim olan bu gözlem kulesi, İskandinavya’nın en yüksek gözlem kulelerinden biridir. Tepesindeki döner restorandan, kentin, göllerin ve ormanların 360 derecelik panoraması izlenir.' },
    { name: 'Vapriikki & Moomin Müzesi', desc: 'Eski bir tekstil fabrikasından dönüştürülen bu geniş müze kompleksi, tarihten hokeye çeşitli sergiler barındırır. İçindeki Muumi Müzesi, dünyaca ünlü Fin yazar Tove Jansson’un yarattığı sevimli Muumi karakterlerine adanmıştır.' },
    { name: 'Pyynikki Sauna & Gözlem Kulesi', desc: 'Dünyanın en eski faal kamu odun saunası olan Rajaportti’ye ev sahipliği yapan Pyynikki, Fin sauna kültürünün kalbidir. Bölgedeki taş gözlem kulesi ise iki göl manzarası ve ünlü donutlarıyla sevilen bir noktadır.' },
    { name: 'Tuğla Fabrika Semti', desc: 'Tampere, “Kuzeyin Manchester’ı” olarak anılan endüstriyel geçmişini, Finlayson ve Tampella gibi devasa kırmızı tuğla fabrika komplekslerinde yaşatır. Bu binalar bugün müzeler, restoranlar ve sinemalarla dolu canlı kültür merkezlerine dönüşmüştür.' },
  ],
  // --- İskandinavya: İzlanda ---
  reykjavik: [
    { name: 'Hallgrímskirkja', desc: 'İzlanda’nın volkanik bazalt sütun oluşumlarından ilham alan bu 74 metrelik ifade dolu kilise, Reykjavik’in en tanınan simgesidir. Kulesinin tepesindeki gözlem terasından, kentin rengârenk çatılarının ve çevredeki dağların panoraması izlenir.' },
    { name: 'Harpa', desc: 'Reykjavik limanı kıyısındaki bu göz alıcı konser salonu ve konferans merkezi, İzlanda manzaralarından esinlenen bal peteği biçimli renkli cam cephesiyle büyüler. Işıkla dans eden bu modern yapı, kentin kültürel ve mimari bir gururudur.' },
    { name: 'Altın Çember', desc: 'İzlanda’nın en popüler turistik rotası olan bu güzergâh, üç doğa harikasını kapsar: kıtaların ayrıldığı Þingvellir Milli Parkı, gökyüzüne su fışkırtan Geysir jeotermal alanı ve görkemli Gullfoss şelalesi. Ülkenin jeolojik gücünü sergiler.' },
    { name: 'Mavi Lagün', desc: 'Bir lav tarlasının ortasındaki bu ünlü jeotermal spa, silika ve minerallerce zengin süt mavisi sularıyla dünyaca meşhurdur. Yakınındaki jeotermal santralden beslenen bu şifalı sular, İzlanda’nın en rahatlatıcı deneyimini sunar.' },
    { name: 'Sun Voyager & Sahil', desc: 'Reykjavik sahilindeki bu çelik heykel, bir Viking gemisini andırsa da aslında bir “rüya gemisi” ve keşfedilmemiş topraklara duyulan özlemin bir simgesidir. Deniz ve dağ manzarası eşliğinde kentin en sevilen fotoğraf noktalarındandır.' },
  ],
  vik: [
    { name: 'Reynisfjara', desc: 'Vík köyü yakınlarındaki bu ünlü plaj, siyah volkanik kumu, dev bazalt sütunları ve mağaralarıyla dünyanın en etkileyici sahillerinden biridir. Güçlü ve tehlikeli “hayalet dalgaları”yla da bilinen bu plaj, dramatik bir doğa harikasıdır.' },
    { name: 'Reynisdrangar', desc: 'Reynisfjara Plajı’nın açığında denizden dimdik yükselen bu sivri bazalt kaya kuleleri, İzlanda folkloruna göre gün doğumunda taşa dönüşmüş trollerdir. Bu efsanevi kayalar, kıyının gizemli ve büyüleyici manzarasını tamamlar.' },
    { name: 'Dyrhólaey', desc: 'Denize doğru uzanan bu yarımada, adını (“kapı-tepe deliği”) içinden gemilerin bile geçebildiği devasa bir doğal deniz kemerinden alır. Ayrıca bir deniz feneri ve yaz aylarında sevimli deniz papağanı (puffin) kolonileriyle ünlüdür.' },
    { name: 'Skógafoss & Sólheimajökull', desc: 'Vík yakınlarındaki Skógafoss, 60 metre yükseklikten dökülen ve güneşli günlerde çift gökkuşağı oluşturan görkemli bir şelaledir. Yakınındaki Sólheimajökull buzul dili ise buzul yürüyüşleri için popüler, ulaşılabilir bir doğa harikasıdır.' },
  ],
  akureyri: [
    { name: 'Akureyri Kilisesi', desc: 'İzlanda’nın kuzeyindeki bu kentin simgesi olan kilise, ünlü Hallgrímskirkja’yı da tasarlayan mimar Guðjón Samúelsson’un eseridir. Bir tepenin üzerinde fiyorda bakan bu modernist beyaz yapı, bazalt sütunları andıran cephesiyle dikkat çeker.' },
    { name: 'Botanik Bahçesi', desc: 'Kutup Dairesi’ne yakınlığına rağmen bu botanik bahçesi, İzlanda’ya özgü türlerin yanı sıra dünyanın dört bir yanından binlerce bitkiyi barındırmasıyla şaşırtır. Bu enlemde bu denli zengin bir bahçenin varlığı, bir doğa mucizesidir.' },
    { name: 'Goðafoss', desc: 'Adı “Tanrıların Şelalesi” anlamına gelen bu görkemli çağlayan, İzlanda’nın Hristiyanlığı kabul ettiği sırada pagan tanrı heykellerinin buraya atıldığı efsanesiyle ünlüdür. Yarım daire biçimli zarif yapısıyla ülkenin en etkileyici şelalelerindendir.' },
    { name: 'Mývatn Gölü', desc: 'Yoğun volkanik aktivitenin şekillendirdiği bu göl bölgesi, sözde kraterler, tuhaf lav oluşumları ve fokurdayan çamur havuzlarıyla adeta başka bir gezegeni andırır. Doğal jeotermal hamamlarıyla da rahatlatıcı bir mola noktasıdır.' },
  ],

  // --- Japonya genişletme ---
  hakone: [
    { name: 'Ashi Gölü & Korsan Gemisi', desc: 'Bir yanardağ kalderasında oluşan bu göl, açık havada Fuji Dağı’nın suya yansıyan manzarasıyla ünlüdür. Gölde sefer yapan gösterişli korsan gemisi replikaları, bu doğa harikasını keşfetmenin keyifli ve popüler bir yoludur.' },
    { name: 'Hakone Teleferiği & Owakudani', desc: 'Bu teleferik hattı, hâlâ aktif olan bir volkanik vadi olan Owakudani üzerinden geçer. Kükürtlü buharların yükseldiği bu vadide, jeotermal suda kaynatılan ve yedikçe ömrü uzattığına inanılan meşhur “kara yumurtalar” satılır.' },
    { name: 'Onsen (Kaplıca)', desc: 'Volkanik aktivitesi sayesinde Hakone, Japonya’nın en ünlü sıcak su kaplıcası (onsen) bölgelerinden biridir. Geleneksel Japon hanları (ryokan) içindeki bu şifalı termal banyolar, dağ manzarası eşliğinde huzurlu bir dinlenme sunar.' },
    { name: 'Hakone Açık Hava Müzesi', desc: 'Dağların doğal manzarasını bir sanat galerisiyle birleştiren bu müze, yeşillikler arasına yerleştirilmiş modern heykellerle doludur. Picasso’nun eserlerine adanmış bir pavyonu ve çocuklar için sanatsal oyun alanlarıyla eşsiz bir deneyim sunar.' },
    { name: 'Hakone Tapınağı', desc: 'Ashi Gölü kıyısındaki ormanın içinde yer alan bu Şinto tapınağı, suyun içinde yükselen ünlü kırmızı “Barış Kapısı” (torii) ile büyüler. Fuji manzarası eşliğindeki bu ikonik kapı, tapınağın en çok fotoğraflanan simgesidir.' },
  ],
  nikko: [
    { name: 'Toshogu Tapınağı', desc: 'Japonya’yı birleştiren şogun Tokugawa Ieyasu’nun anıt mezarı olan bu görkemli tapınak, olağanüstü altın işçiliği ve renkli oymalarıyla göz kamaştırır. “Görme, işitme, söyleme” prensibini betimleyen ünlü “üç bilge maymun” oyması buradadır.' },
    { name: 'Kegon Şelalesi', desc: 'Chuzenji Gölü’nün sularının 97 metre yükseklikten dökülmesiyle oluşan bu görkemli çağlayan, Japonya’nın en ünlü şelalelerindendir. Özellikle sonbaharda çevresini saran kızıl yapraklarla birleşince nefes kesici bir manzara sunar.' },
    { name: 'Chuzenji Gölü', desc: 'Yaklaşık 20.000 yıl önce Nantai Dağı’nın patlamasıyla oluşan bu göl, dağların eteğindeki yüksek konumuyla serin bir yaz sığınağıdır. Özellikle sonbaharda renk cümbüşüne dönüşen çevresiyle Nikko’nun en güzel doğa harikalarındandır.' },
    { name: 'Shinkyo Köprüsü', desc: 'Daiya Nehri üzerindeki bu zarif kırmızı köprü, Nikko’nun kutsal tapınak alanına girişi simgeler ve Japonya’nın en güzel üç köprüsünden biri kabul edilir. Efsaneye göre, azizin nehri geçmesine yardım eden iki dev yılandan oluşmuştur.' },
  ],
  kanazawa: [
    { name: 'Kenroku-en Bahçesi', desc: 'İki asırdan uzun sürede tasarlanan bu görkemli bahçe, geleneksel Japon peyzajının aradığı altı özelliği bir arada barındırdığı için Japonya’nın en güzel üç bahçesinden biri kabul edilir. Gölleri, çay evleri ve mevsimlik güzellikleriyle her daim büyüler.' },
    { name: 'Higashi Chaya (Geyşa Semti)', desc: 'Kanazawa’nın en büyük geyşa semti olan bu bölge, iyi korunmuş ahşap çay evleri (chaya) ve arnavut kaldırımlı sokaklarıyla eski Japonya’nın zarafetini yaşatır. Kentin ünlü altın varak zanaatının sergilendiği dükkânlarıyla da tanınır.' },
    { name: 'Kanazawa Kalesi', desc: 'Bir zamanlar bölgeyi yöneten güçlü Maeda ailesinin ikametgâhı olan bu görkemli kale, Kenroku-en Bahçesi’ne komşudur. Kurşun kaplamalı beyaz çatı kiremitleri ve etkileyici kapılarıyla feodal dönem Japonya’sının gücünü yansıtır.' },
    { name: '21. Yüzyıl Çağdaş Sanat Müzesi', desc: 'Dairesel ve cam bir yapıya sahip bu modern müze, interaktif eserleriyle ünlüdür. En meşhur eseri, ziyaretçilerin suyun altında yürüyormuş gibi göründüğü, göz yanılsaması yaratan “Yüzme Havuzu” enstalasyonudur.' },
    { name: 'Omicho Pazarı', desc: '“Kanazawa’nın Mutfağı” olarak bilinen bu 300 yıllık canlı pazar, Japon Denizi’nin taze deniz ürünlerini sunar. Yengeçler, istiridyeler ve bölgeye özgü lezzetlerle dolu tezgâhlarıyla kentin gastronomi kültürünün kalbidir.' },
  ],
  takayama: [
    { name: 'Sanmachi Eski Şehir', desc: 'Takayama’nın olağanüstü korunmuş bu tarihî merkezi, Edo döneminden kalma ahşap tüccar evleri ve sake üreticileriyle doludur. Zamanda donmuş dar sokakları, geleneksel dükkânları ve atmosferiyle eski Japonya’ya bir yolculuk sunar.' },
    { name: 'Sabah Pazarları', desc: 'Takayama, iki asırdan uzun süredir devam eden geleneksel sabah pazarlarıyla ünlüdür. Nehir kıyısında ve bir tapınak önünde kurulan bu pazarlar, yerel çiftçilerin taze ürünlerini, turşularını ve el sanatlarını doğrudan sunduğu canlı mekânlardır.' },
    { name: 'Shirakawa-go', desc: 'Takayama yakınlarındaki bu UNESCO köyü, ağır kar yükünü taşımak için tasarlanmış dik samanlı çatılı geleneksel “gassho-zukuri” çiftlik evleriyle ünlüdür. Özellikle karla kaplandığında, bu köy adeta bir masal diyarına dönüşür.' },
    { name: 'Hida Folk Köyü', desc: 'Bu açık hava müzesi, Hida bölgesinin dört bir yanından toplanan geleneksel çiftlik evlerini bir araya getirir. Ziyaretçiler, bu tarihî evlerin içinde gezerek dağ bölgesindeki eski Japon köy yaşamını ve el sanatlarını deneyimler.' },
  ],
  sapporo: [
    { name: 'Odori Parkı & Kar Festivali', desc: 'Sapporo’nun merkezini boydan boya kesen bu geniş park, her kış düzenlenen dünyaca ünlü Kar Festivali’ne ev sahipliği yapar. Bu festivalde sergilenen devasa ve ayrıntılı kar ve buz heykelleri, milyonlarca ziyaretçiyi büyüler.' },
    { name: 'Sapporo Bira Müzesi', desc: 'Japonya’nın en eski bira markalarından birinin tarihî fabrikasında yer alan bu müze, Japon bira üretiminin geçmişini anlatır. Kırmızı tuğlalı tarihî binasında, ziyaretçilere biranın yapımını öğrenme ve tadım yapma fırsatı sunar.' },
    { name: 'Mount Moiwa', desc: 'Sapporo’ya tepeden bakan bu dağa çıkan teleferik, özellikle geceleri şehrin ışıklarının oluşturduğu muhteşem panoramayla ünlüdür. Japonya’nın en iyi gece manzaralarından birine sahip olan zirvesi, romantik bir buluşma noktasıdır.' },
    { name: 'Nijo Pazarı & Ramen Sokağı', desc: 'Nijo Pazarı, Hokkaido’nun ünlü taze deniz ürünlerini, özellikle yengeç ve deniz kestanesini sunan canlı bir çarşıdır. Yakınındaki ünlü Ramen Sokağı ise, Sapporo’nun icadı olan zengin ve sıcak miso ramenini tatmak için ideal bir mekândır.' },
  ],
  fukuoka: [
    { name: 'Yatai (Sokak Tezgâhları)', desc: 'Fukuoka, akşamları nehir kıyısında ve sokaklarda kurulan “yatai” adı verilen açık hava yemek tezgâhlarıyla ünlüdür. Bu küçük ve samimi tezgâhlarda, kentin meşhur domuz kemiği çorbalı “tonkotsu rameni” tadılır ve yerel sohbetlere katılınır.' },
    { name: 'Ohori Parkı & Kale', desc: 'Bir zamanlar Fukuoka Kalesi’nin hendeği olan geniş bir gölün etrafına kurulan Ohori Parkı, kentlilerin en sevdiği dinlenme alanıdır. Yanı başındaki Fukuoka Kalesi kalıntıları ise şehrin feodal dönem tarihine tanıklık eder.' },
    { name: 'Kushida Tapınağı', desc: 'Fukuoka’nın koruyucu tapınağı olan bu Şinto mabedi, kentin en büyük festivali Hakata Gion Yamakasa’nın merkezidir. Tapınakta sergilenen devasa ve gösterişli festival arabaları (yamakasa), yerel kültürün canlı bir parçasıdır.' },
    { name: 'Canal City', desc: 'İçinden bir su kanalı geçen bu devasa alışveriş ve eğlence kompleksi, “şehir içinde şehir” olarak tasarlanmıştır. Rengârenk mimarisi, düzenli su ve ışık gösterileriyle Fukuoka’nın en canlı ve modern cazibe merkezlerindendir.' },
  ],
  kamakura: [
    { name: 'Büyük Buda (Daibutsu)', desc: 'Kamakura’nın simgesi olan bu 13. yüzyıldan kalma dev bronz Buda heykeli, yaklaşık 13 metre yüksekliğindedir. Bir zamanlar onu barındıran tapınak bir tsunamiyle yıkıldığından, heykel yüzyıllardır huzurla açık havada oturmaktadır.' },
    { name: 'Hase-dera Tapınağı', desc: 'Bir yamaca kurulu bu tapınak, 9 metrelik devasa ahşap bir Kannon (merhamet tanrıçası) heykeli barındırır. Zarif bahçeleri ve terasından izlenen Kamakura kıyısı ile deniz manzarasıyla huzurlu ve büyüleyici bir mekândır.' },
    { name: 'Tsurugaoka Hachimangu', desc: 'Kamakura’nın en önemli Şinto tapınağı olan bu görkemli mabet, bir zamanlar şehrin siyasi ve kültürel merkeziydi. Geniş bir yürüyüş yolunun sonundaki tapınağa, basamaklı bir merdivenle çıkılır ve kentin tarihini yaşatır.' },
    { name: 'Hokokuji (Bambu Ormanı)', desc: '“Bambu Tapınağı” olarak da bilinen bu Zen tapınağı, arkasındaki yaklaşık 2.000 bambu ağacından oluşan huzurlu ormanıyla ünlüdür. Ziyaretçiler, bu dingin bambu bahçesinin manzarasına karşı geleneksel bir çay evinde matcha içebilir.' },
    { name: 'Enoshima & Sahil', desc: 'Kamakura’dan nostaljik bir tramvayla (Enoden) ulaşılan Enoshima, tapınakları ve mağaralarıyla dolu şirin bir adadır. Yol boyunca uzanan sahil ise Japonya’nın popüler sörf noktalarından biri olup açık havada Fuji Dağı manzarası sunar.' },
  ],
  kobe: [
    { name: 'Kitano Ijinkan', desc: 'Kobe’nin 19. yüzyılda uluslararası ticarete açılmasıyla buraya yerleşen yabancı tüccarların yaşadığı bu semt, Batı tarzı tarihî konaklarla (ijinkan) doludur. Bu zarif evler, kentin kozmopolit ve dışa açık geçmişini yansıtır.' },
    { name: 'Liman & Kobe Kulesi', desc: 'Kobe, Japonya’nın en önemli limanlarından biridir ve yenilenen liman bölgesi kentin canlı bir cazibe merkezidir. Kırmızı çelik örgülü zarif Kobe Kulesi, özellikle geceleri ışıklandırılan liman manzarasının simgesidir.' },
    { name: 'Mount Rokko & Nunobiki', desc: 'Kobe’ye tepeden bakan Rokko Dağı, teleferikle ulaşılan zirvesinden şehrin ve limanın muhteşem gece manzarasını sunar. Dağın eteğindeki Nunobiki Şelalesi ise Japonya’nın en güzel çağlayanlarından biri kabul edilir.' },
    { name: 'Kobe Eti', desc: 'Kobe, dünyanın en pahalı ve en lezzetli etlerinden biri olan “Kobe eti” ile küresel üne sahiptir. Tajima cinsi sığırlardan elde edilen bu et, mermer gibi yağ dokusu ve ağızda dağılan yumuşaklığıyla eşsiz bir gastronomi deneyimi sunar.' },
    { name: 'Nada Sake Bölgesi', desc: 'Kobe’deki Nada bölgesi, kaliteli suyu ve pirinci sayesinde Japonya’nın en büyük ve en ünlü sake (pirinç şarabı) üretim merkezidir. Bölgedeki tarihî üreticiler ve müzeler, bu geleneksel içeceğin yapımını ve tadımını ziyaretçilere sunar.' },
  ],
  nagoya: [
    { name: 'Nagoya Kalesi', desc: 'Şogun Tokugawa Ieyasu tarafından yaptırılan bu görkemli kale, çatısının iki ucunu süsleyen altın kaplama efsanevi balık-kaplan heykelleriyle (shachihoko) ünlüdür. Bu altın figürler, kentin gücünün ve zenginliğinin simgesi olmuştur.' },
    { name: 'Atsuta Tapınağı', desc: 'Japonya’nın en kutsal Şinto tapınaklarından biri olan Atsuta, imparatorluk ailesinin üç kutsal hazinesinden biri olan efsanevi kılıcı (Kusanagi) barındırdığına inanılır. Yaklaşık iki bin yıllık geçmişiyle önemli bir hac merkezidir.' },
    { name: 'Toyota Sanayi & Teknoloji Müzesi', desc: 'Bu müze, dünya devi Toyota’nın bir dokuma tezgâhı üreticisi olarak başlayıp otomobil imparatorluğuna dönüşen hikâyesini anlatır. Çalışan makineleri ve robotlarıyla, Japon endüstriyel dehasının gelişimini interaktif olarak sergiler.' },
    { name: 'Osu Çarşısı', desc: 'Tarihî Osu Kannon tapınağının çevresinde gelişen bu bölge, üstü kapalı canlı alışveriş sokaklarından oluşur. Geleneksel dükkânları modern pop kültürü mağazalarıyla harmanlayan bu çarşı, Nagoya’nın en enerjik ve renkli semtlerindendir.' },
  ],
  fuji: [
    { name: 'Kawaguchiko Gölü', desc: 'Fuji Dağı’nı çevreleyen beş gölden en erişilebilir olanı ve en ünlüsüdür. Rüzgârsız günlerde Fuji’nin kusursuz konisinin durgun sularına yansıması (“ters Fuji”), Japonya’nın en ikonik ve büyüleyici manzaralarından birini oluşturur.' },
    { name: 'Chureito Pagoda', desc: 'Bir tepenin üzerindeki bu beş katlı kırmızı pagoda, arka planında yükselen Fuji Dağı ile birlikte Japonya’nın en klasik manzarasını sunar. Özellikle ilkbaharda önündeki kiraz çiçekleriyle birleşince, adeta bir kartpostal tablosuna dönüşür.' },
    { name: 'Fuji Tırmanışı (Yoshida)', desc: '3.776 metre yüksekliğiyle Japonya’nın en yüksek dağı ve kutsal bir simge olan Fuji’ye, yalnızca yaz aylarında tırmanılabilir. En popüler rota olan Yoshida güzergâhı, dağcıları zirvedeki muhteşem gün doğumu (goraiko) manzarasıyla ödüllendirir.' },
    { name: 'Oshino Hakkai', desc: 'Fuji Dağı’nın kar sularının yer altından yüzyıllarca süzülerek yüzeye ulaştığı bu geleneksel köy, sekiz adet olağanüstü berrak kaynak havuzuyla ünlüdür. Samanlı çatılı evleri ve tertemiz sularıyla dingin ve pitoresk bir köşedir.' },
    { name: 'Fuji Panorama Teleferiği', desc: 'Kawaguchiko Gölü kıyısındaki bu teleferik, kısa sürede bir tepenin zirvesine ulaştırır. Buradan hem Fuji Dağı’nın hem de aşağıdaki gölün panoramik manzarası izlenir; ayrıca çevresi Japon halk masalı temasıyla süslenmiştir.' },
  ],

  // --- İspanya derinleştirme ---
  bilbao: [
    { name: 'Guggenheim Müzesi', desc: 'Mimar Frank Gehry’nin tasarladığı, kıvrımlı titanyum panelleriyle bir gemiyi andıran bu çağdaş sanat müzesi, açılışıyla kentin kaderini değiştirmiştir. Sanayi kenti Bilbao’yu bir kültür başkentine dönüştüren bu yapı, modern mimarinin bir ikonudur.' },
    { name: 'Casco Viejo', desc: 'Bilbao’nun tarihî çekirdeği olan bu bölge, başlangıçtaki “Yedi Sokak” (Zazpikaleak) etrafında gelişmiş, canlı ve otantik bir merkezdir. Dar sokakları, tarihî binaları ve sayısız pintxos (Bask tapası) barıyla kentin ruhunu yansıtır.' },
    { name: 'Ribera Pazarı', desc: 'Nervión Nehri kıyısındaki bu görkemli art deco yapı, üstü kapalı pazarlar arasında Avrupa’nın en büyüklerinden biridir. Taze balık, et ve yerel ürünler sunan tezgâhlarıyla Bilbao’nun köklü gastronomi kültürünün kalbidir.' },
    { name: 'Artxanda Füniküleri', desc: '1915’ten beri hizmet veren bu tarihî füniküler, Bilbao’yu kısa sürede karşısındaki Artxanda tepesine çıkarır. Zirvedeki parktan, Guggenheim dahil tüm şehrin ve çevredeki yeşil dağların panoraması izlenir.' },
  ],
  sansebastian: [
    { name: 'La Concha Plajı', desc: 'Adı “deniz kabuğu” anlamına gelen bu plaj, kusursuz yarım daire biçimi ve altın kumuyla dünyanın en güzel şehir plajlarından biri kabul edilir. Zarif beyaz korkuluklu promenadıyla San Sebastián’ın en tanınan simgesidir.' },
    { name: 'Parte Vieja & Pintxos', desc: 'San Sebastián’ın tarihî eski şehri, dünya gastronomisinin başkentlerinden biri olmasını sağlayan yoğun pintxos (Bask usulü tapas) barlarıyla ünlüdür. Bardan bara gezerek bu minik lezzet şaheserlerini tatmak, kentin en sevilen ritüelidir.' },
    { name: 'Monte Igueldo', desc: 'Körfezin bir ucundaki bu tepeye, 1912’den beri hizmet veren tarihî bir füniküler ile çıkılır. Zirvedeki nostaljik lunapark ve gözlem terası, La Concha Körfezi’nin en klasik ve en muhteşem manzarasını sunar.' },
    { name: 'Monte Urgull', desc: 'Eski şehrin arkasında yükselen bu ağaçlıklı tepe, zirvesindeki tarihî kale (Mota Kalesi) ve dev İsa heykeliyle taçlanır. Surları arasındaki yürüyüş yollarından, şehrin ve limanın panoramik manzarası izlenir.' },
  ],
  toledo: [
    { name: 'Toledo Katedrali', desc: 'İspanya gotiğinin en görkemli başyapıtlarından biri olan bu katedral, yüzyıllar süren inşasıyla mimari zenginliğe sahiptir. El Greco ve Goya gibi ustaların eserlerini barındıran yapı, İspanya Katolikliği’nin ruhani merkezidir.' },
    { name: 'Alcázar', desc: 'Şehrin en yüksek noktasında yükselen bu görkemli kare planlı kale, kökeni Roma dönemine uzanan stratejik bir konumdadır. İspanya İç Savaşı’ndaki ünlü kuşatmaya sahne olan yapı, bugün bir ordu müzesi ve kütüphanedir.' },
    { name: 'El Greco İzleri', desc: 'Toledo, ünlü ressam El Greco’nun hayatının çoğunu geçirdiği ve başyapıtlarını ürettiği kenttir. Santo Tomé Kilisesi’ndeki “Kont Orgaz’ın Cenaze Töreni” tablosu, sanatçının dâhiyane üslubunun en çarpıcı örneğidir.' },
    { name: 'Mirador del Valle', desc: 'Tacus Nehri’nin karşı yakasındaki bu bakış terası, Toledo’nun en klasik ve en ünlü panoramasını sunar. Nehrin bir at nalı gibi çevrelediği kentin, katedrali ve Alcázar’ıyla oluşan silueti buradan izlenir.' },
    { name: 'Yahudi Mahallesi & Sinagoglar', desc: 'Toledo, yüzyıllarca Müslüman, Hristiyan ve Yahudilerin bir arada yaşadığı “Üç Kültür Şehri” olarak bilinir. Dar sokaklı eski Yahudi mahallesindeki Santa María la Blanca ve El Tránsito sinagogları, bu benzersiz hoşgörü mirasının kanıtıdır.' },
  ],
  cordoba: [
    { name: 'Mezquita-Catedral', desc: 'Endülüs Emevileri’nin başkentindeki bu görkemli yapı, bir zamanlar dünyanın en büyük camilerinden biriydi ve sonradan içine bir katedral inşa edilmiştir. Kırmızı-beyaz çift kemerli sütun ormanıyla İslam mimarisinin bir UNESCO şaheseridir.' },
    { name: 'Judería', desc: 'Córdoba’nın eski Yahudi mahallesi olan Judería, dar ve dolambaçlı sokakları, badanalı evleri ve çiçek dolu avlularıyla büyüler. Bir sinagog ve filozof İbn Meymun’un heykelini barındıran bu semt, kentin çok kültürlü altın çağını yaşatır.' },
    { name: 'Alcázar de los Reyes', desc: 'Katolik Kral ve Kraliçe’nin ikametgâhı ve Granada’nın fethini planladıkları yer olan bu ortaçağ kalesi, tarihî önemiyle dikkat çeker. Ancak asıl ünü, havuzları, fıskiyeleri ve palmiyeleriyle bezeli görkemli Mağribi tarzı bahçelerinden gelir.' },
    { name: 'Roma Köprüsü', desc: 'Guadalquivir Nehri üzerinde MÖ 1. yüzyılda inşa edilen bu antik köprü, yüzyıllar boyunca kente giren tek köprüydü. On altı kemeriyle uzanan bu yapı, Mezquita manzarası eşliğinde tarihî bir yürüyüş sunar.' },
    { name: 'Patios (Avlular)', desc: 'Córdoba, sıcak iklime karşı serinlik sağlayan ve rengârenk saksı çiçekleriyle bezeli geleneksel iç avlularıyla (patio) ünlüdür. Her yıl mayısta düzenlenen ve bu avluların halka açıldığı festival, UNESCO’nun İnsanlığın Kültürel Mirası listesindedir.' },
  ],
  malaga: [
    { name: 'Alcazaba & Gibralfaro', desc: 'Endülüs Emevileri döneminden kalma bu görkemli kale kompleksi, İspanya’nın en iyi korunmuş Mağribi istihkâmlarındandır. Bir yürüyüş yoluyla bağlı olduğu tepedeki Gibralfaro Kalesi, şehrin, limanın ve Akdeniz’in muhteşem panoramasını sunar.' },
    { name: 'Picasso Müzesi', desc: '20. yüzyılın en etkili sanatçısı Pablo Picasso, 1881’de Málaga’da doğmuştur ve bu müze onun eserlerine adanmıştır. Ailesinin bağışladığı eserlerle sanatçının farklı dönemlerini sergileyerek doğduğu kentle olan bağını onurlandırır.' },
    { name: 'Katedral (La Manquita)', desc: 'İnşası için ayrılan paranın başka amaçlara harcanması nedeniyle ikinci kulesi hiç tamamlanamayan bu görkemli Rönesans katedrali, halk arasında sevgiyle “tek kollu kadın” (La Manquita) olarak anılır. Bu eksik hali, ona özgün bir kimlik katar.' },
    { name: 'Muelle Uno & Sahil', desc: 'Málaga’nın yenilenen limanındaki Muelle Uno, modern mağazaları, restoranları ve palmiyeli promenadıyla canlı bir yaşam alanıdır. Buradan başlayan geniş şehir plajları, Costa del Sol’un güneşli deniz keyfini kent merkezine taşır.' },
  ],
  santiagocompostela: [
    { name: 'Santiago Katedrali', desc: 'Havari Aziz Yakup’un (Santiago) mezarı üzerine kurulduğuna inanılan bu görkemli katedral, ünlü “Camino de Santiago” hac yolunun nihai varış noktasıdır. Barok cephesi ve tütsü sallayan dev buhurdanıyla dünyanın en önemli hac merkezlerindendir.' },
    { name: 'Praza do Obradoiro', desc: 'Katedralin görkemli barok cephesine bakan bu anıtsal meydan, kentin ve hac yolunun sembolik kalbidir. Dört bir yanı tarihî yapılarla çevrili bu geniş alan, yolculuklarını tamamlayan hacıların sevincine tanıklık eder.' },
    { name: 'Eski Şehir (UNESCO)', desc: 'Santiago de Compostela’nın tarihî merkezi, granitten yapılmış üstü kapalı kemerli sokakları (soportales), meydanları ve manastırlarıyla büyüler. Orta çağ hac kültürünün olağanüstü korunmuş bu dokusu, UNESCO Dünya Mirası listesindedir.' },
    { name: 'Mercado de Abastos', desc: 'Katedralden sonra kentin en çok ziyaret edilen yeri olan bu tarihî pazar, Galiçya bölgesinin bereketini sergiler. Atlantik’ten gelen taze deniz ürünleri, peynirler ve yerel lezzetleriyle bölge mutfağının canlı bir merkezidir.' },
  ],
  // --- Portekiz derinleştirme ---
  sintra: [
    { name: 'Pena Sarayı', desc: 'Sintra tepelerinin zirvesindeki bu rengârenk saray, sarı ve kırmızı kuleleri, egzotik motifleri ve masalsı mimarisiyle Avrupa Romantizminin en çarpıcı örneğidir. Bir manastır kalıntısı üzerine 19. yüzyılda inşa edilen bu yapı, UNESCO korumasındadır.' },
    { name: 'Quinta da Regaleira', desc: 'Bu gizemli malikâne ve bahçesi, simya, masonluk ve tapınak şövalyeleri sembolizmiyle doludur. En ünlü noktası, spiral bir merdivenle inilen ve yeraltı tünellerine bağlanan, dini bir tören alanı olan “Başlatılma Kuyusu”dur.' },
    { name: 'Mağribi Kalesi', desc: 'Sintra tepelerine hâkim bu kale, 8.–9. yüzyıllarda Mağribiler tarafından inşa edilmiş stratejik bir istihkâmdır. Sırtlar boyunca uzanan surları, Pena Sarayı’nın, kasabanın ve uzaktaki Atlas Okyanusu’nun eşsiz panoramasını sunar.' },
    { name: 'Monserrate Sarayı', desc: 'Zarif ve egzotik mimarisiyle bu villa, Mağribi, gotik ve Hint üsluplarını büyüleyici bir uyumla birleştirir. Ancak asıl ünü, dünyanın dört bir yanından getirilen bitkilerin bulunduğu, romantik ve egzotik peyzaj bahçesinden gelir.' },
    { name: 'Cabo da Roca', desc: 'Sintra yakınlarındaki bu sarp burun, Avrupa anakarasının en batı ucudur ve şair Camões’in deyimiyle “karanın bitip denizin başladığı yer”dir. Deniz feneri ve okyanusa dik inen dramatik uçurumlarıyla nefes kesici bir noktadır.' },
  ],
  faro: [
    { name: 'Cidade Velha (Surlu Şehir)', desc: 'Faro’nun surlarla çevrili eski şehri, anıtsal Arco da Vila kapısından geçilerek girilen sakin ve tarihî bir bölgedir. Arnavut kaldırımlı sokakları, katedrali ve çatılarında yuva kuran leylekleriyle Algarve’nin otantik geçmişini yansıtır.' },
    { name: 'Ria Formosa', desc: 'Faro kıyısı boyunca uzanan bu geniş lagün ve sulak alan doğal parkı, adaları, kanalları ve zengin kuş yaşamıyla önemli bir ekosistemdir. Tekne turlarıyla keşfedilen bu labirent, deniz atları ve göçmen kuşlara ev sahipliği yapar.' },
    { name: 'Algarve Kayalık Koyları', desc: 'Faro, Portekiz’in ünlü Algarve sahilinin merkezindedir ve Benagil Mağarası ile Lagos gibi eşsiz doğa harikalarına açılan bir kapıdır. Altın rengi kayalıkları, gizli koyları ve turkuaz sularıyla bu kıyı, dünyanın en güzel sahillerindendir.' },
    { name: 'Kemik Kapeli (Carmo)', desc: 'Carmo Kilisesi’nin arkasındaki bu ürpertici küçük şapel, duvarları ve tavanı yakındaki bir mezarlıktan çıkarılan binlerce keşiş kemiği ve kafatasıyla örülmüştür. Girişindeki “Burada bekleyen kemikler, sizinkileri bekliyor” yazısı, ölümlülüğü hatırlatır.' },
  ],
  coimbra: [
    { name: 'Joanina Kütüphanesi', desc: '18. yüzyıldan kalma bu görkemli barok üniversite kütüphanesi, yaldızlı ahşap oymaları ve egzotik süslemeleriyle dünyanın en güzel kütüphanelerinden biridir. İlginç bir şekilde, kitapları böceklerden korumak için gece burada yaşayan bir yarasa kolonisi barındırır.' },
    { name: 'Eski Üniversite & Kule', desc: 'Avrupa’nın en eski üniversitelerinden biri olan Coimbra Üniversitesi, bir tepenin üzerindeki tarihî sarayda yer alır ve UNESCO korumasındadır. Merkezindeki avlu ve saat kulesinden (“Keçi” lakaplı), şehrin ve Mondego Nehri’nin panoraması izlenir.' },
    { name: 'Coimbra Fado’su', desc: 'Lizbon fadosundan farklı olarak, Coimbra fadosu geleneksel olarak yalnızca üniversitenin siyah pelerinli erkek öğrencileri tarafından söylenir. Genellikle bir sevgiliye veya şehre serenat niteliğindeki bu köklü müzik geleneği, kentin kimliğinin bir parçasıdır.' },
    { name: 'Eski Katedral (Sé Velha)', desc: 'Portekiz’in Mağribilere karşı verdiği mücadele döneminde inşa edilen bu 12. yüzyıl katedrali, adeta bir kaleyi andıran sağlam ve savunmacı mimarisiyle dikkat çeker. Ülkenin en iyi korunmuş Romanesk yapılarından biridir.' },
  ],
  obidos: [
    { name: 'Óbidos Kalesi & Surları', desc: 'Bu şirin kasabayı tamamen çevreleyen ortaçağ surları ve tepesindeki kale, olağanüstü korunmuş haliyle büyüler. Bir zamanlar Portekiz kraliçelerine düğün hediyesi olarak verilen kasabanın surları üzerinde yürümek, benzersiz manzaralar sunar.' },
    { name: 'Rua Direita', desc: 'Óbidos’un iki kapısını birleştiren bu ana cadde, badanalı, sarı ve mavi şeritlerle boyanmış çiçekli evleri ve butik dükkânlarıyla kasabanın en canlı yeridir. Geleneksel el sanatları ve yerel ürünleri sunan bu sokak, kasabanın kalbidir.' },
    { name: 'Ginjinha (Çikolata Bardakta)', desc: 'Óbidos, geleneksel Portekiz vişne likörü “Ginjinha”nın yenilebilir küçük çikolata bardaklarda sunulmasıyla ünlüdür. Likörü içtikten sonra bardağını yemek, kasabaya özgü keyifli ve tatlı bir deneyimdir.' },
    { name: 'Santa Maria Kilisesi', desc: 'Kasabanın ana meydanındaki bu tarihî kilise, 10 yaşındaki bir kralın evlendiği yer olmasıyla ünlüdür. İç duvarlarını baştan başa kaplayan 17. yüzyıl mavi-beyaz azulejo çinileri, onu bir sanat şaheserine dönüştürür.' },
  ],

  // --- Birleşik Krallık derinleştirme ---
  bath: [
    { name: 'Roma Hamamları', desc: 'Romalıların yaklaşık 2.000 yıl önce doğal sıcak su kaynağı üzerine kurduğu bu görkemli hamam kompleksi, kente adını vermiştir. Olağanüstü korunmuş ana havuzu ve tapınağıyla antik Roma’nın sosyal ve dini yaşamına eşsiz bir pencere açar.' },
    { name: 'Royal Crescent & Circus', desc: 'Bath’in Georgian dönemi mimarisinin zirvesi olan bu yapılar, yarım ay (Crescent) ve dairesel (Circus) biçiminde dizilmiş görkemli sıra evlerdir. Sarımsı Bath taşından yapılan bu zarif cepheler, kentin UNESCO Dünya Mirası kimliğinin simgesidir.' },
    { name: 'Bath Abbey', desc: 'Kentin merkezindeki bu görkemli gotik kilise, olağanüstü yelpaze tonozlu tavanı ve batı cephesindeki, meleklerin bir merdivende tırmandığını betimleyen benzersiz taş oymalarıyla ünlüdür. Vitraylarıyla aydınlanan iç mekânı büyüler.' },
    { name: 'Pulteney Köprüsü', desc: 'Avon Nehri üzerindeki bu zarif 18. yüzyıl köprüsü, iki yanı boyunca dükkânlarla dolu olan dünyadaki nadir köprülerden biridir. Palladio üslubundaki mimarisi ve altındaki bent (weir) manzarasıyla kentin en romantik noktasıdır.' },
    { name: 'Thermae Bath Spa', desc: 'Bu modern kaplıca, Britanya’nın tek doğal termal suyunu kullanarak antik Roma geleneğini bugüne taşır. Özellikle açık hava çatı havuzu, buharı tüten şifalı suların içinde Bath’in tarihî silüetini seyretme fırsatı sunar.' },
  ],
  york: [
    { name: 'York Minster', desc: 'İki asırda tamamlanan bu görkemli katedral, Kuzey Avrupa’nın en büyük gotik kiliselerinden biridir. Özellikle ortaçağdan kalma muazzam vitray pencereleri, dünyanın en geniş cam koleksiyonlarından birini oluşturarak iç mekânı ışıkla doldurur.' },
    { name: 'The Shambles', desc: 'Kökeni ortaçağa uzanan bu daracık ve eğri büğrü sokak, üst katları birbirine değecek kadar yaklaşan ahşap dükkânlarıyla Avrupa’nın en iyi korunmuş ortaçağ caddelerindendir. Bir zamanlar kasapların olduğu sokak, Harry Potter’a ilham vermiştir.' },
    { name: 'Şehir Surları', desc: 'York’u çevreleyen bu tarihî surlar, Roma dönemine uzanan temelleri ve ortaçağ kapılarıyla (bar) İngiltere’nin en uzun ve en iyi korunmuş şehir surlarıdır. Üzerinde yürünen bu güzergâh, katedral manzarası eşliğinde bir tarih yolculuğu sunar.' },
    { name: 'Jorvik Viking Merkezi', desc: 'Bu müze, York’un Vikingler dönemindeki adı olan “Jorvik” kentini, bölgede yapılan kazı buluntularına dayanarak canlandırır. Ziyaretçileri, dönemin sesleri ve kokularıyla yeniden yaratılan bir Viking sokağında gezdirerek geçmişe götürür.' },
    { name: 'National Railway Museum', desc: 'Dünyanın en büyük demiryolu müzelerinden biri olan bu kurum, buharlı lokomotiflerin ve kraliyet trenlerinin ikonik örneklerini barındırır. Rekortmen “Mallard” gibi tarihî lokomotifleriyle demiryolunun görkemli tarihini kutlar.' },
  ],
  oxford: [
    { name: 'Christ Church College', desc: 'Oxford Üniversitesi’nin en büyük ve en görkemli kolejlerinden olan Christ Church, hem bir kolej hem de bir katedrali içinde barındırmasıyla benzersizdir. Görkemli yemekhanesi, Harry Potter filmlerindeki Hogwarts’ın Büyük Salonu’na ilham vermiştir.' },
    { name: 'Radcliffe Camera & Bodleian', desc: 'Dairesel ve kubbeli mimarisiyle Oxford’un simgesi olan Radcliffe Camera, bir okuma salonudur. Bağlı olduğu Bodleian Kütüphanesi ise Britanya’nın en eski kütüphanelerinden biri olup her yayından bir kopya alma hakkına sahip devasa bir bilgi hazinesidir.' },
    { name: 'Ahlar Köprüsü (Hertford)', desc: 'Hertford College’ın iki binasını birbirine bağlayan bu zarif geçit köprüsü, Venedik’teki ünlü Ahlar Köprüsü’ne benzetildiği için bu adla anılır. Oxford’un en çok fotoğraflanan ve en romantik simgelerinden biridir.' },
    { name: 'Ashmolean Müzesi', desc: '1683’te halka açılan Ashmolean, Britanya’nın en eski kamu müzesidir. Antik Mısır mumyalarından Raffaello’nun çizimlerine, arkeolojik hazinelerden sanat eserlerine uzanan zengin koleksiyonuyla dünya kültürlerine bir yolculuk sunar.' },
    { name: 'Carfax Kulesi', desc: 'Kentin merkezindeki bu 13. yüzyıl kulesi, bir zamanlar burada bulunan Aziz Martin Kilisesi’nden günümüze kalan tek bölümdür. 99 basamağının tepesindeki gözlem terasından, Oxford’un ünlü “rüya gibi kuleleri”nin panoraması izlenir.' },
  ],
  cambridge: [
    { name: 'King’s College Şapeli', desc: 'İngiliz geç gotik mimarisinin bir başyapıtı olan bu görkemli şapel, dünyanın en büyük yelpaze tonozlu tavanına sahiptir. Muhteşem vitrayları ve her Noel yayınlanan koro konseriyle Cambridge’in en tanınan simgesidir.' },
    { name: 'Punting (Cam Nehri)', desc: 'Cam Nehri üzerinde uzun bir sırıkla itilerek yürütülen düz tekneyle (punt) yapılan bu gezi, Cambridge’in en keyifli deneyimidir. “The Backs” denilen bölgede kolejlerin tarihî arka bahçelerini ve köprülerini sudan izleme fırsatı sunar.' },
    { name: 'Trinity & St John’s', desc: 'Cambridge’in en büyük ve en zengin kolejlerinden Trinity, Isaac Newton gibi dâhiler yetiştirmiştir. Komşusu St John’s ise Venedik’tekine öykünen zarif “İçler Köprüsü” (Bridge of Sighs) ile ünlü, tarihî bir kolejdir.' },
    { name: 'Fitzwilliam Müzesi', desc: 'Cambridge Üniversitesi’nin sanat ve antika müzesi olan bu görkemli kurum, “küçük bir Louvre” olarak anılır. Antik Mısır eserlerinden empresyonist tablolara uzanan zengin ve çeşitli koleksiyonuyla bir kültür hazinesidir.' },
    { name: 'Matematik Köprüsü', desc: 'Queens’ College’daki bu ünlü ahşap köprü, düz kirişlerin ustaca dizilimiyle kavisli bir görünüm yaratan zarif mühendislik tasarımıyla dikkat çeker. Hakkında anlatılan (aslında doğru olmayan) “Newton’un çivisiz yaptığı” efsanesiyle meşhurdur.' },
  ],
  liverpool: [
    { name: 'Albert Dock', desc: 'Bir zamanlar dünya ticaretinin merkezi olan bu tarihî rıhtım, Britanya’nın en büyük korumalı tarihî bina grubudur. Restore edilen tuğla depoları bugün Tate Liverpool ve The Beatles Story gibi müzeleri, restoranları barındıran canlı bir merkezdir.' },
    { name: 'The Beatles Story', desc: 'Dünyanın en ünlü müzik grubu The Beatles’ın memleketi olan Liverpool’daki bu müze, grubun yükselişini ve etkisini anlatır. Grubun ünlendiği efsanevi Cavern Club’ın bir kopyasıyla, o dönemin ruhunu hayranlarına yaşatır.' },
    { name: 'Royal Liver Building', desc: 'Liverpool’un su kenarındaki bu görkemli yapı, tepesindeki iki efsanevi “Liver Kuşu” heykeliyle kentin koruyucusu ve simgesidir. Efsaneye göre bu kuşlar uçup giderse şehir yok olacaktır; bu yüzden biri denize, biri kente bakar.' },
    { name: 'İki Katedral', desc: 'Liverpool, aynı cadde (Hope Street) üzerinde yer alan iki devasa ve çarpıcı katedraliyle benzersizdir. Devasa gotik Anglikan Katedrali ile huni biçimli modern Katolik Katedrali, kentin dini ve mimari çeşitliliğini temsil eder.' },
  ],
  // --- İrlanda ---
  dublin: [
    { name: 'Trinity College & Kells Kitabı', desc: 'İrlanda’nın en eski üniversitesi olan Trinity College, ünlü “Uzun Oda” kütüphanesiyle büyüler. Bu kütüphane, 9. yüzyıldan kalma, olağanüstü süslemeli bir el yazması İncil olan ve ortaçağ sanatının başyapıtı sayılan “Kells Kitabı”nı barındırır.' },
    { name: 'Temple Bar', desc: 'Dublin’in nehir kıyısındaki bu arnavut kaldırımlı bölge, kentin kültür ve eğlence merkezidir. Renkli tarihî pub’ları, canlı geleneksel İrlanda müziği ve hareketli atmosferiyle şehrin en canlı ve en çok ziyaret edilen semtidir.' },
    { name: 'Guinness Storehouse', desc: 'İrlanda’nın dünyaca ünlü siyah birası Guinness’in tarihî fabrikasında yer alan bu müze, biranın yapımını ve kültürünü anlatır. Dev bir bardak şeklinde tasarlanan yapının tepesindeki Gravity Bar, Dublin’in 360 derecelik panoramasını sunar.' },
    { name: 'Dublin Kalesi & Katedraller', desc: 'Yüzyıllarca İngiliz yönetiminin merkezi olan Dublin Kalesi, kentin tarihinin kalbidir. Yakınındaki iki görkemli ortaçağ katedrali, İrlanda’nın koruyucu azizine adanan St Patrick’s ve şehrin en eski yapısı Christ Church, dini mirası temsil eder.' },
    { name: 'Kilmainham Gaol', desc: 'Bu tarihî hapishane, İrlanda’nın bağımsızlık mücadelesinde önemli rol oynayan pek çok milliyetçi liderin tutulduğu ve idam edildiği yerdir. Bugün bir müze olan bu ürpertici mekân, İrlanda’nın özgürlük yolundaki acılı tarihini anlatır.' },
  ],
  galway: [
    { name: 'Latin Mahallesi', desc: 'Galway’in ortaçağdan kalma bu canlı bölgesi, rengârenk cepheli dükkânları, geleneksel pub’ları ve her köşesindeki sokak müzisyenleriyle büyüler. İrlanda’nın bohem ve sanatsal ruhunu en iyi yansıtan, hareketli bir kültür merkezidir.' },
    { name: 'Spanish Arch & Corrib', desc: 'Corrib Nehri’nin denize kavuştuğu noktadaki bu 16. yüzyıl kemeri, kentin İspanya ile yaptığı denizcilik ticaretinin bir kalıntısıdır. Çevresindeki nehir kıyısı, kentlilerin ve ziyaretçilerin toplandığı sevilen bir gezinti alanıdır.' },
    { name: 'Moher Uçurumları', desc: 'Galway yakınlarındaki bu görkemli uçurumlar, Atlas Okyanusu’nun üzerinde 214 metreye varan yükseklikleriyle İrlanda’nın en ünlü doğa harikasıdır. Kuş kolonilerine ev sahipliği yapan bu dramatik kıyı, nefes kesici manzaralar sunar.' },
    { name: 'Connemara', desc: 'Galway’in batısındaki bu bölge, engebeli dağları, ıssız bataklıkları, gölleri ve gotik Kylemore Manastırı’yla İrlanda’nın en vahşi ve romantik doğasını temsil eder. Geleneksel İrlandaca’nın hâlâ konuşulduğu bu topraklar, eşsiz manzaralar barındırır.' },
  ],
  cork: [
    { name: 'English Market', desc: '1788’den beri hizmet veren bu üstü kapalı gıda pazarı, İrlanda’nın en eski ve en ünlü pazarlarından biridir. Yerel çiftçilerin taze ürünleri, geleneksel etleri ve peynirleriyle Cork’un zengin gastronomi kültürünün canlı kalbidir.' },
    { name: 'Blarney Kalesi', desc: 'Cork yakınlarındaki bu ortaçağ kalesi, öpene “ikna ediciliğin sözü” (belagat) yeteneği kazandırdığına inanılan ünlü “Blarney Taşı” ile dünyaca meşhurdur. Taşı öpmek için surların tepesinde geriye doğru eğilmek gerekir.' },
    { name: 'Aziz Fin Barre Katedrali', desc: 'Kentin kurucusu kabul edilen Aziz Fin Barre’a adanan bu görkemli katedral, üç zarif kulesi ve göz alıcı Fransız neo-gotik mimarisiyle Cork’un simgesidir. Detaylı taş oymaları ve vitraylarıyla bir sanat şaheseridir.' },
    { name: 'Cobh & Titanic', desc: 'Cork yakınlarındaki bu renkli sahil kasabası, katedralinin tepede yükseldiği pitoresk manzarasıyla ünlüdür. Aynı zamanda talihsiz Titanic gemisinin son uğrak limanı ve milyonlarca İrlandalı göçmenin Yeni Dünya’ya açıldığı kapı olarak tarihe geçmiştir.' },
  ],
  // --- Hollanda derinleştirme ---
  utrecht: [
    { name: 'Dom Kulesi', desc: '112 metre yüksekliğiyle Hollanda’nın en yüksek kilise kulesi olan bu gotik yapı, Utrecht’in simgesidir. Bir zamanlar katedraline bağlıyken bir fırtınada ayrılan kulenin 465 basamağının tepesinden, açık havada Amsterdam bile görülebilir.' },
    { name: 'Kanal Rıhtımları (Werf)', desc: 'Utrecht, dünyada eşi benzeri olmayan çift katlı kanal sistemiyle ünlüdür. Bir zamanlar depo olarak kullanılan su seviyesindeki rıhtımlar (werf), bugün kanal kıyısındaki teraslarda oturulan şirin kafe ve restoranlara dönüşmüştür.' },
    { name: 'Miffy (Nijntje) Müzesi', desc: 'Utrecht, dünyaca sevilen çizgi tavşan karakteri Miffy’nin (Nijntje) yaratıcısı Dick Bruna’nın memleketidir. Bu müze, tamamen küçük çocuklar için tasarlanmış, sevimli ve interaktif odalarıyla minik ziyaretçileri Miffy’nin dünyasında ağırlar.' },
    { name: 'DOMunder', desc: 'Utrecht’in ana meydanının altında yer alan bu yeraltı arkeoloji deneyimi, kentin 2.000 yıllık tarihini gün yüzüne çıkarır. Ziyaretçiler, bir el feneriyle Roma kalesinden ortaçağ katedraline uzanan gizli kalıntıları keşfeder.' },
  ],
  delft: [
    { name: 'Markt & Nieuwe Kerk', desc: 'Delft’in görkemli ana meydanı, belediye binası ve yüksek kuleli Nieuwe Kerk (Yeni Kilise) ile çevrilidir. Bu kilise, Hollanda kraliyet hanedanı Oranje-Nassau ailesinin mezarlığına ev sahipliği yapmasıyla ulusal öneme sahiptir.' },
    { name: 'Royal Delft (Porselen)', desc: 'Delft, 17. yüzyıldan beri ürettiği ünlü mavi-beyaz el yapımı seramikleriyle (Delftware) dünyaca tanınır. Bu atölye ve müze, hâlâ geleneksel yöntemlerle üretilen bu zarif çinilerin yapım sürecini ve tarihini sergiler.' },
    { name: 'Vermeer Merkezi', desc: 'Delft, “İnci Küpeli Kız” gibi başyapıtların ressamı Johannes Vermeer’in doğduğu ve tüm eserlerini ürettiği kenttir. Bu merkez, sanatçının hayatını, tekniklerini ve kentiyle olan bağını interaktif bir şekilde ziyaretçilere tanıtır.' },
    { name: 'Kanal Yürüyüşü', desc: 'Delft’in tarihî merkezi, ağaçlarla gölgelenmiş kanalları, zarif köprüleri ve 17. yüzyıldan kalma binalarıyla huzurlu bir atmosfer sunar. Vermeer’in tablolarına ilham veren bu pitoresk su yolları boyunca yürümek keyifli bir deneyimdir.' },
  ],
  lahey: [
    { name: 'Mauritshuis', desc: 'Bu zarif müze, Hollanda Altın Çağı resminin başyapıtlarını, özellikle de Vermeer’in dünyaca ünlü “İnci Küpeli Kız” tablosunu barındırmasıyla meşhurdur. Rembrandt gibi ustaların eserleriyle küçük ama son derece değerli bir koleksiyona sahiptir.' },
    { name: 'Binnenhof', desc: 'Bir gölün kıyısındaki bu tarihî yapılar topluluğu, yüzyıllardır Hollanda siyasetinin merkezidir ve parlamentoya ev sahipliği yapar. Ortasındaki gotik Şövalyeler Salonu (Ridderzaal) ile ülkenin en önemli kraliyet ve devlet mekânıdır.' },
    { name: 'Escher in Het Paleis', desc: 'Eski bir kraliyet sarayında yer alan bu müze, imkânsız yapıları ve optik yanılsamalarıyla ünlü grafik sanatçısı M.C. Escher’in eserlerine adanmıştır. Zihin bükücü sanat eserleri ve interaktif sergileriyle ziyaretçileri şaşırtır.' },
    { name: 'Scheveningen', desc: 'Lahey’in ünlü sahil semti olan Scheveningen, geniş kumsalı, tarihî iskelesi ve büyük otelleriyle popüler bir tatil merkezidir. Deniz kıyısı promenadı, restoranları ve etkinlikleriyle Kuzey Denizi’nin canlı bir cazibe noktasıdır.' },
    { name: 'Madurodam', desc: 'Bu benzersiz açık hava müzesi, Hollanda’nın en ünlü binalarını, kanallarını ve simgelerini 1:25 ölçeğinde minyatür maketlerle canlandırır. Hareketli detaylarıyla tüm ülkeyi tek bir parkta gezmeyi sağlayan eğlenceli bir deneyimdir.' },
  ],
  giethoorn: [
    { name: 'Kanal Tekne Turu', desc: '“Hollanda’nın Venedik’i” olarak anılan Giethoorn’da araba yolları yerine kanallar vardır. Sessizce süzülen elektrikli “fısıltı tekneleri” (whisper boat) ile yapılan gezi, bu masalsı köyü keşfetmenin en huzurlu ve en özgün yoludur.' },
    { name: 'Tahta Köprüler', desc: 'Kanallarla bölünmüş Giethoorn’da evler ve çiftlikler, birbirine 170’ten fazla şirin ahşap yaya köprüsüyle bağlanır. Bu zarif köprüler, köye dünyaca ünlü pitoresk ve romantik görünümünü kazandıran en önemli unsurdur.' },
    { name: 'Kamış Çatılı Evler', desc: 'Giethoorn, kanalların ortasındaki küçük adacıklar üzerine kurulmuş, geleneksel kamış çatılı tarihî çiftlik evleriyle büyüler. Bahçeleri ve suya yansıyan görüntüleriyle bu evler, köye bir masal diyarı havası katar.' },
    { name: 'Weerribben-Wieden', desc: 'Giethoorn’u çevreleyen bu geniş milli park, Batı Avrupa’nın en büyük bataklık ekosistemidir. Kano veya tekneyle keşfedilen bu labirent gibi sulak alan, zengin kuş yaşamı ve el değmemiş doğasıyla bir cennettir.' },
  ],
  // --- Belçika derinleştirme ---
  gent: [
    { name: 'Gravensteen Kalesi', desc: 'Adı “Kont Kalesi” anlamına gelen bu görkemli ortaçağ kalesi, Flandre kontları için 12. yüzyılda inşa edilmiştir. Su hendeğiyle çevrili sağlam surları ve içindeki işkence aletleri müzesiyle, kentin ortaçağdaki gücünü ve karanlık geçmişini yansıtır.' },
    { name: 'Gent Altar (Van Eyck)', desc: 'Aziz Bavo Katedrali’nde sergilenen ve Van Eyck kardeşlerin yaptığı bu çok panelli sunak (Mistik Kuzu’ya Tapınma), sanat tarihinin en önemli başyapıtlarından biridir. Yağlıboya tekniğinin gelişimindeki devrimci rolüyle paha biçilmezdir.' },
    { name: 'Graslei & Korenlei', desc: 'Gent’in eski limanı olan bu tarihî iskele, Leie Nehri’nin iki yakasında karşılıklı sıralanan görkemli ortaçağ lonca evleriyle çevrilidir. Kentin en güzel manzarasını sunan bu bölge, canlı atmosferiyle sosyal yaşamın kalbidir.' },
    { name: 'Belfort', desc: '91 metre yüksekliğiyle Gent’in en yüksek çan kulesi olan Belfort, kentin özerkliğinin ve gücünün bir simgesi olarak inşa edilmiştir. UNESCO korumasındaki bu kulenin tepesinden, Gent’in tarihî çatılarının panoraması izlenir.' },
  ],
  anvers: [
    { name: 'Onze-Lieve-Vrouwe Katedrali', desc: '123 metrelik kulesiyle Antwerp siluetine hâkim olan bu görkemli gotik katedral, Belçika’nın en büyük kilisesidir. Kentte yaşamış büyük Barok ustası Peter Paul Rubens’in birkaç başyapıtını sergilemesiyle bir sanat hazinesidir.' },
    { name: 'Merkez Tren Garı', desc: '“Demiryolu Katedrali” olarak anılan Antwerp Merkez Garı, görkemli taş cephesi, dev cam kubbesi ve ihtişamlı iç mekânıyla dünyanın en güzel tren istasyonlarından biri kabul edilir. Bir ulaşım noktasından çok bir mimari şaheserdir.' },
    { name: 'Grote Markt & Belediye', desc: 'Antwerp’in tarihî ana meydanı, süslü lonca evleri ve görkemli Rönesans belediye binasıyla çevrilidir. Ortasındaki Brabo Çeşmesi, kente adını verdiğine inanılan bir devin elinin denize atılışını betimleyen efsaneyi canlandırır.' },
    { name: 'Elmas Bölgesi', desc: 'Antwerp, yüzyıllardır dünyanın en önemli elmas ticaret ve işleme merkezi olup küresel elmasların büyük çoğunluğu bu kentten geçer. Merkez Gar yakınındaki bu bölge, yüzlerce kuyumcu ve elmas şirketiyle kentin parlayan bir kimliğidir.' },
    { name: 'MAS Müzesi', desc: 'Kırmızı kumtaşı ve dalgalı cam cephesiyle dikkat çeken bu modern “Nehir Kıyısı Müzesi”, Antwerp’in dünyayla olan bağlarını ve liman tarihini anlatır. Ücretsiz çatı terasından, kentin ve limanın 360 derecelik panoraması izlenir.' },
  ],
};

export function attractionsFor(placeId) {
  return ATTRACTIONS[placeId] || [];
}

// Bir mekanı, keşif olarak eklenmeye hazır bir nesneye çevirir (yerel arşiv kaynaklı).
export function attractionToDiscovery(attraction, place, dateKey) {
  return {
    placeName: attraction.name,
    city: place.city || place.name,
    country: place.country || '',
    date: dateKey,
    lat: attraction.lat ?? place.lat ?? null,
    lng: attraction.lng ?? place.lng ?? null,
    summary: attraction.desc || '',
    sources: place.sources || [],
    userNotes: '',
    photoUri: null,
    enrichSource: 'local',
  };
}
